INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('877ab0c9-5d11-45d5-83a4-9ba89450020d','en_MZ','PRIVACY_HEADER_1_SUB_1','Introduction','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('32b83b46-26c3-4c14-a262-2c6361c8f329','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_1','This is the Privacy Policy for HCM Console','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('557ce921-b9b9-4281-9356-35ab1492878e','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_2','HCM Console is a software that enables delivery of public services to you by the relevant government agency or contractor and/or payment of taxes and/or fees by you to a government agency. It is powered by the DIGIT platform, which is developed and maintained by eGov Foundation.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('802550af-0371-4829-bc12-b5e6877f7406','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_3','HCM Console has been adopted in your jurisdiction by Name of Government Agency.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0f4fd564-7b64-4aae-b12d-78026d8e018d','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_4','You are viewing this Privacy Policy because you are going to use HCM Console to access a public service and/or pay taxes and/or fees to a government agency.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b945640b-a0e8-4be9-9708-955df4f663ca','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_5','When you use HCM Console, your data — including personally identifiable information (PII) — may be collected, stored, processed, used, and shared.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b849e2f2-45b5-409c-8dd9-93d5192114d4','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_6','This Privacy Policy describes the basis for such data collection, storage, processing, use, and sharing, and provides further details on how this will be done.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('38ddb5a5-dfd1-4476-b8bb-17b70ac92a7d','en_MZ','PRIVACY_HEADER_1_SUB_1_DESC_7','This Privacy Policy also describes your rights with respect to such data.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ab7c54ba-49c9-4636-bf13-daa3405719e4','en_MZ','PRIVACY_HEADER_2_SUB_2','Definitions','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31e44e15-11d7-4504-b0bd-f0a85aa16617','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','In this Privacy Policy:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cba081d2-0031-45a0-979a-629136c7db98','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','a. “You” refers to you, the reader of this policy, and more broadly to any user of HCM Console','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3838803e-cb98-4d45-bdc8-7664b8fe83c5','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','b. “Data” or “your data” refers to such data about you as may be collected, stored, processed, used, and/or shared during your usage of HCM Console','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9dd984c3-c831-445e-99f2-f716d06ac56f','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3_SUBDESC_1','i. Please note that if you are a government employee or contractor, your name, designation, and official contact information (phone number, email ID, postal address) are not considered PII. ','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7b6d394a-15d5-45b5-8107-360682547b20','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3_SUBDESC_2','ii. Your national ID number or other ID document number, while not in itself PII, will be treated as PII. ','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a9218687-332a-44f7-9147-117a1b38df81','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','c. “Personally Identifiable Information” or “PII” refers to such data about you as would enable persons viewing that data to identify and/or contact you, such as your name, parent/guardian’s name, personal phone number, personal email ID, personal postal / residential address, photographs of you, photographs / scanned copies of your ID documents, and biometric information such as your fingerprint or retinal imprint.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d8f54747-6437-4032-8a81-51ae6fe5007c','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','d. ''Program Owner'', ''Government Agency'', and ''Relevant Government'' all refer to [Name of Government Agency].','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bb7a1eea-c805-448f-9d61-27d7e384a466','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_6','d. “Program Owner”, “Government Agency”, and “Relevant Government” all refer to Name of Government Agency. ','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5ecda2b5-f164-4f97-bd06-2b4049fd5458','en_MZ','PRIVACY_HEADER_3_SUB_3','Basis for Data Collection, Storage, Processing, Use, and Sharing','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a8fe446f-a70d-4f8b-a68c-8d55ba0e5093','en_MZ','PRIVACY_HEADER_3_SUB_3_DESC_1','digit-privacy-policy','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a0ec4cef-04ec-4d08-99e5-6f8dba6c6616','en_MZ','PRIVACY_HEADER_3_SUB_3_DESC_2','The basis for such data collection, storage, processing, use, and sharing is that Program Owner is a government agency, and is acting in pursuance of its mandate to deliver services to and/or collect taxes and/or fees from you. This is a legitimate purpose, and your consent is not required for such data collection, storage, processing, use, and sharing.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4ae3aab9-81b2-49a6-9b86-fe4528353bb8','en_MZ','PRIVACY_HEADER_4_SUB_4','Data Collection','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e8b479d-3fbd-4531-8563-63292170d29d','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1','When you access services through Solution Name, your data (including PII) may be collected in the following ways:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc7c5465-1c77-4999-9ced-838a8a5220b3','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_1','You provide this data through the use of the mobile application','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4efc414e-d0dd-41cb-9075-2c5809d57a3f','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_2','You provide this data through the use of a Whatsapp chatbot','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f315a10-ac36-4978-af6b-d0fa90d5b195','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_3','You provide this data through the use of a phone helpline or IVR system','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('63230d69-14cf-403d-8bab-ec3698335390','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_4','You provide this data through the use of a government website','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('39bfe5b8-c857-443f-916a-2e80eeed1fb9','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_5','You provide this data in person, at a Citizen Service Centre, government office, or similar location.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a0e4b71b-50c3-4fb8-818b-3622cc06982e','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_6','You provide this data to a recognised extension worker / intermediary / volunteer','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fe31626b-2528-4ab7-a9f2-f2550907e847','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_7','HCM Console accesses this data from existing administrative records','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('edf1e73d-fe39-4ec5-b49e-472ca49da84c','en_MZ','PRIVACY_HEADER_4_SUB_4_DESC_2','HCM Console follows the principles of purpose limitation and data minimisation by default. You will only be asked to provide data (including PII) if this data is needed by Program Owner to provide you with the services you are requesting and/or accept your payment of taxes and/or fees.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c7c464f1-8e43-4325-8266-d89670c57741','en_MZ','PRIVACY_HEADER_5_SUB_5','Data Storage','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4d2204c3-248d-456c-84a8-6cac2df2b2d5','en_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1','By default, HCM Console adopts the following practices to ensure that your PII is stored securely:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('44540ff0-c453-49bd-984b-e9c40c4879a4','en_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_1','Secure digital storage: The DIGIT Platform is designed with default security settings that provide robust protection. While administrators can adjust these settings to fit specific needs, the out-of-the-box configuration is secure.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bcbdee0e-eb16-41e7-b4ce-1586f7503343','en_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_2','Encryption at rest: The DIGIT Platform Encryption Service enables encryption of all sensitive data stored by HCM Console.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('846df13a-94fb-46db-a77c-eaea29446410','en_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_3','Encryption in transit: All data is transmitted using HTTPS (TLS Encryption).','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('47ced807-b627-4d34-9af2-b3463bb638ad','en_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_4','Signed audit logs: All changes made to data are recorded in a signed audit log, ensuring non-repudiability – i.e. it is always possible to track who has made a given change, and that user cannot refute that they made that change.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d8286780-704b-4a5d-b635-571e25137796','en_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_5','User Registry: Solution name stores all your PII in a single, secure registry, known as a User Registry. Access to the User Registry is limited / controlled – see the “Data Processing & Use” section for details.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ffd5dc88-2426-481c-aab5-bf588ab323a8','en_MZ','PRIVACY_HEADER_6_SUB_1','Data Processing & Use','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e749f18-83cd-4728-888c-2f09c1bf78fa','en_MZ','PRIVACY_HEADER_6_SUB_6_DESC_1','When you access services from Program Owner, your data (including PII) will be processed and used to provide you the services you are requesting and/or to collect and record the taxes and/or fees you are paying.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('96cc2588-531e-4c50-b16a-be6ffc0abc8e','en_MZ','PRIVACY_HEADER_6_SUB_6_DESC_2','HCM Console follows the principles of least privilege and purpose limitation by default. Only such individuals / users as need to see your data (including PII) to do their jobs will have access to it.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('80da3782-c655-48ff-b09c-10da33044c32','en_MZ','PRIVACY_HEADER_6_SUB_6_DESC_3','HCM Console ensures access is limited to only such users by requiring authentication and authorisation – i.e. each user must log in and verify who they are – and role-based access controls (RBAC), wherein the data they are able to access is determined by their role.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c17f5d80-72f3-4497-a81e-630f5313e892','en_MZ','PRIVACY_HEADER_6_SUB_6_DESC_4','eGov Foundation does not encourage the creation of “super user” roles with wide access, absent specific purpose.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('17ff9939-4312-42bd-b986-eeb7966df2d4','en_MZ','PRIVACY_HEADER_7_SUB_1','Data Sharing','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f3d99836-368f-496c-936f-85632924f3ee','en_MZ','PRIVACY_HEADER_7_SUB_7_DESC_1','When you access services from or pay taxes and/or fees to Program Owner, your data (including PII) is collected, stored, and processed and used as described above.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('235de4d0-2fda-4c76-bcfd-8f0d9e071c3f','en_MZ','PRIVACY_HEADER_7_SUB_7_DESC_2','Your data may be shared with the following entities, for the following purposes:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8d812a01-b85f-4fb8-9c00-cfa43a681b34','en_MZ','PRIVACY_HEADER_7_SUB_7_DESC_3','HCM Console follows the principles of least privilege and purpose limitation by default. This means that PII is never used / shared for the purposes of analytics, or in any case where the purpose of data sharing is served by aggregated or depersonalised data.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('64f9a50c-56e5-45cc-9015-1ed277f536a5','en_MZ','PRIVACY_HEADER_7_SUB_7_DESC_4','Your data will not be shared with entities other than those listed above, unless you consent to such further sharing, or unless such sharing is mandated by law or the order of a Court or similar judicial body.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7d33874a-0dd3-430d-bde9-6beac15d6312','en_MZ','PRIVACY_HEADER_8_SUB_1','Data Retention and Deletion','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7809130f-ff54-4f3d-866b-413614491332','en_MZ','PRIVACY_HEADER_8_SUB_8_DESC_1','Your data (including PII) will be retained for such period of time as may be specified by Program Owner and/or specified by relevant law.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a3ecf38c-4fe2-4c36-aa11-58631f3040fb','en_MZ','PRIVACY_HEADER_8_SUB_8_DESC_2','Your data (including PII) may be deleted by Program Owner as per their established processes and/or as specified by relevant law.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0b2681f7-f218-412f-8ebe-4c79d61a5b40','en_MZ','PRIVACY_HEADER_8_SUB_8_DESC_3','You do not have a right to request Program Owner to delete your data, unless such right is recognised / provide by Program Owner and/or by relevant law.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('288514c7-4046-4b41-83a5-f042fd383dda','en_MZ','PRIVACY_HEADER_8_SUB_8_DESC_4','Please note that deleting your account on the HCM Console website or mobile app, or deleting any messages you have exchanged with Program Owner employees or contractors over SMS, chatbot, etc. does not mean that your data (including PII) has been deleted from HCM Console / Program Owner’s records.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0d1ca19e-0922-4df8-9993-337661aef590','en_MZ','PRIVACY_HEADER_9_SUB_9','Your Rights with respect to this Data','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('855f2994-f181-4789-b490-e3ffde5a0520','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_1','You have the following rights with respect to data (including PII) covered by this Privacy Policy:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ce19b59-5f4d-41f2-8a2f-9dafa9b5f7d6','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_2','a. You have the right to know what data is being collected, stored, processed, used, and shared. This Privacy Policy has provided you with the relevant information.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6edf42e1-761b-4801-b915-04f5cd029e4d','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3','b. You have the right to view your data, and to request correction of the data in case of any errors. ','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a480983b-35eb-4936-bba5-057a6a72458b','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3_SUBDESC_1','i. Program Owner will determine the procedure for correction.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f87c6ba1-d068-47c1-9830-8ef3346b3aba','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3_SUBDESC_2','ii. To access this information, please contact Program Owner contact details.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8a55e48e-d55b-4205-8f2b-a23d75630404','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_4','c. You have the right to know with whom your data has been / is being shared.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c60e42b9-72ee-4669-ae15-403968c8fd9f','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_4_SUBDESC_1','i. To access this information, please contact Program Owner contact details.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('831fbaa5-07d3-43ae-9027-7a99c57a4d42','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5','d. In case your data is to be shared with any person or organisation not already described in the “Data Sharing” section of this policy, Program Owner shall contact you and seek your consent for such sharing.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bf55b4a9-6f97-4d8e-9721-fac1772d553a','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5_SUBDESC_1','ii. You have the right to refuse such consent, in which case, your data cannot be shared with such additional person or organisation.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0eb69f6e-7905-418b-9220-ed124d834a2a','en_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5_SUBDESC_2','ii.This provision may not apply in case the sharing of your data with such additional person or organisation is mandated by law or the order of any court / judicial body.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('954b8927-a645-4aac-8767-d35dc25a7ee4','en_MZ','PRIVACY_POLICY_ACCEPT_TEXT','I Accept','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bcb8f7a9-75c6-4bb4-b72f-77befad4960c','en_MZ','PRIVACY_POLICY_DECLINE_TEXT','I Do Not Accept','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
