INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('312da7f7-2f29-412b-9b53-543960920a26','pt_MZ','PRIVACY_HEADER_1_SUB_1','Introdução','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cefcb626-48cc-4043-b4fc-5dd7dc162218','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_1','Esta é a Política de Privacidade do Console HCM','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('80e20f05-284b-4918-be10-880aefeb02f4','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_2','O HCM Console é um software que permite a prestação de serviços públicos a você pela agência governamental ou contratante relevante e/ou o pagamento de impostos e/ou taxas por você a uma agência governamental. É alimentado pela plataforma DIGIT, desenvolvida e mantida pela eGov Foundation.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7a8f6c74-cec2-4560-8831-f7618c73efb2','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_3','O Console HCM foi adotado em sua jurisdição pelo Nome da Agência Governamental.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92ec8629-bc7e-4289-bd43-5da974bf793a','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_4','Você está visualizando esta Política de Privacidade porque usará o Console HCM para acessar um serviço público e/ou pagar impostos e/ou taxas a uma agência governamental.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('18603ea2-12dd-41c5-a4ef-70c19ca3223e','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_5','Quando você usa o HCM Console, seus dados — incluindo informações de identificação pessoal (PII) — podem ser coletados, armazenados, processados, usados ​​e compartilhados.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0aadd778-c841-442b-b2d2-8693453cec1b','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_6','Esta Política de Privacidade descreve a base para tal coleta, armazenamento, processamento, uso e compartilhamento de dados e fornece mais detalhes sobre como isso será feito.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('56c6ba32-85b3-4f83-bb52-8289c0ab990e','pt_MZ','PRIVACY_HEADER_1_SUB_1_DESC_7','Esta Política de Privacidade também descreve os seus direitos em relação a esses dados.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3e3d586c-a5d7-464c-a6ca-28e3adb84ba9','pt_MZ','PRIVACY_HEADER_2_SUB_2','Definições','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57eb8d05-cde7-4b9e-81ba-29625f248b9a','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','Nesta Política de Privacidade:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2bf7f460-54e0-4abf-9cc3-5331077fe3d9','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','um. “Você” refere-se a você, o leitor desta política, e de forma mais ampla a qualquer usuário do Console HCM','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a892dbd1-1e38-46ea-8d87-58ecc72608de','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','b. “Dados” ou “seus dados” referem-se aos dados sobre você que podem ser coletados, armazenados, processados, usados ​​e/ou compartilhados durante seu uso do Console HCM','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0866f9f7-421c-401d-9b18-caa0e483a39a','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3_SUBDESC_1','eu. Observe que se você for um funcionário ou contratado do governo, seu nome, designação e informações de contato oficiais (número de telefone, ID de e-mail, endereço postal) não são considerados PII.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4793d940-c126-4749-a195-e0dba3568320','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3_SUBDESC_2','ii. Seu número de identificação nacional ou outro número de documento de identificação, embora não seja PII em si, será tratado como PII.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a04a572d-0684-441e-8426-85eb73b972eb','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','c. “Informações de identificação pessoal” ou “PII” referem-se aos dados sobre você que permitiriam às pessoas que visualizam esses dados identificá-lo e/ou contatá-lo, como seu nome, nome dos pais/responsáveis, número de telefone pessoal, ID de e-mail pessoal, endereço postal/residencial pessoal, fotografias suas, fotografias/cópias digitalizadas de seus documentos de identificação e informações biométricas, como sua impressão digital ou impressão na retina.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a76ddc1f-4a48-4772-a2a0-eb06ce827e65','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','d. ''Proprietário do Programa'', ''Agência Governamental'' e ''Governo Relevante'' referem-se todos a [Nome da Agência Governamental].','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('98050ffb-b562-4059-b987-7a8704238331','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_6','d. “Proprietário do Programa”, “Agência Governamental” e “Governo Relevante” referem-se ao Nome da Agência Governamental.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1192f69f-0b95-4686-8e9d-facc972ad936','pt_MZ','PRIVACY_HEADER_3_SUB_3','Base para coleta, armazenamento, processamento, uso e compartilhamento de dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8742291b-a2ab-404a-ba52-fd445e81a347','pt_MZ','PRIVACY_HEADER_3_SUB_3_DESC_1','política de privacidade de dígitos','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0c037d1b-7bc9-4426-b46b-48181e030485','pt_MZ','PRIVACY_HEADER_3_SUB_3_DESC_2','A base para tal coleta, armazenamento, processamento, uso e compartilhamento de dados é que o Proprietário do Programa é uma agência governamental e está agindo de acordo com seu mandato para fornecer serviços e/ou cobrar impostos e/ou taxas de você. Este é um propósito legítimo e o seu consentimento não é necessário para tal coleta, armazenamento, processamento, uso e compartilhamento de dados.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c5e0fc68-ac24-4fe4-bf2d-d1ff979500b7','pt_MZ','PRIVACY_HEADER_4_SUB_4','Coleta de dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('25070784-7eda-4200-b0f6-8b918d99d7ae','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1','Quando você acessa serviços por meio do Solution Name, seus dados (incluindo PII) podem ser coletados das seguintes maneiras:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b03f6fb0-6566-483c-8448-9611e0806ec4','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_1','Você fornece esses dados por meio do uso do aplicativo móvel','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ef400d01-46e4-4068-a0cb-1d8481ed1337','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_2','Você fornece esses dados por meio de um chatbot do Whatsapp','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ea10c57-ebcf-4a11-9bb6-81821605fa44','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_3','Você fornece esses dados por meio de uma linha telefônica de apoio ou sistema IVR','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9dc91cc5-07ca-4d9a-af12-182e69fe7893','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_4','Você fornece esses dados através do uso de um site do governo','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('034528e6-9f36-421f-a1e4-702d680ddcdc','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_5','Você fornece esses dados pessoalmente, em um Centro de Atendimento ao Cidadão, repartição governamental ou local semelhante.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc65fd73-fc22-42d4-bd2c-239a898c6186','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_6','Você fornece esses dados a um extensionista/intermediário/voluntário reconhecido','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e2bbe0c8-5bf7-49c6-9e6a-176ae4387aca','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_7','O Console do HCM acessa esses dados de registros administrativos existentes','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('737b26e2-a5a3-4806-a119-eabddb290da1','pt_MZ','PRIVACY_HEADER_4_SUB_4_DESC_2','O Console HCM segue os princípios de limitação de finalidade e minimização de dados por padrão. Você só será solicitado a fornecer dados (incluindo PII) se esses dados forem necessários ao Proprietário do Programa para lhe fornecer os serviços que você está solicitando e/ou aceitar o pagamento de impostos e/ou taxas.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('74d82e98-863b-452c-b255-a89646633d62','pt_MZ','PRIVACY_HEADER_5_SUB_5','Armazenamento de dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a381faf3-dbb1-4686-803f-84b5d9425667','pt_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1','Por padrão, o Console HCM adota as seguintes práticas para garantir que suas PII sejam armazenadas com segurança:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2f85b061-d152-41b2-b161-e0cd51d50988','pt_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_1','Armazenamento digital seguro: A plataforma DIGIT foi projetada com configurações de segurança padrão que fornecem proteção robusta. Embora os administradores possam ajustar essas configurações para atender a necessidades específicas, a configuração pronta para uso é segura.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5d11268f-d27d-4ed3-9bef-4eec02a7a5c3','pt_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_2','Criptografia em repouso: O serviço de criptografia da plataforma DIGIT permite a criptografia de todos os dados confidenciais armazenados pelo console HCM.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c5d83a21-695c-4b56-82be-aef939ff3682','pt_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_3','Criptografia em trânsito: Todos os dados são transmitidos usando HTTPS (criptografia TLS).','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('34c8d596-6da2-454c-b402-0d292404fa3c','pt_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_4','Registros de auditoria assinados: Todas as alterações feitas nos dados são registradas em um registro de auditoria assinado, garantindo a não repudiabilidade – ou seja, é sempre possível rastrear quem fez uma determinada alteração, e esse usuário não pode refutar que fez essa alteração.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc4e5143-b22d-4eea-ba40-ebdc9966d262','pt_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_5','Registro do usuário: o nome da solução armazena todas as suas PII em um registro único e seguro, conhecido como Registro do usuário. O acesso ao Cadastro de Usuários é limitado/controlado – consulte a seção “Processamento e utilização de dados” para obter detalhes.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('68a9e9b5-3737-4f52-abf2-89c6049c767d','pt_MZ','PRIVACY_HEADER_6_SUB_1','Processamento e uso de dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba5998fe-081c-4292-8325-aa6fc0df149d','pt_MZ','PRIVACY_HEADER_6_SUB_6_DESC_1','Quando você acessa os serviços do Proprietário do Programa, seus dados (incluindo PII) serão processados ​​e usados ​​para fornecer os serviços que você está solicitando e/ou para coletar e registrar os impostos e/ou taxas que você está pagando.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3bcae2e1-ec8b-4391-88fe-3b08769bad76','pt_MZ','PRIVACY_HEADER_6_SUB_6_DESC_2','O Console HCM segue os princípios de privilégio mínimo e limitação de finalidade por padrão. Somente os indivíduos/usuários que precisarem ver seus dados (incluindo PII) para realizar seu trabalho terão acesso a eles.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f2f99c6f-2390-4cf7-b071-da98c20068f8','pt_MZ','PRIVACY_HEADER_6_SUB_6_DESC_3','O Console HCM garante que o acesso seja limitado apenas a esses usuários, exigindo autenticação e autorização – ou seja, cada usuário deve fazer login e verificar quem é – e controles de acesso baseados em função (RBAC), em que os dados que eles podem acessar são determinados por sua função.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e17b3a63-7590-47be-a817-e637808522de','pt_MZ','PRIVACY_HEADER_6_SUB_6_DESC_4','A Fundação eGov não incentiva a criação de funções de “superusuário” com amplo acesso, sem finalidade específica.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('165cd428-4518-4754-9126-570fce1f8608','pt_MZ','PRIVACY_HEADER_7_SUB_1','Compartilhamento de dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6aaa5617-fe2d-4d08-9958-07c5dac476ce','pt_MZ','PRIVACY_HEADER_7_SUB_7_DESC_1','Quando você acessa serviços ou paga impostos e/ou taxas ao Proprietário do Programa, seus dados (incluindo PII) são coletados, armazenados, processados ​​e usados ​​conforme descrito acima.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d79fd6c7-1148-44cc-ae67-cc46b5173130','pt_MZ','PRIVACY_HEADER_7_SUB_7_DESC_2','Os seus dados poderão ser partilhados com as seguintes entidades, para as seguintes finalidades:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('004e473c-a459-4eac-9553-0d5cb4607367','pt_MZ','PRIVACY_HEADER_7_SUB_7_DESC_3','O Console HCM segue os princípios de privilégio mínimo e limitação de finalidade por padrão. Isto significa que as IPI nunca são utilizadas/partilhadas para fins de análise, ou em qualquer caso em que o propósito de partilha de dados seja servido por dados agregados ou despersonalizados.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('71de2ac0-e7c3-4b59-bca9-d052c77b2c08','pt_MZ','PRIVACY_HEADER_7_SUB_7_DESC_4','Os seus dados não serão partilhados com entidades que não sejam as listadas acima, a menos que você consinta com tal partilha adicional, ou a menos que tal partilha seja obrigatória por lei ou por ordem de um Tribunal ou órgão judicial semelhante.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2802e7e2-69a1-40f5-9d7d-eb1669ab8801','pt_MZ','PRIVACY_HEADER_8_SUB_1','Retenção e exclusão de dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dad42da9-458c-45cc-b114-c551447b373f','pt_MZ','PRIVACY_HEADER_8_SUB_8_DESC_1','Seus dados (incluindo PII) serão retidos pelo período de tempo especificado pelo Proprietário do Programa e/ou especificado pela lei aplicável.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1151ffef-6c47-4264-88c8-aa35ae8f9d28','pt_MZ','PRIVACY_HEADER_8_SUB_8_DESC_2','Seus dados (incluindo PII) podem ser excluídos pelo Proprietário do Programa de acordo com seus processos estabelecidos e/ou conforme especificado pela lei aplicável.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a0f3fe44-29d0-492f-80ea-c33dde482f55','pt_MZ','PRIVACY_HEADER_8_SUB_8_DESC_3','Você não tem o direito de solicitar que o Proprietário do Programa exclua seus dados, a menos que tal direito seja reconhecido/fornecido pelo Proprietário do Programa e/ou pela lei relevante.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a30c8f1b-52f5-402a-9666-ce21ae50fe46','pt_MZ','PRIVACY_HEADER_8_SUB_8_DESC_4','Observe que excluir sua conta no site ou aplicativo móvel do Console HCM, ou excluir quaisquer mensagens que você tenha trocado com funcionários ou contratados do Proprietário do Programa por SMS, chatbot, etc., não significa que seus dados (incluindo PII) tenham sido excluídos dos registros do Console HCM/Proprietário do Programa.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bdff900a-9761-4250-81bd-f8fe0fab1806','pt_MZ','PRIVACY_HEADER_9_SUB_9','Seus direitos em relação a estes dados','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bd784444-6062-45d3-a330-5d1270d0cc84','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_1','Você tem os seguintes direitos com relação aos dados (incluindo PII) cobertos por esta Política de Privacidade:','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('89deda1f-0161-44e8-8c35-78159c308a44','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_2','um. Você tem o direito de saber quais dados estão sendo coletados, armazenados, processados, usados ​​e compartilhados. Esta Política de Privacidade forneceu-lhe as informações relevantes.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9c2cb5f-4500-4c39-ad0d-c5e3a602a116','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3','b. Você tem o direito de visualizar seus dados e solicitar a correção dos dados em caso de erros.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9678ff8e-2df0-41e1-8f38-f37e29ba5670','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3_SUBDESC_1','eu. O Proprietário do Programa determinará o procedimento para correção.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b882c0dd-f804-4ff9-a938-c2fee34dadbc','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3_SUBDESC_2','ii. Para acessar essas informações, entre em contato com os dados de contato do proprietário do programa.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('97803580-039e-4bfc-bf8a-35a379cfa735','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_4','c. Tem o direito de saber com quem os seus dados foram/estão a ser partilhados.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5fbb11f9-9a1c-4079-9d92-777d987f18e6','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_4_SUBDESC_1','eu. Para acessar essas informações, entre em contato com os dados de contato do proprietário do programa.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('635ae55a-6598-471a-b478-49666e7b747b','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5','d. Caso seus dados sejam compartilhados com qualquer pessoa ou organização ainda não descrita na seção “Compartilhamento de Dados” desta política, o Proprietário do Programa entrará em contato com você e solicitará seu consentimento para tal compartilhamento.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bca1e099-6c0d-4807-ac3b-99d9c15f480f','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5_SUBDESC_1','ii. Tem o direito de recusar esse consentimento, caso em que os seus dados não poderão ser partilhados com essa pessoa ou organização adicional.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('375a0663-1146-43c2-8767-e11fd958e6fc','pt_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5_SUBDESC_2','ii.Esta disposição pode não se aplicar caso o compartilhamento de seus dados com essa pessoa ou organização adicional seja obrigatório por lei ou por ordem de qualquer tribunal/órgão judicial.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('236bc42d-c28e-4d21-99a3-cbc217150c49','pt_MZ','PRIVACY_POLICY_ACCEPT_TEXT','Aceito','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
