INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b475b596-7d97-4351-9803-ef94188c7e36','fr_MZ','PRIVACY_HEADER_1_SUB_1','Introduction','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('01c7347e-0890-4cb6-96ce-38d33502a9da','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_1','Ceci est la politique de confidentialité de la console HCM','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cf3d8cfe-09de-486c-97ee-74ed1f98f801','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_2','HCM Console est un logiciel qui permet la fourniture de services publics par l''agence gouvernementale ou l''entrepreneur concerné et/ou le paiement de taxes et/ou de frais par vous à une agence gouvernementale. Il est alimenté par la plateforme DIGIT, développée et maintenue par la Fondation eGov.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('881ff853-65ed-49ec-b502-e19a818fa500','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_3','La console HCM a été adoptée dans votre juridiction par le nom de l''agence gouvernementale.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9c2cb0b9-b8bf-48e5-8872-9dfe3ae9512c','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_4','Vous consultez cette politique de confidentialité car vous allez utiliser HCM Console pour accéder à un service public et/ou payer des taxes et/ou des frais à une agence gouvernementale.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d908cee9-a37d-4dd4-af88-fbbd788163e8','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_5','Lorsque vous utilisez HCM Console, vos données, y compris les informations personnelles identifiables (PII), peuvent être collectées, stockées, traitées, utilisées et partagées.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e4e8eaa8-a0cb-48f2-b0cd-da382c502789','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_6','Cette politique de confidentialité décrit la base de cette collecte, stockage, traitement, utilisation et partage de données, et fournit plus de détails sur la manière dont cela sera effectué.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a480082d-5252-423b-b66b-98a9145f1242','fr_MZ','PRIVACY_HEADER_1_SUB_1_DESC_7','Cette politique de confidentialité décrit également vos droits concernant ces données.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8b887ef1-4781-4e56-90d6-776df54d9c31','fr_MZ','PRIVACY_HEADER_2_SUB_2','Définitions','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b182b632-c9c5-4791-86a7-71f19143f5cf','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','Dans cette politique de confidentialité :','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5400189-5ee7-4b8a-a9b1-de7276d4aa40','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','un. « Vous » désigne vous, lecteur de cette politique, et plus largement tout utilisateur de HCM Console.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('04718565-b519-4afe-a5d4-7070502b5e3a','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','b. « Données » ou « vos données » font référence aux données vous concernant qui peuvent être collectées, stockées, traitées, utilisées et/ou partagées lors de votre utilisation de HCM Console.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1be2f7e1-8bf8-4c50-8ff9-e5b3f30308a2','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3_SUBDESC_1','je. Veuillez noter que si vous êtes un employé ou un entrepreneur du gouvernement, votre nom, votre désignation et vos coordonnées officielles (numéro de téléphone, identifiant de messagerie, adresse postale) ne sont pas considérés comme des informations personnelles.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99da9427-cd38-4281-890a-2a98f2c284bf','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3_SUBDESC_2','ii. Votre numéro d’identification nationale ou autre numéro de document d’identité, bien qu’il ne s’agisse pas en lui-même de PII, sera traité comme PII.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67cd7862-3e3a-4a26-a5f4-bafd878d156e','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','c. Les « informations personnellement identifiables » ou « PII » font référence aux données vous concernant qui permettraient aux personnes consultant ces données de vous identifier et/ou de vous contacter, telles que votre nom, le nom de votre parent/tuteur, votre numéro de téléphone personnel, votre identifiant de messagerie personnel, votre adresse postale/résidentielle personnelle, des photographies de vous, des photographies/copies numérisées de vos documents d''identité et des informations biométriques telles que votre empreinte digitale ou votre empreinte rétinienne.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a8e9b179-1758-4320-acf0-cdc4de3c0ada','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','d. « Propriétaire du programme », « Agence gouvernementale » et « Gouvernement concerné » font tous référence à [Nom de l''agence gouvernementale].','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1526aa54-f8c2-4a30-bda0-da369376f388','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_6','d. « Propriétaire du programme », « Agence gouvernementale » et « Gouvernement concerné » font tous référence au nom de l''agence gouvernementale.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('36076653-4f2e-4c35-9316-c444dcd7206b','fr_MZ','PRIVACY_HEADER_3_SUB_3','Base de la collecte, du stockage, du traitement, de l''utilisation et du partage des données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bfd2dbd6-f356-49de-8fc9-8b979891c7b9','fr_MZ','PRIVACY_HEADER_3_SUB_3_DESC_1','politique-de-confidentialité-de-digit','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa3cbe23-abd1-4cfb-b929-3ec33d1982fa','fr_MZ','PRIVACY_HEADER_3_SUB_3_DESC_2','La base de cette collecte, stockage, traitement, utilisation et partage de données est que le propriétaire du programme est une agence gouvernementale et agit conformément à son mandat de fournir des services et/ou de collecter des taxes et/ou des frais auprès de vous. Il s’agit d’un objectif légitime et votre consentement n’est pas requis pour une telle collecte, stockage, traitement, utilisation et partage de données.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3e20a8e2-6e13-40d4-959e-005a3d1c4a84','fr_MZ','PRIVACY_HEADER_4_SUB_4','Collecte de données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('71fc304f-4699-49f3-9bff-955bc1be4223','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1','Lorsque vous accédez aux services via Solution Name, vos données (y compris vos informations personnelles) peuvent être collectées des manières suivantes :','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba199f4a-3cca-4152-8ebf-4a5bc7098fdf','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_1','Vous fournissez ces données via l’utilisation de l’application mobile','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('932df9e3-c402-4b92-946c-f9d59a46b4d1','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_2','Vous fournissez ces données via l''utilisation d''un chatbot Whatsapp','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('edd89dd9-c3a2-47f9-97a7-021468e6fc28','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_3','Vous fournissez ces données via l’utilisation d’une ligne d’assistance téléphonique ou d’un système IVR','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('18fd2e15-2197-4894-af8c-c237047aa73c','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_4','Vous fournissez ces données via l’utilisation d’un site Web gouvernemental','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2c7f61d8-0b78-426a-b25d-afa82b5a740d','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_5','Vous fournissez ces données en personne, dans un centre de services aux citoyens, dans un bureau gouvernemental ou dans un lieu similaire.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1258648c-1df0-480a-ae26-118187fcac91','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_6','Vous fournissez ces données à un vulgarisateur/intermédiaire/bénévole reconnu','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa4958fb-7348-48e6-a980-a8e009412fc9','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_1_SUBDESC_7','La console HCM accède à ces données à partir des enregistrements administratifs existants','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('22552c24-e13c-4989-aca6-c9294f09212c','fr_MZ','PRIVACY_HEADER_4_SUB_4_DESC_2','HCM Console suit par défaut les principes de limitation des finalités et de minimisation des données. Il vous sera demandé de fournir des données (y compris des informations personnelles) uniquement si ces données sont nécessaires au propriétaire du programme pour vous fournir les services que vous demandez et/ou accepter votre paiement de taxes et/ou de frais.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31bb32a2-c193-4c92-b7f6-cfbdc0026f69','fr_MZ','PRIVACY_HEADER_5_SUB_5','Stockage des données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('be2cdd32-58e3-4918-9b72-86fcb23d7622','fr_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1','Par défaut, la console HCM adopte les pratiques suivantes pour garantir que vos informations personnelles sont stockées en toute sécurité :','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ba78910-265d-447d-861d-fd1ffbe9a032','fr_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_1','Stockage numérique sécurisé : la plate-forme DIGIT est conçue avec des paramètres de sécurité par défaut qui offrent une protection robuste. Même si les administrateurs peuvent ajuster ces paramètres pour répondre à des besoins spécifiques, la configuration prête à l''emploi est sécurisée.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e6f14170-a596-49b2-a1ce-a5cc3c06459d','fr_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_2','Chiffrement au repos : le service de chiffrement de la plateforme DIGIT permet le chiffrement de toutes les données sensibles stockées par la console HCM.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b67d82b7-836b-4d78-b63f-ac4ac41fbbaf','fr_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_3','Cryptage en transit : toutes les données sont transmises via HTTPS (TLS Encryption).','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5ec27733-9260-4198-a775-a99cf226825e','fr_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_4','Journaux d''audit signés : toutes les modifications apportées aux données sont enregistrées dans un journal d''audit signé, garantissant la non-répudiabilité – c''est-à-dire qu''il est toujours possible de savoir qui a apporté une modification donnée, et cet utilisateur ne peut pas réfuter qu''il a effectué cette modification.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99cdb30a-d33d-4577-919f-7bf97fb90070','fr_MZ','PRIVACY_HEADER_5_SUB_5_DESC_1_SUBDESC_5','Registre d''utilisateurs : le nom de la solution stocke toutes vos informations personnelles dans un registre unique et sécurisé, appelé registre d''utilisateurs. L''accès au registre des utilisateurs est limité/contrôlé – voir la section « Traitement et utilisation des données » pour plus de détails.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9c222ec9-6cc0-4194-9e10-ab73e9dfc013','fr_MZ','PRIVACY_HEADER_6_SUB_1','Traitement et utilisation des données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('771d1692-55f5-4a28-9dd3-85debdf33939','fr_MZ','PRIVACY_HEADER_6_SUB_6_DESC_1','Lorsque vous accédez aux services du propriétaire du programme, vos données (y compris vos informations personnelles) seront traitées et utilisées pour vous fournir les services que vous demandez et/ou pour collecter et enregistrer les taxes et/ou frais que vous payez.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('88cd0c05-8e83-4e64-b6a6-edf87247f66f','fr_MZ','PRIVACY_HEADER_6_SUB_6_DESC_2','La console HCM suit par défaut les principes du moindre privilège et de la limitation des objectifs. Seules les personnes/utilisateurs qui ont besoin de voir vos données (y compris vos informations personnelles) pour effectuer leur travail y auront accès.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('853b5400-43b2-4444-a466-c2d18de50012','fr_MZ','PRIVACY_HEADER_6_SUB_6_DESC_3','La console HCM garantit que l''accès est limité uniquement à ces utilisateurs en exigeant une authentification et une autorisation (c''est-à-dire que chaque utilisateur doit se connecter et vérifier qui il est) et des contrôles d''accès basés sur les rôles (RBAC), dans lesquels les données auxquelles ils peuvent accéder sont déterminées par leur rôle.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4cfc3e85-2cf1-4bc1-a4c4-78e394a0f246','fr_MZ','PRIVACY_HEADER_6_SUB_6_DESC_4','La Fondation eGov n’encourage pas la création de rôles de « super-utilisateur » avec un large accès, sans objectif spécifique.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e48f02d6-1883-424d-b805-8124289aae52','fr_MZ','PRIVACY_HEADER_7_SUB_1','Partage de données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('59adf0ef-eb53-4b23-aaf0-46b87d67697a','fr_MZ','PRIVACY_HEADER_7_SUB_7_DESC_1','Lorsque vous accédez aux services du propriétaire du programme ou payez des taxes et/ou des frais au propriétaire du programme, vos données (y compris vos informations personnelles) sont collectées, stockées, traitées et utilisées comme décrit ci-dessus.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d03d8a40-4f9b-46bb-8471-627cdcc8a604','fr_MZ','PRIVACY_HEADER_7_SUB_7_DESC_2','Vos données peuvent être partagées avec les entités suivantes, aux fins suivantes :','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('529986d7-c23a-422c-b64c-7e480a426511','fr_MZ','PRIVACY_HEADER_7_SUB_7_DESC_3','La console HCM suit par défaut les principes du moindre privilège et de la limitation des objectifs. Cela signifie que les informations personnelles ne sont jamais utilisées/partagées à des fins d''analyse, ou dans tous les cas où l''objectif du partage de données est atteint par des données agrégées ou dépersonnalisées.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2140f031-dde4-4543-9ec7-06dbf2024d37','fr_MZ','PRIVACY_HEADER_7_SUB_7_DESC_4','Vos données ne seront pas partagées avec des entités autres que celles énumérées ci-dessus, à moins que vous ne consentiez à un tel partage ultérieur, ou à moins que ce partage ne soit rendu obligatoire par la loi ou par l''ordonnance d''un tribunal ou d''un organe judiciaire similaire.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e2485b56-2575-4375-925d-33e0207caabe','fr_MZ','PRIVACY_HEADER_8_SUB_1','Conservation et suppression des données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5ce201c1-e488-4a99-abe9-7063512f3d74','fr_MZ','PRIVACY_HEADER_8_SUB_8_DESC_1','Vos données (y compris vos informations personnelles) seront conservées pendant la période spécifiée par le propriétaire du programme et/ou spécifiée par la loi en vigueur.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('225f5ee2-776e-46e1-aead-46684cb89c89','fr_MZ','PRIVACY_HEADER_8_SUB_8_DESC_2','Vos données (y compris vos informations personnelles) peuvent être supprimées par le propriétaire du programme conformément à leurs processus établis et/ou comme spécifié par la loi en vigueur.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('13f3b8a5-daa4-45e6-a597-b5adb3a114d3','fr_MZ','PRIVACY_HEADER_8_SUB_8_DESC_3','Vous n''avez pas le droit de demander au propriétaire du programme de supprimer vos données, à moins que ce droit ne soit reconnu/accordé par le propriétaire du programme et/ou par la loi applicable.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7f00446-0185-4809-be07-18a676ddbde7','fr_MZ','PRIVACY_HEADER_8_SUB_8_DESC_4','Veuillez noter que la suppression de votre compte sur le site Web ou l''application mobile de la console HCM, ou la suppression de tout message que vous avez échangé avec les employés ou sous-traitants du propriétaire du programme par SMS, chatbot, etc. ne signifie pas que vos données (y compris les informations personnelles) ont été supprimées des enregistrements de la console HCM/du propriétaire du programme.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bd7e4364-c400-4f3f-ae70-3675850683f5','fr_MZ','PRIVACY_HEADER_9_SUB_9','Vos droits concernant ces données','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('157ae1f4-a826-46ac-a734-c7d32265f3bf','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_1','Vous disposez des droits suivants concernant les données (y compris les informations personnelles) couvertes par la présente politique de confidentialité :','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('34b5f9ae-fa5a-4170-ad1b-dc9c8174f05d','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_2','un. Vous avez le droit de savoir quelles données sont collectées, stockées, traitées, utilisées et partagées. Cette politique de confidentialité vous a fourni les informations pertinentes.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4ca39031-0786-47a3-82b0-2681060bae9c','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3','b. Vous avez le droit de consulter vos données et de demander leur correction en cas d''erreurs.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0bc79028-aaf6-4a40-8ef2-ec1b27d92694','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3_SUBDESC_1','je. Le propriétaire du programme déterminera la procédure de correction.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db1d3405-17ed-4e4a-80ba-87fcd06eb484','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_3_SUBDESC_2','ii. Pour accéder à ces informations, veuillez contacter les coordonnées du propriétaire du programme.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2a6165d4-79b1-4dba-81f8-8cea03845432','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_4','c. Vous avez le droit de savoir avec qui vos données ont été/sont partagées.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6cf40e80-d64f-4e03-ac99-500ec2befd0a','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_4_SUBDESC_1','je. Pour accéder à ces informations, veuillez contacter les coordonnées du propriétaire du programme.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1630902d-137f-412d-8d67-493825629e6d','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5','d. Dans le cas où vos données doivent être partagées avec toute personne ou organisation non déjà décrite dans la section « Partage de données » de cette politique, le propriétaire du programme vous contactera et demandera votre consentement pour un tel partage.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bdbc4b69-485b-4f2b-9a58-33d1f9f4a69e','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5_SUBDESC_1','ii. Vous avez le droit de refuser un tel consentement, auquel cas vos données ne peuvent pas être partagées avec cette personne ou organisation supplémentaire.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('75d42675-4b43-4531-808f-cb1d6ad8f5b8','fr_MZ','PRIVACY_HEADER_9_SUB_9_DESC_5_SUBDESC_2','ii.Cette disposition peut ne pas s''appliquer si le partage de vos données avec une telle personne ou organisation supplémentaire est imposé par la loi ou par l''ordonnance d''un tribunal/organe judiciaire.','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c9be3c0a-22bf-4507-8de2-433c00019633','fr_MZ','PRIVACY_POLICY_ACCEPT_TEXT','J''accepte','mz','digit-privacy-policy',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
