INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5915184a-e51d-41f3-80ac-c3337b5fda9a','en_MZ','BPA_EDCR_DETAILS','eDCR Details','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ecf993b3-16ad-488e-a806-d5024d9b7320','en_MZ','BPA_FAQ_ANS_ONE','When an eDCR scrutiny fails, the error information is marked across each line item in the output file. The architect can make the corrections accordingly and resubmit the plan real time. This can be done any number of times without incurring any additional charges.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b2b610db-0af3-45da-ad53-7880f2f7f75a','en_MZ','BPA_FAQ_ANS_THREE','The eDCR scrutiny system compares the parameters in the drawings against the by laws set in the corresponding administrative region and evaluates if they are violating. In the output file, against each paramter that is evaluated, there will be an indication to show if that is approved or rejected. The entire scrutiny process takes ~5 seconds','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('910faab6-a2ba-4f6e-add0-8e7a448c5afd','en_MZ','BPA_FAQ_ANS_TWO','You can renew permits at the counter or through the portal. After logging in, search for the relevant permit application in the portal. Then click on link for the permit that you wish to renew. Next, complete the application for the renewal of permit and click submit.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5e75f09b-b5e3-4a6d-a334-fabecd7fc54e','en_MZ','BPA_FAQ_QUES_ONE','What happens when eDCR scrutiny fails? ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('91c62067-1cdd-42fb-a01b-e613fac949dd','en_MZ','BPA_FAQ_QUES_THREE','How does eDCR Scrutiny works and how much time it takes to get the diagrams scrutinized? ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('98be7876-c5d8-4f25-8755-ca2b9b286804','en_MZ','BPA_FAQ_QUES_TWO','How do I renew my permit? ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
