INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eef92175-fb48-4e09-9ed5-e66c343945fe','en_MZ','CCF_ADHERENCE_TO_DATA_PRINCIPLES_INFO_LABEL','We adhere to the principles of accountability, transparency, purposeful and proportional collection, usage, storage and disclosure of personally identifiable information (“PII”).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
