INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4b7a3665-a81d-4cdb-bcf2-73e2e4a38ec9','en_MZ','CCF_COLLECT_AND_PROGRAM_LABEL','WHAT DATA DO WE COLLECT? / WHAT IS ‘DATA’ UNDER THIS ‘PROGRAM’?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0a688d20-1564-434f-ad12-84f95b602143','en_MZ','CCF_COLLECT_INFO_ADMINISTRATIVE_LABEL','Data from administrative record systems, such as revenue survey number or other property identifier, connection number, meter number etc. may also be recorded. In the event a person makes payments to the local government, information related to the payment, such as transaction number may also be recorded.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('83e8000e-7ded-42ce-87bd-294090093cb3','en_MZ','CCF_COLLECT_INFO_IMPROVE_LABEL','We collect information/data (“data”) to improve and provide better services to you. We collect and process PII such as your first name, last name, parent’s / guardian’s name, address, email address, telephone number, age, gender, identification documents. We may collect your educational, demographic, location, device and other similar information.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5449ca76-0f27-480d-b392-30066dc3e345','en_MZ','CCF_COLLECT_IP_ADDRESS_LABEL','We collect information such as Internet Protocol (IP) addresses, domain name, browser type, Operating System, Date and Time of the visit, pages visited, IMEI/IMSI number, device ID, location information, language settings, handset make & model etc. However, no attempt is made to link these with the true identity of individuals visiting Urban DIGIT app, website, Whatsapp Chatbot etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa01ca9c-d3e2-4919-b13d-02d0de9734c6','en_MZ','CCF_COLLECT_IP_SERVICES_USED_LABEL','The information collected by us shall depend on the services being used by you and may vary from time to time, which will be informed through changes in this policy.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1f4021f0-b4fe-49bf-b7fd-3708667b3cee','en_MZ','CCF_COLLECT_THIS_DATA_INFO_LABEL','We collect data directly from you (when you use our services) as and when you register and login into the app/website. We may also collect data from Union, State, and Local governments, including their agents/employees, as well as receive data that is available openly for public use.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('064a5fff-b786-493e-9631-02143ff44121','en_MZ','CCF_COLLECT_THIS_DATA_LABEL','HOW DO WE COLLECT THIS DATA?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
