INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ea346885-5c0e-49f2-8c2d-957790a8ec88','en_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_1_1_LABEL','Data from administrative record systems, such as revenue survey number or other property identifier, connection number, meter number etc. may also be recorded. In the event a person makes payments to the local government, information related to the payment, such as transaction number may also be recorded.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('affa9312-7a2b-4cb2-968d-75fc610475dd','en_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_1_LABEL','We collect information/data (“data”) to improve and provide better services to you. We collect and process PII such as your first name, last name, parent’s / guardian’s name, address, email address, telephone number, age, gender, identification documents. We may collect your educational, demographic, location, device and other similar information.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f7eb9063-fc70-494c-8a2e-5c85bbe598df','en_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_2_LABEL','We collect information such as Internet Protocol (IP) addresses, domain name, browser type, Operating System, Date and Time of the visit, pages visited, IMEI/IMSI number, device ID, location information, language settings, handset make & model etc. However, no attempt is made to link these with the true identity of individuals visiting PROGRAM NAME app, website, Whatsapp Chatbot etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('36b058ed-a136-4f5e-8186-a73bb0f737da','en_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_3_LABEL','The information collected by us shall depend on the services being used by you and may vary from time to time, which will be informed through changes in this policy.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
