INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9e8cbc72-ab06-41ca-b3be-70794cdd6688','en_MZ','CCF_PP_DD_DEAL_LABEL','PROGRAM NAME refers to the services being provided through PROGRAM NAME  website, mobile App, OTHER CHANNELS AS RELEVANT.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('984a1847-5730-450a-a083-0a73d05a03ef','en_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_INFO_LABEL','We collect data directly from you (when you use our services) as and when you register and login into the app/website. We may also collect data from Union, State, and Local governments, including their agents/employees, as well as receive data that is available openly for public use.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e954d159-5451-440e-b453-fc31a2be2045','en_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_LABEL','HOW DO WE COLLECT THIS DATA?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b2239aeb-b4b6-4a60-bdbb-081be96d4c2a','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_1_LABEL','Unless indicated otherwise, this data will be retained for a minimum period of AS PER UNION / STATE / ULB LAWS and a maximum period of AS PER UNION / STATE / ULB LAWS. You can review and edit your data, as well as delete your data from the app/website by following the procedures AS PER UNION / STATE / ULB LAWS.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('50006a1a-b27d-44e0-804d-8ebcccde2495','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_LABEL','Your data is stored in a secure manner. PROGRAM NAME is powered by the DIGIT platform, which has embedded privacy settings (such as encryption), which does not allow your data to be visible to anyone, except persons who are authorised to do so by virtue of their official role. ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ef04e0af-12dd-44a7-aa51-05d3ea4ea820','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_2_LABEL','You may delete your account any time you wish. In case of deletion, we will remove all your PII  from the system, so that it is not visible and/or accessible from any regular operation. However, the PII may be retained in an encrypted manner for the purpose of legal requirements/compliances AS PER UNION / STATE / ULB LAWS from the date of deletion/termination.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('be6167c9-82d2-46d3-bb5c-f80aba5fd1bf','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_3_LABEL','After deletion, in case you wish to recreate your profile, the same is permissible and none of the previously captured information will be populated automatically. You need to register as a fresh user.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('09c3c0a1-fc0b-457f-9efa-cfb2c0c759bf','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_4_LABEL','If you simply delete/remove the application from your mobile device but do not delete your profile or unregister yourself from the app/website, you shall continue to be a registered user of the app and we shall continue to send you all communications that you have opted for unless and until you opt-out of such communications, or AS PER UNION / STATE / ULB LAW.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f2d1de8c-8f7b-4ba8-b2ee-4c93d4dc5d31','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_5_LABEL','In case you surrender/disconnect your PROGRAM NAME registered mobile number it is recommended to delete your profile or unregister yourself from the application also.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1de125bc-73c6-4a07-a583-58fc088c4c38','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_6_LABEL',' We have data security measures adopted to ensure that users data is safe and away from dangers of cyber/physical harms. More about the data security measures can be read ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('94a84a92-e909-4301-a9a3-3276c16e980e','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LABEL','HOW DO WE STORE THIS DATA?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('261c01a1-276f-4207-ad8e-40b29f39742c','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LINK_HERE_LABEL',' here. ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2db38015-5efb-410f-99ba-0eb5ef6bc7e9','en_MZ','CCF_PP_GRIEVANCES_INFO_LABEL','In case of any grievances, you may send your complaints for redressal over Grievance Portal available at ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('436c86f5-6bf5-4750-98b7-9e39719d5956','en_MZ','CCF_PP_GRIEVANCES_INFO_LINK_LABEL','Link','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ae3c85f7-35c8-479b-bff9-da8b1faec0c0','en_MZ','CCF_PP_GRIEVANCES_LABEL','GRIEVANCES','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9cd33035-09a9-40f6-8e75-6d5e1a65a7ee','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_10_LABEL','Payments made through the PROGRAM NAME App/website are processed via secure payment gateways.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('daae5876-d5ce-45b6-bd20-5769aa8a1106','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_11_LABEL','We will not process, disclose, or share your data except as described in this policy, or as otherwise authorized by you.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99be8450-24cb-483f-93c3-874d15b4fa4b','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_1_LABEL','We use this data to serve you with the best civic experience, such as providing digital grievance redressal systems, efficient service delivery, creating dashboards of ULB activities, etc. Data is only processed on the basis of a legal mandate and for a legitimate and necessary purpose (to deliver to you the services you are requesting, and to make improvements in service delivery and administration, as well as any other purposes specified by law).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('41973b5a-0073-4b8e-bfd8-76a9053c97c0','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_2_LABEL','We process data which is necessary to provide you with the services you are requesting','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eaf40ca6-1714-4d56-9b09-d88293421917','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_3_LABEL','We may process, disclose, or share certain metadata, as well as aggregated and anonymised data, in order to assess and improve the status of such service delivery over time.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('11936e0e-fc87-4fc2-8bc1-c2d384fb45e2','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_4_LABEL','We may disclose or share this data to/with employees and/or contractors of the urban local body, state government, or other government agencies, service providers, whose role requires them to view or use this information in order to perform their official duties, including providing you the service(s) you are requesting.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ea31359-534b-4672-b6d1-9e073c3e8f2f','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_5_LABEL','Data processed or shared while resolving any disputes that may arise with respect to the transactions/deals that you may conduct using the app/website.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('360994dd-327a-43f0-806e-6865944e4409','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_6_LABEL','Data processed or shared for monitoring user activity and preferences as evidence from user’s activity on app to provide a better experience in future.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8fffd617-7a96-4ccb-80a2-c526d704755a','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_7_LABEL','Detecting, investigating and preventing activities that may violate our policies or that may be illegal or unlawful.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f59592e8-e738-48ba-826d-f7e2336b0031','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_8_LABEL','Conducting research or analysing of the user preferences and demographics as statistical-masked data and not as individual data.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('02614427-949b-49fb-b2b0-23f949fd12b7','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_9_LABEL','We may disclose or share this data in order to comply with the law or any legal process, including when required in judicial, arbitral, or administrative proceedings.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e4d0a2ec-9b32-4a60-bea5-c2b69e4ad611','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_LABEL','WHY AND HOW DO WE PROCESS, DISCLOSE, AND/OR SHARE THIS DATA?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06968d20-d4d5-473b-9b1d-d307aa3039c5','en_MZ','CCF_PP_HOW_DO_WE_PROTECT_INFO_LABEL','By default, PII is maintained in a masked format. Persons with the appropriate authorisation can put in a request for this data to be unmasked. We log each such request, thus creating a non-repudiable and auditable trail of each such access to PII.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6c3feadb-638a-486a-b1b1-b66f19ee6e5a','en_MZ','CCF_PP_HOW_DO_WE_PROTECT_LABEL','HOW DO WE PROTECT PERSONALLY IDENTIFIABLE INFORMATION (PII)?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b912e183-5b02-40a4-bebc-4bb396023c2d','en_MZ','CCF_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME is a collaboration between PARTNER(S) NAME(S) and eGovernments Foundation. It is powered by DIGIT, which is an open-source software platform developed by eGovernments Foundation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('88950bdc-2c85-4fd5-a59d-2a9bf7294860','en_MZ','CCF_PP_PRIVANCY_SECURITY_LABEL','[PROGRAM NAME] (“we” or “us” or “our”) respects the privacy of our users (“user” or “you” also referred to as ‘your’). Hence, we maintain the highest standards for secure activities , user information/data privacy and security.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('174c55dd-78a5-48b2-8506-32cf50832371','en_MZ','CCF_PP_REFERS_LABEL','Through PROGRAM NAME, you can access and avail services offered by STATE OR ULB NAME Government departments, Central Government department, Local bodies & their agencies and corporate/private bodies (utility services) (Service Providers). You can use PROGRAM NAME website / application / services in different ways such as, service discovery, availing services, registering grievances, and so on.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f338e1a6-1deb-485e-a895-4d4369778455','en_MZ','CCF_PRIVACYPOLICY_HEADER','Privacy Policy','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d0c0e377-4a2f-48cd-94c4-44526ad23e1e','en_MZ','CCF_PRIVACY_PLOICY_DESCRIBES_LABEL','This Privacy Policy describes and determines how we deal with your personal and usage information in accordance with the applicable laws of India.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c1c34536-b88d-4305-886f-e4e99661d37a','en_MZ','CCF_PRIVACY_POLICY_',' Privacy Policy','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('83f42958-201c-4351-93b6-c8eb8f1b1cab','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_CONDUCTING_LABEL','Conducting research or analysing of the user preferences and demographics as statistical-masked data and not as individual data.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f1ff5572-dea3-4c4d-a17d-a38667c9bfb9','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_DETECTING_LABEL','Detecting, investigating and preventing activities that may violate our policies or that may be illegal or unlawful.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8afbe012-a285-41b6-86e0-2964b643b05d','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_EMPLOYEES_LABEL','We may disclose or share this data to/with employees and/or contractors of the urban local body, state government, or other government agencies, service providers, whose role requires them to view or use this information in order to perform their official duties, including providing you the service(s) you are requesting. ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d0f907af-ecb3-46f7-a413-f422c95a69a4','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_INFO_LABEL','We use this data to serve you with the best civic experience, such as providing digital grievance redressal systems, efficient service delivery, creating dashboards of ULB activities, etc. Data is only processed on the basis of a legal mandate and for a legitimate and necessary purpose (to deliver to you the services you are requesting, and to make improvements in service delivery and administration, as well as any other purposes specified by law).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d5f61751-363f-4059-8d97-9cd1a3c6fe8f','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_LABEL','WHY AND HOW DO WE PROCESS, DISCLOSE, AND/OR SHARE THIS DATA?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3511e511-423e-45a7-a7de-adac4ce197c8','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_METADATA_LABEL','We may process, disclose, or share certain metadata, as well as aggregated and anonymised data, in order to assess and improve the status of such service delivery over time.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('62ff7a2e-1c22-4824-9a4b-d295e3a8841b','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_MONITIRING_LABEL','Data processed or shared for monitoring user activity and preferences as evidence from user’s activity on app to provide a better experience in future.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bc77a2e9-2a3b-4c28-976a-eadd95a717c3','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_NOT_SHARE_LABEL','We will not process, disclose, or share your data except as described in this policy, or as otherwise authorized by you.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c2153305-8d92-403e-adfb-aadc48c81665','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_ORDER_TO_COMPLY_LABEL','We may disclose or share this data in order to comply with the law or any legal process, including when required in judicial, arbitral, or administrative proceedings.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bb79c710-6bfc-4d7b-ac8b-8b5d2d628ae1','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_PAYMENTS_LABEL','Payments made through the Urban DIGIT App/website are processed via secure payment gateways.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('af93bd37-6b6c-45c2-b215-9cc803e404cf','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_PROVIDE_SERVICES_LABEL','We process data which is necessary to provide you with the services you are requesting','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1afb64b2-ad2e-4f39-abee-ac48724e9243','en_MZ','CCF_PROCESS_DISCLOSE_SHARE_RESOLVING_LABEL','Data processed or shared while resolving any disputes that may arise with respect to the transactions/deals that you may conduct using the app/website.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('02b3beaa-3b3c-4338-9184-e18f9a599391','en_MZ','CCF_PROTECT_PERSONALLY_INFO_LABEL','By default, PII is maintained in a masked format. Persons with the appropriate authorisation can put in a request for this data to be unmasked. We log each such request, thus creating a non-repudiable and auditable trail of each such access to PII.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2be386bb-0603-42b9-b1b7-64afb67db74f','en_MZ','CCF_PROTECT_PERSONALLY_LABEL','HOW DO WE PROTECT PERSONALLY IDENTIFIABLE INFORMATION (PII)?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6c70a5ce-587d-4df7-8781-4782546016f2','en_MZ','CCF_RESPECT_PRIVACY_OF_USERS_LABEL','We respect the privacy of our users. Hence, we maintain the highest standards for secure activities , user information/data privacy and security.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('baab9497-7404-4fef-a8e8-7fb405841370','en_MZ','CCF_STORE_DELETE_YOUR_ACCOUNT_LABEL','You may delete your account any time you wish. In case of deletion, we will remove all your PII  from the system, so that it is not visible and/or accessible from any regular operation. However, the PII may be retained in an encrypted manner for the purpose of legal requirements/compliances {AS PER UNION / STATE / ULB LAWS} from the date of deletion/termination.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('af93100b-6e34-4239-9361-a18d5fcb3992','en_MZ','CCF_STORE_DISCONNECT_LABEL','In case you surrender/disconnect your registered mobile number it is recommended to delete your profile or unregister yourself from the application also.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('663da50e-a123-4303-9992-8db11393a873','en_MZ','CCF_STORE_RECREATE_PROFILE_LABEL','After deletion, in case you wish to recreate your profile, the same is permissible and none of the previously captured information will be populated automatically. You need to register as a fresh user.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92119841-470d-4ace-b431-b7dcfe3d5940','en_MZ','CCF_STORE_REVIEW_EDIT_LABEL','You can review and edit your data, as well as delete your data from the app/website by following the procedures {AS PER UNION / STATE / ULB LAWS}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3913621b-c7e0-4b7c-a7fb-d9f3353a1419','en_MZ','CCF_STORE_SECURE_MANNER_LABEL','Your data is stored in a secure manner. DIGIT platform, which has embedded privacy settings (such as encryption), which does not allow your data to be visible to anyone, except persons who are authorized to do so by virtue of their official role. Unless indicated otherwise, this data will be retained for a minimum period of {AS PER UNION / STATE / ULB LAWS} and a maximum period of {AS PER UNION / STATE / ULB LAWS}. ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('424018ed-06f0-4cec-b1fa-726475748d04','en_MZ','CCF_STORE_SECURITY_MEASURES_LABEL','We have data security measures adopted to ensure that users data is safe and away from dangers of cyber/physical harms. ','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1c5c9f11-3aaa-4206-bb7a-4f87eb7c87e8','en_MZ','CCF_STORE_THIS_DATA_LABEL','HOW DO WE STORE THIS DATA?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('21d33d24-9045-4339-adc1-4ce94932b7cf','en_MZ','CCF_STORE_UNREGISTER_LABEL','If you simply delete/remove the application from your mobile device but do not delete your profile or unregister yourself from the app/website, you shall continue to be a registered user of the app and we shall continue to send you all communications that you have opted for unless and until you opt-out of such communications, or {AS PER UNION / STATE / ULB LAW}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0d11d366-a9e5-4be6-ad11-7915fa9da2dc','en_MZ','CCF_TERM_OF_USE_',' Terms Of Use','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
