INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fab6a0fe-f05c-4285-bc2f-e56d5ff3e043','en_MZ','CITIZEN_CONSENT_FORM_PP_ACCESS_AVAIL_LABEL','Through PROGRAM NAME, you can access and avail services offered by STATE OR ULB NAME Government departments, Central Government department, Local bodies & their agencies and corporate/private bodies (utility services) (Service Providers). You can use PROGRAM NAME website / application / services in different ways such as, service discovery, availing services, registering grievances, and so on.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3d38c25e-9982-4d3c-938d-b8f789ac317d','en_MZ','CITIZEN_CONSENT_FORM_PP_DD_DEAL_LABEL','This Privacy Policy describes and determines how we deal with your personal and usage information in accordance with the applicable laws of India.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('da20ac1d-df64-4236-a949-98878d43a8d0','en_MZ','CITIZEN_CONSENT_FORM_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME is a collaboration between PARTNER(S) NAME(S) and eGovernments Foundation. It is powered by DIGIT, which is an open-source software platform developed by eGovernments Foundation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
