INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('306bb1ed-d260-4075-9d5b-e0d091296897','en_MZ','PRIVACY_HEADER_2_SUB_1_DESC_1','You have added a column or field with the characteristic name to the shapefiles that you want to load shapes for. If using compounding characteristics, you have added multiple columns. More Information: Preparing Shapefiles','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f25e973-1161-4eb2-8670-1308132ee369','en_MZ','PRIVACY_HEADER_2_SUB_1_DESC_2','To update the geotable with shapes that are uploaded to the Business Document Server, you need SAP HANA 2.0 Rev 45','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('02f4bfbe-81de-4fce-b4fe-4a4a3ba3a1a0','en_MZ','PRIVACY_HEADER_2_SUB_2','Procedure','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92dfa58b-c289-4c1f-b072-9c13e3710e7b','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','1. You are on the BI Clients tab in the characteristic editing screen in the BW modeling tools. You have chosen Shapes or Shapes and Point Data as the geographical type.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7afdcadf-05f7-4e31-9187-93f882e698f3','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','2. Choose Upload Shapefiles under Actions. Choose Go. The BW/4 back end opens.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b44514cd-dd6e-418f-9e1b-444474ab453e','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','3. Select your shapefiles. You need the following three shapefiles: .dbf, . shp, .shx. The shapefiles must be in the Spatial Reference ID 4326 and should all have the same name before the ending.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('606882c0-e69f-4b55-8fed-2066b95a3407','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','4. Choose Update Geotable under Actions. Choose Go. You can choose either Delta Update or Full Update.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b4b58915-febf-41d3-a9ed-64b8c63c1900','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','5. The uploaded shapes are transformed and stored in SRID (Spatial Reference ID) 3857.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4172b0bc-3ec3-4032-9650-dff1bc509742','en_MZ','SETTINGS','Settings','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
