INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f9b8e7f-a110-47f6-a342-b70f676bb407','pt_MZ','BPA_FAQ_ANS_ONE','Quando uma verificação do eDCR falha, as informações do erro são marcadas em cada item de linha no arquivo de saída. O arquiteto pode fazer as correções necessárias e reenviar o plano em tempo real. Isso pode ser feito inúmeras vezes sem incorrer em custos adicionais.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('559911b5-7552-4bd3-87c9-c049d2de1874','pt_MZ','BPA_FAQ_ANS_THREE','O sistema de fiscalização do eDCR compara os parâmetros dos sorteios com os estatutos estabelecidos na região administrativa correspondente e avalia se estão em violação. No arquivo de saída, contra cada parâmetro avaliado, haverá uma indicação para mostrar se foi aprovado ou rejeitado. Todo o processo de verificação leva cerca de 5 segundos','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ea65d84-f107-4f5e-8c00-317288975dc4','pt_MZ','BPA_FAQ_ANS_TWO','Você pode renovar as licenças no balcão ou através do portal. Após fazer login, pesquise o pedido de licença relevante no portal. Em seguida, clique no link da licença que deseja renovar. Em seguida, preencha o pedido de renovação da licença e clique em enviar.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('192c4ff8-be0b-4c0f-9df3-c3af2dc13e46','pt_MZ','BPA_FAQ_QUES_ONE','O que acontece quando o escrutínio do eDCR falha?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fe3dc806-99c7-4e53-948b-9f32fc3e98fc','pt_MZ','BPA_FAQ_QUES_THREE','Como funciona o eDCR Scrutiny e quanto tempo leva para que os diagramas sejam examinados?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
