INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6392cafc-a538-43b2-a414-744b90a5eb44','pt_MZ','CCF_ADHERENCE_TO_DATA_PRINCIPLES_INFO_LABEL','Aderimos aos princípios de responsabilidade, transparência, coleta, uso, armazenamento e divulgação proposital e proporcional de informações de identificação pessoal (“PII”).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
