INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ff028067-d6f7-4be5-a819-515309586c89','pt_MZ','CCF_COLLECT_AND_PROGRAM_LABEL','QUE DADOS COLETAMOS? / O QUE SÃO ‘DADOS’ NESTE ‘PROGRAMA’?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('90e752ef-13ad-4950-a06b-42d469aa350e','pt_MZ','CCF_COLLECT_INFO_ADMINISTRATIVE_LABEL','Dados de sistemas de registro administrativo, como número de pesquisa de receitas ou outro identificador de propriedade, número de conexão, número de medidor, etc., também podem ser registrados. Caso uma pessoa efetue pagamentos ao governo local, também poderão ser registradas informações relacionadas ao pagamento, como o número da transação.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3414c32d-8636-4abc-9ef9-cd39143cad2e','pt_MZ','CCF_COLLECT_INFO_IMPROVE_LABEL','Coletamos informações/dados (“dados”) para melhorar e fornecer melhores serviços a você. Coletamos e processamos IPI, como seu nome, sobrenome, nome dos pais/responsáveis, endereço, endereço de e-mail, número de telefone, idade, sexo, documentos de identificação. Poderemos coletar suas informações educacionais, demográficas, de localização, de dispositivo e outras informações semelhantes.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('23276bdf-e9f6-4897-9aa5-67ae44c63e4f','pt_MZ','CCF_COLLECT_IP_ADDRESS_LABEL','Coletamos informações como endereços de protocolo de Internet (IP), nome de domínio, tipo de navegador, sistema operacional, data e hora da visita, páginas visitadas, número IMEI/IMSI, ID do dispositivo, informações de localização, configurações de idioma, marca e modelo do aparelho, etc. No entanto, nenhuma tentativa é feita para vinculá-los à verdadeira identidade dos indivíduos que visitam o aplicativo Urban DIGIT, site, Whatsapp Chatbot etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a1a51c67-dd06-4cec-a2dc-2fa0728dda47','pt_MZ','CCF_COLLECT_IP_SERVICES_USED_LABEL','As informações coletadas por nós dependerão dos serviços que você utiliza e podem variar de tempos em tempos, o que será informado por meio de alterações nesta política.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9a0d590-7eba-4185-bc55-a18766353855','pt_MZ','CCF_COLLECT_THIS_DATA_INFO_LABEL','Coletamos dados diretamente de você (quando você usa nossos serviços) conforme e quando você se registra e faz login no aplicativo/site. Também poderemos coletar dados de governos da União, Estaduais e Locais, incluindo seus agentes/funcionários, bem como receber dados que estejam disponíveis abertamente para uso público.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa9a97a2-91b3-42c3-a06a-82b9e98b2223','pt_MZ','CCF_COLLECT_THIS_DATA_LABEL','COMO COLETAMOS ESSES DADOS?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8ed5c7fe-4501-4b32-a60a-fa45b2ce2240','pt_MZ','CCF_DATA_COLLECTION_SHARING_INFO_LABEL','Ao utilizar este serviço, você confirma que leu, compreendeu e aceitou esta Política, e que podemos coletar, processar, divulgar e/ou compartilhar seus dados conforme descrito nesta Política.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ded9e913-4f6a-4f2e-a4e7-e44e239b1410','pt_MZ','CCF_DATA_COLLECTION_SHARING_LABEL','SEU CONSENTIMENTO PARA COLETA, PROCESSAMENTO, DIVULGAÇÃO E/OU COMPARTILHAMENTO DE DADOS.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('98431b22-3f20-4357-95a1-f9b79a1a5a70','pt_MZ','CCF_I_AGREE_THE_DIGITS_','Eu concordo com os DÍGITOS','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8f3895d5-bf4b-498a-80eb-771f46da7aa3','pt_MZ','CCF_POLICY_BE_CHANGED_INFO_LABEL','Sim, esta política está sujeita a alterações a qualquer momento e sem aviso prévio. Esta página será atualizada com qualquer política modificada e tais alterações não serão consideradas em vigor até e a menos que sejam mostradas nesta página.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
