INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f6a14210-210a-4daf-ab06-432dd435438d','pt_MZ','CCF_PP_DATA_COLLECTION_PROCESSING_LABEL','SEU CONSENTIMENTO PARA COLETA, PROCESSAMENTO, DIVULGAÇÃO E/OU COMPARTILHAMENTO DE DADOS.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('65a9a9f0-a167-4a92-a8b4-ac958e2a0701','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_1_1_LABEL','Dados de sistemas de registro administrativo, como número de pesquisa de receitas ou outro identificador de propriedade, número de conexão, número de medidor, etc., também podem ser registrados. Caso uma pessoa efetue pagamentos ao governo local, também poderão ser registradas informações relacionadas ao pagamento, como o número da transação.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('97b7c564-4f5b-4dbb-b865-75aaab7e2c0f','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_1_LABEL','Coletamos informações/dados (“dados”) para melhorar e fornecer melhores serviços a você. Coletamos e processamos IPI, como seu nome, sobrenome, nome dos pais/responsáveis, endereço, endereço de e-mail, número de telefone, idade, sexo, documentos de identificação. Poderemos coletar suas informações educacionais, demográficas, de localização, de dispositivo e outras informações semelhantes.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('32e78b76-d5e2-406c-b295-e43fb0c00786','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_2_LABEL','Coletamos informações como endereços de protocolo de Internet (IP), nome de domínio, tipo de navegador, sistema operacional, data e hora da visita, páginas visitadas, número IMEI/IMSI, ID do dispositivo, informações de localização, configurações de idioma, marca e modelo do aparelho, etc. No entanto, nenhuma tentativa é feita para vinculá-los à verdadeira identidade dos indivíduos que visitam o aplicativo PROGRAM NAME, site, Whatsapp Chatbot etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8114f699-1ef2-46c7-8eb3-5058a0a85d13','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_3_LABEL','As informações coletadas por nós dependerão dos serviços que você utiliza e podem variar de tempos em tempos, o que será informado por meio de alterações nesta política.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('56e15ec2-7c56-401f-830f-61d1c5ddc6f3','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_INFO_4_LABEL','Para obter mais informações sobre as categorias de dados que coletamos e a estrutura de consentimento, consulte nosso','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('349a9dda-ba82-4813-9569-62d68449b57b','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_LABEL','QUE DADOS COLETAMOS? / O QUE SÃO ‘DADOS’ NESTE ‘PROGRAMA’?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5704c9ba-8d42-4aeb-bec0-a31327b7b388','pt_MZ','CCF_PP_DATA_DO_WE_COLLECT_PP_LINK_LABEL','política de privacidade detalhada.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('56ef2b96-004c-45ea-b301-ea1b3388c3ec','pt_MZ','CCF_PP_DD_DEAL_LABEL','NOME DO PROGRAMA refere-se aos serviços fornecidos através do site NOME DO PROGRAMA, aplicativo móvel e OUTROS CANAIS RELEVANTES.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8c0e7cac-3fe1-42b9-9812-55367d5ade17','pt_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_INFO_LABEL','Coletamos dados diretamente de você (quando você usa nossos serviços) conforme e quando você se registra e faz login no aplicativo/site. Também poderemos coletar dados de governos da União, Estaduais e Locais, incluindo seus agentes/funcionários, bem como receber dados que estejam disponíveis abertamente para uso público.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca234863-07f0-4a96-9290-f5ce96410d11','pt_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_LABEL','COMO COLETAMOS ESSES DADOS?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c902840d-a941-4c65-aed6-cd4f5aa9e457','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_1_LABEL','Salvo indicação em contrário, estes dados serão retidos por um período mínimo de acordo com as LEIS DA UNIÃO/ESTADO/ULB e um período máximo de acordo com as LEIS DA UNIÃO/ESTADO/ULB. Você pode revisar e editar seus dados, bem como excluí-los do aplicativo/site seguindo os procedimentos CONFORME AS LEIS DA UNIÃO/ESTADO/ULB.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('59467f23-e61d-4140-9e36-196f9c407f45','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_LABEL','Seus dados são armazenados de forma segura. O NOME DO PROGRAMA é alimentado pela plataforma DIGIT, que possui configurações de privacidade incorporadas (como criptografia), que não permitem que seus dados fiquem visíveis para ninguém, exceto pessoas autorizadas a fazê-lo em virtude de sua função oficial.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('75507bf7-3a9b-4471-9e3f-31b0fd650031','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_2_LABEL','Você pode excluir sua conta a qualquer momento que desejar. Em caso de exclusão, removeremos todas as suas IPI do sistema, para que não fiquem visíveis e/ou acessíveis em qualquer operação regular. No entanto, as PII podem ser retidas de maneira criptografada para fins de requisitos/conformidades legais CONFORME AS LEIS DA UNIÃO/ESTADO/ULB a partir da data de exclusão/rescisão.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('25fd7cbe-27f8-4469-9da0-6e42e6003cbb','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_3_LABEL','Após a exclusão, caso você queira recriar seu perfil, o mesmo é permitido e nenhuma das informações capturadas anteriormente será preenchida automaticamente. Você precisa se registrar como um novo usuário.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('beabe8d4-8329-4ba3-8594-a50b25d07c5a','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_4_LABEL','Se você simplesmente excluir/remover o aplicativo do seu dispositivo móvel, mas não excluir seu perfil ou cancelar o registro no aplicativo/site, você continuará sendo um usuário registrado do aplicativo e continuaremos a enviar-lhe todas as comunicações pelas quais você optou, a menos e até que você desista de tais comunicações, ou CONFORME LEI DA UNIÃO/ESTADO/ULB.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7f27185d-ee02-4dc6-8e1b-d4732a3054aa','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_5_LABEL','Caso você entregue/desconecte seu número de celular cadastrado no NOME DO PROGRAMA, é recomendável excluir seu perfil ou cancelar também seu registro no aplicativo.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c2204d3f-6c1a-4147-87cb-1ebf36ce632c','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_6_LABEL','Adotamos medidas de segurança de dados para garantir que os dados dos usuários estejam seguros e longe de perigos de danos cibernéticos/físicos. Mais sobre as medidas de segurança de dados pode ser lido','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3b960225-84d3-4725-b358-5862c74b9946','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LABEL','COMO ARMAZENAMOS ESSES DADOS?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('325cbb86-3170-4303-92f9-56585106ead0','pt_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LINK_HERE_LABEL','aqui.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a21c0cad-6f67-462e-b6e4-32a6f18deb64','pt_MZ','CCF_PP_GRIEVANCES_INFO_LABEL','Em caso de qualquer reclamação, você poderá enviar suas reclamações para reparação através do Portal de Reclamações disponível em','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c1605c79-6334-49ef-af96-68427eab0b3b','pt_MZ','CCF_PP_GRIEVANCES_INFO_LINK_LABEL','Link','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('be5607c5-c1f8-4ca9-b5fa-6066a52d6c5e','pt_MZ','CCF_PP_GRIEVANCES_LABEL','QUEIXAS','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba0f7698-0578-4178-9417-6abd875c0c1b','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_10_LABEL','Os pagamentos feitos por meio do aplicativo/site PROGRAM NAME são processados ​​por meio de gateways de pagamento seguros.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7991f76-af45-427f-aa01-04a03fd3b828','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_11_LABEL','Não processaremos, divulgaremos ou compartilharemos seus dados, exceto conforme descrito nesta política ou conforme autorizado por você.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c482640f-5c71-4839-89a3-73916da6a72a','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_1_LABEL','Usamos esses dados para lhe oferecer a melhor experiência cívica, como fornecer sistemas digitais de reparação de reclamações, prestação eficiente de serviços, criação de painéis de atividades ULB, etc. Os dados são processados ​​apenas com base em um mandato legal e para uma finalidade legítima e necessária (para fornecer a você os serviços que você está solicitando e para fazer melhorias na prestação e administração de serviços, bem como quaisquer outros fins especificados por lei).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e0f9bca5-3a42-4079-9d9c-cca5bcb9fe7e','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_2_LABEL','Processamos dados necessários para lhe fornecer os serviços que você está solicitando','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eb87f4bd-1c4c-478a-8948-0fd24706f90a','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_3_LABEL','Poderemos processar, divulgar ou partilhar determinados metadados, bem como dados agregados e anonimizados, a fim de avaliar e melhorar o estado dessa prestação de serviços ao longo do tempo.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6c0ba806-de0d-40ff-a674-7e0f11180358','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_4_LABEL','Poderemos divulgar ou compartilhar esses dados com/com funcionários e/ou contratados do órgão urbano local, governo estadual ou outras agências governamentais, prestadores de serviços, cuja função exija que eles visualizem ou usem essas informações para desempenhar suas funções oficiais, incluindo fornecer a você o(s) serviço(s) que você está solicitando.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('227032ed-425a-45d5-826a-172f0b7aa0e1','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_5_LABEL','Dados processados ​​ou compartilhados durante a resolução de quaisquer disputas que possam surgir em relação às transações/negócios que você pode realizar usando o aplicativo/site.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c45dd22b-6add-4af0-afad-cd8a9f9e0753','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_6_LABEL','Dados processados ​​ou compartilhados para monitorar a atividade e preferências do usuário como evidência da atividade do usuário no aplicativo para fornecer uma experiência melhor no futuro.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2c187e1e-7933-42fa-bdd9-b0e0601e747e','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_7_LABEL','Detectar, investigar e prevenir atividades que possam violar nossas políticas ou que possam ser ilegais ou ilícitas.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('28c3ad1d-7df2-4ad0-8e85-375ee1635337','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_8_LABEL','Realizar pesquisas ou analisar as preferências e dados demográficos do usuário como dados estatísticos mascarados e não como dados individuais.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('49d38fae-d26b-4fe8-8ba1-ccde5bebaa42','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_9_LABEL','Poderemos divulgar ou compartilhar esses dados para cumprir a lei ou qualquer processo legal, inclusive quando exigido em processos judiciais, arbitrais ou administrativos.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5adcafea-4ff8-44d2-a377-2da43007e9b3','pt_MZ','CCF_PP_HOW_DO_WE_PROCESS_LABEL','POR QUE E COMO PROCESSAMOS, DIVULGAMOS E/OU COMPARTILHAMOS ESSES DADOS?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c6587c0a-fea5-46a6-aa96-e9e77aa74852','pt_MZ','CCF_PP_HOW_DO_WE_PROTECT_INFO_LABEL','Por padrão, as PII são mantidas em um formato mascarado. Pessoas com a devida autorização podem solicitar a desmascaração desses dados. Registramos cada uma dessas solicitações, criando assim uma trilha não repudiável e auditável de cada acesso às PII.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('81e15781-aa27-4c0f-893b-f2e2a2b54589','pt_MZ','CCF_PP_HOW_DO_WE_PROTECT_LABEL','COMO PROTEGEMOS AS INFORMAÇÕES DE IDENTIFICAÇÃO PESSOAL (PII)?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c6900a04-9eaf-4896-8ef6-6ca3c5822e98','pt_MZ','CCF_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME é uma colaboração entre PARTNER(S) NAME(S) e eGovernments Foundation. É desenvolvido pela DIGIT, que é uma plataforma de software de código aberto desenvolvida pela eGovernments Foundation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d89f18b0-c4f9-4c79-b9f5-a284243a4108','pt_MZ','CCF_PP_PRIVANCY_SECURITY_LABEL','[NOME DO PROGRAMA] (“nós” ou “nos” ou “nosso”) respeita a privacidade de nossos usuários (“usuário” ou “você” também conhecido como “seu”). Portanto, mantemos os mais altos padrões de atividades seguras, privacidade e segurança de informações/dados do usuário.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d3d26bb4-f601-4496-816d-29abb79e9a04','pt_MZ','CCF_PP_REFERS_LABEL','Através do NOME DO PROGRAMA, você pode acessar e aproveitar os serviços oferecidos pelos departamentos governamentais do ESTADO OU NOME DA ULB, departamento do governo central, órgãos locais e suas agências e órgãos corporativos/privados (serviços de utilidade pública) (provedores de serviços). Você pode usar o site/aplicativo/serviços do NOME DO PROGRAMA de diferentes maneiras, como descoberta de serviços, aproveitamento de serviços, registro de reclamações e assim por diante.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('710b349c-4024-43e8-90c2-5ae9bf471ca4','pt_MZ','CCF_PRIVACYPOLICY_HEADER','política de Privacidade','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51307c1a-e6f6-4d4c-b326-b765e17c19ff','pt_MZ','CCF_PRIVACY_PLOICY_DESCRIBES_LABEL','Esta Política de Privacidade descreve e determina como lidamos com suas informações pessoais e de uso de acordo com as leis aplicáveis ​​da Índia.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1ad089cd-e7a7-4067-93d7-67336f9fc02e','pt_MZ','CCF_PRIVACY_POLICY_','política de Privacidade','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ef48418f-70c8-433a-8d5b-6e754dc746da','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_CONDUCTING_LABEL','Realizar pesquisas ou analisar as preferências e dados demográficos do usuário como dados estatísticos mascarados e não como dados individuais.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('638b4fbc-b5cd-4098-9057-bb3e0ae9fead','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_DETECTING_LABEL','Detectar, investigar e prevenir atividades que possam violar nossas políticas ou que possam ser ilegais ou ilícitas.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9b66eca2-15db-4ad0-bae4-fe7afc09605b','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_EMPLOYEES_LABEL','Poderemos divulgar ou compartilhar esses dados com/com funcionários e/ou contratados do órgão urbano local, governo estadual ou outras agências governamentais, prestadores de serviços, cuja função exija que eles visualizem ou usem essas informações para desempenhar suas funções oficiais, incluindo fornecer a você o(s) serviço(s) que você está solicitando.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b44bee0d-2665-4efd-9807-72d40317360a','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_INFO_LABEL','Usamos esses dados para lhe oferecer a melhor experiência cívica, como fornecer sistemas digitais de reparação de reclamações, prestação eficiente de serviços, criação de painéis de atividades ULB, etc. Os dados são processados ​​apenas com base em um mandato legal e para uma finalidade legítima e necessária (para fornecer a você os serviços que você está solicitando e para fazer melhorias na prestação e administração de serviços, bem como quaisquer outros fins especificados por lei).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3af3b222-1ca3-46fc-82fc-30520e16127a','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_LABEL','POR QUE E COMO PROCESSAMOS, DIVULGAMOS E/OU COMPARTILHAMOS ESSES DADOS?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('08013b8a-7404-4165-b8ee-f45d9c1408a2','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_METADATA_LABEL','Poderemos processar, divulgar ou partilhar determinados metadados, bem como dados agregados e anonimizados, a fim de avaliar e melhorar o estado dessa prestação de serviços ao longo do tempo.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e77bf660-698f-4db3-af39-058aeae2f8ed','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_MONITIRING_LABEL','Dados processados ​​ou compartilhados para monitorar a atividade e preferências do usuário como evidência da atividade do usuário no aplicativo para fornecer uma experiência melhor no futuro.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('629e8c0a-6454-4d23-ae45-3a8d54f945d3','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_NOT_SHARE_LABEL','Não processaremos, divulgaremos ou compartilharemos seus dados, exceto conforme descrito nesta política ou conforme autorizado por você.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('82d84149-a2b0-4b11-b4f5-899343262546','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_ORDER_TO_COMPLY_LABEL','Poderemos divulgar ou compartilhar esses dados para cumprir a lei ou qualquer processo legal, inclusive quando exigido em processos judiciais, arbitrais ou administrativos.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('983a1b44-305d-4b30-8cbd-41aefb52357e','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_PAYMENTS_LABEL','Os pagamentos efetuados através do aplicativo/site Urban DIGIT são processados ​​através de gateways de pagamento seguros.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0a730ad3-e538-4791-ad55-3febc5582390','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_PROVIDE_SERVICES_LABEL','Processamos dados necessários para lhe fornecer os serviços que você está solicitando','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fd7f946b-781d-4b06-bf9e-4b1f8d6dca78','pt_MZ','CCF_PROCESS_DISCLOSE_SHARE_RESOLVING_LABEL','Dados processados ​​ou compartilhados durante a resolução de quaisquer disputas que possam surgir em relação às transações/negócios que você pode realizar usando o aplicativo/site.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9dc8f258-052a-4b8a-9ff8-6020bfd6411c','pt_MZ','CCF_PROTECT_PERSONALLY_INFO_LABEL','Por padrão, as PII são mantidas em um formato mascarado. Pessoas com a devida autorização podem solicitar a desmascaração desses dados. Registramos cada uma dessas solicitações, criando assim uma trilha não repudiável e auditável de cada acesso às PII.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e719dc17-6cd9-4858-894e-455e77b5b3bd','pt_MZ','CCF_PROTECT_PERSONALLY_LABEL','COMO PROTEGEMOS AS INFORMAÇÕES DE IDENTIFICAÇÃO PESSOAL (PII)?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9dc36814-6055-48ad-aec8-09aed62affb0','pt_MZ','CCF_RESPECT_PRIVACY_OF_USERS_LABEL','Respeitamos a privacidade dos nossos usuários. Portanto, mantemos os mais altos padrões de atividades seguras, privacidade e segurança de informações/dados do usuário.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('07ad0f38-9c8d-422a-be03-c5b559bca588','pt_MZ','CCF_STORE_DELETE_YOUR_ACCOUNT_LABEL','Você pode excluir sua conta a qualquer momento que desejar. Em caso de exclusão, removeremos todas as suas IPI do sistema, para que não fiquem visíveis e/ou acessíveis em qualquer operação regular. No entanto, as PII podem ser retidas de maneira criptografada para fins de conformidade/requisitos legais {CONFORME LEIS DA UNIÃO/ESTADO/ULB} a partir da data de exclusão/rescisão.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e6f53ae2-cab2-464a-92f3-bb54d7ee3e32','pt_MZ','CCF_STORE_DISCONNECT_LABEL','Caso você entregue/desconecte seu número de celular cadastrado é recomendável deletar seu perfil ou cancelar também seu cadastro no aplicativo.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8833ed40-05e6-496e-b0ff-279f49f682d7','pt_MZ','CCF_STORE_RECREATE_PROFILE_LABEL','Após a exclusão, caso você queira recriar seu perfil, o mesmo é permitido e nenhuma das informações capturadas anteriormente será preenchida automaticamente. Você precisa se registrar como um novo usuário.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cc1840f0-b682-4abe-9bf6-9c0ea641a181','pt_MZ','CCF_STORE_REVIEW_EDIT_LABEL','Você pode revisar e editar seus dados, bem como excluí-los do aplicativo/site seguindo os procedimentos {CONFORME LEIS DA UNIÃO/ESTADO/ULB}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d930a716-de46-47b0-91c9-5c2a74647386','pt_MZ','CCF_STORE_SECURE_MANNER_LABEL','Seus dados são armazenados de forma segura. Plataforma DIGIT, que possui configurações de privacidade incorporadas (como criptografia), que não permitem que seus dados fiquem visíveis para ninguém, exceto pessoas que estejam autorizadas a fazê-lo em virtude de sua função oficial. Salvo indicação em contrário, estes dados serão retidos por um período mínimo de {AS PER UNION / STATE / ULB LEIS} e um período máximo de {AS PER UNION / STATE / ULB LAWS}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8c1ba8fd-1fb9-42e8-9292-10596660ccbc','pt_MZ','CCF_STORE_SECURITY_MEASURES_LABEL','Adotamos medidas de segurança de dados para garantir que os dados dos usuários estejam seguros e longe de perigos de danos cibernéticos/físicos.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('094a9a86-65e4-44d3-950a-e6b8366c8df5','pt_MZ','CCF_STORE_THIS_DATA_LABEL','COMO ARMAZENAMOS ESSES DADOS?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('03c5f016-06d3-4946-a3b8-7ac38e3cb412','pt_MZ','CCF_STORE_UNREGISTER_LABEL','Se você simplesmente excluir/remover o aplicativo do seu dispositivo móvel, mas não excluir seu perfil ou cancelar seu registro no aplicativo/site, você continuará sendo um usuário registrado do aplicativo e continuaremos a enviar-lhe todas as comunicações pelas quais você optou, a menos e até que você desista de tais comunicações, ou {CONFORME LEI DA UNIÃO/ESTADO/ULB}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1a91c2cc-51bc-464b-8e83-e1849cf6d81e','pt_MZ','CCF_TERM_OF_USE_','Termos de uso','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
