INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cbc8f672-d25c-4b02-b846-9cb79f8ff8d3','pt_MZ','CITIZEN_CHARTER_DOC_DESC','Descrição do Documento da Carta do Cidadão.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('94aad7ce-3a21-4eb6-adc9-b9f688a6a842','pt_MZ','CITIZEN_CONSENT_FORM_PP_ACCESS_AVAIL_LABEL','Através do NOME DO PROGRAMA, você pode acessar e aproveitar os serviços oferecidos pelos departamentos governamentais do ESTADO OU NOME DA ULB, departamento do governo central, órgãos locais e suas agências e órgãos corporativos/privados (serviços de utilidade pública) (provedores de serviços). Você pode usar o site/aplicativo/serviços do NOME DO PROGRAMA de diferentes maneiras, como descoberta de serviços, aproveitamento de serviços, registro de reclamações e assim por diante.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6422c9b1-161b-45ba-9133-1312a33fcc51','pt_MZ','CITIZEN_CONSENT_FORM_PP_DD_DEAL_LABEL','Esta Política de Privacidade descreve e determina como lidamos com suas informações pessoais e de uso de acordo com as leis aplicáveis ​​da Índia.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cdfbf255-ed4c-4402-9ad4-90193d5df7ed','pt_MZ','CITIZEN_CONSENT_FORM_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME é uma colaboração entre PARTNER(S) NAME(S) e eGovernments Foundation. É desenvolvido pela DIGIT, que é uma plataforma de software de código aberto desenvolvida pela eGovernments Foundation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('297056e8-6de5-45c6-a7be-462093ea5b79','pt_MZ','CITIZEN_CONSENT_FORM_PP_PRIVANCY_SECURITY_LABEL','{NOME DO PROGRAMA} (“nós” ou “nos” ou “nosso”) respeita a privacidade de nossos usuários (“usuário” ou “você” também conhecido como “seu”). Portanto, mantemos os mais altos padrões de atividades seguras, privacidade e segurança de informações/dados do usuário.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4108b7a-531f-4996-b688-45160938fe1f','pt_MZ','CITIZEN_CONSENT_FORM_PP_REFERS_LABEL','NOME DO PROGRAMA refere-se aos serviços fornecidos através do site NOME DO PROGRAMA, aplicativo móvel e OUTROS CANAIS RELEVANTES.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
