INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('752e9ad2-b908-477d-b754-b11aa1af7acb','pt_MZ','PRIVACY_HEADER_2_SUB_1','Pré-requisitos','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4cc7e131-b0ab-4fc9-b260-7e036b446c2b','pt_MZ','PRIVACY_HEADER_2_SUB_1_DESC_1','Você adicionou uma coluna ou campo com o nome da característica aos shapefiles para os quais deseja carregar formas. Se estiver usando características compostas, você adicionou diversas colunas. Mais informações: Preparando Shapefiles','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5444cdc5-bd29-4314-8173-691413befcd9','pt_MZ','PRIVACY_HEADER_2_SUB_1_DESC_2','Para atualizar a tabela geográfica com formas que são carregadas no Business Document Server, você precisa do SAP HANA 2.0 Rev 45','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c3585057-7835-4b8b-9d28-d19584245387','pt_MZ','PRIVACY_HEADER_2_SUB_2','Procedimento','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('afe7ccea-e254-43a1-9d3e-0653113d05cc','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','1. Você está na aba Clientes BI na tela de edição de características nas ferramentas de modelagem do BW. Você escolheu Formas ou Formas e dados de pontos como tipo geográfico.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('69dbaf0f-bfc4-4a31-81e7-50cf2a4bdeab','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','2. Escolha Carregar Shapefiles em Ações. Escolha Ir. O back-end do BW/4 é aberto.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d2efc09b-e321-4ce3-bd21-e8c13caa31d9','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','3. Selecione seus shapefiles. Você precisa dos três shapefiles a seguir: .dbf, . shp, .shx. Os shapefiles devem estar na Referência Espacial ID 4326 e devem ter todos o mesmo nome antes do final.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a6160d9d-4f9d-443c-8064-938ee06cdf27','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','4. Escolha Atualizar tabela geográfica em Ações. Escolha Ir. Você pode escolher Atualização Delta ou Atualização Completa.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3852c528-fcb8-4085-a598-65d52e219ed3','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','5. As formas carregadas são transformadas e armazenadas no SRID (Spatial Reference ID) 3857.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bd80262e-aef5-4dc2-9f61-b1029fe037e0','pt_MZ','SETTINGS','Configurações','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
