INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('34c81371-d8d9-42a4-a778-9cd779fec44d','fr_MZ','BPA_EDCR_DETAILS','Détails de l''eDCR','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba67fd9e-3b78-41a9-8a91-47c32dcfc1ce','fr_MZ','BPA_FAQ_ANS_ONE','Lorsqu''un examen eDCR échoue, les informations d''erreur sont marquées sur chaque élément de ligne du fichier de sortie. L''architecte peut apporter les corrections en conséquence et soumettre à nouveau le plan en temps réel. Cette opération peut être effectuée plusieurs fois sans encourir de frais supplémentaires.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6689ebbd-1258-449a-a0b9-b1e3c2177cc9','fr_MZ','BPA_FAQ_ANS_THREE','Le système de contrôle eDCR compare les paramètres des dessins avec les règlements en vigueur dans la région administrative correspondante et évalue s''ils enfreignent. Dans le fichier de sortie, pour chaque paramètre évalué, il y aura une indication indiquant s''il est approuvé ou rejeté. L''ensemble du processus d''examen prend environ 5 secondes','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('516bb036-b661-4a03-8e15-346d004fe381','fr_MZ','BPA_FAQ_ANS_TWO','Vous pouvez renouveler les permis au comptoir ou via le portail. Après vous être connecté, recherchez la demande de permis correspondante sur le portail. Cliquez ensuite sur le lien du permis que vous souhaitez renouveler. Ensuite, remplissez la demande de renouvellement de permis et cliquez sur Soumettre.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('21154c48-b257-48f2-8561-733077adfdad','fr_MZ','BPA_FAQ_QUES_ONE','Que se passe-t-il lorsque l’examen eDCR échoue ?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51db2267-b353-4c47-a895-d317ab96ca4f','fr_MZ','BPA_FAQ_QUES_THREE','Comment fonctionne l''examen eDCR et combien de temps faut-il pour examiner les diagrammes ?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
