INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('03e81f44-82ff-424f-9e9d-48237d0d6acc','fr_MZ','CCF_COLLECT_INFO_ADMINISTRATIVE_LABEL','Les données provenant des systèmes d''enregistrement administratif, telles que le numéro d''enquête sur les revenus ou tout autre identifiant de propriété, le numéro de connexion, le numéro de compteur, etc. peuvent également être enregistrées. Dans le cas où une personne effectue des paiements au gouvernement local, les informations relatives au paiement, telles que le numéro de transaction, peuvent également être enregistrées.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0980ae3-900c-437a-af21-b651f0b18459','fr_MZ','CCF_COLLECT_INFO_IMPROVE_LABEL','Nous collectons des informations/données (« données ») pour améliorer et vous fournir de meilleurs services. Nous collectons et traitons les informations personnelles telles que votre prénom, votre nom, le nom du parent/tuteur, votre adresse, votre adresse e-mail, votre numéro de téléphone, votre âge, votre sexe, vos documents d''identification. Nous pouvons collecter vos informations éducatives, démographiques, de localisation, d''appareil et autres informations similaires.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db6cb99a-51c5-4ece-a94f-8856d8beb866','fr_MZ','CCF_COLLECT_IP_ADDRESS_LABEL','Nous collectons des informations telles que les adresses IP (Internet Protocol), le nom de domaine, le type de navigateur, le système d''exploitation, la date et l''heure de la visite, les pages visitées, le numéro IMEI/IMSI, l''identifiant de l''appareil, les informations de localisation, les paramètres de langue, la marque et le modèle du combiné, etc. Cependant, aucune tentative n''est faite pour les relier à la véritable identité des personnes visitant l''application Urban DIGIT, le site Web, le chatbot Whatsapp, etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba97ddda-46a5-4500-aac9-fb0a951c163f','fr_MZ','CCF_COLLECT_IP_SERVICES_USED_LABEL','Les informations que nous collectons dépendent des services que vous utilisez et peuvent varier de temps à autre, qui seront informées par les modifications apportées à cette politique.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0f46eef2-9371-4c00-aa6f-4a5ce52146ee','fr_MZ','CCF_COLLECT_THIS_DATA_INFO_LABEL','Nous collectons des données directement auprès de vous (lorsque vous utilisez nos services) au fur et à mesure de votre inscription et de votre connexion à l''application/au site Web. Nous pouvons également collecter des données auprès des gouvernements de l''Union, de l''État et locaux, y compris de leurs agents/employés, ainsi que recevoir des données qui sont librement accessibles au public.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
