INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('574daf4a-d1df-4b1c-ad8e-74fb7f23c19c','fr_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_INFO_LABEL','Nous collectons des données directement auprès de vous (lorsque vous utilisez nos services) au fur et à mesure de votre inscription et de votre connexion à l''application/au site Web. Nous pouvons également collecter des données auprès des gouvernements de l''Union, de l''État et locaux, y compris de leurs agents/employés, ainsi que recevoir des données qui sont librement accessibles au public.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
