INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('890d9723-d99a-4386-8c37-6b493c113703','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_1_LABEL','Sauf indication contraire, ces données seront conservées pendant une durée minimale de SELON LES LOIS DE L''UNION / ETAT / ULB et une durée maximale de SELON LES LOIS DE L''UNION / ETAT / ULB. Vous pouvez consulter et modifier vos données, ainsi que supprimer vos données de l''application/du site Web en suivant les procédures SELON LES LOIS DE L''UNION / DE L''ÉTAT / DE L''ULB.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2a3b626a-56c5-4e54-8f9e-0fedc34c7e44','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_LABEL','Vos données sont stockées de manière sécurisée. PROGRAM NAME est alimenté par la plateforme DIGIT, qui intègre des paramètres de confidentialité (tels que le cryptage), qui ne permettent à personne de voir vos données, à l''exception des personnes autorisées à le faire en vertu de leur rôle officiel.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7448dff-665e-4f06-948e-f7501ae058bf','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_2_LABEL','Vous pouvez supprimer votre compte à tout moment. En cas de suppression, nous supprimerons toutes vos informations personnelles du système, afin qu''elles ne soient plus visibles et/ou accessibles lors de toute opération régulière. Cependant, les PII peuvent être conservées de manière cryptée à des fins d''exigences/conformités légales CONFORMÉMENT AUX LOIS DE L''UNION/ÉTAT/ULB à compter de la date de suppression/résiliation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4ec1075e-9668-4f4c-967e-05b6aa088d78','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_3_LABEL','Après la suppression, si vous souhaitez recréer votre profil, cela est autorisé et aucune des informations précédemment capturées ne sera renseignée automatiquement. Vous devez vous inscrire en tant que nouvel utilisateur.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1d71c757-8317-49a9-8be9-13aa86ab37ea','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_4_LABEL','Si vous supprimez/supprimez simplement l''application de votre appareil mobile mais ne supprimez pas votre profil ou ne vous désinscrivez pas de l''application/du site Web, vous continuerez à être un utilisateur enregistré de l''application et nous continuerons à vous envoyer toutes les communications que vous avez choisi à moins et jusqu''à ce que vous vous désinscriviez de ces communications, ou CONFORMÉMENT À LA LOI DE L''UNION/ÉTAT/ULB.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e07a65d-e5ff-4216-b560-4e36df70da43','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_5_LABEL','Si vous abandonnez/déconnectez votre numéro de mobile enregistré NOM DU PROGRAMME, il est recommandé de supprimer votre profil ou de vous désinscrire également de l''application.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d35790e8-5889-44aa-a0e1-d57e3368b92f','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_6_LABEL','Nous avons adopté des mesures de sécurité des données pour garantir que les données des utilisateurs sont en sécurité et à l''abri des dangers de dommages cybernétiques/physiques. En savoir plus sur les mesures de sécurité des données peut être lu','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dbeee6ca-aa1d-41d8-af36-9e7302bdad73','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LABEL','COMMENT CONSERVONS-NOUS CES DONNÉES ?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('79461f46-7b8a-4f5d-97b3-b4b2c0b636d1','fr_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LINK_HERE_LABEL','ici.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1943ee62-0bf6-485a-b496-8bf61bf41cc0','fr_MZ','CCF_PP_GRIEVANCES_INFO_LABEL','En cas de griefs, vous pouvez envoyer vos plaintes pour obtenir réparation via le portail des griefs disponible à l''adresse','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b16e1cd1-61aa-4e59-b6fa-07d29fce4de5','fr_MZ','CCF_PP_GRIEVANCES_INFO_LINK_LABEL','Lien','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('061ea91b-bb04-4577-8a7a-ccaac2368f18','fr_MZ','CCF_PP_GRIEVANCES_LABEL','GRIEFS','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9c4e88c-3344-49a6-9764-20f83b57df11','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_10_LABEL','Les paiements effectués via l''application/le site Web PROGRAM NAME sont traités via des passerelles de paiement sécurisées.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9bac2e43-dbd8-414a-94ef-276c237f9d89','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_11_LABEL','Nous ne traiterons, ne divulguerons ni ne partagerons vos données sauf comme décrit dans cette politique ou comme autrement autorisé par vous.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('109c5a0c-6469-4e65-9803-74669287e62a','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_1_LABEL','Nous utilisons ces données pour vous offrir la meilleure expérience civique, par exemple en fournissant des systèmes numériques de règlement des réclamations, une prestation de services efficace, en créant des tableaux de bord des activités de l''ULB, etc. Les données ne sont traitées que sur la base d''un mandat légal et dans un but légitime et nécessaire (pour vous fournir les services que vous demandez et pour apporter des améliorations à la prestation et à l''administration des services, ainsi qu''à toute autre fin spécifiée par la loi).','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c51f923a-0a07-4731-b59d-9bbdb921c522','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_2_LABEL','Nous traitons les données nécessaires pour vous fournir les services que vous demandez','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ee2174ad-5368-44d2-bbf9-24ea1497e64e','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_3_LABEL','Nous pouvons traiter, divulguer ou partager certaines métadonnées, ainsi que des données agrégées et anonymisées, afin d''évaluer et d''améliorer l''état de cette prestation de services au fil du temps.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dd578ebc-f7a1-4f3c-a18a-bc1ab144e378','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_4_LABEL','Nous pouvons divulguer ou partager ces données avec/avec des employés et/ou des sous-traitants de l''organisme local urbain, du gouvernement de l''État ou d''autres agences gouvernementales, prestataires de services, dont le rôle les oblige à consulter ou à utiliser ces informations afin d''exercer leurs fonctions officielles, y compris pour vous fournir le(s) service(s) que vous demandez.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6e3df1fe-7e0b-4612-b109-92f42dc67e8f','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_5_LABEL','Données traitées ou partagées lors de la résolution de tout litige pouvant survenir concernant les transactions/accords que vous pouvez effectuer en utilisant l''application/le site Web.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0e8307fc-a589-4d31-875b-48f604724cf2','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_6_LABEL','Données traitées ou partagées pour surveiller l''activité et les préférences de l''utilisateur comme preuve de l''activité de l''utilisateur sur l''application afin de fournir une meilleure expérience à l''avenir.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1650c160-e97c-4155-8796-5e8c2dd88f7b','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_7_LABEL','Détecter, enquêter et prévenir les activités qui pourraient violer nos politiques ou qui pourraient être illégales ou illégales.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8ffb79d4-fd89-4fef-b7ac-610295474212','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_8_LABEL','Effectuer des recherches ou analyser les préférences et les données démographiques des utilisateurs en tant que données masquées statistiques et non en tant que données individuelles.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('23562678-737e-4f7e-bec6-61183a7653fd','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_9_LABEL','Nous pouvons divulguer ou partager ces données afin de nous conformer à la loi ou à toute procédure judiciaire, y compris lorsque cela est requis dans le cadre d''une procédure judiciaire, arbitrale ou administrative.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('80f52d60-321a-4b0c-89be-a3ae83527e91','fr_MZ','CCF_PP_HOW_DO_WE_PROCESS_LABEL','POURQUOI ET COMMENT TRAITONS-NOUS, DIVULGUILLONS ET/OU PARTAGEONS CES DONNÉES ?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7cf54efd-bb21-4fc0-931c-12f1b7940f16','fr_MZ','CCF_PP_HOW_DO_WE_PROTECT_INFO_LABEL','Par défaut, les informations personnelles sont conservées dans un format masqué. Les personnes disposant des autorisations appropriées peuvent demander le démasquage de ces données. Nous enregistrons chacune de ces demandes, créant ainsi une trace non répudiable et vérifiable de chacun de ces accès aux informations personnelles.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('085e4ae9-1a0e-4fa3-aa9d-8ea4d0b3283b','fr_MZ','CCF_PP_HOW_DO_WE_PROTECT_LABEL','COMMENT PROTÉGEONS-NOUS LES INFORMATIONS PERSONNELLES IDENTIFIABLES (PII) ?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e3311cca-19c8-4fa8-95c1-134a2b7f2710','fr_MZ','CCF_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME est une collaboration entre PARTNER(S) NAME(S) et eGovernments Foundation. Il est alimenté par DIGIT, une plate-forme logicielle open source développée par eGovernments Foundation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8bce40c5-006e-4608-bff3-e0f9bdcf5c9b','fr_MZ','CCF_PP_PRIVANCY_SECURITY_LABEL','[NOM DU PROGRAMME] (« nous » ou « notre » ou « notre ») respecte la vie privée de nos utilisateurs (« utilisateur » ou « vous » également appelé « votre »). Par conséquent, nous maintenons les normes les plus élevées en matière d’activités sécurisées, de confidentialité et de sécurité des informations/données des utilisateurs.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0444f2d-c146-4432-a3ab-1cfad42ea896','fr_MZ','CCF_PP_REFERS_LABEL','Grâce au NOM DU PROGRAMME, vous pouvez accéder et bénéficier des services offerts par les services gouvernementaux de l''ÉTAT OU DE L''ULB, les services du gouvernement central, les organismes locaux et leurs agences et les organismes corporatifs/privés (services publics) (prestataires de services). Vous pouvez utiliser le site Web/l''application/les services de PROGRAM NAME de différentes manières, par exemple pour la découverte de services, l''utilisation de services, l''enregistrement de griefs, etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e35197cb-afae-4adb-87d2-29ac22dee6ab','fr_MZ','CCF_PRIVACYPOLICY_HEADER','politique de confidentialité','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
