INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('294d47e2-5813-4438-99d5-25479bee93b6','fr_MZ','CCF_RESPECT_PRIVACY_OF_USERS_LABEL','Nous respectons la vie privée de nos utilisateurs. Par conséquent, nous maintenons les normes les plus élevées en matière d’activités sécurisées, de confidentialité et de sécurité des informations/données des utilisateurs.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('76922546-726d-40ea-bb1f-e734d80437e8','fr_MZ','CCF_STORE_DELETE_YOUR_ACCOUNT_LABEL','Vous pouvez supprimer votre compte à tout moment. En cas de suppression, nous supprimerons toutes vos informations personnelles du système, afin qu''elles ne soient plus visibles et/ou accessibles lors de toute opération régulière. Toutefois, les PII peuvent être conservées de manière cryptée à des fins d''exigences/conformités légales {SELON L''UNION / L''ÉTAT / LOIS ULB} à compter de la date de suppression/résiliation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('184e3cab-30f4-49de-9fbd-27703331e7e5','fr_MZ','CCF_STORE_DISCONNECT_LABEL','Si vous abandonnez/déconnectez votre numéro de mobile enregistré, il est recommandé de supprimer votre profil ou de vous désinscrire également de l''application.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f27b4805-ae22-4649-8e3e-b6f240f6548a','fr_MZ','CCF_STORE_RECREATE_PROFILE_LABEL','Après la suppression, si vous souhaitez recréer votre profil, cela est autorisé et aucune des informations précédemment capturées ne sera renseignée automatiquement. Vous devez vous inscrire en tant que nouvel utilisateur.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('727cb4ca-90d5-459c-9cc9-4d9407f5a902','fr_MZ','CCF_STORE_REVIEW_EDIT_LABEL','Vous pouvez consulter et modifier vos données, ainsi que supprimer vos données de l''application/du site Web en suivant les procédures {SELON L''UNION / L''ÉTAT / LOIS ULB}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8dd4bce0-5917-4f26-96c1-8d4d76b1ff08','fr_MZ','CCF_STORE_SECURE_MANNER_LABEL','Vos données sont stockées de manière sécurisée. Plateforme DIGIT, qui intègre des paramètres de confidentialité (tels que le cryptage), qui ne permettent à personne de voir vos données, à l''exception des personnes autorisées à le faire en vertu de leur fonction officielle. Sauf indication contraire, ces données seront conservées pendant une durée minimale de {SELON L''UNION / ETAT / LOIS ULB} et une durée maximale de {SELON L''UNION / ETAT / LOIS ULB}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e0f384dc-2c22-420a-93ff-74edc52fe318','fr_MZ','CCF_STORE_SECURITY_MEASURES_LABEL','Nous avons adopté des mesures de sécurité des données pour garantir que les données des utilisateurs sont en sécurité et à l''abri des dangers de dommages cybernétiques/physiques.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ae93268-c006-441c-a251-f3e6b26de8d3','fr_MZ','CCF_STORE_THIS_DATA_LABEL','COMMENT CONSERVONS-NOUS CES DONNÉES ?','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('91fda8f3-af9f-4735-8889-d5dba06f4b34','fr_MZ','CCF_STORE_UNREGISTER_LABEL','Si vous supprimez/supprimez simplement l''application de votre appareil mobile mais ne supprimez pas votre profil ou ne vous désinscrivez pas de l''application/du site Web, vous continuerez à être un utilisateur enregistré de l''application et nous continuerons à vous envoyer toutes les communications que vous avez choisi à moins et jusqu''à ce que vous vous désinscriviez de ces communications, ou {CONFORMÉMENT À LA LOI DE L''UNION / DE L''ÉTAT / DE L''ULB}.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
