INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('586913a0-4701-44ee-bdfe-561d00eb79bd','fr_MZ','CITIZEN_CONSENT_FORM_PP_ACCESS_AVAIL_LABEL','Grâce au NOM DU PROGRAMME, vous pouvez accéder et bénéficier des services offerts par les services gouvernementaux de l''ÉTAT OU DE L''ULB, les services du gouvernement central, les organismes locaux et leurs agences et les organismes corporatifs/privés (services publics) (prestataires de services). Vous pouvez utiliser le site Web/l''application/les services de PROGRAM NAME de différentes manières, par exemple pour la découverte de services, l''utilisation de services, l''enregistrement de griefs, etc.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9e6d885e-9006-4652-82ce-0da6c4b1f8bb','fr_MZ','CITIZEN_CONSENT_FORM_PP_DD_DEAL_LABEL','Cette politique de confidentialité décrit et détermine la manière dont nous traitons vos informations personnelles et d''utilisation conformément aux lois applicables en Inde.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('14226ddd-6c65-4bd4-8414-c0fb329b5989','fr_MZ','CITIZEN_CONSENT_FORM_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME est une collaboration entre PARTNER(S) NAME(S) et eGovernments Foundation. Il est alimenté par DIGIT, une plate-forme logicielle open source développée par eGovernments Foundation.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9348c8d3-c3f9-43b0-935f-7cb1ca1e088d','fr_MZ','CITIZEN_CONSENT_FORM_PP_PRIVANCY_SECURITY_LABEL','{NOM DU PROGRAMME} (« nous » ou « notre » ou « notre ») respecte la vie privée de nos utilisateurs (« utilisateur » ou « vous » également appelé « votre »). Par conséquent, nous maintenons les normes les plus élevées en matière d’activités sécurisées, de confidentialité et de sécurité des informations/données des utilisateurs.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
