INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a6f12203-2481-4b56-88e3-f007982b89b7','fr_MZ','PRIVACY_HEADER_2_SUB_1','Conditions préalables','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('989a5d28-27ab-4095-82be-d2812d9e1906','fr_MZ','PRIVACY_HEADER_2_SUB_1_DESC_1','Vous avez ajouté une colonne ou un champ portant le nom de la caractéristique aux fichiers de formes pour lesquels vous souhaitez charger des formes. Si vous utilisez des caractéristiques composées, vous avez ajouté plusieurs colonnes. Plus d''informations : Préparation des fichiers de formes','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9af7de97-5138-467e-8f8f-098d349da130','fr_MZ','PRIVACY_HEADER_2_SUB_1_DESC_2','Pour mettre à jour la géotable avec les formes téléchargées sur le Business Document Server, vous avez besoin de SAP HANA 2.0 Rev 45.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7500eb7d-e410-48b4-8a28-4a3f6c99bd7c','fr_MZ','PRIVACY_HEADER_2_SUB_2','Procédure','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d362675d-8736-47ee-a8b1-6d7c3543c778','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','1. Vous êtes sur l''onglet Clients BI dans l''écran d''édition des caractéristiques dans les outils de modélisation BW. Vous avez choisi Formes ou Formes et données de points comme type géographique.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3990db7a-385f-4ff1-94af-6d65e549c584','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','2. Choisissez Télécharger des fichiers de formes sous Actions. Choisissez Aller. Le back-end BW/4 s’ouvre.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('868be234-6d7a-46a7-8a9f-83896496d022','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','3. Sélectionnez vos fichiers de formes. Vous avez besoin des trois fichiers de formes suivants : .dbf, . shp, .shx. Les fichiers de formes doivent figurer dans l''ID de référence spatiale 4326 et doivent tous avoir le même nom avant la fin.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c6ff8774-ade5-4466-b52f-c18033727a34','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','4. Choisissez Mettre à jour la géotable sous Actions. Choisissez Aller. Vous pouvez choisir entre la mise à jour Delta ou la mise à jour complète.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6a83d85e-c26c-4db9-bbd2-fff438dbec7a','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','5. Les formes téléchargées sont transformées et stockées dans SRID (Spatial Reference ID) 3857.','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc352ef5-7477-468d-816c-8a7ae3b96a3b','fr_MZ','SETTINGS','Paramètres','mz','digit-ui',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
