INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('404aaf8b-ccec-4417-9fc3-35bd1a15eb6b','en_MZ','FACILITIES_EXCEL_README_POINTS_1','If there are no Facilities available for selection, the “List of Available Facilities“ tab in the template will be empty. To create new facility data, add the name of the Facility Name, Facility Type, Facility Status, Capacity. The “Facility Code” column needs to be left empty if this is a new facility. If it is a facility being reused (which is available in the template after downloading) the user only needs to do step 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8ef6c26c-eae9-42fb-9f64-11e2cbe08916','en_MZ','FACILITIES_EXCEL_README_POINTS_2','To map the facility to the correct boundary, the user needs to copy the correct boundary code of the boundary from the “List of Campaign Boundaries“ sheet that the facility needs to be mapped to. If there is a facility that is mapped to multiple boundaries, the System Admin will have to add the boundary codes of all the boundaries that facility is mapped to by separating them by commas in the cell to add Boundary Codes for that Facility.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('32264cc2-e0f8-44ce-9cd9-e7a5638212ac','en_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1','Creating new facility data/using existing facility data once the template is downloaded :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
