INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5ebcd7c2-21c3-48f6-acb2-0770b2d7dd5b','en_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','To map the facility to the correct boundary, the user needs to copy the correct boundary code of the boundary from the “Boundary Data“ sheet that the facility needs to be mapped to.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
