INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db8405f1-92a0-4e96-b78b-41b24b1a0cdb','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_1_DESC_1','Download the excel template by clicking on the “Download Template” button.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4fd690d0-b28d-4b7d-af31-da1df8b9c609','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_1_DESC_2','Open the Template that was downloaded in the previous step will have 3 sheets and the first sheet you will see is a “Read Me” sheet. The second Sheet named “List of Available Facilities“ will have a list of all the available facilities that can be used in the campaign. If there is no facility available, this sheet will be empty. The third sheet will be named “List of Campaign Boundaries“ which will have all the boundaries with their respective Boundary Codes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92233c1d-dff4-40ef-b1d3-a3789d547f8c','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2','Creating new facility data/using existing facility data once the template is downloaded:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8a6ea041-7881-4820-957c-ad4d89e4531d','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_1','If there are no Facilities available for selection, the “List of Available Facilities“ tab in the template will be empty. To create new facility data, add the name of the Facility Name, Facility Type, Facility Status, Capacity. The “Facility Code” column needs to be left empty if this is a new facility. If it is a facility being reused (which is available in the template after downloading) the user only needs to do step 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5939122d-15c8-4e62-8d29-ec2ff0bf2f3a','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_2','To map the facility to the correct boundary, the user needs to copy the correct boundary code of the boundary from the “List of Campaign Boundaries“ sheet that the facility needs to be mapped to. If there is a facility that is mapped to multiple boundaries, the System Admin will have to add the boundary codes of all the boundaries that facility is mapped to by separating them by commas in the cell to add Boundary Codes for that Facility.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42700048-0630-45c7-8d8d-b68dc56e9d51','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_3','Save the sheet with the updated targets for each village on the excel template.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('38b49c53-aee1-4e7f-acc0-c523f8297fb3','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_4','Press the “Browse In My Files” button on the “Upload Facility Data” screen and select the saved file with all targets from the system.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a406a779-f57c-496f-a5e3-60ce89e600ea','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_5','Deactivating existing Facilities for a campaign.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('72fa2607-1fb0-4f73-bf38-6d66c5310048','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_6','After the user has downloaded the template for facilities, if the system has existing facility data to be reused, the template will be pre populated with those list of facilities.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc9c6107-c72d-4925-9ac3-863e4e5271e4','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_7','If the user then chooses not use specific facilities, they can delete those lines of data for those specific facilities that need to be removed and upload the sheet with only those facilities that are needed for the campaign with the correct boundary codes mapped to those facilities.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('986dd41f-402d-4a6f-9c7d-353b18594f21','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1','Case when there is no facility data in the system:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('72da2599-07b0-4d86-95e6-c82d362dfde9','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_1','Step 1: When there is no facility data in the system, the “List of available facility” template will be empty. For every facility added the user needs to input the Facility Name (must be unique), Facility Type (Warehouse/Health Facility), Facility Status (Temporary/Permanent), Capacity (Number input)','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('73ec707f-89d6-4e36-8431-982c1c870b7d','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_2','Step 2: To map the facilities to a given boundary the user needs to copy the correct Boundary Code from the “Boundary Data” sheet. If there are more than one boundaries that a facility needs to be mapped to, the user can add all the boundary codes separated by commas','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9aab0ee8-1193-42a6-82b9-e5b9b688c629','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_3','Step 3: For every facility, the user needs to add Active or Inactive for all facilities under the “Facility Usage” column. All the Facilities marked as “Active” will be used in the campaign being created the ones marked “Inactive” will not be used in the campaign being created.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('efb1b6b7-1adc-483f-a5f3-4bd307346b49','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_4','Step 4: Once all the facilities are added the user needs to save the file on their system and upload the file by pressing “Browse in My Files” option.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca08c4e8-490d-4ee3-84de-250bd6d05685','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2','Case when there is existing facility data in the system:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ebb52768-15ed-44f1-b41a-bc022f22604a','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_1','Step 1: When you open the downloaded facility template, please refer to the List of available Facility sheet. For existing facilities, kindly add entries in the Boundary Code column. You can find the boundary codes in the Boundary Data sheet. If a facility maps to multiple boundaries, please separate the codes with commas.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a17854ce-94ad-4a0f-b9ea-3e537fdaf8ad','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Step 2: In this step the user will have to add entries in the Facility Usage column with valid entries being either Active or Inactive where the user can set the usage for a facility to Active if the facility is being is used for a campaign or else can be set to Inactive. The inputs in the Facility Usage column need to be added for all entries.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('420ca176-9e69-499b-9a73-fd8c36c530f6','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_3','Step 3: For adding new Facilities which are not present in the list of existing facilities, the user needs to input the Facility Name (must be unique), Facility Type (Warehouse/Health Facility), Facility Status (Temporary/Permanent), Capacity (Number input), Boundary Code(from the Boundary Data Sheet) and Facility Usage (Active/Inactive) as explained previously','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dfe768e5-75cf-4227-ac6d-1a5fb2b66d88','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_4','Step 4: Once all the facilities are added the user needs to save the file on their system and upload the file by pressing “Browse in My Files” option.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5cf2f1c3-48e8-4842-84e5-212340b77c6b','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_3','Cases for common errors:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('77fc515e-948d-4e1f-a316-d062b482beb4','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_1','If the user has removed Facility codes for an existing facility in the list then system will create a duplicate facility with those column values.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5e49b2c3-286b-4a0f-8b91-f1a450d36018','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_2','If the user deletes any columns from the “List of Available Facilities” from the sheet and uploads the sheet, the system will throw an error and the user will have to download the template again and reupload the correct sheet with the correct data.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c9abaf17-0386-48cc-9f8d-c1055dbc3fb2','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_3','If the user deletes any of the headers in the sheet and uploads the sheet, the system will throw an error and the user will have to download the template again and reupload the correct sheet with the correct data.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bc914def-1137-4b72-8c09-84b5ca92e53b','en_MZ','FACILITYWITHBOUNDARY_README_MAINHEADER','Read me instructions for facility upload','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
