INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4dd3cd7-ce52-4548-bf08-f1adeab5ee07','en_MZ','MP_VILLAGE_TERRAIN','Village terrain','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cd1819cf-8d6c-466f-9b10-3a71cb9ced82','en_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_1','If there are no Facilities available for selection, the “List of Available Facilities“ tab in the template will be empty. To create new facility data, add the name of the Facility Name, Facility Type, Facility Status, Capacity. The “Facility Code” column needs to be left empty if this is a new facility. If it is a facility being reused (which is available in the template after downloading) the user only needs to do step 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ebaebce3-a629-4018-bafa-a0bac2dd4461','en_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_10','If the user deletes any of the headers in the sheet and uploads the sheet, the system will throw an error and the user will have to download the template again and reupload the correct sheet with the correct data.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7c96d80d-fad1-48e1-ab39-3ad5bfdf698f','en_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_2','To map the facility to the correct boundary, the user needs to copy the correct boundary code of the boundary from the “List of Campaign Boundaries“ sheet that the facility needs to be mapped to. If there is a Facility that is mapped to multiple boundaries, the System Admin will have to add the boundary codes of all the boundaries that Facility is mapped to by separating them by commas in the cell to add Boundary Codes for that Facility.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5dba3340-8096-4f32-a8df-8a367c806d5c','en_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_3','Save the sheet with the updated targets for each village on the Excel Template.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7c1b0f1-5051-4f79-a335-bcdc26b2bfdd','en_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_4','Press the “Browse In My Files” button on the “Upload Facility Data” screen and select the saved file with all targets from the system.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3443aa10-c427-491e-94bb-7871c2cdc6d2','en_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_5','Deactivating existing Facilities for a campaign.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
