INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7ebfe3d-97f6-477a-ab9f-44d8ce762213','en_MZ','UNIFIED_CONSOLE_README_HEADER_1_DESC_1','Download the microplan template to add facility details, user assignments, and target data in one place. The sheet includes dropdowns for selecting boundaries, facility types, roles, and other required fields.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
