INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('60a913ae-16e3-40c5-a61d-30c27f9ee50d','en_MZ','USERWITHBOUNDARY_README_HEADER_1','Downloading excel templates for creating users:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2fc99340-2be2-41cb-932b-21bd9c0f0416','en_MZ','USERWITHBOUNDARY_README_HEADER_1_DESC_1','Download the excel template by clicking on the “Download Template” button.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ee0e9a5-887a-4c80-8f12-8f50938ae923','en_MZ','USERWITHBOUNDARY_README_HEADER_1_DESC_2','Open the excel template that was downloaded in the previous step will have 3 sheets and the first sheet you will see is a “Read Me” sheet. The second Sheet named “Create List of Users“ that will be an empty sheet where the user needs to enter data to create users for the campaign. The third sheet will be named “List of Campaign Boundaries“ which will have all the boundaries selected in the “Boundary Details“ step with their respective boundary codes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5dec3ad9-12b1-4c63-9de6-91a23e87049b','en_MZ','USERWITHBOUNDARY_README_HEADER_2','Creating users for the campaign:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d6ba700e-3599-48be-9b7e-121c098f14bd','en_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_1','The System Admin will have to create a separate entry for each user. The System Admin will have to add The Name of the User (Mandatory), Phone Number (Mandatory),Role (Mandatory) Employment Type (Mandatory), Boundary Code (Mandatory). If there is a user who is mapped to multiple roles, the System Admin will have to add all the roles that user is mapped to by separating them by commas in the cell to add Roles for that user.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('86f863fc-1397-402b-ba47-b413f04ae9bf','en_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_2','Each user being created needs to be assigned to a boundary using the Boundary Code of the required boundary which can be found in the “List of Campaign Boundaries“. If there is a user who is mapped to multiple boundaries, the System Admin will have to add the boundary codes of all the boundaries that user is mapped to by separating them by commas in the cell to add Boundary Codes for that user.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2ac5ce31-9bd3-418f-b8f2-c1271864d225','en_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_3','Save the sheet with the updated targets for each village on the excel template .','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad9bcf8a-5da4-4b6a-a8e8-4a274ecac60b','en_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_4','Press the “Browse In My Files” button on the “Upload Target” screen and select the saved file with all targets from the system.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('37d3623c-cffa-47f0-ae31-3bfa1a8d61ad','en_MZ','USERWITHBOUNDARY_README_HEADER_3','Cases for common errors:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f807e2d6-74ef-4f88-9bbf-68e0049a32b1','en_MZ','USERWITHBOUNDARY_README_HEADER_3_DESC_1','If the user has not added boundary codes for all user entries, the system will throw an error with line number where the boundary code is missing','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('10d68c5f-b651-48a8-81b4-fde2712c2619','en_MZ','USERWITHBOUNDARY_README_HEADER_3_DESC_2','If the user deletes any of the headers in the sheet and uploads the sheet, the system will throw an error and the user will have to download the template again and reupload the correct sheet with the correct data.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3a61cc8f-1d41-4df4-a36c-0ef6b000b0fa','en_MZ','USERWITHBOUNDARY_README_MAINHEADER','Read me instructions for user upload','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0577dc8-8502-438e-863d-1041e5b3f1d2','en_MZ','USER_CREDENTIAL_BODY_DETAILS','<strong>Campaign Details:</strong><br/><strong>Campaign:</strong> {campaignName}<br/><strong>User Credential Access Link:</strong> <a href="{accessLink}">Access Link</a><br/><strong>App Download:</strong> <a href="{appLink}">App Link</a>','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e3c0f288-7210-4bd3-b745-b92a1280f4ce','en_MZ','USER_CREDENTIAL_BODY_INTRO','Hi {campaignManagerName},<br/><br/>Your health campaign setup is now complete! The app has been configured and user credentials have been generated for your team.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31d20764-52a9-46ad-afd9-d2086dd27eca','en_MZ','USER_CREDENTIAL_BODY_NOTES','<strong>Important Notes:</strong><br/>All team credentials are active and ready for use.<br/>The app includes all configurations specific to your campaign requirements.<br/>Please distribute credentials securely to authorized team members only.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8f11233d-d1f0-4042-abf8-de0f1efb188d','en_MZ','USER_CREDENTIAL_BODY_SUPPORT','<strong>Need Support?</strong><br/>If you encounter any issues during download or have questions about the setup, please contact our support team at <a href=mailto:support@egov.org.in''>support@egov.org.in</a>.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
