INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d5bf5588-98b9-47e5-8197-1c9b2c3ced93','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_1','Definir a população total e alvo após o download do modelo:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a3aa2d23-ab09-486f-9159-a9a7f668bf4f','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_1','Vá à ficha do distrito para o qual pretende definir as metas e adicione os dados da população total e alvo para cada aldeia.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('52a60f42-b0be-4aae-8638-cc3a5a796b43','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','Insira a população alvo e total de cada aldeia na ficha de cada distrito. Se alguma aldeia não tiver metas definidas, a ficha terá erros.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ea7c2538-287e-4f7e-876d-84ae9cc46b9e','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_3','Salve a planilha com o alvo atualizado e a população total de cada aldeia no modelo Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('607e0bfb-f583-416c-aaf6-dd9b11f2c3f8','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_4','Pressione o botão ''Navegar em meus arquivos'' na tela de upload da população e selecione o arquivo salvo com toda a população alvo e total do sistema.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('23baa414-56b1-40fb-a3ab-34e4cacfe00f','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_2','Casos de erros comuns:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('85ee8a10-9292-42d1-9fa8-df3da198fa5e','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_2_DESC_1','Se o usuário não tiver definido metas ou população total para cada aldeia, o sistema gerará um erro com o número da linha onde falta a população alvo ou total.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1d8e72bb-4db3-4494-9691-46ff0c0e498f','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_2_DESC_2','Se o usuário excluir qualquer aldeia da planilha ou excluir uma planilha de distrito completa e carregar a planilha, o sistema gerará um erro. O usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corrigidos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('93337c24-6226-4061-b353-06336c6c05e0','pt_MZ','BOUNDARY_MICROPLAN_README_HEADER_2_DESC_3','Se o usuário excluir qualquer um dos cabeçalhos da planilha e carregá-la, o sistema gerará um erro. O usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corrigidos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3cdf01bb-cf3f-4e89-aba1-6aac9dfce8df','pt_MZ','BOUNDARY_README_HEADER_1','Baixando modelos do Excel para definição de metas:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c4eb1147-1d1b-4a92-85a7-7e0eec30a173','pt_MZ','BOUNDARY_README_HEADER_1_DESC_1','Baixe o modelo Excel clicando no botão “Baixar modelo”.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cd925ddd-3c2f-4b90-b945-dc998df3ab3c','pt_MZ','BOUNDARY_README_HEADER_1_DESC_2','Abra o modelo Excel que foi baixado na etapa anterior e a primeira planilha que você verá é uma planilha “Leia-me”. As restantes folhas serão nomeadas de acordo com o nome dos distritos seleccionados no passo “Selecção de Limites”, tendo cada folha de distrito uma lista de todas as aldeias mapeadas para esse distrito.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a2f777a9-8953-4869-b47b-1f1076f35285','pt_MZ','BOUNDARY_README_HEADER_2','Definir metas após o download do modelo:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('989fb13a-f2f0-4d14-a704-f506c60fc569','pt_MZ','BOUNDARY_README_HEADER_2_DESC_1','Vá para a ficha do distrito para o qual deseja definir metas e adicione números na coluna “Metas” para cada Aldeia.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
