INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bbce8359-b878-4eb2-8e8c-559e126224be','pt_MZ','FACILITIES_EXCEL_README_POINTS_1','Se não houver instalações disponíveis para seleção, a aba “Lista de instalações disponíveis” no modelo estará vazia. Para criar novos dados de instalação, adicione o nome do Nome da Instalação, Tipo de Instalação, Status da Instalação, Capacidade. A coluna “Código da Instalação” precisa ser deixada em branco se esta for uma instalação nova. Caso se trate de uma instalação sendo reaproveitada (que fica disponível no template após o download) o usuário só precisa realizar o passo 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('68e691bc-2e88-4a5b-b43d-7fc57313ef9b','pt_MZ','FACILITIES_EXCEL_README_POINTS_2','Para mapear a instalação para o limite correto, o usuário precisa copiar o código de limite correto do limite da planilha “Lista de Limites de Campanha” para a qual a instalação precisa ser mapeada. Se houver uma instalação mapeada para vários limites, o administrador do sistema terá que adicionar os códigos de limite de todos os limites para os quais a instalação está mapeada, separando-os por vírgulas na célula para adicionar códigos de limite para essa instalação.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('744fbf0f-600b-41c8-bb30-8063856d97fe','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1','Criar novos dados de instalações/usar dados de instalações existentes após o download do modelo:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fb43d7b7-de5c-457c-9891-46c121a3c6f1','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_1','Se não houver instalações disponíveis para seleção, a aba “Lista de instalações disponíveis” no modelo estará vazia. Para criar novos dados de instalação, adicione o nome do Nome da Instalação, Tipo de Instalação, Status da Instalação, Capacidade e Uso da Instalação.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7c8befac-c9a2-4b1d-9ac0-0a0d04a72c41','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','Para mapear a instalação para o limite correto, o usuário precisa copiar o código de limite correto do limite da planilha “Dados do limite” para a qual a instalação precisa ser mapeada.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eacffe6c-886d-4b00-99de-be834a627c19','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_3','Salve a planilha com os detalhes da instalação inseridos no modelo Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('863a5a0b-866a-499f-87b7-b93b5f9c995e','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_4','Pressione o botão “Navegar em meus arquivos” na tela “Carregar dados da instalação” e selecione o arquivo salvo com todos os dados da instalação do sistema.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8807bf62-50b9-485f-94fa-e78bc4b89873','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_2','Desativando instalações existentes para uma campanha','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06f9e74c-3d24-4add-9aa3-442b7ebb0952','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_2_DESC_1','Depois que o usuário tiver baixado o modelo para instalações, se o sistema tiver dados de instalações existentes para serem reutilizados, o modelo será pré-preenchido com essa lista de instalações.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42a821f0-1774-4cf1-9fc1-8dc0f9dc1eb0','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_2_DESC_2','Se o usuário optar por não usar instalações específicas, ele poderá desativar essa instalação marcando o campo ''Uso da instalação'' como ''Inativo''.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6577ebda-5f0d-415f-ba1b-b9d019a5c265','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3','Casos de erros comuns:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42705a28-9127-4fae-aa5f-f06214468045','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3_DESC_1','Se o usuário tiver removido o código de limite da instalação para uma instalação existente na lista, o sistema emitirá uma mensagem de erro.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('798a7adc-1f49-40bb-afe0-5bd3859d9d36','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3_DESC_2','Se o usuário excluir alguma coluna da “Lista de Instalações Disponíveis” da planilha e carregar a planilha, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fccca221-05ef-4929-a660-edb123e1c6fc','pt_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3_DESC_3','Se o usuário excluir algum dos cabeçalhos da planilha e carregá-la, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1c97e890-913e-44aa-9934-8ef81307f046','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_1','Baixando modelos do Excel para configuração de instalações:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ba38f93-7194-4f61-b67a-6f671fddeef7','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_1_DESC_1','Baixe o modelo Excel clicando no botão “Baixar modelo”.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8724b7ee-5a43-49ff-bb61-db331927af34','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_1_DESC_2','Abra o modelo que foi baixado na etapa anterior terá 3 planilhas e a primeira planilha que você verá é uma planilha “Leia-me”. A segunda Folha denominada “Lista de Instalações Disponíveis” conterá uma lista de todas as instalações disponíveis que podem ser utilizadas na campanha. Se não houver nenhuma facilidade disponível, esta folha estará vazia. A terceira folha será denominada “Lista de Limites de Campanha” que conterá todos os limites com seus respectivos Códigos de Limites.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('98ccd85c-9620-454f-b952-8fe1a39aa833','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2','Criar novos dados de instalações/usar dados de instalações existentes após o download do modelo:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9171d4ed-0d4a-408e-ab13-12ad8003b2f2','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_1','Se não houver instalações disponíveis para seleção, a aba “Lista de instalações disponíveis” no modelo estará vazia. Para criar novos dados de instalação, adicione o nome do Nome da Instalação, Tipo de Instalação, Status da Instalação, Capacidade. A coluna “Código da Instalação” precisa ser deixada em branco se esta for uma instalação nova. Caso se trate de uma instalação sendo reaproveitada (que fica disponível no template após o download) o usuário só precisa realizar o passo 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('17fa6492-d5c5-40b4-b321-cb1e2a62e63d','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_2','Para mapear a instalação para o limite correto, o usuário precisa copiar o código de limite correto do limite da planilha “Lista de Limites de Campanha” para a qual a instalação precisa ser mapeada. Se houver uma instalação mapeada para vários limites, o administrador do sistema terá que adicionar os códigos de limite de todos os limites para os quais a instalação está mapeada, separando-os por vírgulas na célula para adicionar códigos de limite para essa instalação.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('775d5a64-5600-4a92-a245-4fcbcfcdd349','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_3','Salve a planilha com as metas atualizadas para cada aldeia no modelo Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('33f69a1c-4bcd-4135-b197-8f6c487e434e','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_4','Pressione o botão “Browse In My Files” na tela “Upload Facility Data” e selecione o arquivo salvo com todos os alvos do sistema.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ec466a21-dab2-4aba-9ece-ffc44645d6e1','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_5','Desativando Instalações existentes para uma campanha.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad96541c-61e9-436c-83a0-f9989709f643','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_6','Depois que o usuário tiver baixado o modelo para instalações, se o sistema tiver dados de instalações existentes para serem reutilizados, o modelo será pré-preenchido com essa lista de instalações.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1f43ee13-22f3-4d63-bd1e-f7d610a4a4c3','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_7','Se o usuário optar por não usar instalações específicas, ele poderá excluir as linhas de dados dessas instalações específicas que precisam ser removidas e carregar a planilha apenas com as instalações necessárias para a campanha com os códigos de limite corretos mapeados para essas instalações.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67c235f5-c565-4077-8457-6fc457d2d524','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1','Caso em que não há dados da instalação no sistema:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f219fdad-9ef8-45ef-bef3-16eb0ec9b5ff','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_1','Passo 1: Quando não houver dados de instalações no sistema, o modelo “Lista de instalações disponíveis” estará vazio. Para cada instalação adicionada, o usuário precisa inserir o nome da instalação (deve ser exclusivo), tipo de instalação (armazém/instalação de saúde), status da instalação (temporário/permanente), capacidade (entrada de número)','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5960a1e4-ef67-4e14-a643-3098bbcda31a','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_2','Passo 2: Para mapear as instalações para um determinado limite, o usuário precisa copiar o Código do Limite correto da planilha “Dados do Limite”. Se houver mais de um limite para o qual uma instalação precisa ser mapeada, o usuário poderá adicionar todos os códigos de limite separados por vírgulas','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fe3b794b-6f44-4440-8fa1-f36fce93df45','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_3','Etapa 3: Para cada instalação, o usuário precisa adicionar Ativo ou Inativo para todas as instalações na coluna “Uso da Instalação”. Todas as Instalações marcadas como “Ativas” serão utilizadas na campanha que está sendo criada, as marcadas como “Inativas” não serão utilizadas na campanha que está sendo criada.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b9dc7e91-5b8a-40a0-97d2-7bb7fcdd8c61','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_4','Passo 4: Depois que todas as facilidades forem adicionadas, o usuário precisa salvar o arquivo em seu sistema e fazer upload do arquivo pressionando a opção “Navegar em Meus Arquivos”.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92229aa3-ad74-4ae4-bc3a-ad84d1b35a0c','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2','Caso em que existem dados de instalações existentes no sistema:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e3c8a3f9-719b-430d-a1ad-84d3bc8e84d9','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_1','Passo 1: Ao abrir o modelo de instalação baixado, consulte a folha Lista de instalações disponíveis. Para instalações existentes, adicione entradas na coluna Código de limite. Você pode encontrar os códigos de limite na planilha Dados de limite. Se uma instalação mapear vários limites, separe os códigos com vírgulas.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('61ce3f68-36ee-450f-b935-c699a85796d8','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Etapa 2: nesta etapa, o usuário terá que adicionar entradas na coluna Uso da instalação com entradas válidas sendo Ativas ou Inativas, onde o usuário pode definir o uso de uma instalação como Ativo se a instalação estiver sendo usada para uma campanha ou então pode ser definida como Inativa. As entradas na coluna Uso da Instalação precisam ser adicionadas para todas as entradas.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c9e12649-8503-4386-84e9-6bf50dee93a3','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_3','Etapa 3: Para adicionar novas instalações que não estão presentes na lista de instalações existentes, o usuário precisa inserir o nome da instalação (deve ser exclusivo), tipo de instalação (armazém/instalação de saúde), status da instalação (temporário/permanente), capacidade (entrada de número), código de limite (da folha de dados de limite) e uso da instalação (ativo/inativo) conforme explicado anteriormente','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('00c87384-7e66-4c1d-8044-a757ae2d220e','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_4','Passo 4: Depois que todas as facilidades forem adicionadas, o usuário precisa salvar o arquivo em seu sistema e fazer upload do arquivo pressionando a opção “Navegar em Meus Arquivos”.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad325897-71ae-4961-9461-96dfcd7305b7','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_3','Casos de erros comuns:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('24a7b0a1-9d25-4d37-9a93-ac2a77dedab4','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_1','Se o usuário tiver removido os códigos de instalação de uma instalação existente na lista, o sistema criará uma instalação duplicada com esses valores de coluna.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5dff5563-18bc-419d-8f30-f3b1f50ada75','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_2','Se o usuário excluir alguma coluna da “Lista de Instalações Disponíveis” da planilha e carregar a planilha, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8dab78a1-30cb-42a9-87c1-5d33c8757a9a','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_3','Se o usuário excluir algum dos cabeçalhos da planilha e carregá-la, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06849aae-9ef6-4c0c-a668-7ba4b2114b7b','pt_MZ','FACILITYWITHBOUNDARY_README_MAINHEADER','Leia-me as instruções para upload de instalações','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
