INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c0316d53-b7e5-4518-b43c-d7d8071d46b7','pt_MZ','MP_VILLAGE_TERRAIN','Terreno da aldeia','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('918dea1b-3adf-460c-9a4b-0959352ad213','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_1','Se não houver instalações disponíveis para seleção, a aba “Lista de instalações disponíveis” no modelo estará vazia. Para criar novos dados de instalação, adicione o nome do Nome da Instalação, Tipo de Instalação, Status da Instalação, Capacidade. A coluna “Código da Instalação” precisa ser deixada em branco se esta for uma instalação nova. Caso se trate de uma instalação sendo reaproveitada (que fica disponível no template após o download) o usuário só precisa realizar o passo 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a64ea0a2-0967-4537-ac2a-87442db46ced','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_10','Se o usuário excluir algum dos cabeçalhos da planilha e carregá-la, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51b84789-8f23-4e00-8ccc-c03fc1a7993b','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_2','Para mapear a instalação para o limite correto, o usuário precisa copiar o código de limite correto do limite da planilha “Lista de Limites de Campanha” para a qual a instalação precisa ser mapeada. Se houver uma instalação mapeada para vários limites, o administrador do sistema terá que adicionar os códigos de limite de todos os limites para os quais a instalação está mapeada, separando-os por vírgulas na célula para adicionar códigos de limite para essa instalação.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('449867d8-f428-4525-9e82-d108deb38565','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_3','Salve a planilha com as metas atualizadas para cada aldeia no modelo Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('084f0fb6-fd53-4325-88bd-419e8f322c73','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_4','Pressione o botão “Browse In My Files” na tela “Upload Facility Data” e selecione o arquivo salvo com todos os alvos do sistema.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d0d7df72-e684-42b6-aeae-4f2e4a080a24','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_5','Desativando Instalações existentes para uma campanha.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f185c381-57b4-445a-b883-8dd2a31e23b1','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_6','Após o usuário ter baixado o modelo para Instalações, se o sistema tiver dados de instalações existentes para serem reutilizados, o modelo será pré-preenchido com essa lista de Instalações.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9fd1bc5-8a60-4996-bbd0-f9103ffe412e','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_7','Se o usuário optar por não usar instalações específicas, ele poderá excluir as linhas de dados dessas instalações específicas que precisam ser removidas e carregar a planilha apenas com as instalações necessárias para a campanha com os códigos de limite corretos mapeados para essas instalações.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6bfedab0-181a-4ede-aa3d-bbd49e69bc40','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_8','Se o usuário tiver removido os códigos de instalação de uma instalação existente na lista, o sistema criará uma instalação duplicada com esses valores de coluna.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a28960bc-111c-4711-bfea-d76790c0eadd','pt_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_9','Se o usuário excluir alguma coluna da “Lista de Instalações Disponíveis” da planilha e carregar a planilha, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7914d98-5df2-4da6-8f30-529ec13b1c9d','pt_MZ','MR_DN_FACILITY_EXCEL_HEADER_1','Criação de novos dados de instalações/utilização de dados de instalações existentes após o download do modelo','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
