INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('50cab8b2-de4f-4255-b6ce-4aea7edbb80c','pt_MZ','UNIFIED_CONSOLE_README_HEADER_1','Upload de microplano de folha única','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67a22e4a-346a-4961-a639-abcdbf4cf8de','pt_MZ','UNIFIED_CONSOLE_README_HEADER_1_DESC_1','Baixe o modelo de microplano para adicionar detalhes de instalações, atribuições de usuários e dados de destino em um só lugar. A planilha inclui menus suspensos para selecionar limites, tipos de instalações, funções e outros campos obrigatórios.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5aee4a2b-1438-4086-92bc-94c402d8720c','pt_MZ','UNIFIED_CONSOLE_README_HEADER_1_DESC_2','Preencha todos os campos obrigatórios, atualize as metas para cada limite e revise as entradas para verificar a precisão antes de enviar o arquivo concluído. Entradas ausentes, colunas excluídas ou cabeçalhos modificados resultarão em erros de upload. Assim que a planilha estiver concluída, salve-a e carregue-a para carregar todos os dados do microplano da campanha.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c06ba316-473f-46b4-bea2-6f83cd196e32','pt_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1','Orientações para preenchimento da ficha de usuário','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d3d3c645-5301-471b-838b-4a30ffb1beda','pt_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_1','Consulte a planilha ''Funções do usuário'' para ler e compreender a acessibilidade de cada função.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('17eaae00-9703-42c8-a365-7a3b3a600f19','pt_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','Por favor, preencha os dados do usuário (Nome, número de contato e e-mail) em cada uma das planilhas pertencentes à função de acordo.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0fe3db79-6c3a-44db-86e3-18f3504cf628','pt_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_3','Não atribua o usuário duplicado nas funções de aprovador de estimativa de microplano e aprovador de estimativa de microplano nacional.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dfa22f3d-5e5b-45e4-841f-f5c092ba4105','pt_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_4','Não atribua usuários duplicados nas funções de atribuidor de limites de instalações e de atribuidor de limites de instalações nacionais.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3a1940ca-41bb-42da-b43c-ba30be064636','pt_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_5','Não atribua usuários duplicados nas funções de aprovador de dados populacionais e de aprovador de dados populacionais nacionais.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('273d5f48-3def-43e1-a760-2174516b5e8a','pt_MZ','USERWITHBOUNDARY_README_HEADER_1','Baixando modelos do Excel para criação de usuários:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3863ff73-4290-446d-957e-998b1d0df698','pt_MZ','USERWITHBOUNDARY_README_HEADER_1_DESC_1','Baixe o modelo Excel clicando no botão “Baixar modelo”.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('196a4667-5c14-45da-89bf-ee330cb5a649','pt_MZ','USERWITHBOUNDARY_README_HEADER_1_DESC_2','Abra o modelo Excel que foi baixado na etapa anterior terá 3 planilhas e a primeira planilha que você verá é uma planilha “Leia-me”. A segunda Planilha denominada “Criar Lista de Usuários“ que será uma planilha vazia onde o usuário deverá inserir os dados para criar usuários para a campanha. A terceira folha será denominada “Lista de Limites de Campanha” que terá todos os limites selecionados na etapa “Detalhes dos Limites” com seus respectivos códigos de limites.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('128144d1-da72-4893-b3e5-c12a9febfffa','pt_MZ','USERWITHBOUNDARY_README_HEADER_2','Criando usuários para a campanha:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3b010c6a-d1ae-4f7e-b15d-6a5d9837a297','pt_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_1','O administrador do sistema terá que criar uma entrada separada para cada usuário. O administrador do sistema terá que adicionar o nome do usuário (obrigatório), número de telefone (obrigatório), função (obrigatório), tipo de emprego (obrigatório), código de limite (obrigatório). Se houver um usuário mapeado para diversas funções, o administrador do sistema terá que adicionar todas as funções para as quais esse usuário está mapeado, separando-as por vírgulas na célula para adicionar funções para esse usuário.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4702cbd-b89e-476b-b68f-f37c2785f930','pt_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_2','Cada usuário criado precisa ser atribuído a um limite usando o Código de Limite do limite necessário, que pode ser encontrado na “Lista de Limites de Campanha“. Se houver um usuário mapeado para vários limites, o administrador do sistema terá que adicionar os códigos de limite de todos os limites para os quais o usuário está mapeado, separando-os por vírgulas na célula para adicionar códigos de limite para esse usuário.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57ed06b3-4ee9-434d-8eaf-60e1c43e6bff','pt_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_3','Salve a planilha com as metas atualizadas para cada aldeia no modelo Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('028c5015-cdfe-4f4e-b22f-da238e89143b','pt_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_4','Pressione o botão “Browse In My Files” na tela “Upload Target” e selecione o arquivo salvo com todos os alvos do sistema.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d8bb4c75-beb1-434b-9c23-34ba3483df54','pt_MZ','USERWITHBOUNDARY_README_HEADER_3','Casos de erros comuns:','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4cd00f1-948f-4e51-a137-a4b8a2cf1866','pt_MZ','USERWITHBOUNDARY_README_HEADER_3_DESC_1','Se o usuário não adicionou códigos de limite para todas as entradas do usuário, o sistema gerará um erro com o número da linha onde o código de limite está faltando','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('afdbf45b-0a1b-4494-a49a-45fa7e5228aa','pt_MZ','USERWITHBOUNDARY_README_HEADER_3_DESC_2','Se o usuário excluir algum dos cabeçalhos da planilha e carregá-la, o sistema gerará um erro e o usuário terá que baixar o modelo novamente e recarregar a planilha correta com os dados corretos.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67f5fb96-d19f-4c2c-9627-644116fa055e','pt_MZ','USERWITHBOUNDARY_README_MAINHEADER','Leia-me instruções para upload do usuário','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db6af016-5ea4-4637-b174-994380dc0ec4','pt_MZ','USER_CREDENTIAL_BODY_DETAILS','<strong>Detalhes da campanha:</strong><br/><strong>Campanha:</strong> {campaignName}<br/><strong>Link de acesso à credencial do usuário:</strong> <a href="{accessLink}">Link de acesso</a><br/><strong>Download do aplicativo:</strong> <a href="{appLink}">Link do aplicativo</a>','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1df10847-bc6d-4646-aae7-7a50d974c3f0','pt_MZ','USER_CREDENTIAL_BODY_INTRO','Olá, {campaignManagerName},<br/><br/>A configuração da sua campanha de saúde foi concluída. O aplicativo foi configurado e as credenciais de usuário foram geradas para sua equipe.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f2b9cd7a-e1aa-4ef6-af03-0c21a7ef9790','pt_MZ','USER_CREDENTIAL_BODY_NOTES','<strong>Observações importantes:</strong><br/>Todas as credenciais da equipe estão ativas e prontas para uso.<br/>O aplicativo inclui todas as configurações específicas para os requisitos da sua campanha.<br/>Distribua as credenciais com segurança apenas para membros autorizados da equipe.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a86a7b81-d95e-45af-8644-bf2ed67f492e','pt_MZ','USER_CREDENTIAL_BODY_SUPPORT','<strong>Precisa de suporte?</strong><br/>Se você encontrar algum problema durante o download ou tiver dúvidas sobre a configuração, entre em contato com nossa equipe de suporte em <a href=mailto:support@egov.org.in''>support@egov.org.in</a>.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c9725e15-95ec-4f4f-b2d2-438eccdc9fcd','pt_MZ','USER_CREDENTIAL_BODY_THANKS','Sua campanha está pronta para ser publicada.<br/><br/>Obrigado por usar o Console para gerenciar sua campanha de saúde.<br/>Atenciosamente,<br/>Equipe do Console','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('add103cf-fa77-4dff-a968-778fe1cac978','pt_MZ','USER_CREDENTIAL_SUBJECT','{campaignName} - Credenciais da sua equipe e aplicativo pronto para download','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
