INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca27588c-9695-4fb0-a8f4-d6fed26122b6','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_1','Définition de la population totale et cible une fois le modèle téléchargé :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bc7b37c6-a864-4726-8b97-d3e9c126a85e','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_1','Accédez à la feuille du district pour lequel vous souhaitez définir des objectifs et ajoutez les données de population totale et cible pour chaque village.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('410995c2-c8f7-4781-bcad-6413cbc8c218','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','Entrez la population cible et la population totale de chaque village dans la feuille de chaque district. Si un village n’a pas d’objectifs fixés, la feuille comportera des erreurs.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('215af08a-2102-4886-b8e3-45ade72dc2bb','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_3','Enregistrez la feuille avec la cible mise à jour et la population totale pour chaque village sur le modèle Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6db55d31-0750-4f34-9d37-699a8741879b','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_1_DESC_4','Appuyez sur le bouton « Parcourir mes fichiers » sur l''écran de téléchargement de la population et sélectionnez le fichier enregistré avec toute la population cible et totale du système.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0e56cd75-7295-4177-ae77-4c855b922b7e','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_2','Cas d''erreurs courantes :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ee5a7055-ec54-4a4f-932c-dbdb60a2e7f2','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_2_DESC_1','Si l''utilisateur n''a pas défini d''objectifs ou de population totale pour chaque village, le système générera une erreur avec le numéro de ligne où l''objectif ou la population totale est manquant.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d08608c1-f902-4890-8374-60bbecab4ab1','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_2_DESC_2','Si l''utilisateur supprime un village de la feuille ou supprime une feuille de district complète et télécharge la feuille, le système générera une erreur. L''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données corrigées.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0a55d4be-6c75-4957-be42-2a208d48c993','fr_MZ','BOUNDARY_MICROPLAN_README_HEADER_2_DESC_3','Si l''utilisateur supprime l''un des en-têtes de la feuille et télécharge la feuille, le système générera une erreur. L''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données corrigées.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('383f5b8f-ddb7-458f-bbae-24d7f83775ca','fr_MZ','BOUNDARY_README_HEADER_1','Téléchargement de modèles Excel pour définir des objectifs :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1cc8ffc9-a1cd-416c-a9e6-4f022bd6d9fa','fr_MZ','BOUNDARY_README_HEADER_1_DESC_1','Téléchargez le modèle Excel en cliquant sur le bouton « Télécharger le modèle ».','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bcb4fc5b-da0b-4d68-9baf-553ca8b21f93','fr_MZ','BOUNDARY_README_HEADER_1_DESC_2','Ouvrez le modèle Excel téléchargé à l''étape précédente et la première feuille que vous verrez est une feuille « Lisez-moi ». Les feuilles restantes seront nommées d''après le nom des districts sélectionnés à l''étape « Sélection des limites », chaque feuille de district comportant une liste de tous les villages cartographiés dans ce district.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bdbbf39a-11ab-4740-a8c9-ebb448c3d1ca','fr_MZ','BOUNDARY_README_HEADER_2','Définition des objectifs une fois le modèle téléchargé :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ecc1e76d-60ee-47c4-a9f4-8ddd2ba9184a','fr_MZ','BOUNDARY_README_HEADER_2_DESC_1','Accédez à la feuille du district pour lequel vous souhaitez définir des objectifs et ajoutez des chiffres dans la colonne « Cibles » pour chaque village.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('32a967a4-807a-454d-b258-432b1912f9eb','fr_MZ','BOUNDARY_README_HEADER_2_DESC_2','Entrez les objectifs pour chaque village dans la feuille de chaque district sous la colonne « Cible au niveau de la limite sélectionnée ». Si un village n’a pas d’objectifs fixés, la feuille comportera des erreurs.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e346d9e8-9816-4b15-9ee7-0c49a2093c91','fr_MZ','BOUNDARY_README_HEADER_2_DESC_3','Enregistrez la feuille avec les objectifs mis à jour pour chaque village sur le modèle Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
