INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1ae2f1f0-afc7-4ed9-8521-efd083d34444','fr_MZ','ES_CAMPAIGN_TIMELINE','Chronologie','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a9d9d2e1-6583-42ce-8dac-2841f03b40b1','fr_MZ','FACILITIES_EXCEL_README_POINTS_1','S''il n''y a aucune installation disponible pour la sélection, l''onglet « Liste des installations disponibles » dans le modèle sera vide. Pour créer de nouvelles données d''installation, ajoutez le nom de l''installation, le type d''installation, l''état de l''installation et la capacité. La colonne « Code d''établissement » doit rester vide s''il s''agit d''un nouvel établissement. S''il s''agit d''une installation en cours de réutilisation (qui est disponible dans le modèle après le téléchargement), l''utilisateur n''a qu''à effectuer l''étape 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('356a8722-8e21-4c60-9794-7928738f9f08','fr_MZ','FACILITIES_EXCEL_README_POINTS_2','Pour mapper l''installation à la limite correcte, l''utilisateur doit copier le code de limite correct de la limite de la feuille « Liste des limites de campagne » sur laquelle l''installation doit être cartographiée. S''il existe une installation mappée à plusieurs limites, l''administrateur système devra ajouter les codes de limite de toutes les limites auxquelles cette installation est mappée en les séparant par des virgules dans la cellule pour ajouter des codes de limite pour cette installation.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('388a6f41-807a-4949-8fa1-6e183edd18a6','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1','Création de nouvelles données d''installation/utilisation des données d''installation existantes une fois le modèle téléchargé :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('82c52e22-dd82-40a1-aeaf-6d8dffa388d2','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_1','S''il n''y a aucune installation disponible pour la sélection, l''onglet « Liste des installations disponibles » dans le modèle sera vide. Pour créer de nouvelles données d''installation, ajoutez le nom de l''installation, le type d''installation, l''état de l''installation, la capacité et l''utilisation de l''installation.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bd993a40-ddc2-492e-a293-186a2e0f4734','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','Pour mapper l''installation à la limite correcte, l''utilisateur doit copier le code de limite correct de la limite de la feuille « Données de limite » sur laquelle l''installation doit être cartographiée.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7c25ec2-4022-4998-8bc6-bc0c699b6d61','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_3','Enregistrez la feuille avec les détails de l''établissement saisis dans le modèle Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fdf8ee79-eec2-4c1a-9a9d-899378628117','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_4','Appuyez sur le bouton « Parcourir mes fichiers » sur l''écran « Télécharger les données de l''installation » et sélectionnez le fichier enregistré avec toutes les données de l''installation du système.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('43fa50c2-3dac-415b-a334-cff608b8e777','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_2','Désactivation des installations existantes pour une campagne','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2ffd40ae-648b-4a11-97e2-67682bdd8017','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_2_DESC_1','Une fois que l''utilisateur a téléchargé le modèle pour les installations, si le système dispose de données d''installation existantes à réutiliser, le modèle sera pré-rempli avec cette liste d''installations.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c5a9c35-e74a-4f60-b5c3-c77564062694','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_2_DESC_2','Si l''utilisateur choisit ensuite de ne pas utiliser des installations spécifiques, il peut désactiver ces installations en marquant le champ « Utilisation des installations » comme « Inactif ».','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('001a51a5-d28f-48e7-97a5-d98217f4f60a','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3','Cas d''erreurs courantes :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67b071fc-b01b-43ad-92ac-45059492b854','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3_DESC_1','Si l''utilisateur a supprimé le code de limite d''installation pour une installation existante dans la liste, le système affichera un message d''erreur.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4aa3e8bf-ef68-4790-9430-04bb39c5f543','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3_DESC_2','Si l''utilisateur supprime des colonnes de la « Liste des installations disponibles » de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('885b1b2b-0ca9-4f37-971a-a5f1e46ea8f7','fr_MZ','FACILITYWITHBOUNDARY_MICROPLAN_README_HEADER_3_DESC_3','Si l''utilisateur supprime l''un des en-têtes de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7974fa7d-de88-42e0-9a03-4d50c14607e4','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_1','Téléchargement de modèles Excel pour la configuration des installations :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3a764230-f0de-4dd1-afd1-b1f9782f1bfc','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_1_DESC_1','Téléchargez le modèle Excel en cliquant sur le bouton « Télécharger le modèle ».','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('985e3558-1017-4634-b990-db4a5a49bb5a','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_1_DESC_2','Ouvrez le modèle téléchargé à l''étape précédente et comportera 3 feuilles et la première feuille que vous verrez est une feuille « Lisez-moi ». La deuxième feuille intitulée « Liste des installations disponibles » contiendra une liste de toutes les installations disponibles pouvant être utilisées dans la campagne. S''il n''y a aucune installation disponible, cette feuille sera vide. La troisième feuille sera nommée « Liste des limites de campagne » et contiendra toutes les limites avec leurs codes de limites respectifs.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06a18f10-a342-4083-8873-4bf2c1151fbb','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2','Création de nouvelles données d''installation/utilisation des données d''installation existantes une fois le modèle téléchargé :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('278aff15-d838-4799-9c41-7d4e77bc21aa','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_1','S''il n''y a aucune installation disponible pour la sélection, l''onglet « Liste des installations disponibles » dans le modèle sera vide. Pour créer de nouvelles données d''installation, ajoutez le nom de l''installation, le type d''installation, l''état de l''installation et la capacité. La colonne « Code d''établissement » doit rester vide s''il s''agit d''un nouvel établissement. S''il s''agit d''une installation en cours de réutilisation (qui est disponible dans le modèle après le téléchargement), l''utilisateur n''a qu''à effectuer l''étape 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6db41824-b915-4585-ab51-4564853c8f0e','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_2','Pour mapper l''installation à la limite correcte, l''utilisateur doit copier le code de limite correct de la limite de la feuille « Liste des limites de campagne » sur laquelle l''installation doit être cartographiée. S''il existe une installation mappée à plusieurs limites, l''administrateur système devra ajouter les codes de limite de toutes les limites auxquelles cette installation est mappée en les séparant par des virgules dans la cellule pour ajouter des codes de limite pour cette installation.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5e647fcb-d969-4d33-958c-5efca4bd1783','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_3','Enregistrez la feuille avec les objectifs mis à jour pour chaque village sur le modèle Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('71bf4a0a-ffd4-41e5-9518-2cd8de2e1be2','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_4','Appuyez sur le bouton « Parcourir mes fichiers » sur l''écran « Télécharger les données de l''installation » et sélectionnez le fichier enregistré avec toutes les cibles du système.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e00bec58-e2d1-41a1-a554-e3c1261ab60b','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_5','Désactivation des installations existantes pour une campagne.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3b54efdb-0c34-496d-b34a-ab58d0f6385a','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_6','Une fois que l''utilisateur a téléchargé le modèle pour les installations, si le système dispose de données d''installation existantes à réutiliser, le modèle sera pré-rempli avec cette liste d''installations.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c92e98f4-5da7-4416-800a-602e8ceea6c6','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_DESC_7','Si l''utilisateur choisit ensuite de ne pas utiliser des installations spécifiques, il peut supprimer les lignes de données pour ces installations spécifiques qui doivent être supprimées et télécharger la feuille avec uniquement les installations nécessaires à la campagne avec les codes de limite corrects mappés à ces installations.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('721ce155-77b4-42d5-af31-f2d83d182996','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1','Cas où il n''y a pas de données d''installation dans le système :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('66b4f820-719d-429a-882d-c4ffcc512f56','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_1','Étape 1 : Lorsqu''il n''y a pas de données d''établissement dans le système, le modèle « Liste des établissements disponibles » sera vide. Pour chaque établissement ajouté, l''utilisateur doit saisir le nom de l''établissement (doit être unique), le type d''établissement (entrepôt/établissement de santé), le statut de l''établissement (temporaire/permanent), la capacité (saisie du numéro)','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d1d62f7b-1bab-45a8-bd1b-e2a653e8e8b7','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_2','Étape 2 : Pour cartographier les installations sur une limite donnée, l''utilisateur doit copier le code de limite correct à partir de la feuille « Données de limite ». S''il existe plusieurs limites auxquelles une installation doit être mappée, l''utilisateur peut ajouter tous les codes de limite séparés par des virgules.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('adaf122c-6860-4ac5-be7f-97d4462ad8fe','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_3','Étape 3 : Pour chaque installation, l''utilisateur doit ajouter Actif ou Inactif pour toutes les installations dans la colonne « Utilisation des installations ». Toutes les installations marquées comme « Actives » seront utilisées dans la campagne en cours de création, celles marquées « Inactives » ne seront pas utilisées dans la campagne en cours de création.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1cd0be35-63f3-4373-87a2-08af4243306f','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_4','Étape 4 : Une fois toutes les fonctionnalités ajoutées, l''utilisateur doit enregistrer le fichier sur son système et télécharger le fichier en appuyant sur l''option « Parcourir dans mes fichiers ».','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d2fd995b-27fb-4b7c-a40e-371d1f24017f','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2','Cas où il existe des données d''installation existantes dans le système :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('05694fdd-e9cd-4cb3-8af8-920db5974a0a','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_1','Étape 1 : Lorsque vous ouvrez le modèle d''installation téléchargé, veuillez vous référer à la feuille Liste des installations disponibles. Pour les installations existantes, veuillez ajouter des entrées dans la colonne Code limite. Vous pouvez trouver les codes de limites dans la feuille de données des limites. Si une installation correspond à plusieurs limites, veuillez séparer les codes par des virgules.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('89663d4e-2c08-4247-84a1-344f4480651c','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Étape 2 : Dans cette étape, l''utilisateur devra ajouter des entrées dans la colonne Utilisation de l''installation avec des entrées valides étant soit Actives, soit Inactives, où l''utilisateur peut définir l''utilisation d''une installation sur Active si l''installation est utilisée pour une campagne ou bien peut être définie sur Inactif. Les entrées dans la colonne Utilisation des installations doivent être ajoutées pour toutes les entrées.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7c26440-82fa-4ddc-a59d-53464fb39636','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_3','Étape 3 : Pour ajouter de nouvelles installations qui ne sont pas présentes dans la liste des installations existantes, l''utilisateur doit saisir le nom de l''installation (doit être unique), le type d''installation (entrepôt/établissement de santé), le statut de l''installation (temporaire/permanent), la capacité (saisie numérique), le code de limite (à partir de la fiche de données des limites) et l''utilisation de l''installation (active/inactive), comme expliqué précédemment.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6d690c7f-9bc0-4caa-832c-52393644cdbe','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_4','Étape 4 : Une fois toutes les fonctionnalités ajoutées, l''utilisateur doit enregistrer le fichier sur son système et télécharger le fichier en appuyant sur l''option « Parcourir dans mes fichiers ».','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc06eec6-f384-4d9a-9ff1-0eb08589c472','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_3','Cas d''erreurs courantes :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bb76141a-1002-4dd9-a039-2a7e619d9351','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_1','Si l''utilisateur a supprimé les codes d''établissement pour un établissement existant dans la liste, le système créera un établissement en double avec ces valeurs de colonne.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ff1f805-699a-42c0-8361-3fd21c96b800','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_2','Si l''utilisateur supprime des colonnes de la « Liste des installations disponibles » de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a30405c8-1498-49e6-aa32-c24dfdaf361e','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_3_DESC_3','Si l''utilisateur supprime l''un des en-têtes de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('04557f9f-f093-49c6-a417-3db35ef43411','fr_MZ','FACILITYWITHBOUNDARY_README_MAINHEADER','Lisez-moi les instructions pour le téléchargement des installations','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
