INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6168207a-4d62-4414-9fa4-c28ee2ca82ea','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_1','S''il n''y a aucune installation disponible pour la sélection, l''onglet « Liste des installations disponibles » dans le modèle sera vide. Pour créer de nouvelles données d''installation, ajoutez le nom de l''installation, le type d''installation, l''état de l''installation et la capacité. La colonne « Code d''établissement » doit rester vide s''il s''agit d''un nouvel établissement. S''il s''agit d''une installation en cours de réutilisation (qui est disponible dans le modèle après le téléchargement), l''utilisateur n''a qu''à effectuer l''étape 2.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9d944bbe-fd85-4298-941d-299b8b59897f','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_10','Si l''utilisateur supprime l''un des en-têtes de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6cc5c3d2-6996-43bb-bbf2-fd844d4270b1','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_2','Pour mapper l''installation à la limite correcte, l''utilisateur doit copier le code de limite correct de la limite de la feuille « Liste des limites de campagne » sur laquelle l''installation doit être cartographiée. S''il existe une installation mappée à plusieurs limites, l''administrateur système devra ajouter les codes de limite de toutes les limites auxquelles l''installation est mappée en les séparant par des virgules dans la cellule pour ajouter des codes de limite pour cette installation.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c90b54a2-7583-418a-8a5c-a935d9730899','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_3','Enregistrez la feuille avec les objectifs mis à jour pour chaque village sur le modèle Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e1f73706-fb36-48af-acfb-f5c09da92774','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_4','Appuyez sur le bouton « Parcourir mes fichiers » sur l''écran « Télécharger les données de l''installation » et sélectionnez le fichier enregistré avec toutes les cibles du système.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9a106a39-94fe-44d6-805b-94c2603669fe','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_5','Désactivation des installations existantes pour une campagne.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dce194fe-dd7c-4444-a7a6-3d6ec14ed4be','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_6','Une fois que l''utilisateur a téléchargé le modèle pour les installations, si le système dispose de données d''installation existantes à réutiliser, le modèle sera pré-rempli avec la liste des installations.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('585f451f-712a-4ddf-ab31-d4262cb2367e','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_7','Si l''utilisateur choisit ensuite de ne pas utiliser des installations spécifiques, il peut supprimer les lignes de données pour ces installations spécifiques qui doivent être supprimées et télécharger la feuille avec uniquement les installations nécessaires à la campagne avec les codes de limite corrects mappés à ces installations.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('73305bae-eac8-44c5-86d1-8027a2401ab1','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_8','Si l''utilisateur a supprimé les codes d''établissement pour un établissement existant dans la liste, le système créera un établissement en double avec ces valeurs de colonne.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92611d09-6d04-488b-9d7f-b00a908af11e','fr_MZ','MR_DN_FACILITIES_EXCEL_README_POINTS_9','Si l''utilisateur supprime des colonnes de la « Liste des installations disponibles » de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa7fc0a1-59f8-4ecf-8276-bfdb42fbf0ec','fr_MZ','MR_DN_FACILITY_EXCEL_HEADER_1','Création de nouvelles données d''installation/utilisation des données d''installation existantes une fois le modèle téléchargé','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
