INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2fb1e990-039f-41e5-8f81-38a61fe2bb40','fr_MZ','MR_DN_POPULATION_EXCEL_README_POINTS_1','Accédez à la feuille du district pour lequel vous souhaitez définir des objectifs et ajoutez des chiffres dans la colonne « Cibles » pour chaque village.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('857702c1-ce7a-490c-b140-138eb64420d1','fr_MZ','MR_DN_POPULATION_EXCEL_README_POINTS_2','Entrez les objectifs pour chaque village dans la feuille de chaque district sous la colonne « Cibles ». Si un village n’a pas d’objectifs définis, la feuille comportera des erreurs.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
