INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9daaa80-7d79-4485-b26e-2f70c172dda9','fr_MZ','MR_DN_POPULATION_EXCEL_README_POINTS_5','Si l''utilisateur n''a pas défini d''objectifs pour chaque village, le système générera une erreur avec le numéro de ligne où les cibles sont manquantes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6fa90fa0-ce30-4844-adb9-3cf9839b03ba','fr_MZ','MR_DN_POPULATION_EXCEL_README_POINTS_6','Si l''utilisateur supprime un village de la feuille ou supprime une feuille de district complète et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
