INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4b476d9a-42d7-4ccf-b1eb-25d4a84bd297','fr_MZ','UNIFIED_CONSOLE_README_HEADER_1','Téléchargement Microplan d''une seule feuille','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e163bf6-efc7-4bd8-9eff-0f7d03421b8a','fr_MZ','UNIFIED_CONSOLE_README_HEADER_1_DESC_1','Téléchargez le modèle de microplan pour ajouter les détails des installations, les affectations des utilisateurs et les données cibles en un seul endroit. La feuille comprend des listes déroulantes pour sélectionner les limites, les types d''installations, les rôles et d''autres champs obligatoires.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c2b822e-7e2d-4515-abce-3f24be271d9a','fr_MZ','UNIFIED_CONSOLE_README_HEADER_1_DESC_2','Remplissez tous les champs obligatoires, mettez à jour les cibles pour chaque limite et vérifiez l''exactitude des entrées avant de télécharger le fichier complété. Les entrées manquantes, les colonnes supprimées ou les en-têtes modifiés entraîneront des erreurs de téléchargement. Une fois la feuille terminée, enregistrez-la et téléchargez-la pour charger toutes les données du microplan de la campagne.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aceb5b11-3fbb-4ec3-9da8-d8025a2bbef8','fr_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1','Directives pour remplir la fiche utilisateur','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e5ebda6e-f7b7-4a4e-aab7-7ba26d7f782e','fr_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_1','Veuillez parcourir la fiche « Rôles utilisateur » pour lire et comprendre l''accessibilité de chaque rôle.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6e899ee9-0143-457c-9b0f-7df6682c1d45','fr_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_2','Veuillez remplir les détails de l''utilisateur (nom, numéro de contact et e-mail) dans chacune des feuilles appartenant au rôle en conséquence.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7856e7eb-db45-4fd5-9c91-0c86f9ec4ac1','fr_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_3','Veuillez ne pas attribuer l''utilisateur en double aux rôles d''approbateur d''estimation Microplan et d''approbateur d''estimation Microplan national.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9d332ce8-58d5-4c0b-98c6-bc4b9a0ee540','fr_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_4','Veuillez ne pas attribuer d''utilisateurs en double dans les rôles d''attribution de limites d''installation et d''attribution de limites d''installation nationale.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2afd474d-f8ce-42b1-a7ca-80ba0bb3e194','fr_MZ','USERWITHBOUNDARY_MICROPLAN_README_HEADER_1_DESC_5','Veuillez ne pas attribuer d''utilisateurs en double dans les rôles d''approbateur de données démographiques et d''approbateur de données démographiques nationales.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5520235-6ffd-4f9a-af5d-88d51a2b69f0','fr_MZ','USERWITHBOUNDARY_README_HEADER_1','Téléchargement de modèles Excel pour créer des utilisateurs :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc232b99-0041-42b2-b5f4-96e3f8593e95','fr_MZ','USERWITHBOUNDARY_README_HEADER_1_DESC_1','Téléchargez le modèle Excel en cliquant sur le bouton « Télécharger le modèle ».','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ab842eb-2e2d-45eb-b77b-f1c2bc9f14ea','fr_MZ','USERWITHBOUNDARY_README_HEADER_1_DESC_2','Ouvrez le modèle Excel téléchargé à l''étape précédente et comportera 3 feuilles et la première feuille que vous verrez est une feuille « Lisez-moi ». La deuxième feuille nommée « Créer une liste d''utilisateurs » qui sera une feuille vide dans laquelle l''utilisateur devra saisir des données pour créer des utilisateurs pour la campagne. La troisième feuille sera nommée « Liste des limites de campagne » et contiendra toutes les limites sélectionnées à l''étape « Détails des limites » avec leurs codes de limites respectifs.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad72b168-c333-4e1e-9de3-7811e779c11e','fr_MZ','USERWITHBOUNDARY_README_HEADER_2','Création d''utilisateurs pour la campagne :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4194b81a-8c44-4a0b-b603-1c0ca0332e6e','fr_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_1','L''administrateur système devra créer une entrée distincte pour chaque utilisateur. L''administrateur système devra ajouter le nom de l''utilisateur (obligatoire), le numéro de téléphone (obligatoire), le rôle (obligatoire), le type d''emploi (obligatoire), le code limite (obligatoire). Si un utilisateur est mappé à plusieurs rôles, l''administrateur système devra ajouter tous les rôles auxquels cet utilisateur est mappé en les séparant par des virgules dans la cellule pour ajouter des rôles pour cet utilisateur.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('70e28d08-b01d-4d61-aeae-7886d77b876c','fr_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_2','Chaque utilisateur créé doit être attribué à une limite à l''aide du code de limite de la limite requise qui se trouve dans la « Liste des limites de campagne ». Si un utilisateur est mappé à plusieurs limites, l''administrateur système devra ajouter les codes de limite de toutes les limites auxquelles cet utilisateur est mappé en les séparant par des virgules dans la cellule pour ajouter des codes de limite pour cet utilisateur.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4dc1be60-cdda-44e1-9021-a4c9288fd149','fr_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_3','Enregistrez la feuille avec les objectifs mis à jour pour chaque village sur le modèle Excel.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dbdf7add-14f7-486f-b4c9-2ee441a5cc96','fr_MZ','USERWITHBOUNDARY_README_HEADER_2_DESC_4','Appuyez sur le bouton « Parcourir mes fichiers » sur l''écran « Télécharger la cible » et sélectionnez le fichier enregistré avec toutes les cibles du système.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fb0eebe5-75e9-450e-b7aa-5e3058021334','fr_MZ','USERWITHBOUNDARY_README_HEADER_3','Cas d''erreurs courantes :','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('679fdd86-b5fe-4f1c-ad2c-bbc770074485','fr_MZ','USERWITHBOUNDARY_README_HEADER_3_DESC_1','Si l''utilisateur n''a pas ajouté de codes limites pour toutes les entrées utilisateur, le système générera une erreur avec le numéro de ligne où le code limite est manquant.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c8123b7a-572a-4f08-84d2-f835ac32fc3b','fr_MZ','USERWITHBOUNDARY_README_HEADER_3_DESC_2','Si l''utilisateur supprime l''un des en-têtes de la feuille et télécharge la feuille, le système générera une erreur et l''utilisateur devra télécharger à nouveau le modèle et télécharger à nouveau la bonne feuille avec les données correctes.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('73c59af6-2312-43bd-ae0f-860f5326bcfe','fr_MZ','USERWITHBOUNDARY_README_MAINHEADER','Lisez-moi les instructions pour le téléchargement par l''utilisateur','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('224a8fef-46e9-4fae-acc7-7b544cad8670','fr_MZ','USER_CREDENTIAL_BODY_DETAILS','<strong>Détails de la campagne :</strong><br/><strong>Campagne :</strong> {campaignName}<br/><strong>Lien d''accès aux informations d''identification de l''utilisateur :</strong> <a href="{accessLink}">Lien d''accès</a><br/><strong>Téléchargement de l''application :</strong> <a href="{appLink}">Lien de l''application</a>','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8d27d5e6-bf29-46e3-bfba-6f851b59306f','fr_MZ','USER_CREDENTIAL_BODY_INTRO','Bonjour {campaignManagerName},<br/><br/>La configuration de votre campagne de santé est maintenant terminée ! L''application a été configurée et les informations d''identification utilisateur ont été générées pour votre équipe.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('658f1604-23d7-421d-abc5-c5d8358dcf0a','fr_MZ','USER_CREDENTIAL_BODY_NOTES','<strong>Remarques importantes :</strong><br/>Tous les identifiants de l''équipe sont actifs et prêts à être utilisés.<br/>L''application inclut toutes les configurations spécifiques aux exigences de votre campagne.<br/>Veuillez distribuer les identifiants en toute sécurité aux membres autorisés de l''équipe uniquement.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('94031f74-3494-4c2c-b846-4dbaf1480437','fr_MZ','USER_CREDENTIAL_BODY_SUPPORT','<strong>Besoin d''assistance ?</strong><br/>Si vous rencontrez des problèmes lors du téléchargement ou si vous avez des questions sur la configuration, veuillez contacter notre équipe d''assistance à l''adresse <a href=mailto:support@egov.org.in''>support@egov.org.in</a>.','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('83698a2a-8f4f-43e5-8c7b-c7b77b9c6c89','fr_MZ','USER_CREDENTIAL_BODY_THANKS','Votre campagne est prête à être lancée.<br/><br/>Merci d''utiliser Console pour la gestion de votre campagne de santé.<br/>Cordialement,<br/>Équipe Console','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('23c8162a-73af-4f55-81ee-3d2164c1efe9','fr_MZ','USER_CREDENTIAL_SUBJECT','{campaignName} – Les informations d''identification de votre équipe et votre application sont prêtes à être téléchargées','mz','hcm-admin-schemas',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
