INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b9384885-2c9e-4d47-bce6-e783906471a4','en_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configure the application permission','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7f9316ee-0c48-4a24-b3ae-5957725d9168','en_MZ','MODULE_DESCRIPTION_ATTENDANCE','Record attendance of field workers and beneficiaries at distribution sites. Ensures accurate participation tracking for operational reporting.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('071136c7-837e-4d9b-90d7-d50e9790c0e3','en_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Record households that were locked, unavailable, or unreachable during the round. Enables structured follow-ups and helps ensure no eligible child is missed.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6a882979-88f2-4fe2-a528-b69ca88c19cb','en_MZ','MODULE_DESCRIPTION_COMPLAINTS','Let field workers log issues raised by caregivers or the community during distribution—such as concerns about medicines, missed households, or service quality—to support timely follow-up and resolution.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8244422e-31ce-4398-b139-538c1f347cef','en_MZ','MODULE_DESCRIPTION_DELIVERY','Record household-level deliveries during the campaign. Captures delivery status, quantity, and confirmation details at the point of distribution.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ae5e8706-3c71-46da-aff4-0a797e83b885','en_MZ','MODULE_DESCRIPTION_HFREFERRAL','Record and manage referrals for children who require further assessment or treatment. Capture referral reasons—such as contraindications, adverse reactions, or danger signs—and track completion at the designated health facility.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0889c75-85dc-4bf9-a9ba-04fe8c9ed4d5','en_MZ','MODULE_DESCRIPTION_INVENTORY','Track and update resources stock levels at each distribution point. Record receipts, issues, consumption, and losses to maintain accurate visibility of medicines across the campaign.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8782d79c-78e3-420e-8629-8d85911971aa','en_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Manages user permissions needed for camera access, network usage, and device location functionality.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0fc2d94f-7121-4a79-9165-8ec0e6ae813d','en_MZ','MODULE_DESCRIPTION_REGISTRATION','Register eligible children for the campaign and capture all required demographic and caregiver details. During field visits, record the delivery and follow-up needs.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ec2d0906-7e70-40b2-bef1-70b6d91128de','en_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare reported stock against expected balances at the end of each day or round. Identify discrepancies and validate inventory data to maintain accurate resources accounting.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c2e2430b-b469-4adf-a491-de26faa82653','en_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Access summary and detailed stock reports for analysis across facilities, CHWs, and rounds. Supports monitoring of consumption, balances, and losses throughout the campaign.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
