INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('df4702c2-9f90-4dd8-96fe-cd20bcc4dcca','pt_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurar a permissão do aplicativo','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fff979a7-dfbd-48a3-aa05-c0d24e49e6c4','pt_MZ','MODULE_DESCRIPTION_ATTENDANCE','Registar a presença dos trabalhadores de campo e dos beneficiários nos locais de distribuição. Garante o rastreamento preciso da participação para relatórios operacionais.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6895aa60-1c06-4775-b9ab-7086f8cad926','pt_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Registre os domicílios que estavam trancados, indisponíveis ou inacessíveis durante a rodada. Permite acompanhamentos estruturados e ajuda a garantir que nenhuma criança qualificada seja perdida.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1176e6d8-82dc-419d-88a4-d8ba27d42fa5','pt_MZ','MODULE_DESCRIPTION_COMPLAINTS','Deixe que os trabalhadores de campo registem as questões levantadas pelos prestadores de cuidados ou pela comunidade durante a distribuição – tais como preocupações sobre medicamentos, famílias perdidas ou qualidade do serviço – para apoiar o acompanhamento e a resolução atempados.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f432b150-435f-4508-ba1b-c4f6401e7c2e','pt_MZ','MODULE_DESCRIPTION_DELIVERY','Registre as entregas domiciliares durante a campanha. Captura o status da entrega, a quantidade e os detalhes de confirmação no ponto de distribuição.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('774524e3-a445-4174-9f87-35aba5f9e43e','pt_MZ','MODULE_DESCRIPTION_HFREFERRAL','Registre e gerencie encaminhamentos para crianças que necessitam de avaliação ou tratamento adicional. Capture motivos de encaminhamento – como contraindicações, reações adversas ou sinais de perigo – e acompanhe a conclusão na unidade de saúde designada.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e06c11d-663e-4348-9d45-e1c720b34188','pt_MZ','MODULE_DESCRIPTION_INVENTORY','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9d372cbb-b521-4c4d-8ead-eb9700c70491','pt_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gerencia as permissões de usuário necessárias para acesso à câmera, uso da rede e funcionalidade de localização do dispositivo.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3c3b5969-89a0-4b43-b4b8-a96b4008389e','pt_MZ','MODULE_DESCRIPTION_REGISTRATION','Registre crianças qualificadas para a campanha e capture todos os detalhes demográficos e de cuidadores necessários. Durante as visitas de campo, registre as necessidades de entrega e acompanhamento.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7b25bc29-4e59-4872-b7b2-3cdebc4dab11','pt_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare o estoque relatado com os saldos esperados no final de cada dia ou rodada. Identifique discrepâncias e valide dados de inventário para manter uma contabilidade precisa dos recursos.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('904ee536-7520-4115-8bc4-33ae10a6fa39','pt_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Acesse relatórios de estoque resumidos e detalhados para análise em instalações, ACS e rondas. Suporta monitoramento de consumo, saldos e perdas ao longo da campanha.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('82ae1b63-daf5-4a35-8028-f54401dfd022','pt_MZ','MOH_LGA','MOH LGA','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
