INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4456c2f6-0ae0-4b82-98f9-f562eeae3453','fr_MZ','CMP_DRAWER_WHAT_IS_APP_CONFIG_SCREEN','Configurez les paramètres et les fonctionnalités de l''application mobile pour votre campagne.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0f723e49-5c8b-4e1b-bc6a-dd44009a5504','fr_MZ','CMP_DRAWER_WHAT_IS_CONTENT','Dans Elements, vous pouvez modifier les étiquettes, les en-têtes et les champs du formulaire. Vous pouvez personnaliser le nom, le type et le comportement de chaque champ pour répondre aux besoins de votre campagne.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('96c32fb8-7978-4e55-ae6f-6133671fc2e4','fr_MZ','CMP_DRAWER_WHAT_IS_CONTENT_TEMPLATE','Dans Elements, vous pouvez activer ou désactiver des composants et mettre à jour leurs étiquettes et paramètres d''affichage pour ce modèle.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9792a768-416a-409a-81da-10aebf7b6ce9','fr_MZ','CMP_DRAWER_WHAT_IS_ELEMENTOS','Les éléments de formulaire sont les éléments constitutifs des écrans de votre application mobile. Configurez les types de champs, les étiquettes et les règles de champ pour créer des formulaires conviviaux.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2d351e0b-e3f2-4775-acd9-3eb95a8dd21f','fr_MZ','CMP_DRAWER_WHAT_IS_ELEMENTS','Les éléments de formulaire sont les éléments constitutifs des écrans de votre application mobile. Configurez les types de champs, les étiquettes et les règles de champ pour créer des formulaires conviviaux.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('65b21692-a4bd-4e93-8cf3-3ce4b9996858','fr_MZ','CMP_DRAWER_WHAT_IS_LOGIC','Dans Logiques, vous pouvez modifier les validations et la logique associées à l''attribut sélectionné','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
