INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('978485d8-c36a-416c-a92a-d790315e331e','fr_MZ','CMP_DRAWER_WHAT_IS_MODULE_APP_CONFIG_SCREEN','Configurez les formulaires utilisés dans l''application mobile. Modifiez les propriétés des champs, définissez les types de champs et gérez les règles de visibilité ou de champ. Utilisez le panneau des propriétés du champ pour personnaliser chaque champ et ajouter des traductions pour les étiquettes d''interface afin de prendre en charge plusieurs langues.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
