INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7191c80-9638-43ee-ba11-718de06074d0','fr_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurer l''autorisation de l''application','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('14c743ac-d36d-4122-ba02-c79ada947764','fr_MZ','MODULE_DESCRIPTION_ATTENDANCE','Présence record des agents de terrain et des bénéficiaires sur les sites de distribution. Assure un suivi précis de la participation pour les rapports opérationnels.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f171f715-cb19-41e2-b243-c8b2553c1944','fr_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Enregistrez les foyers qui étaient verrouillés, indisponibles ou inaccessibles pendant le cycle. Permet des suivis structurés et permet de garantir qu’aucun enfant éligible n’est oublié.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('331c9818-5144-4859-8861-a438580d6654','fr_MZ','MODULE_DESCRIPTION_COMPLAINTS','Laissez les agents de terrain consigner les problèmes soulevés par les soignants ou la communauté lors de la distribution, tels que les inquiétudes concernant les médicaments, les ménages manqués ou la qualité du service, afin de permettre un suivi et une résolution en temps opportun.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2c00d2d2-1080-4133-a7ae-367241c0c81c','fr_MZ','MODULE_DESCRIPTION_DELIVERY','Enregistrez les livraisons au niveau des ménages pendant la campagne. Capture l’état de la livraison, la quantité et les détails de confirmation au point de distribution.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42d4bc9c-5126-4733-9b2b-171ecfa10f80','fr_MZ','MODULE_DESCRIPTION_HFREFERRAL','Enregistrez et gérez les références pour les enfants qui nécessitent une évaluation ou un traitement plus approfondi. Saisissez les raisons de la référence, telles que les contre-indications, les effets indésirables ou les signes de danger, et suivez l''achèvement du traitement dans l''établissement de santé désigné.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f730b1a-9fd0-4b37-928e-92988a208be2','fr_MZ','MODULE_DESCRIPTION_INVENTORY','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('55c41171-9925-4e53-9d0b-62dcf6288294','fr_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gère les autorisations utilisateur nécessaires à l''accès à la caméra, à l''utilisation du réseau et à la fonctionnalité de localisation des appareils.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('89995287-120e-4d66-a18e-d4fba7fd7217','fr_MZ','MODULE_DESCRIPTION_REGISTRATION','Inscrivez les enfants éligibles à la campagne et capturez tous les détails démographiques et de tuteurs requis. Lors des visites sur le terrain, enregistrez les besoins en matière de livraison et de suivi.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('365a400c-b725-418e-93fd-4dab8e66cd8a','fr_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Comparez le stock déclaré avec les soldes attendus à la fin de chaque journée ou tour. Identifiez les écarts et validez les données d’inventaire pour maintenir une comptabilité précise des ressources.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7e20da1d-f78e-425e-aa3a-c04bdcdd17c1','fr_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Accédez à des rapports de stock récapitulatifs et détaillés pour une analyse dans les établissements, les ASC et les tournées. Prend en charge le suivi de la consommation, des soldes et des pertes tout au long de la campagne.','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7b541124-efef-42a7-a871-262eaa0fcf04','fr_MZ','MOH_LGA','Ministère de la Santé LGA','mz','hcm-appconfiguration',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
