INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('953eb0b4-91a3-436c-8202-b0331186db54','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_DESCRIPTION','Ask the caregiver if the child is experiencing any general illness or discomfort, such as weakness, diarrhea, vomiting, difficulty breathing, or other health concerns.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('89b00706-c48a-4e0a-b3ee-65cc579e61ec','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_LABEL','Is the child sick?','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('36571614-533f-4e42-bdb1-84349754c9ce','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_LABEL_REQUIRED_MESSAGE','This field is required','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a296a2be-8cf4-48d0-a2ae-d250d44cb383','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_DESCRIPTION','Check if the child currently feels unusually hot to the touch or if the caregiver has measured a high temperature in the last 24 hours. If possible, measure the child’s temperature with a thermometer.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b96ab939-a003-43c3-8997-0fd07cca05bb','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_LABEL','Is the child having fever?','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('09e675c4-ef5d-4d01-a222-4964bb8aaf6a','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_LABEL_REQUIRED_MESSAGE','This field is required','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('573430b4-c8f8-403a-b28f-89f2ba73b80c','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_3_DESCRIPTION','Ask the caregiver if the child experienced any unusual symptoms after taking SPAQ during the previous cycle, such as rash, vomiting, diarrhea, or any signs of allergic reactions.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('16415ec5-2217-4e17-9938-6c19d2a99fb3','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_3_LABEL','Is there any side effect to SPAQ which was administered last cycle?','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e479266-3b3a-43e8-ae1b-954b784c04e2','en_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_3_LABEL_REQUIRED_MESSAGE','This field is required','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
