INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('628a6aa5-621f-4a35-a015-fc6771ad31be','en_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configure the application permission','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('291c7838-01d0-4dec-98ec-87c15db77a82','en_MZ','MODULE_DESCRIPTION_ATTENDANCE','Record attendance of field workers and beneficiaries at distribution sites. Ensures accurate participation tracking for operational reporting.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b5cd827a-85a9-4998-90e8-820ac6c1fc97','en_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Record households that were locked, unavailable, or unreachable during the round. Enables structured follow-ups and helps ensure no eligible child is missed.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aadadf9f-b06e-4891-8750-1caddc258b60','en_MZ','MODULE_DESCRIPTION_COMPLAINTS','Let field workers log issues raised by caregivers or the community during distribution—such as concerns about medicines, missed households, or service quality—to support timely follow-up and resolution.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8ed9722c-9ffc-49f7-9c63-654b791b51d4','en_MZ','MODULE_DESCRIPTION_DELIVERY','Record household-level deliveries during the campaign. Captures delivery status, quantity, and confirmation details at the point of distribution.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('41191b8d-4bf8-4aa7-ae54-72e7e1d4db29','en_MZ','MODULE_DESCRIPTION_HFREFERRAL','Record and manage referrals for children who require further assessment or treatment. Capture referral reasons—such as contraindications, adverse reactions, or danger signs—and track completion at the designated health facility.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7f7a06cf-cf9f-4b06-8b94-147a845af846','en_MZ','MODULE_DESCRIPTION_INVENTORY','Track and update resources stock levels at each distribution point. Record receipts, issues, consumption, and losses to maintain accurate visibility of medicines across the campaign.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3d74c421-40a1-42ab-aa91-4100f420a607','en_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Manages user permissions needed for camera access, network usage, and device location functionality.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f9ce319e-084d-48a5-b1b1-524a1d1b6983','en_MZ','MODULE_DESCRIPTION_REGISTRATION','Register eligible children for the campaign and capture all required demographic and caregiver details. During field visits, record the delivery and follow-up needs.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d1f257d2-2f5c-446c-8266-6f22d022c27a','en_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare reported stock against expected balances at the end of each day or round. Identify discrepancies and validate inventory data to maintain accurate resources accounting.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3f767c1d-b2f1-4060-aa68-d70ad3cb4bea','en_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Access summary and detailed stock reports for analysis across facilities, CHWs, and rounds. Supports monitoring of consumption, balances, and losses throughout the campaign.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
