INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('450aa9ba-c69d-4395-a570-ca9165d1da24','pt_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_LABEL_REQUIRED_MESSAGE','Este campo é obrigatório','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5708845f-4c77-4c52-9715-bf359fa8031c','pt_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_DESCRIPTION','Verifique se a criança sente um calor incomum ao toque ou se o cuidador mediu uma temperatura elevada nas últimas 24 horas. Se possível, meça a temperatura da criança com um termômetro.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
