INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6c1c833a-ca65-41d9-bcb5-9616f89c80cd','pt_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_LABEL_REQUIRED_MESSAGE','Este campo é obrigatório','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
