INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('30a3fadf-603f-4171-813e-d559a90dcf10','pt_MZ','MODULE_DESCRIPTION_ATTENDANCE','Registar a presença dos trabalhadores de campo e dos beneficiários nos locais de distribuição. Garante o rastreamento preciso da participação para relatórios operacionais.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6e6e4511-bb26-40b9-b2f9-f86c4b34c9d0','pt_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Registre os domicílios que estavam trancados, indisponíveis ou inacessíveis durante a rodada. Permite acompanhamentos estruturados e ajuda a garantir que nenhuma criança qualificada seja perdida.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7f9a182f-cfac-40bf-a359-88273460a044','pt_MZ','MODULE_DESCRIPTION_COMPLAINTS','Deixe que os trabalhadores de campo registem as questões levantadas pelos prestadores de cuidados ou pela comunidade durante a distribuição – tais como preocupações sobre medicamentos, famílias perdidas ou qualidade do serviço – para apoiar o acompanhamento e a resolução atempados.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b1af14d0-8837-4146-bd97-899037710ac8','pt_MZ','MODULE_DESCRIPTION_DELIVERY','Registre as entregas domiciliares durante a campanha. Captura o status da entrega, a quantidade e os detalhes de confirmação no ponto de distribuição.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0645225d-5132-4ac5-8442-82cef7f8dc01','pt_MZ','MODULE_DESCRIPTION_HFREFERRAL','Registre e gerencie encaminhamentos para crianças que necessitam de avaliação ou tratamento adicional. Capture motivos de encaminhamento – como contraindicações, reações adversas ou sinais de perigo – e acompanhe a conclusão na unidade de saúde designada.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4f9a95b0-e0d7-4fd5-a816-9c365de2e04f','pt_MZ','MODULE_DESCRIPTION_INVENTORY','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3fa8baf2-14b5-4672-b1eb-becd1f33e65f','pt_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gerencia as permissões de usuário necessárias para acesso à câmera, uso da rede e funcionalidade de localização do dispositivo.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7e52a5fa-56f6-4f71-a996-4077dbcf02ac','pt_MZ','MODULE_DESCRIPTION_REGISTRATION','Registre crianças qualificadas para a campanha e capture todos os detalhes demográficos e de cuidadores necessários. Durante as visitas de campo, registre as necessidades de entrega e acompanhamento.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('05c223ae-c1b0-4e45-b6a7-f0f9aff64689','pt_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare o estoque relatado com os saldos esperados no final de cada dia ou rodada. Identifique discrepâncias e valide dados de inventário para manter uma contabilidade precisa dos recursos.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('407b900f-125c-4804-ad5a-96ef3d802cca','pt_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Acesse relatórios de estoque resumidos e detalhados para análise em instalações, ACS e rondas. Suporta monitoramento de consumo, saldos e perdas ao longo da campanha.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
