INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cf7f292d-2c92-421a-bb3c-61bef235162a','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_DESCRIPTION','Demandez à la personne qui s''occupe de vous si l''enfant souffre d''une maladie ou d''un inconfort général, comme une faiblesse, de la diarrhée, des vomissements, des difficultés respiratoires ou d''autres problèmes de santé.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
