INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f9bf282-792d-463d-8fd1-2b69d795372e','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_DESCRIPTION','Vérifiez si l''enfant se sent actuellement inhabituellement chaud au toucher ou si la personne qui s''occupe de lui a mesuré une température élevée au cours des dernières 24 heures. Si possible, mesurez la température de l’enfant avec un thermomètre.','mz','hcm-base-inventory-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
