INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f6003645-1eec-4034-93ef-60fd30bcc639','en_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configure the application permission','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bf43c1b6-b414-4e86-8b00-d6c1d3d7af7c','en_MZ','MODULE_DESCRIPTION_ATTENDANCE','Record attendance of field workers and beneficiaries at distribution sites. Ensures accurate participation tracking for operational reporting.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('657f0ba0-7e60-4d2f-8384-0ccdd1381cd8','en_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Record households that were locked, unavailable, or unreachable during the round. Enables structured follow-ups and helps ensure no eligible child is missed.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3bce0835-6de6-423d-9f0c-c53649a95941','en_MZ','MODULE_DESCRIPTION_COMPLAINTS','Let field workers log issues raised by caregivers or the community during distribution—such as concerns about medicines, missed households, or service quality—to support timely follow-up and resolution.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca41207d-b2b4-42a7-9c63-898293a64358','en_MZ','MODULE_DESCRIPTION_DELIVERY','Record household-level deliveries during the campaign. Captures delivery status, quantity, and confirmation details at the point of distribution.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d4a6efb1-04e6-47cc-ae08-70a1625ed3a1','en_MZ','MODULE_DESCRIPTION_HFREFERRAL','Record and manage referrals for children who require further assessment or treatment. Capture referral reasons—such as contraindications, adverse reactions, or danger signs—and track completion at the designated health facility.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4acb2670-d603-442b-b3fa-19fa0d96330f','en_MZ','MODULE_DESCRIPTION_INVENTORY','Track and update resources stock levels at each distribution point. Record receipts, issues, consumption, and losses to maintain accurate visibility of medicines across the campaign.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('36ce3f61-9f8c-4a4b-b6e1-7c3d1238e98c','en_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Manages user permissions needed for camera access, network usage, and device location functionality.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
