INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3f555b46-ad08-4595-bd8c-c8cfb2427b90','pt_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurar a permissão do aplicativo','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1466d8f2-76b6-4462-9864-5283b84f3117','pt_MZ','MODULE_DESCRIPTION_ATTENDANCE','Registar a presença dos trabalhadores de campo e dos beneficiários nos locais de distribuição. Garante o rastreamento preciso da participação para relatórios operacionais.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('56257ff0-632e-42da-96d3-f7125f4dc31f','pt_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Registre os domicílios que estavam trancados, indisponíveis ou inacessíveis durante a rodada. Permite acompanhamentos estruturados e ajuda a garantir que nenhuma criança qualificada seja perdida.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('554a4d1e-8400-4aa8-b9b5-252cd47b99a3','pt_MZ','MODULE_DESCRIPTION_COMPLAINTS','Deixe que os trabalhadores de campo registem as questões levantadas pelos prestadores de cuidados ou pela comunidade durante a distribuição – tais como preocupações sobre medicamentos, famílias perdidas ou qualidade do serviço – para apoiar o acompanhamento e a resolução atempados.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4a03dacf-66e1-4763-87ac-0be45fecd749','pt_MZ','MODULE_DESCRIPTION_DELIVERY','Registre as entregas domiciliares durante a campanha. Captura o status da entrega, a quantidade e os detalhes de confirmação no ponto de distribuição.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('85808f10-3afb-4700-a2b0-2253c339d3a1','pt_MZ','MODULE_DESCRIPTION_HFREFERRAL','Registre e gerencie encaminhamentos para crianças que necessitam de avaliação ou tratamento adicional. Capture motivos de encaminhamento – como contraindicações, reações adversas ou sinais de perigo – e acompanhe a conclusão na unidade de saúde designada.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5bc9c1d-a727-438b-9190-740dbd7021ed','pt_MZ','MODULE_DESCRIPTION_INVENTORY','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('50fd060b-c016-4ab2-90f5-8c23e27b3abd','pt_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gerencia as permissões de usuário necessárias para acesso à câmera, uso da rede e funcionalidade de localização do dispositivo.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('705ea230-f950-4194-8604-84d95cdf099e','pt_MZ','MODULE_DESCRIPTION_REGISTRATION','Registre crianças qualificadas para a campanha e capture todos os detalhes demográficos e de cuidadores necessários. Durante as visitas de campo, registre as necessidades de entrega e acompanhamento.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f6e48cd-be8d-4410-8526-0d63808f90ed','pt_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare o estoque relatado com os saldos esperados no final de cada dia ou rodada. Identifique discrepâncias e valide dados de inventário para manter uma contabilidade precisa dos recursos.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bb2d9cd3-cb2f-4802-89b2-684cc01975b3','pt_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Acesse relatórios de estoque resumidos e detalhados para análise em instalações, ACS e rondas. Suporta monitoramento de consumo, saldos e perdas ao longo da campanha.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e066df1-de44-4fe9-a7c2-f6eef03b8741','pt_MZ','MRN','NRM {1}','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
