INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('531cb24d-e8ac-4dd3-a410-b10ca6b4c87a','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_DESCRIPTION','Demandez à la personne qui s''occupe de vous si l''enfant souffre d''une maladie ou d''un inconfort général, comme une faiblesse, de la diarrhée, des vomissements, des difficultés respiratoires ou d''autres problèmes de santé.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2fc1cc3d-06d2-4b44-a549-85604c1a3b99','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_LABEL','L''enfant est-il malade ?','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42fcb400-ce3b-4326-b506-2d3a0b952059','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_1_LABEL_REQUIRED_MESSAGE','Ce champ est obligatoire','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('74609be4-d705-4eae-b217-ad0cfcf2a57f','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_DESCRIPTION','Vérifiez si l''enfant se sent actuellement inhabituellement chaud au toucher ou si la personne qui s''occupe de lui a mesuré une température élevée au cours des dernières 24 heures. Si possible, mesurez la température de l’enfant avec un thermomètre.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
