INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c790f73-4ddc-4154-b496-ecc248cf6648','fr_MZ','APPONE_ELIGIBILITYCHECKLIST_QUESTION_2_LABEL_REQUIRED_MESSAGE','Ce champ est obligatoire','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
