INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('324dc1f6-6a00-4e57-83b9-dcb20553e10c','fr_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurer l''autorisation de l''application','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a16d20c5-07f4-4108-b436-9f47e25c6544','fr_MZ','MODULE_DESCRIPTION_ATTENDANCE','Présence record des agents de terrain et des bénéficiaires sur les sites de distribution. Assure un suivi précis de la participation pour les rapports opérationnels.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('564c5414-5f8f-458a-ba4c-2af24fe23885','fr_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Enregistrez les foyers qui étaient verrouillés, indisponibles ou inaccessibles pendant le cycle. Permet des suivis structurés et permet de garantir qu’aucun enfant éligible n’est oublié.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('37207384-b15d-4d8a-846e-55035c889049','fr_MZ','MODULE_DESCRIPTION_COMPLAINTS','Laissez les agents de terrain consigner les problèmes soulevés par les soignants ou la communauté lors de la distribution, tels que les inquiétudes concernant les médicaments, les ménages manqués ou la qualité du service, afin de permettre un suivi et une résolution en temps opportun.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c71e6254-0458-45e9-ba18-54fa1155467f','fr_MZ','MODULE_DESCRIPTION_DELIVERY','Enregistrez les livraisons au niveau des ménages pendant la campagne. Capture l’état de la livraison, la quantité et les détails de confirmation au point de distribution.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('83c9892c-6f2e-432f-9cfd-14aabb6139df','fr_MZ','MODULE_DESCRIPTION_HFREFERRAL','Enregistrez et gérez les références pour les enfants qui nécessitent une évaluation ou un traitement plus approfondi. Saisissez les raisons de la référence, telles que les contre-indications, les effets indésirables ou les signes de danger, et suivez l''achèvement du traitement dans l''établissement de santé désigné.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('87444b99-e876-47f8-b6e7-e5b598b80e23','fr_MZ','MODULE_DESCRIPTION_INVENTORY','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bb4190f1-ad17-4693-8a17-b5edc67ccaf4','fr_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gère les autorisations utilisateur nécessaires à l''accès à la caméra, à l''utilisation du réseau et à la fonctionnalité de localisation des appareils.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ddc81573-e99a-4026-80a2-c62a8b632a15','fr_MZ','MODULE_DESCRIPTION_REGISTRATION','Inscrivez les enfants éligibles à la campagne et capturez tous les détails démographiques et de tuteurs requis. Lors des visites sur le terrain, enregistrez les besoins en matière de livraison et de suivi.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2fe17754-45a0-41ef-b59b-91f4227f3930','fr_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Comparez le stock déclaré avec les soldes attendus à la fin de chaque journée ou tour. Identifiez les écarts et validez les données d’inventaire pour maintenir une comptabilité précise des ressources.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31c9b7be-f777-4454-9b77-4bb20e642708','fr_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Accédez à des rapports de stock récapitulatifs et détaillés pour une analyse dans les établissements, les ASC et les tournées. Prend en charge le suivi de la consommation, des soldes et des pertes tout au long de la campagne.','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cdb01f49-7429-473c-a3fa-74729e3f4269','fr_MZ','MRN','MRN {1}','mz','hcm-base-inventory-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
