INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e07dc840-9492-41cf-9b8f-639766680393','en_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configure the application permission','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa5f17ed-4901-49f5-85de-b9f03b5091a8','en_MZ','MODULE_DESCRIPTION_ATTENDANCE','Record attendance of field workers and beneficiaries at distribution sites. Ensures accurate participation tracking for operational reporting.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f9f4054d-6a38-4180-aafa-3b11a2fa82aa','en_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Record households that were locked, unavailable, or unreachable during the round. Enables structured follow-ups and helps ensure no eligible child is missed.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('170b498c-acc8-4080-a6ae-5ece6e86b2b9','en_MZ','MODULE_DESCRIPTION_COMPLAINTS','Let field workers log issues raised by caregivers or the community during distribution—such as concerns about medicines, missed households, or service quality—to support timely follow-up and resolution.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad326291-41d6-46cf-9ed1-d1ef99f04384','en_MZ','MODULE_DESCRIPTION_DELIVERY','Record household-level deliveries during the campaign. Captures delivery status, quantity, and confirmation details at the point of distribution.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5da20366-9cdb-449b-9834-696d31e59549','en_MZ','MODULE_DESCRIPTION_HFREFERRAL','Record and manage referrals for children who require further assessment or treatment. Capture referral reasons—such as contraindications, adverse reactions, or danger signs—and track completion at the designated health facility.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3a616ef2-fd41-4251-911b-d938d9764850','en_MZ','MODULE_DESCRIPTION_INVENTORY','Track and update resources stock levels at each distribution point. Record receipts, issues, consumption, and losses to maintain accurate visibility of medicines across the campaign.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8b0579d7-1e43-4aba-a9e2-c5ae5a8b40ba','en_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Manages user permissions needed for camera access, network usage, and device location functionality.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c2eff441-fe50-40dd-9f16-d58f54bf0f06','en_MZ','MODULE_DESCRIPTION_REGISTRATION','Register eligible children for the campaign and capture all required demographic and caregiver details. During field visits, record the delivery and follow-up needs.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4321b526-b563-45df-898d-20ddcd6b4f20','en_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare reported stock against expected balances at the end of each day or round. Identify discrepancies and validate inventory data to maintain accurate resources accounting.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('13c4605c-3895-4f72-a4cd-3d3bc6ccff10','en_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Access summary and detailed stock reports for analysis across facilities, CHWs, and rounds. Supports monitoring of consumption, balances, and losses throughout the campaign.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
