INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('186b2b08-d86a-495d-8645-4276d9904ded','pt_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurar a permissão do aplicativo','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20aec85f-3e3c-41b8-be14-db829b07aeeb','pt_MZ','MODULE_DESCRIPTION_ATTENDANCE','Registar a presença dos trabalhadores de campo e dos beneficiários nos locais de distribuição. Garante o rastreamento preciso da participação para relatórios operacionais.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4b739643-f305-435d-b677-db584d7388fe','pt_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Registre os domicílios que estavam trancados, indisponíveis ou inacessíveis durante a rodada. Permite acompanhamentos estruturados e ajuda a garantir que nenhuma criança qualificada seja perdida.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('42df0880-4f09-4ffe-9fd6-e29ca96aa7f6','pt_MZ','MODULE_DESCRIPTION_COMPLAINTS','Deixe que os trabalhadores de campo registem as questões levantadas pelos prestadores de cuidados ou pela comunidade durante a distribuição – tais como preocupações sobre medicamentos, famílias perdidas ou qualidade do serviço – para apoiar o acompanhamento e a resolução atempados.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6bd3390c-be3f-490f-bed9-cb47af01f2db','pt_MZ','MODULE_DESCRIPTION_DELIVERY','Registre as entregas domiciliares durante a campanha. Captura o status da entrega, a quantidade e os detalhes de confirmação no ponto de distribuição.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8322eaad-6df4-4de7-8503-12b0e6456f7c','pt_MZ','MODULE_DESCRIPTION_HFREFERRAL','Registre e gerencie encaminhamentos para crianças que necessitam de avaliação ou tratamento adicional. Capture motivos de encaminhamento – como contraindicações, reações adversas ou sinais de perigo – e acompanhe a conclusão na unidade de saúde designada.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1bf46408-9480-4ed6-b2b6-50458b896330','pt_MZ','MODULE_DESCRIPTION_INVENTORY','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7b74b6b1-d645-4b05-9e56-daff7b114efb','pt_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gerencia as permissões de usuário necessárias para acesso à câmera, uso da rede e funcionalidade de localização do dispositivo.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3edeb64e-7703-4b7a-a923-ee47436aae83','pt_MZ','MODULE_DESCRIPTION_REGISTRATION','Registre crianças qualificadas para a campanha e capture todos os detalhes demográficos e de cuidadores necessários. Durante as visitas de campo, registre as necessidades de entrega e acompanhamento.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('636537d4-20ac-452b-9109-adbb7c41ab81','pt_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare o estoque relatado com os saldos esperados no final de cada dia ou rodada. Identifique discrepâncias e valide dados de inventário para manter uma contabilidade precisa dos recursos.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4a99d8d5-5320-4325-bc5d-00d42772dbe1','pt_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Acesse relatórios de estoque resumidos e detalhados para análise em instalações, ACS e rondas. Suporta monitoramento de consumo, saldos e perdas ao longo da campanha.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('08f6150c-45d2-45ed-a0f0-56831d8b1625','pt_MZ','MRN_NUMBER','Número MRN','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
