INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ace3d6eb-5118-4733-8e3a-4cd68ebcc955','fr_MZ','CMP_DRAWER_WHAT_IS_CONTENT','Dans Elements, vous pouvez modifier les étiquettes, les en-têtes et les champs du formulaire. Vous pouvez personnaliser le nom, le type et le comportement de chaque champ pour répondre aux besoins de votre campagne.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e5d4e89-194e-4a53-9b3b-3c0b46224846','fr_MZ','CMP_DRAWER_WHAT_IS_CONTENT_TEMPLATE','Dans Elements, vous pouvez activer ou désactiver des composants et mettre à jour leurs étiquettes et paramètres d''affichage pour ce modèle.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dd231d71-63e4-4593-a4ee-485edb8cc8be','fr_MZ','CMP_DRAWER_WHAT_IS_ELEMENTOS','Les éléments de formulaire sont les éléments constitutifs des écrans de votre application mobile. Configurez les types de champs, les étiquettes et les règles de champ pour créer des formulaires conviviaux.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
