INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('11ffa81c-01ad-4761-b5ee-5bd99594c4f7','fr_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurer l''autorisation de l''application','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f6600cf-0f2a-43f8-bc1e-72e58f5f7bb9','fr_MZ','MODULE_DESCRIPTION_ATTENDANCE','Présence record des agents de terrain et des bénéficiaires sur les sites de distribution. Assure un suivi précis de la participation pour les rapports opérationnels.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8a8b40a2-9fdd-4ecd-81d3-4632bf6b4577','fr_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Enregistrez les foyers qui étaient verrouillés, indisponibles ou inaccessibles pendant le cycle. Permet des suivis structurés et permet de garantir qu’aucun enfant éligible n’est oublié.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c671c98b-69e8-457c-b86f-5fff803333b7','fr_MZ','MODULE_DESCRIPTION_COMPLAINTS','Laissez les agents de terrain consigner les problèmes soulevés par les soignants ou la communauté lors de la distribution, tels que les inquiétudes concernant les médicaments, les ménages manqués ou la qualité du service, afin de permettre un suivi et une résolution en temps opportun.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('009d8ec4-6332-4b76-a842-82b5e273a879','fr_MZ','MODULE_DESCRIPTION_DELIVERY','Enregistrez les livraisons au niveau des ménages pendant la campagne. Capture l’état de la livraison, la quantité et les détails de confirmation au point de distribution.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f56d9c6f-edb4-4283-99f8-b1bfd917e11b','fr_MZ','MODULE_DESCRIPTION_HFREFERRAL','Enregistrez et gérez les références pour les enfants qui nécessitent une évaluation ou un traitement plus approfondi. Saisissez les raisons de la référence, telles que les contre-indications, les effets indésirables ou les signes de danger, et suivez l''achèvement du traitement dans l''établissement de santé désigné.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e35e5069-2678-4519-9a49-398d3d4c904c','fr_MZ','MODULE_DESCRIPTION_INVENTORY','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b0bac7cd-410d-4230-abe8-813395e4e648','fr_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gère les autorisations utilisateur nécessaires à l''accès à la caméra, à l''utilisation du réseau et à la fonctionnalité de localisation des appareils.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('85eda22d-bee9-4b07-9932-ccc6091c425d','fr_MZ','MODULE_DESCRIPTION_REGISTRATION','Inscrivez les enfants éligibles à la campagne et capturez tous les détails démographiques et de tuteurs requis. Lors des visites sur le terrain, enregistrez les besoins en matière de livraison et de suivi.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f8aaee8-c33e-4dd5-9db2-4beb527b903e','fr_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Comparez le stock déclaré avec les soldes attendus à la fin de chaque journée ou tour. Identifiez les écarts et validez les données d’inventaire pour maintenir une comptabilité précise des ressources.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('105a961d-150c-4604-b382-48709ddeea45','fr_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Accédez à des rapports de stock récapitulatifs et détaillés pour une analyse dans les établissements, les ASC et les tournées. Prend en charge le suivi de la consommation, des soldes et des pertes tout au long de la campagne.','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('570ac33c-255e-4f99-9eaa-0bcdfcc75db9','fr_MZ','MRN_NUMBER','Numéro MRN','mz','hcm-base-registration-mr-dn',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
