INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0d818853-0028-49e4-916e-2e8dce8403d5','en_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configure the application permission','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e298237d-de10-4ee6-86be-a69a4f01353d','en_MZ','MODULE_DESCRIPTION_ATTENDANCE','Record attendance of field workers and beneficiaries at distribution sites. Ensures accurate participation tracking for operational reporting.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5c7d1145-fa09-4ccc-b563-4d45f0f987fc','en_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Record households that were locked, unavailable, or unreachable during the round. Enables structured follow-ups and helps ensure no eligible child is missed.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e1ce906-d36f-4ad3-add9-6b92eb6e6e28','en_MZ','MODULE_DESCRIPTION_COMPLAINTS','Let field workers log issues raised by caregivers or the community during distribution—such as concerns about medicines, missed households, or service quality—to support timely follow-up and resolution.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ee55de3a-1ee1-4bdb-a50e-1ba7ac89adba','en_MZ','MODULE_DESCRIPTION_DELIVERY','Record household-level deliveries during the campaign. Captures delivery status, quantity, and confirmation details at the point of distribution.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2c27bdd3-345b-4491-88cb-994254ce17ff','en_MZ','MODULE_DESCRIPTION_HFREFERRAL','Record and manage referrals for children who require further assessment or treatment. Capture referral reasons—such as contraindications, adverse reactions, or danger signs—and track completion at the designated health facility.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0e3362cf-cd8e-44d5-9343-bf57290c2cfa','en_MZ','MODULE_DESCRIPTION_INVENTORY','Track and update resources stock levels at each distribution point. Record receipts, issues, consumption, and losses to maintain accurate visibility of medicines across the campaign.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9d216748-88e4-4b44-8a44-c3653b43db52','en_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Manages user permissions needed for camera access, network usage, and device location functionality.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4fa595c9-9beb-452d-8e56-2d4eb729a3b9','en_MZ','MODULE_DESCRIPTION_REGISTRATION','Register eligible children for the campaign and capture all required demographic and caregiver details. During field visits, record the delivery and follow-up needs.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f5ee73da-2bf2-4288-a640-a172eb52def5','en_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare reported stock against expected balances at the end of each day or round. Identify discrepancies and validate inventory data to maintain accurate resources accounting.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bc5417b0-30e1-4d04-b320-e7348399fe98','en_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Access summary and detailed stock reports for analysis across facilities, CHWs, and rounds. Supports monitoring of consumption, balances, and losses throughout the campaign.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
