INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2550a501-164f-4369-b03c-cd57fbb147bb','fr_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurer l''autorisation de l''application','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99c43186-1983-44e5-94d4-dc391a4e5da5','fr_MZ','MODULE_DESCRIPTION_ATTENDANCE','Présence record des agents de terrain et des bénéficiaires sur les sites de distribution. Assure un suivi précis de la participation pour les rapports opérationnels.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b95e6e44-97d6-4245-b0b3-22fc2a519959','fr_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Enregistrez les foyers qui étaient verrouillés, indisponibles ou inaccessibles pendant le cycle. Permet des suivis structurés et permet de garantir qu’aucun enfant éligible n’est oublié.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce07d371-d3b5-4e08-84a7-bf2aeb6392cb','fr_MZ','MODULE_DESCRIPTION_COMPLAINTS','Laissez les agents de terrain consigner les problèmes soulevés par les soignants ou la communauté lors de la distribution, tels que les préoccupations concernant les médicaments, les ménages manqués ou la qualité du service, afin de permettre un suivi et une résolution en temps opportun.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7d4bab14-4b9d-497d-a4a4-434d77383ab4','fr_MZ','MODULE_DESCRIPTION_DELIVERY','Enregistrez les livraisons au niveau des ménages pendant la campagne. Capture l’état de la livraison, la quantité et les détails de confirmation au point de distribution.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1a6d27a8-b7e8-4980-96b1-861dfb6e2bc1','fr_MZ','MODULE_DESCRIPTION_HFREFERRAL','Enregistrez et gérez les références pour les enfants qui nécessitent une évaluation ou un traitement plus approfondi. Saisissez les raisons de la référence, telles que les contre-indications, les effets indésirables ou les signes de danger, et suivez l''achèvement du traitement dans l''établissement de santé désigné.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ee3af487-3fcd-437b-a33d-35f7eb6c50e6','fr_MZ','MODULE_DESCRIPTION_INVENTORY','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20a32326-58b8-4b40-a174-3aac57437871','fr_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gère les autorisations utilisateur nécessaires à l''accès à la caméra, à l''utilisation du réseau et à la fonctionnalité de localisation des appareils.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad4a55ce-aa3b-4ea9-b6d1-4639bd5a57ec','fr_MZ','MODULE_DESCRIPTION_REGISTRATION','Inscrivez les enfants éligibles à la campagne et capturez tous les détails démographiques et de tuteurs requis. Lors des visites sur le terrain, enregistrez les besoins en matière de livraison et de suivi.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('292891e8-9967-4224-b445-a18b06608d3f','fr_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Comparez le stock déclaré avec les soldes attendus à la fin de chaque journée ou tour. Identifiez les écarts et validez les données d’inventaire pour maintenir une comptabilité précise des ressources.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('375cd755-3fc1-4466-8e48-e6b77de918b0','fr_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Accédez à des rapports de stock récapitulatifs et détaillés pour une analyse dans les établissements, les ASC et les tournées. Prend en charge le suivi de la consommation, des soldes et des pertes tout au long de la campagne.','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('922de4f6-2195-446c-a903-98ebc658af90','fr_MZ','MRN_NUMBER','Numéro MRN','mz','hcm-base-registration-oncho',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
