INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5dfd331b-90df-49f0-a25a-d4d8af2287aa','en_MZ','ATTENDANCEFLOW','Attendance','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9e0afc2b-bcc8-4660-9854-d917c5d973c5','en_MZ','ATTENDANCE_DESC','Track attendance of field workers and beneficiaries during campaign activities. Captures essential information for accurate reporting and follow-up actions.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b960baad-cea5-4c8c-b082-6f7681766b76','en_MZ','ATTENDANCE_REGISTER_README_ERROR_1','Register ID is required when boundary is selected — A boundary column has been filled but the Register ID cell is empty. The Register ID is auto-populated by formula — ensure you have not accidentally cleared it.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bb8e7ff6-def1-495f-9500-e21ec076d598','en_MZ','ATTENDANCE_REGISTER_README_ERROR_2','At least one boundary must be selected for the register — A Register ID has been entered but no boundary column has a value. Fill at least one boundary column for every register row.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('55e1e0f7-5328-4bc5-b6b3-574f84388630','en_MZ','ATTENDANCE_REGISTER_README_ERROR_3','Invalid boundary code — The boundary value entered is not recognised for this campaign. Use only the boundary codes available in the column dropdowns.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b8012383-ee27-48fe-af37-c27a5942fdaa','en_MZ','ATTENDANCE_REGISTER_README_ERROR_4','Duplicate Register ID found — The same Register ID appears more than once within the sheet. Each register must have a unique ID. If you created multiple registers at the same boundary, overwrite the auto-populated Register ID to make each one unique.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3b861602-bd18-4328-993b-9146db30735b','en_MZ','ATTENDANCE_REGISTER_README_ERROR_5','Register ID already exists in the system — This Register ID has already been created in a previous upload. Remove or rename the duplicate row before re-uploading.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b4490ee3-fc1d-4559-ac70-347650ccf063','en_MZ','ATTENDANCE_REGISTER_README_ERROR_HEADER','Common errors and what they mean:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('daafbe4f-68ac-4207-9563-57d5255bdc63','en_MZ','ATTENDANCE_REGISTER_README_HEADER_1','How to fill this template:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('07d0c18d-d583-44e4-aad5-ff78f9f5b04f','en_MZ','ATTENDANCE_REGISTER_README_IMPORTANT','Important','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('86ecae3e-d5a1-45b2-af7c-4329429bd2ed','en_MZ','ATTENDANCE_REGISTER_README_IMPORTANT_DESC','Once registers are successfully created, their boundary and project details cannot be changed from this screen. Contact your system administrator for any corrections.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce2b213f-9a36-485d-8fa8-60b2797cebcd','en_MZ','ATTENDANCE_REGISTER_README_STEP_1','Download the template using the button above and open it in Microsoft Excel or a compatible spreadsheet application. Do not convert the file to CSV before uploading, as the auto-fill formulas in the Register ID column may stop working.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ed549aa1-54ef-45ca-8401-77a335d92a42','en_MZ','ATTENDANCE_REGISTER_README_STEP_2','Each row in the template represents one attendance register. Fill in the boundary columns from left to right — for example, State, then District, then the lowest level you want the register created at. You must fill at least one boundary column per row; rows with no boundary filled will be rejected. The register will be created at the lowest boundary level you have filled in.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('87a61e90-2ba3-4b3a-b502-77ca44407a5a','en_MZ','ATTENDANCE_REGISTER_README_STEP_3','The Register ID column is auto-populated based on the lowest boundary you enter. You may overwrite this value if you want a custom name, but every Register ID in the sheet must be unique — duplicate IDs will cause an error and the entire upload will be rejected until resolved.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba4090c9-008a-4035-a411-0ec6c5ad2145','en_MZ','ATTENDANCE_REGISTER_README_STEP_4','What happens after you upload: Your file will be processed in the background. You will see a status update on this screen once processing is complete. If any rows have errors, you will be able to download a copy of your file with error details noted against each row. Fix the flagged rows and re-upload to complete register creation.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b78b4ed7-70fe-4dfd-84dd-9a6fe09aa5c6','en_MZ','ATTENDEE_README_ENROLLMENT_DESC_1','When a user is mapped to a register, their enrollment date is set automatically to the date of mapping — you do not need to fill this column. The enrollment date determines from which day attendance can be marked for that user.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0131aacf-c03a-4bc8-8cf0-a8c4605b6097','en_MZ','ATTENDEE_README_ENROLLMENT_DESC_2','If you need to remove a user from a register, set their Status column to Disabled. This will trigger an immediate de-enrollment, and attendance cannot be marked for that user from that date onwards. If you enter a future date in the De-enrollment Date column instead, the user will remain active until that date and attendance marking will be automatically blocked after it.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('80bf3e6b-e838-4d98-8e29-70f1f8d59f3e','en_MZ','ATTENDEE_README_ENROLLMENT_DESC_3','If you need to move a user from one register to another, you must first disable them from their current register. Once their status is set to Disabled and the file is uploaded, they can be mapped to a new register, this can be done on the same day.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('add0fbaf-4d6f-4f00-8b7e-4488bc18b012','en_MZ','ATTENDEE_README_ERROR_1','Register ID is required — A pre-filled Register ID was accidentally cleared. Re-download the template and do not edit any pre-filled cells.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ec6d3c0e-a85e-488c-8942-27d56b2077a4','en_MZ','ATTENDEE_README_ERROR_10','Cannot change de-enrollment date for this register — The de-enrollment date is locked once set. Contact your system administrator if this needs to be changed.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f77c21ce-579b-4020-8a9b-c96185c58521','en_MZ','ATTENDEE_README_ERROR_2','Register ID does not match expected register — A row contains a Register ID from a different template. Re-download the template for this register and re-enter the data.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f598866b-a957-4efe-a4d5-5acb05e02a06','en_MZ','ATTENDEE_README_ERROR_3','Register already exists in a different campaign — The register belongs to another campaign and the entire sheet will be rejected. Ensure you have downloaded the template from the correct campaign.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bc4e1976-49eb-48b4-90cc-075ac5aa60ee','en_MZ','ATTENDEE_README_ERROR_4','Enrollment date is required to enroll a new attendee or staff — Enrollment Date is mandatory for all new users, and must also be filled if Team Code or De-enrollment Date is entered. Use DD-MM-YYYY or DD/MM/YYYY format.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('12e2d7a9-c1f3-4824-b0d1-6862788a81ad','en_MZ','ATTENDEE_README_ERROR_5','Invalid date format. Use DD-MM-YYYY or DD/MM/YYYY — A date cell contains an unrecognised format or extra characters. Accepted formats are DD-MM-YYYY and DD/MM/YYYY only.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('35fe5dd8-d77c-4531-b8fd-942812fa78bc','en_MZ','ATTENDEE_README_ERROR_6','Date must be between register start and end dates — An Enrollment or De-enrollment Date falls outside the register''s valid date range. Check the campaign dates and correct accordingly.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2cf41c19-3c8b-43b2-89ce-26ce0129418b','en_MZ','ATTENDEE_README_ERROR_7','De-enrollment date cannot be before enrollment date — The De-enrollment Date is earlier than the Enrollment Date on the same row. Correct so that de-enrollment is on or after enrollment.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1531b2d2-22aa-45da-b310-685275b4a386','en_MZ','ATTENDEE_README_ERROR_8','Individual is already actively enrolled in another attendance register — This user must be de-enrolled from their current register before being added here. Once de-enrolled, they can be mapped to this register on the same day.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('996f4935-a6e6-42cf-9854-1e622f492f51','en_MZ','ATTENDEE_README_ERROR_9','Cannot change enrollment date for this register — The enrollment date from a user''s previous enrollment in this register cannot be modified. Leave it as it was in the original record.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa534983-7b84-41a4-a3fb-24b94d9bdf47','en_MZ','ATTENDEE_README_HEADER_1','How to fill this template:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7d37b53-6cc0-4f96-9fd9-91322313a5c2','en_MZ','ATTENDEE_README_HEADER_2','Common errors and what they mean:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('70d93625-e32f-46a2-bfe9-4e61bb6aaaed','en_MZ','ATTENDEE_README_HEADER_3','Common errors and what they mean:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('af6e3351-0bfc-4039-bff0-a0cf5d88e3e4','en_MZ','ATTENDEE_README_STEP_1','Download the template using the button above. The template will be pre-filled with all users currently created in the system, split across three sheets — Frontline Workers, Attendance Markers, and Attendance Approvers. Always download a fresh copy of the template before filling it, as the user list and available registers may have changed since your last download.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c105b87a-38bc-4d3a-8cbe-585c1c003654','en_MZ','ATTENDEE_README_STEP_2','Columns highlighted in grey (User ID, Name, Login ID, Role, Boundary, and Register ID) are locked and must not be edited. Any changes to these columns will cause that row to be rejected on upload.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('83df7603-867a-4223-a2dc-ab2fa774ea54','en_MZ','ATTENDEE_README_STEP_3','This template is specific to a single register — the Register ID is already pre-filled for all rows and cannot be changed. If you need to map users to a different register, download the template from that register separately.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8432f4d4-1e02-46e7-9352-89f6f2608a7d','en_MZ','ATTENDEE_README_STEP_4','`Enrollment Date` is mandatory for all users. It decides from when attendance can be marked in the register. Rows without this date will be skipped and users will not be mapped. Enter the date in DD-MM-YYYY format. The date should be within the campaign duration','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3aa119aa-15fc-4e80-940a-fb3f8ca5d3e2','en_MZ','ATTENDEE_README_STEP_5','De-enrollment date: The De-enrollment Date column is optional. If you enter a future date here, the user will remain active until that date and attendance marking will be automatically blocked from the following day onwards.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0c3fcba8-0884-422f-9bfe-7bd3a42df91c','en_MZ','ATTENDEE_README_STEP_6','If you need to move a user from one register to another, they must be de-enrolled from their current register first. Once de-enrolled, they can be mapped to a new register on any day after their de-enrollment date.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('da8fd2ff-c53b-45c7-85e5-1b45d0bc81a7','en_MZ','ATTENDEE_README_STEP_7','What happens after you upload: Your file will be processed in the background. You will see a status update on this screen once processing is complete.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
