INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('950d4863-5e54-43b4-a40a-613d99656e4c','en_MZ','EXTRA_SHEET_ERROR','Extra sheet(s) found in the uploaded file','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b1543ba2-af5b-4ed3-91e8-a21b38a8fa03','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1','Case when there is no facility data in the system:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b98d35f3-43a8-45d8-8b11-2696234f90aa','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_1','Step 1: When there is no facility data in the system, the “List of available facility” template will be empty. For every facility added the user needs to input the Facility Name (must be unique), Facility Type (Warehouse/Health Facility), Facility Status (Temporary/Permanent), Capacity (Number input)','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d649d899-a0a7-44c5-a864-e46aa9b4c40e','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_2','Step 2: To map the facilities to a given boundary the user needs to copy the correct Boundary Code from the “Boundary Data” sheet. If there are more than one boundaries that a facility needs to be mapped to, the user can add all the boundary codes separated by commas','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c1e9c42b-6143-4cf9-aec1-f41fb0432c3d','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_3','Step 3: For every facility, the user needs to add Active or Inactive for all facilities under the “Facility Usage” column. All the Facilities marked as “Active” will be used in the campaign being created the ones marked “Inactive” will not be used in the campaign being created.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dd744fc1-957c-40aa-8b93-211a111a8da2','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_4','Step 4: Once all the facilities are added the user needs to save the file on their system and upload the file by pressing “Browse in My Files” option.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5411aeaf-10e6-42d4-b77b-5d7e69b981c8','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2','Case when there is existing facility data in the system:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5f5e9562-05ed-43cf-96d4-d339944eb3c8','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_1','Step 1: When you open the downloaded facility template, please refer to the List of available Facility sheet. For existing facilities, kindly add entries in the Boundary Code column. You can find the boundary codes in the Boundary Data sheet. If a facility maps to multiple boundaries, please separate the codes with commas.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9a92bdc8-8cd6-40fb-a477-d9fb78ff70c3','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Step 2: In this step the user will have to add entries in the Facility Usage column with valid entries being either Active or Inactive where the user can set the usage for a facility to Active if the facility is being is used for a campaign or else can be set to Inactive. The inputs in the Facility Usage column need to be added for all entries.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b3e1c04e-f2ab-43d1-8499-39e5c5d7044d','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_3','Step 3: For adding new Facilities which are not present in the list of existing facilities, the user needs to input the Facility Name (must be unique), Facility Type (Warehouse/Health Facility), Facility Status (Temporary/Permanent), Capacity (Number input), Boundary Code(from the Boundary Data Sheet) and Facility Usage (Active/Inactive) as explained previously','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('82ac0045-afa1-4290-a387-f682cc3fde2f','en_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_4','Step 4: Once all the facilities are added the user needs to save the file on their system and upload the file by pressing “Browse in My Files” option.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
