INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3de48bd7-6e4d-4a66-b708-7b87aa80c140','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_1','O ID do registro é necessário quando o limite é selecionado — Uma coluna de limite foi preenchida, mas a célula ID do registro está vazia. O ID do registro é preenchido automaticamente por fórmula – certifique-se de não apagá-lo acidentalmente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('04510257-82b3-4f8d-8443-9aed7d9c6827','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_2','Pelo menos um limite deve ser selecionado para o registro — Um ID de registro foi inserido, mas nenhuma coluna de limite possui um valor. Preencha pelo menos uma coluna de limite para cada linha de registro.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6471383b-46ab-45a3-b1c7-31177cfe21ec','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_3','Código de limite inválido — O valor de limite inserido não é reconhecido para esta campanha. Use apenas os códigos de limite disponíveis nos menus suspensos da coluna.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2c384ffd-83ca-42f2-9465-2dc508776cac','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_4','ID de registro duplicado encontrado — O mesmo ID de registro aparece mais de uma vez na planilha. Cada registro deve ter um ID único. Se você criou vários registros no mesmo limite, substitua o ID do registro preenchido automaticamente para tornar cada um deles exclusivo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa0d9f07-790d-4900-b99c-da37795bda09','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_5','Register ID já existe no sistema — Este Register ID já foi criado em um upload anterior. Remova ou renomeie a linha duplicada antes de fazer upload novamente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5d563995-074d-4c68-aa2a-50205ac93c0b','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_HEADER','Erros comuns e o que eles significam:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e737863-650f-4746-9268-c78b78c95863','pt_MZ','ATTENDANCE_REGISTER_README_HEADER_1','Como preencher este modelo:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('23edd2f8-97f6-4031-b8e7-8ec10f517342','pt_MZ','ATTENDANCE_REGISTER_README_IMPORTANT','Importante','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('96b473ab-aaf0-4053-a87f-5fd4f92c2010','pt_MZ','ATTENDANCE_REGISTER_README_IMPORTANT_DESC','Depois que os registros forem criados com sucesso, seus limites e detalhes do projeto não poderão ser alterados nesta tela. Entre em contato com o administrador do sistema para quaisquer correções.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ab7e59bf-89b4-43e2-a523-79eb5991cbe7','pt_MZ','ATTENDANCE_REGISTER_README_STEP_1','Baixe o modelo usando o botão acima e abra-o no Microsoft Excel ou em um aplicativo de planilha compatível. Não converta o arquivo para CSV antes de carregá-lo, pois as fórmulas de preenchimento automático na coluna ID do registro podem parar de funcionar.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d3fb7a4d-ae16-4050-8fd5-893d9aa18f70','pt_MZ','ATTENDANCE_REGISTER_README_STEP_2','Cada linha do modelo representa um registro de presença. Preencha as colunas de limite da esquerda para a direita — por exemplo, Estado, depois Distrito e, em seguida, o nível mais baixo em que deseja que o registro seja criado. Você deve preencher pelo menos uma coluna de limite por linha; linhas sem limite preenchido serão rejeitadas. O registro será criado no nível de limite mais baixo que você preencheu.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51800b7f-57be-4b2d-94c5-dd9c6b5c47df','pt_MZ','ATTENDANCE_REGISTER_README_STEP_3','A coluna Register ID é preenchida automaticamente com base no limite mais baixo inserido. Você pode substituir esse valor se quiser um nome personalizado, mas cada ID de registro na planilha deve ser exclusivo — IDs duplicados causarão um erro e todo o upload será rejeitado até ser resolvido.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c2b791e0-f7fd-4492-9454-83d8a2ac376c','pt_MZ','ATTENDANCE_REGISTER_README_STEP_4','O que acontece depois do upload: seu arquivo será processado em segundo plano. Você verá uma atualização de status nesta tela assim que o processamento for concluído. Se alguma linha apresentar erros, você poderá fazer download de uma cópia do seu arquivo com os detalhes dos erros anotados em cada linha. Corrija as linhas sinalizadas e faça upload novamente para concluir a criação do registro.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f0bd268-984e-4d8b-afc8-6e25344f10bf','pt_MZ','ATTENDEE_README_ENROLLMENT_DESC_1','Quando um usuário é mapeado para um cadastro, sua data de inscrição é definida automaticamente para a data do mapeamento — não é necessário preencher esta coluna. A data de inscrição determina a partir de qual dia a frequência poderá ser marcada para aquele usuário.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('827eb106-831c-4041-82a1-1eeb9f25c685','pt_MZ','ATTENDEE_README_ENROLLMENT_DESC_2','Se você precisar remover um usuário de um cadastro, defina sua coluna Status como Desativado. Isso acionará o cancelamento imediato da inscrição e a presença não poderá ser marcada para esse usuário a partir dessa data. Se você inserir uma data futura na coluna Data de Desinscrição, o usuário permanecerá ativo até essa data e a marcação de frequência será automaticamente bloqueada após ela.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d10a97f5-cf6f-4199-988b-17bab9683042','pt_MZ','ATTENDEE_README_ENROLLMENT_DESC_3','Se você precisar mover um usuário de um registro para outro, você deve primeiro desativá-lo do seu registro atual. Uma vez que seu status esteja definido como Desativado e o upload do arquivo, eles poderão ser mapeados para um novo cadastro, isso pode ser feito no mesmo dia.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c590ceb3-c515-4444-a975-b25330934f73','pt_MZ','ATTENDEE_README_ERROR_1','O ID de registro é obrigatório — Um ID de registro pré-preenchido foi apagado acidentalmente. Baixe novamente o modelo e não edite nenhuma célula pré-preenchida.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('33628498-9a0d-4a76-8b5a-28ac713156d9','pt_MZ','ATTENDEE_README_ERROR_10','Não é possível alterar a data de cancelamento da inscrição para este registro — A data de cancelamento da inscrição é bloqueada depois de definida. Entre em contato com o administrador do sistema se isso precisar ser alterado.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce568c83-6a68-49c9-bab5-152561e04da7','pt_MZ','ATTENDEE_README_ERROR_2','O ID do registro não corresponde ao registro esperado — Uma linha contém um ID do registro de um modelo diferente. Baixe novamente o modelo para este registro e insira novamente os dados.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d746f336-4d61-44af-bb4a-90742c5ae70f','pt_MZ','ATTENDEE_README_ERROR_3','Cadastro já existe em outra campanha — O cadastro pertence a outra campanha e toda a planilha será rejeitada. Certifique-se de ter baixado o modelo da campanha correta.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('833a5bae-ce1f-4aa5-8121-a31acd7ec37b','pt_MZ','ATTENDEE_README_ERROR_4','A data de inscrição é obrigatória para inscrever um novo participante ou equipe — a data de inscrição é obrigatória para todos os novos usuários e também deve ser preenchida se o código da equipe ou a data de cancelamento de inscrição forem inseridos. Use o formato DD-MM-AAAA ou DD/MM/AAAA.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('19271100-1083-44fa-a81a-0ad9a5c40d9d','pt_MZ','ATTENDEE_README_ERROR_5','Formato de data inválido. Use DD-MM-AAAA ou DD/MM/AAAA — Uma célula de data contém um formato não reconhecido ou caracteres extras. Os formatos aceitos são apenas DD-MM-AAAA e DD/MM/AAAA.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6aa7b38c-21fd-45db-b894-afad26a3cf99','pt_MZ','ATTENDEE_README_ERROR_6','A data deve estar entre as datas de início e término do registro — uma data de inscrição ou cancelamento de inscrição está fora do intervalo de datas válido do registro. Verifique as datas da campanha e corrija de acordo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1f057cf8-ee2a-4986-a253-33ce55953e5c','pt_MZ','ATTENDEE_README_ERROR_7','A data de cancelamento de inscrição não pode ser anterior à data de inscrição — A data de cancelamento de inscrição é anterior à data de inscrição na mesma linha. Corrija para que o cancelamento da inscrição ocorra no momento ou após a inscrição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a270754c-2601-43c4-886a-f05713e10ff0','pt_MZ','ATTENDEE_README_ERROR_8','Indivíduo já está ativamente inscrito em outro cadastro de presença — Este usuário deve ter sua inscrição cancelada em seu cadastro atual antes de ser adicionado aqui. Uma vez cancelados, eles podem ser mapeados para este cadastro no mesmo dia.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('867d3dfd-4b49-4c80-bca7-433846f62123','pt_MZ','ATTENDEE_README_ERROR_9','Não é possível alterar a data de inscrição neste cadastro — A data de inscrição da inscrição anterior de um usuário neste cadastro não pode ser modificada. Deixe como estava no registro original.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('79b79a74-0a3a-433d-a136-5582cee7b75d','pt_MZ','ATTENDEE_README_HEADER_1','Como preencher este modelo:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce75f4e1-0474-4183-afbe-9e81bdf29a2d','pt_MZ','ATTENDEE_README_HEADER_2','Erros comuns e o que eles significam:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('913a9db2-56d3-4814-ad61-695503c6db59','pt_MZ','ATTENDEE_README_HEADER_3','Erros comuns e o que eles significam:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f4f0a34a-afe8-4086-9b48-72df3d0934cf','pt_MZ','ATTENDEE_README_STEP_1','Baixe o modelo usando o botão acima. O modelo será pré-preenchido com todos os usuários atualmente criados no sistema, divididos em três planilhas – Trabalhadores da Linha de Frente, Marcadores de Presença e Aprovadores de Presença. Sempre baixe uma nova cópia do modelo antes de preenchê-lo, pois a lista de usuários e os cadastros disponíveis podem ter mudado desde o último download.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('41982552-867a-4b87-a2ea-a33e3731fd58','pt_MZ','ATTENDEE_README_STEP_2','As colunas destacadas em cinza (ID do usuário, Nome, ID de login, Função, Limite e ID do registro) estão bloqueadas e não devem ser editadas. Quaisquer alterações nessas colunas farão com que essa linha seja rejeitada no upload.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9743eec5-0679-4686-82d5-715b8f373a12','pt_MZ','ATTENDEE_README_STEP_3','Este modelo é específico para um único registro — o ID do registro já está pré-preenchido para todas as linhas e não pode ser alterado. Se você precisar mapear usuários para um cadastro diferente, baixe o modelo desse cadastro separadamente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f896ca0a-6317-4832-adb8-421851401d39','pt_MZ','ATTENDEE_README_STEP_4','`Data de inscrição` é obrigatória para todos os usuários. Decide a partir de quando a presença pode ser marcada no cadastro. As linhas sem esta data serão ignoradas e os usuários não serão mapeados. Insira a data no formato DD-MM-AAAA. A data deve estar dentro da duração da campanha','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c65974e4-d3d7-4529-a464-7b7979c33470','pt_MZ','ATTENDEE_README_STEP_5','Data de cancelamento de inscrição: A coluna Data de cancelamento de inscrição é opcional. Se você inserir aqui uma data futura, o usuário permanecerá ativo até aquela data e a marcação de presença será automaticamente bloqueada a partir do dia seguinte.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('820c01ba-3f21-448e-92f0-4c8c8769279d','pt_MZ','ATTENDEE_README_STEP_6','Se você precisar mover um usuário de um registro para outro, primeiro ele deverá ser desinscrito do registro atual. Após o cancelamento da inscrição, eles poderão ser mapeados para um novo cadastro em qualquer dia após a data do cancelamento da inscrição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8c7e3367-4a07-4989-b792-9a0389be9db3','pt_MZ','ATTENDEE_README_STEP_7','O que acontece depois do upload: seu arquivo será processado em segundo plano. Você verá uma atualização de status nesta tela assim que o processamento for concluído.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('25a7ca76-1953-45f2-bd0e-383e19348b65','pt_MZ','AT_LEAST_ONE_FIELD_MUST_BE_SELECTED','Pelo menos um campo deve estar presente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dd148a2f-d2a5-4e52-8fa2-df161bb34c44','pt_MZ','AT_LEAST_ONE_FILE_REQUIRED_ERROR','Erro: é necessário pelo menos um arquivo','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('52279e49-37c9-4e30-8738-0fdf0364a0d0','pt_MZ','BACK','Voltar','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
