INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('24e6d131-e864-4bc9-8405-3e1ecbc22f98','pt_MZ','CAMPAIGN_TAB_SUB_TEXT','As condições de entrega que você configurar nesta etapa decidirão os critérios de elegibilidade para seus beneficiários. Você pode configurar diversas condições de entrega com base nos diferentes critérios de elegibilidade seguidos na campanha. Cada critério de elegibilidade deve ser criado como uma condição de entrega separada. Cada condição para um tipo de beneficiário individual pode ser criada usando 4 atributos, ou seja, Idade, Peso, Altura e Sexo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
