INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('881c7d20-095e-4340-95f4-6c5b6397dc4d','pt_MZ','CMP_DRAWER_WHAT_IS_CONTENT','No Elements você pode editar rótulos, cabeçalhos e campos de formulários. Você pode personalizar o nome, o tipo e o comportamento de cada campo para atender às necessidades da sua campanha','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
