INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6241097e-f760-42c5-86bc-b0420315389e','pt_MZ','EXTRA_SHEET_ERROR','Folhas extras encontradas no arquivo enviado','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1da1cd19-9ba4-4a56-a034-181098c8a141','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1','Caso em que não há dados da instalação no sistema:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('065b5a17-4f7b-43b2-b582-44b00e2b2976','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_1','Passo 1: Quando não houver dados de instalações no sistema, o modelo “Lista de instalações disponíveis” estará vazio. Para cada instalação adicionada, o usuário precisa inserir o nome da instalação (deve ser exclusivo), tipo de instalação (armazém/instalação de saúde), status da instalação (temporário/permanente), capacidade (entrada de número)','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8bdf9cf5-d7ca-4aeb-b70d-b2dc8daac6e5','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_2','Passo 2: Para mapear as instalações para um determinado limite, o usuário precisa copiar o Código do Limite correto da planilha “Dados do Limite”. Se houver mais de um limite para o qual uma instalação precisa ser mapeada, o usuário poderá adicionar todos os códigos de limite separados por vírgulas','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e8d0dc3b-2149-421f-8513-38979e2d599b','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_3','Etapa 3: Para cada instalação, o usuário precisa adicionar Ativo ou Inativo para todas as instalações na coluna “Uso da Instalação”. Todas as Instalações marcadas como “Ativas” serão utilizadas na campanha que está sendo criada, as marcadas como “Inativas” não serão utilizadas na campanha que está sendo criada.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ecd5b9f-2671-46ae-8614-9c5922f9535c','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_4','Passo 4: Depois que todas as facilidades forem adicionadas, o usuário precisa salvar o arquivo em seu sistema e fazer upload do arquivo pressionando a opção “Navegar em Meus Arquivos”.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3e432e72-e697-472a-be93-5a15b46bdac6','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2','Caso em que existem dados de instalações existentes no sistema:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('53b200d7-2c85-4b8d-ada5-12f6868d2f0e','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_1','Passo 1: Ao abrir o modelo de instalação baixado, consulte a folha Lista de instalações disponíveis. Para instalações existentes, adicione entradas na coluna Código de limite. Você pode encontrar os códigos de limite na planilha Dados de limite. Se uma instalação mapear vários limites, separe os códigos com vírgulas.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1846d5f0-05cb-4dee-a69d-33df5bfa2069','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Etapa 2: nesta etapa, o usuário terá que adicionar entradas na coluna Uso da instalação com entradas válidas sendo Ativas ou Inativas, onde o usuário pode definir o uso de uma instalação como Ativo se a instalação estiver sendo usada para uma campanha ou então pode ser definida como Inativa. As entradas na coluna Uso da Instalação precisam ser adicionadas para todas as entradas.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('14bc7341-5b62-4d32-9911-40c64c4946bb','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_3','Etapa 3: Para adicionar novas instalações que não estão presentes na lista de instalações existentes, o usuário precisa inserir o nome da instalação (deve ser exclusivo), tipo de instalação (armazém/instalação de saúde), status da instalação (temporário/permanente), capacidade (entrada de número), código de limite (da folha de dados de limite) e uso da instalação (ativo/inativo) conforme explicado anteriormente','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('01fa66d9-4efa-4460-af22-616e5b7c094a','pt_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_4','Passo 4: Depois que todas as facilidades forem adicionadas, o usuário precisa salvar o arquivo em seu sistema e fazer upload do arquivo pressionando a opção “Navegar em Meus Arquivos”.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('837bfdfa-88d4-43f8-b74c-3c03f4b544af','pt_MZ','FACILITY_DETAILS','Detalhes da instalação','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
