INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2ae0e6ce-f50a-48e5-bb1e-63d79d85881f','pt_MZ','FACILITY_SEARCH_DESC','Localize unidades de saúde e pontos de atendimento próximos. Permite que os trabalhadores de campo encontrem instalações para coleta de recursos ou encaminhamentos.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
