INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3c2c8bfb-52cb-4d86-b4f1-fe456eb6efd9','pt_MZ','HCM_MOBILE_APP_BUTTON_EDIT','Editar aplicativo móvel','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cd0e139a-c34b-4bd5-b66e-651d0836161b','pt_MZ','HCM_MOBILE_APP_DESC','Configure o aplicativo móvel que os trabalhadores de campo usarão. Configure formulários, habilite recursos e personalize a interface de acordo com os requisitos de sua campanha.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ab86089e-2825-4470-a6d5-fd2941e195d8','pt_MZ','HCM_MOBILE_APP_HEADING','Configurar aplicativo móvel','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cdb9287b-0d06-474d-9a62-c628c3fc5cec','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_ATTENDANCEFLOW','Registar a presença dos trabalhadores de campo e dos beneficiários durante as actividades de distribuição. Garante um rastreamento preciso da participação para relatórios.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0682424-feb1-405d-9db2-53576503374d','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_COMPLAINTFLOW','Registre e gerencie reclamações de campanhas de distribuição. Permite captura e resolução rápida de problemas para melhorar a qualidade do serviço.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d1030001-bb05-4ec2-bdf3-c958296902c7','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_DELIVERYFLOW','Monitorar os níveis de estoque líquido de inseticidas e a logística de distribuição. Rastreie o estoque em locais e pontos de distribuição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('68e0ee3b-b62d-4ea5-a517-e59bbf04c71b','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_HFREFERALFLOW','Referência é o processo de direcionar uma pessoa, cliente ou caso a outro indivíduo, profissional ou organização para obter mais assistência, serviços ou experiência.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c14b78a9-701c-4f4a-a9fb-5f86ff8bbc39','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_INVENTORYFLOW','Gerenciar inventário de inseticidas e equipamentos para campanhas de pulverização residual interna.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('015a525d-7f65-4045-acf7-350fd099c9dc','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_REGISTRATIONFLOW','Cadastrar beneficiários para campanhas de distribuição de mosquiteiros. Captura detalhes pessoais, dados demográficos familiares e elegibilidade para alocação líquida.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('644d4295-8143-44b1-ad91-a0b9e4e73e18','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNET_ATTENDANCEFLOW','Registar a presença dos trabalhadores de campo e dos beneficiários nos locais de distribuição. Garante o rastreamento preciso da participação para relatórios operacionais.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('100182f8-8677-4421-867a-998e61a9d83a','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNET_COMPLAINTFLOW','Registrar e resolver reclamações durante a distribuição de mosquiteiros. Permite a captura rápida de problemas e melhora a capacidade de resposta da campanha e a qualidade do serviço.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5f91c8c5-1791-46b2-a8ac-453789a68eef','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNET_DELIVERYFLOW','Registar as entregas de mosquiteiros a nível familiar durante a campanha. Captura o status da entrega, a quantidade e os detalhes de confirmação no ponto de distribuição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8cac5645-219d-424f-b459-d0197fc26869','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNET_HFREFERALFLOW','Referência é o processo de direcionar uma pessoa, cliente ou caso a outro indivíduo, profissional ou organização para obter mais assistência, serviços ou experiência.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc2d3b37-d71a-41ab-ad32-3a1cab4bbe44','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNET_INVENTORYFLOW','Gerencie o estoque líquido desde o armazém central até a entrega final. Rastreie transações, verifique quantidades e evite uso indevido durante a distribuição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2e6addd4-06a0-439c-bd02-2af600991570','pt_MZ','HCM_MODULE_DESCRIPTION_BEDNET_REGISTRATIONFLOW','Cadastrar beneficiários para campanhas de distribuição de mosquiteiros inseticidas. Captura informações pessoais, dados demográficos e critérios de elegibilidade para distribuição direcionada.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
