INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7978bfde-5701-4b86-a1e4-bef8b3216909','pt_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurar a permissão do aplicativo','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7d23aee4-c191-4462-a0ab-d02a290499e1','pt_MZ','MODULE_DESCRIPTION_ATTENDANCE','Registar a presença dos trabalhadores de campo e dos beneficiários nos locais de distribuição. Garante o rastreamento preciso da participação para relatórios operacionais.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('afb728fd-0215-49d3-8c6e-97c19a907f4a','pt_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Registre os domicílios que estavam trancados, indisponíveis ou inacessíveis durante a rodada. Permite acompanhamentos estruturados e ajuda a garantir que nenhuma criança qualificada seja perdida.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67b63e43-0d71-49f8-a878-d6e8fd3168be','pt_MZ','MODULE_DESCRIPTION_COMMUNITYREGISTRATION','Permitir a entrega de vacinas ou medicamentos aos beneficiários em escolas e outras instalações comunitárias, como orfanatos, acampamentos e instituições residenciais, onde a entrega domiciliar não se aplica.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('291b5cc4-5c29-4442-9224-54eba31aa464','pt_MZ','MODULE_DESCRIPTION_COMPLAINTS','Deixe que os trabalhadores de campo registem as questões levantadas pelos prestadores de cuidados ou pela comunidade durante a distribuição – tais como preocupações sobre medicamentos, famílias perdidas ou qualidade do serviço – para apoiar o acompanhamento e a resolução atempados.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3a0cca35-6382-4c9c-b26e-f4bace87be64','pt_MZ','MODULE_DESCRIPTION_DELIVERY','Registre as entregas domiciliares durante a campanha. Captura o status da entrega, a quantidade e os detalhes de confirmação no ponto de distribuição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('24ec83db-4d7f-48e8-8c44-856a1d05bbb4','pt_MZ','MODULE_DESCRIPTION_HFREFERRAL','Registre e gerencie encaminhamentos para crianças que necessitam de avaliação ou tratamento adicional. Capture motivos de encaminhamento – como contraindicações, reações adversas ou sinais de perigo – e acompanhe a conclusão na unidade de saúde designada.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f11e3bb-744d-4615-beff-df790868e7e2','pt_MZ','MODULE_DESCRIPTION_INSIDEMONITORING','Captura dados pós-campanha a nível familiar para validar a cobertura vacinal, semelhante ao LQAS. Os monitores registram pontos de GPS, respostas de pesquisas, motivos de vacinação perdida, conscientização do cuidador e detalhes de vigilância. Fornece um resumo da liquidação (contagem de crianças perdidas, sinalizadores de risco, status de cobertura, comentários) e é acessível apenas para funções de monitor configuradas.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('23494f12-8609-409b-b461-23a79054333e','pt_MZ','MODULE_DESCRIPTION_INVENTORY','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e097db04-bf26-46d9-82eb-b25835fb115a','pt_MZ','MODULE_DESCRIPTION_LQA','O cabeçalho do lote/grupo em uma pesquisa LQA registra detalhes de localização, informações do topógrafo e coordenadas GPS. Inclui estado, distrito, vila, ID do cluster, nome do enumerador, detalhes do supervisor, latitude, longitude e data da pesquisa. Isso garante rastreamento, verificação e relatórios precisos das atividades de pesquisa de campo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4342827e-afc1-4709-a684-8ee8075d53cc','pt_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gerencia as permissões de usuário necessárias para acesso à câmera, uso da rede e funcionalidade de localização do dispositivo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('635fab5b-e68f-4834-ae22-c10a5b9250f1','pt_MZ','MODULE_DESCRIPTION_REGISTRATION','Registre crianças qualificadas para a campanha e capture todos os detalhes demográficos e de cuidadores necessários. Durante as visitas de campo, registre as necessidades de entrega e acompanhamento.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cf6f7029-bd1b-425b-ba70-141e1399eb7c','pt_MZ','MODULE_DESCRIPTION_STOCK','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d34be1d9-feca-41db-a2e8-88ae29218f3f','pt_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Compare o estoque relatado com os saldos esperados no final de cada dia ou rodada. Identifique discrepâncias e valide dados de inventário para manter uma contabilidade precisa dos recursos.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57986451-73d8-4987-bdee-f4a1e19ca6b1','pt_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Acesse relatórios de estoque resumidos e detalhados para análise em instalações, ACS e rondas. Suporta monitoramento de consumo, saldos e perdas ao longo da campanha.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7ac23221-cc08-46a2-ac5e-3805fd822ba4','pt_MZ','MODULE_FEATURES','Recursos do módulo','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fdae52aa-3559-4ad7-9f21-babc5455dc77','pt_MZ','MODULE_FEATURES_DESCRIPTION','Ative ou desative recursos específicos do aplicativo para sua campanha. Alguns recursos precisam de configuração para corresponder ao seu fluxo de trabalho. Outros trabalham com configurações padrão.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c4c70520-360a-4eb7-b01d-8860612e4f80','pt_MZ','MONITORING_ITN_DP','Monitoramento','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
