INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a24b062e-ac42-4c12-86d2-304ee2b9060a','fr_MZ','ATTENDANCEFLOW','Présence','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5ff3946-ccab-419b-8f59-322328fe0d34','fr_MZ','ATTENDANCE_DESC','Suivez la présence des agents de terrain et des bénéficiaires pendant les activités de campagne. Capture les informations essentielles pour des rapports précis et des actions de suivi.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2bd64a78-3f08-4d49-8590-574f248f67d0','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_1','L''ID de registre est requis lorsque la limite est sélectionnée : une colonne de limite a été remplie mais la cellule ID de registre est vide. L''ID de registre est automatiquement renseigné par une formule : assurez-vous de ne pas l''avoir effacé accidentellement.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57929df0-ea48-48f7-8810-cabd149cbf67','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_2','Au moins une limite doit être sélectionnée pour le registre — Un ID de registre a été saisi mais aucune colonne de limite n''a de valeur. Remplissez au moins une colonne de limite pour chaque ligne de registre.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a9cebdba-98de-4b5c-a119-1b12353d875b','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_3','Error 500 (Server Error)!!1500.That’s an error.There was an error. Please try again later.That’s all we know.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('88e7b0aa-118d-422e-8d5d-9425ab57e28b','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_4','ID de registre en double trouvé : le même ID de registre apparaît plus d''une fois dans la feuille. Chaque registre doit avoir un identifiant unique. Si vous avez créé plusieurs registres à la même limite, écrasez l''ID de registre renseigné automatiquement pour rendre chacun d''entre eux unique.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1e765f2f-1ae2-40d5-9e45-de1a19221cab','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_5','L''ID de registre existe déjà dans le système — Cet ID de registre a déjà été créé lors d''un téléchargement précédent. Supprimez ou renommez la ligne en double avant de la télécharger à nouveau.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fb1e8187-22ca-4736-841b-af923b15adc4','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_HEADER','Erreurs courantes et leur signification :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4f69fc98-5ad4-4e37-8500-0ea00b4e106e','fr_MZ','ATTENDANCE_REGISTER_README_HEADER_1','Comment remplir ce modèle :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9646681c-2f04-4aec-bd59-6c50137143c6','fr_MZ','ATTENDANCE_REGISTER_README_IMPORTANT','Important','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('059799ed-3089-42a5-95e0-5f19f9e91c02','fr_MZ','ATTENDANCE_REGISTER_README_IMPORTANT_DESC','Une fois les registres créés avec succès, leurs limites et les détails du projet ne peuvent pas être modifiés à partir de cet écran. Contactez votre administrateur système pour toute correction.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cbdaff4e-f47a-41e7-b14f-66621e371f05','fr_MZ','ATTENDANCE_REGISTER_README_STEP_1','Téléchargez le modèle à l''aide du bouton ci-dessus et ouvrez-le dans Microsoft Excel ou dans un tableur compatible. Ne convertissez pas le fichier au format CSV avant de le télécharger, car les formules de remplissage automatique dans la colonne ID de registre pourraient cesser de fonctionner.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('85a4a0c6-325a-4029-a7bd-8ba8422d47eb','fr_MZ','ATTENDANCE_REGISTER_README_STEP_2','Chaque ligne du modèle représente un registre de présence. Remplissez les colonnes de limites de gauche à droite – par exemple, État, puis District, puis le niveau le plus bas auquel vous souhaitez que le registre soit créé. Vous devez remplir au moins une colonne de limite par ligne ; les lignes sans limite remplie seront rejetées. Le registre sera créé au niveau de limite le plus bas que vous avez rempli.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d4dc849a-80c1-457d-9526-46ce494deb60','fr_MZ','ATTENDANCE_REGISTER_README_STEP_3','La colonne ID de registre est automatiquement renseignée en fonction de la limite la plus basse que vous entrez. Vous pouvez écraser cette valeur si vous souhaitez un nom personnalisé, mais chaque identifiant de registre dans la feuille doit être unique : les identifiants en double provoqueront une erreur et l''intégralité du téléchargement sera rejetée jusqu''à ce qu''elle soit résolue.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06f5c61b-1b41-49aa-ae56-c5f2cbb9cc19','fr_MZ','ATTENDANCE_REGISTER_README_STEP_4','Que se passe-t-il après le téléchargement : Votre fichier sera traité en arrière-plan. Vous verrez une mise à jour du statut sur cet écran une fois le traitement terminé. Si des lignes contiennent des erreurs, vous pourrez télécharger une copie de votre fichier avec les détails des erreurs notés pour chaque ligne. Corrigez les lignes marquées et téléchargez à nouveau pour terminer la création du registre.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('84cc575a-7104-4457-aef8-e1d71a458040','fr_MZ','ATTENDEE_README_ENROLLMENT_DESC_1','Lorsqu''un utilisateur est mappé à un registre, sa date d''inscription est automatiquement définie sur la date de mappage — vous n''avez pas besoin de remplir cette colonne. La date d''inscription détermine à partir de quel jour la présence peut être marquée pour cet utilisateur.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6955023e-63d5-43c3-8858-63835d71aaeb','fr_MZ','ATTENDEE_README_ENROLLMENT_DESC_2','Si vous devez supprimer un utilisateur d''un registre, définissez sa colonne Statut sur Désactivé. Cela déclenchera une désinscription immédiate et la présence ne pourra plus être marquée pour cet utilisateur à partir de cette date. Si vous saisissez plutôt une date future dans la colonne Date de désinscription, l''utilisateur restera actif jusqu''à cette date et la notation de présence sera automatiquement bloquée après celle-ci.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f4a2ee7f-ee4d-4f2d-9e2f-52dd31f8301a','fr_MZ','ATTENDEE_README_ENROLLMENT_DESC_3','Si vous devez déplacer un utilisateur d''un registre à un autre, vous devez d''abord le désactiver de son registre actuel. Une fois que leur statut est défini sur Désactivé et que le fichier est téléchargé, ils peuvent être mappés à un nouveau registre, cela peut être fait le même jour.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b4def42c-03f7-4179-b17d-13214365bf60','fr_MZ','ATTENDEE_README_ERROR_1','L''ID de registre est requis : un ID de registre pré-rempli a été accidentellement effacé. Téléchargez à nouveau le modèle et ne modifiez aucune cellule pré-remplie.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c5631c58-1bc6-40a8-a656-342f5e32698a','fr_MZ','ATTENDEE_README_ERROR_10','Impossible de modifier la date de désinscription pour ce registre — La date de désinscription est verrouillée une fois définie. Contactez votre administrateur système si cela doit être modifié.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a03d5b12-677b-4a70-8792-64135c19906c','fr_MZ','ATTENDEE_README_ERROR_2','L''ID de registre ne correspond pas au registre attendu : une ligne contient un ID de registre provenant d''un modèle différent. Téléchargez à nouveau le modèle de ce registre et saisissez à nouveau les données.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('069b7ece-4c61-460c-8048-43421388761c','fr_MZ','ATTENDEE_README_ERROR_3','Le registre existe déjà dans une autre campagne — Le registre appartient à une autre campagne et la fiche entière sera rejetée. Assurez-vous d''avoir téléchargé le modèle de la bonne campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4858bf1-0fcd-4d8e-a8e1-e10415b473e1','fr_MZ','ATTENDEE_README_ERROR_4','La date d''inscription est requise pour inscrire un nouveau participant ou un nouveau membre du personnel. La date d''inscription est obligatoire pour tous les nouveaux utilisateurs et doit également être renseignée si le code d''équipe ou la date de désinscription est saisi. Utilisez le format JJ-MM-AAAA ou JJ/MM/AAAA.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7bc58d3-001d-41ea-96c9-334170355b9f','fr_MZ','ATTENDEE_README_ERROR_5','Format de date invalide. Use DD-MM-YYYY or DD/MM/YYYY — A date cell contains an unrecognised format or extra characters. Accepted formats are DD-MM-YYYY and DD/MM/YYYY only.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eeb4241a-04e0-429f-86e3-e44434c3cea7','fr_MZ','ATTENDEE_README_ERROR_6','La date doit être comprise entre les dates de début et de fin du registre — Une date d''inscription ou de désinscription se situe en dehors de la plage de dates valide du registre. Vérifiez les dates de la campagne et corrigez en conséquence.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6015fc58-0c15-4fa6-816a-1875ecbea3ad','fr_MZ','ATTENDEE_README_ERROR_7','La date de désinscription ne peut pas être antérieure à la date d''inscription : la date de désinscription est antérieure à la date d''inscription sur la même ligne. Corriger pour que la désinscription ait lieu au moment de l''inscription ou après.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('854aa5cd-f881-4e9e-9793-2f41b4292845','fr_MZ','ATTENDEE_README_ERROR_8','L''individu est déjà activement inscrit dans un autre registre de présence — Cet utilisateur doit être désinscrit de son registre actuel avant d''être ajouté ici. Une fois désinscrits, ils peuvent être mappés à ce registre le même jour.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8af94daf-d2a6-4df3-9638-76b94776de93','fr_MZ','ATTENDEE_README_ERROR_9','Impossible de modifier la date d''inscription pour ce registre — La date d''inscription de l''inscription précédente d''un utilisateur dans ce registre ne peut pas être modifiée. Laissez-le tel qu''il était dans le dossier original.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa2da9e3-9914-4073-aa69-d4b54246ac69','fr_MZ','ATTENDEE_README_HEADER_1','Comment remplir ce modèle :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('73e36987-2362-484e-9329-d1293a5ac746','fr_MZ','ATTENDEE_README_HEADER_2','Erreurs courantes et leur signification :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8bdc29a1-9c8f-4af5-a46e-2e1823e64d7f','fr_MZ','ATTENDEE_README_HEADER_3','Erreurs courantes et leur signification :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e23bb23-7db7-4372-a98a-4e17d202a23f','fr_MZ','ATTENDEE_README_STEP_1','Téléchargez le modèle en utilisant le bouton ci-dessus. Le modèle sera pré-rempli avec tous les utilisateurs actuellement créés dans le système, répartis sur trois feuilles : travailleurs de première ligne, marqueurs de présence et approbateurs de présence. Téléchargez toujours une nouvelle copie du modèle avant de le remplir, car la liste des utilisateurs et les registres disponibles peuvent avoir changé depuis votre dernier téléchargement.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0f3b04d1-1e85-41fc-94cf-d747aab2f21a','fr_MZ','ATTENDEE_README_STEP_2','Les colonnes surlignées en gris (ID utilisateur, nom, ID de connexion, rôle, limite et ID de registre) sont verrouillées et ne doivent pas être modifiées. Toute modification apportée à ces colonnes entraînera le rejet de cette ligne lors du téléchargement.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a04db378-a356-41c0-b861-33e08ca11db3','fr_MZ','ATTENDEE_README_STEP_3','Ce modèle est spécifique à un seul registre : l''ID du registre est déjà pré-rempli pour toutes les lignes et ne peut pas être modifié. Si vous devez mapper les utilisateurs à un autre registre, téléchargez le modèle de ce registre séparément.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c12c6a3b-d8bd-482e-abe0-c23c34bc6b6d','fr_MZ','ATTENDEE_README_STEP_4','La « Date d''inscription » est obligatoire pour tous les utilisateurs. Il décide à partir de quand la présence peut être inscrite sur le registre. Les lignes sans cette date seront ignorées et les utilisateurs ne seront pas mappés. Saisissez la date au format JJ-MM-AAAA. La date doit être comprise dans la durée de la campagne','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2ab47943-c105-4e0c-ab59-e2ca4d7d2c77','fr_MZ','ATTENDEE_README_STEP_5','Date de désinscription : La colonne Date de désinscription est facultative. Si vous saisissez ici une date future, l''utilisateur restera actif jusqu''à cette date et le marquage de présence sera automatiquement bloqué à partir du lendemain.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f61d87d-d175-4c9a-8abe-a0272b4bc53c','fr_MZ','ATTENDEE_README_STEP_6','Si vous devez déplacer un utilisateur d''un registre à un autre, il doit d''abord être désinscrit de son registre actuel. Une fois désinscrits, ils peuvent être mappés à un nouveau registre n’importe quel jour après leur date de désinscription.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8040b658-1baa-4224-acf6-4f3f342ed8a8','fr_MZ','ATTENDEE_README_STEP_7','Que se passe-t-il après le téléchargement : Votre fichier sera traité en arrière-plan. Vous verrez une mise à jour du statut sur cet écran une fois le traitement terminé.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
