INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('993ddc5c-8b79-4ff7-9097-9453d19fea51','fr_MZ','CMP_DRAWER_WHAT_IS_APP_CONFIG_SCREEN','Configurez les paramètres et les fonctionnalités de l''application mobile pour votre campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0e6add5-f864-4916-a5d7-69e8b0139c8f','fr_MZ','CMP_DRAWER_WHAT_IS_CONTENT','Dans Elements, vous pouvez modifier les étiquettes, les en-têtes et les champs du formulaire. Vous pouvez personnaliser le nom, le type et le comportement de chaque champ pour répondre aux besoins de votre campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1d7ad093-bdd6-4b98-8afa-bc6f60a12ef4','fr_MZ','CMP_DRAWER_WHAT_IS_CONTENT_TEMPLATE','Dans Elements, vous pouvez activer ou désactiver des composants et mettre à jour leurs étiquettes et paramètres d''affichage pour ce modèle.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1d9bffc1-a84f-4747-a3b0-c296eedddb0e','fr_MZ','CMP_DRAWER_WHAT_IS_FEATURE_APP_CONFIG_SCREEN','Configurez les formulaires utilisés dans l''application mobile. Modifiez les propriétés des champs, définissez les types de champs et gérez les règles de visibilité ou de champ. Utilisez le panneau des propriétés du champ pour personnaliser chaque champ et ajouter des traductions pour les étiquettes d''interface afin de prendre en charge plusieurs langues.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b8a4315c-5aea-404e-8060-ddb6d8ada0e6','fr_MZ','CMP_DRAWER_WHAT_IS_LOGIQUE','Dans Logic, vous pouvez modifier les validations et la logique associées à l''attribut sélectionné','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
