INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('72648378-94bc-452b-853c-b4d3129f4201','fr_MZ','EXTRA_SHEET_ERROR','Feuille(s) supplémentaire(s) trouvée(s) dans le fichier téléchargé','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('568cd36c-04fe-4965-b474-221dab79ae5c','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1','Cas où il n''y a pas de données d''installation dans le système :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('68931e5b-2621-47be-8154-4071bcccf501','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_1','Étape 1 : Lorsqu''il n''y a pas de données d''établissement dans le système, le modèle « Liste des établissements disponibles » sera vide. Pour chaque établissement ajouté, l''utilisateur doit saisir le nom de l''établissement (doit être unique), le type d''établissement (entrepôt/établissement de santé), le statut de l''établissement (temporaire/permanent), la capacité (saisie du numéro)','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('10679aba-fb95-4d47-8001-7a42e8be8f9e','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_2','Étape 2 : Pour cartographier les installations sur une limite donnée, l''utilisateur doit copier le code de limite correct à partir de la feuille « Données de limite ». S''il existe plusieurs limites auxquelles une installation doit être mappée, l''utilisateur peut ajouter tous les codes de limite séparés par des virgules.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7083026-b412-4ea7-ac45-9dc4d3dbb49b','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_3','Étape 3 : Pour chaque installation, l''utilisateur doit ajouter Actif ou Inactif pour toutes les installations dans la colonne « Utilisation des installations ». Toutes les installations marquées comme « Actives » seront utilisées dans la campagne en cours de création, celles marquées « Inactives » ne seront pas utilisées dans la campagne en cours de création.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad8434f9-5676-41fb-b747-5a55d786b82d','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_1_DESC_4','Étape 4 : Une fois toutes les fonctionnalités ajoutées, l''utilisateur doit enregistrer le fichier sur son système et télécharger le fichier en appuyant sur l''option « Parcourir dans mes fichiers ».','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('08a03a2d-cab4-4a0e-8dc7-b52641c09670','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2','Cas où il existe des données d''installation existantes dans le système :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eaea7c0e-80de-4093-ada6-2daa3812301d','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_1','Étape 1 : Lorsque vous ouvrez le modèle d''installation téléchargé, veuillez vous référer à la feuille Liste des installations disponibles. Pour les installations existantes, veuillez ajouter des entrées dans la colonne Code limite. Vous pouvez trouver les codes de limites dans la feuille de données des limites. Si une installation correspond à plusieurs limites, veuillez séparer les codes par des virgules.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b01683c2-7641-4cb5-b4ba-9162b18fbed6','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Étape 2 : Dans cette étape, l''utilisateur devra ajouter des entrées dans la colonne Utilisation de l''installation avec des entrées valides étant soit Actives, soit Inactives, où l''utilisateur peut définir l''utilisation d''une installation sur Active si l''installation est utilisée pour une campagne ou bien peut être définie sur Inactif. Les entrées dans la colonne Utilisation des installations doivent être ajoutées pour toutes les entrées.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20244021-9e0c-43f1-9eb0-478755ddc53b','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_3','Étape 3 : Pour ajouter de nouvelles installations qui ne sont pas présentes dans la liste des installations existantes, l''utilisateur doit saisir le nom de l''installation (doit être unique), le type d''installation (entrepôt/établissement de santé), le statut de l''installation (temporaire/permanent), la capacité (saisie numérique), le code de limite (à partir de la fiche de données des limites) et l''utilisation de l''installation (active/inactive), comme expliqué précédemment.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('84bcc2c2-9465-44a9-95c0-4115740eb2bc','fr_MZ','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_4','Étape 4 : Une fois toutes les fonctionnalités ajoutées, l''utilisateur doit enregistrer le fichier sur son système et télécharger le fichier en appuyant sur l''option « Parcourir dans mes fichiers ».','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f6b1a435-b9d3-4f3b-955c-7906d06dc426','fr_MZ','FACILITY_DETAILS','Détails de l''installation','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
