INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8c02c3df-f928-4bc8-ac04-ed2402fbd4c8','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_ATTENDANCEFLOW','Présence record des agents de terrain et des bénéficiaires lors des activités de distribution. Assure un suivi précis de la participation pour les rapports.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('21bef157-04b7-477a-a5e3-310a382c8f1a','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_COMPLAINTFLOW','Enregistrez et gérez les plaintes liées aux campagnes de distribution. Permet une capture et une résolution rapides des problèmes pour améliorer la qualité du service.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('289d1df0-1d73-4dbf-986e-6307a301b212','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_DELIVERYFLOW','Surveiller les niveaux de stocks nets d’insecticides et la logistique de distribution. Suivez l’inventaire sur tous les sites et points de distribution.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3943f6bf-66bd-4931-8237-c478fc329957','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_HFREFERALFLOW','La référence est le processus consistant à diriger une personne, un client ou un cas vers une autre personne, un professionnel ou une organisation pour obtenir une assistance, des services ou une expertise supplémentaires.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8db1bd4c-d722-4adb-b457-c70623bcdebb','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_INVENTORYFLOW','Gérer l’inventaire des insecticides et des équipements pour les campagnes de pulvérisation intradomiciliaire à effet rémanent.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e5f9162a-6276-4694-b45d-4ca6b588ccd6','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNETS_REGISTRATIONFLOW','Enregistrez les bénéficiaires des campagnes de distribution de moustiquaires. Capture les détails personnels, les données démographiques des ménages et l’éligibilité à l’allocation nette.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7929473-8126-4212-b121-e8bb49b6ae02','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNET_ATTENDANCEFLOW','Présence record des agents de terrain et des bénéficiaires sur les sites de distribution. Assure un suivi précis de la participation pour les rapports opérationnels.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d96ef4d8-3cc0-4bf4-a77f-805bc9bbfc70','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNET_COMPLAINTFLOW','Enregistrez et résolvez les plaintes pendant la distribution des moustiquaires. Permet une capture rapide des problèmes et améliore la réactivité des campagnes et la qualité du service.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
