INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7d41cf7-34d6-4caa-8eb0-b21f3ef4f5dd','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNET_HFREFERALFLOW','La référence est le processus consistant à diriger une personne, un client ou un cas vers une autre personne, un professionnel ou une organisation pour obtenir une assistance, des services ou une expertise supplémentaires.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7b1ad2ca-0493-460f-825b-ddc42ac2294f','fr_MZ','HCM_MODULE_DESCRIPTION_BEDNET_INVENTORYFLOW','Gérez le stock net depuis l’entrepôt central jusqu’à la livraison du dernier kilomètre. Suivez les transactions, vérifiez les quantités et évitez les utilisations abusives lors de la distribution.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
