INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('43aa47d4-4991-400c-8d2e-505deede29c7','fr_MZ','MODULES','Modules','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3aec8ccd-4099-4b09-a987-8be29c7522e5','fr_MZ','MODULE_DESCRIPTION_APP_PERMISSION_CONFIG','Configurer l''autorisation de l''application','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('49772220-b4da-4726-ab37-eb852b3fba78','fr_MZ','MODULE_DESCRIPTION_ATTENDANCE','Présence record des agents de terrain et des bénéficiaires sur les sites de distribution. Assure un suivi précis de la participation pour les rapports opérationnels.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('554cc85c-2eac-41bb-8130-3c556ec99c49','fr_MZ','MODULE_DESCRIPTION_CLOSEHOUSEHOLD','Enregistrez les foyers qui étaient verrouillés, indisponibles ou inaccessibles pendant le cycle. Permet des suivis structurés et permet de garantir qu’aucun enfant éligible n’est oublié.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4abf69c9-d98c-43b9-8524-2cd87209ac66','fr_MZ','MODULE_DESCRIPTION_COMMUNITYREGISTRATION','Permettre la livraison de vaccins ou de médicaments aux bénéficiaires dans les écoles et autres établissements de vie communautaire tels que les orphelinats, les camps et les institutions résidentielles, où la livraison à domicile ne s''applique pas.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('70a01ddb-5914-429a-8f97-a8009f8978f1','fr_MZ','MODULE_DESCRIPTION_COMPLAINTS','Laissez les agents de terrain consigner les problèmes soulevés par les soignants ou la communauté lors de la distribution, tels que les inquiétudes concernant les médicaments, les ménages manqués ou la qualité du service, afin de permettre un suivi et une résolution en temps opportun.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1a93fbf4-1907-4681-80fb-dfda67748f7e','fr_MZ','MODULE_DESCRIPTION_DELIVERY','Enregistrez les livraisons au niveau des ménages pendant la campagne. Capture l’état de la livraison, la quantité et les détails de confirmation au point de distribution.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c8900b30-b07a-4b7e-8884-6b3dc2f70f51','fr_MZ','MODULE_DESCRIPTION_HFREFERRAL','Enregistrez et gérez les références pour les enfants qui nécessitent une évaluation ou un traitement plus approfondi. Saisissez les raisons de la référence, telles que les contre-indications, les effets indésirables ou les signes de danger, et suivez l''achèvement du traitement dans l''établissement de santé désigné.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('383bfe99-76e0-4945-ae4c-d9a2d4c69352','fr_MZ','MODULE_DESCRIPTION_INSIDEMONITORING','Capture les données post-campagne au niveau des ménages pour valider la couverture vaccinale, similaire au LQAS. Les moniteurs enregistrent les points GPS, les réponses aux enquêtes, les raisons de vaccination manquées, la sensibilisation des soignants et les détails de la surveillance. Fournit un résumé du règlement (nombre d’enfants manqués, indicateurs de risque, statut de couverture, commentaires) et est accessible uniquement aux rôles de surveillance configurés.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('021e950e-e1a7-4855-bb82-b36b5cb2d6ed','fr_MZ','MODULE_DESCRIPTION_INVENTORY','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bbbdcc73-bf28-4109-9bfb-be584559cf4f','fr_MZ','MODULE_DESCRIPTION_LQA','L''en-tête de lot/cluster d''une enquête LQA enregistre les détails de l''emplacement, les informations de l''arpenteur et les coordonnées GPS. Il comprend l''état, le district, le village, l''identifiant du cluster, le nom de l''enquêteur, les détails du superviseur, la latitude, la longitude et la date de l''enquête. Cela garantit un suivi, une vérification et un reporting précis des activités d’enquête sur le terrain.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('df63c148-0835-40f3-afaa-ca0904b694fd','fr_MZ','MODULE_DESCRIPTION_PERMISSIONHANDLER','Gère les autorisations utilisateur nécessaires à l''accès à la caméra, à l''utilisation du réseau et à la fonctionnalité de localisation des appareils.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ed6d644e-f26a-498a-b532-e30640dc08cb','fr_MZ','MODULE_DESCRIPTION_REGISTRATION','Inscrivez les enfants éligibles à la campagne et capturez tous les détails démographiques et de tuteurs requis. Lors des visites sur le terrain, enregistrez les besoins en matière de livraison et de suivi.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5012d145-54ea-4f15-8c3e-95b9bb29f0b3','fr_MZ','MODULE_DESCRIPTION_STOCK','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fd39d368-0fa3-4827-b4d3-929c8c29af55','fr_MZ','MODULE_DESCRIPTION_STOCKRECONCILIATION','Comparez le stock déclaré avec les soldes attendus à la fin de chaque journée ou tour. Identifiez les écarts et validez les données d’inventaire pour maintenir une comptabilité précise des ressources.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1fc837e0-7e87-4bc3-bd55-c01c9b9b3e6c','fr_MZ','MODULE_DESCRIPTION_STOCKREPORTS','Accédez à des rapports de stock récapitulatifs et détaillés pour une analyse dans les établissements, les ASC et les tournées. Prend en charge le suivi de la consommation, des soldes et des pertes tout au long de la campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5c842db8-8c4a-4144-8c35-fa2ef1780d49','fr_MZ','MODULE_FEATURES','Caractéristiques des modules','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5e9c6751-0612-4268-bd7f-d0e8b95b7d21','fr_MZ','MODULE_FEATURES_DESCRIPTION','Activez ou désactivez des fonctionnalités d''application spécifiques pour votre campagne. Certaines fonctionnalités nécessitent une configuration pour correspondre à votre flux de travail. D''autres fonctionnent avec les paramètres par défaut.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9151b5d6-8ecb-49e1-affe-bd04c30a8dbf','fr_MZ','MONITORING_ITN_DP','Surveillance','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
