INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('91ab5232-8931-4341-93f5-71f0a438e377','fr_MZ','MONITOR_LOCAL','Moniteur local','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
