INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('39d802cb-cc7f-4898-850f-64d0803c4e29','fr_MZ','MSG','Ajoutez vos niveaux de hiérarchie de limites en cliquant sur le bouton « Ajouter un nouveau niveau de hiérarchie de limites ». Si vous souhaitez supprimer un niveau, cliquez sur l''icône de suppression à côté du niveau que vous souhaitez supprimer.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
