INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fcca4b0e-f25c-4d23-aa36-6f3e43e518c7','en_MZ','BPA_FAQ_ANS_ONE','When an eDCR scrutiny fails, the error information is marked across each line item in the output file. The architect can make the corrections accordingly and resubmit the plan real time. This can be done any number of times without incurring any additional charges.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a13c3920-2a4d-42c3-bbd4-7d80c68744b9','en_MZ','BPA_FAQ_ANS_THREE','The eDCR scrutiny system compares the parameters in the drawings against the by laws set in the corresponding administrative region and evaluates if they are violating. In the output file, against each paramter that is evaluated, there will be an indication to show if that is approved or rejected. The entire scrutiny process takes ~5 seconds','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('90cae06c-6d04-4128-97fe-390a726f0357','en_MZ','BPA_FAQ_ANS_TWO','You can renew permits at the counter or through the portal. After logging in, search for the relevant permit application in the portal. Then click on link for the permit that you wish to renew. Next, complete the application for the renewal of permit and click submit.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a41eb9e6-5800-46f6-b851-f12904556247','en_MZ','BPA_FAQ_QUES_ONE','What happens when eDCR scrutiny fails? ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8c6c966f-46f6-4656-81d8-82325a9998c6','en_MZ','BPA_FAQ_QUES_THREE','How does eDCR Scrutiny works and how much time it takes to get the diagrams scrutinized? ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
