INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('584e46bd-65c9-4421-b09c-949d290df730','en_MZ','CCF_PP_DD_DEAL_LABEL','PROGRAM NAME refers to the services being provided through PROGRAM NAME  website, mobile App, OTHER CHANNELS AS RELEVANT.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eb050cb5-7b88-432d-9bde-ccd30653f280','en_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_INFO_LABEL','We collect data directly from you (when you use our services) as and when you register and login into the app/website. We may also collect data from Union, State, and Local governments, including their agents/employees, as well as receive data that is available openly for public use.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c46fd74f-3ab1-4563-97b9-c0c0c8130afa','en_MZ','CCF_PP_DO_WE_COLLECT_THIS_DATA_LABEL','HOW DO WE COLLECT THIS DATA?','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a16044a0-c18d-48a0-80b6-cc83377ec04d','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_1_LABEL','Unless indicated otherwise, this data will be retained for a minimum period of AS PER UNION / STATE / ULB LAWS and a maximum period of AS PER UNION / STATE / ULB LAWS. You can review and edit your data, as well as delete your data from the app/website by following the procedures AS PER UNION / STATE / ULB LAWS.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ae1a1f5a-97d8-47f5-9460-aef166c380f4','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_1_LABEL','Your data is stored in a secure manner. PROGRAM NAME is powered by the DIGIT platform, which has embedded privacy settings (such as encryption), which does not allow your data to be visible to anyone, except persons who are authorised to do so by virtue of their official role. ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1bf44beb-af46-4172-8453-f01a14cbf439','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_2_LABEL','You may delete your account any time you wish. In case of deletion, we will remove all your PII  from the system, so that it is not visible and/or accessible from any regular operation. However, the PII may be retained in an encrypted manner for the purpose of legal requirements/compliances AS PER UNION / STATE / ULB LAWS from the date of deletion/termination.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a0e9589a-5620-40ae-969e-e405e4256206','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_3_LABEL','After deletion, in case you wish to recreate your profile, the same is permissible and none of the previously captured information will be populated automatically. You need to register as a fresh user.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f008fcc9-869f-49eb-9f62-230202dd1933','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_4_LABEL','If you simply delete/remove the application from your mobile device but do not delete your profile or unregister yourself from the app/website, you shall continue to be a registered user of the app and we shall continue to send you all communications that you have opted for unless and until you opt-out of such communications, or AS PER UNION / STATE / ULB LAW.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5006a81b-ae60-4b2d-8b9d-527e30724b8d','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_5_LABEL','In case you surrender/disconnect your PROGRAM NAME registered mobile number it is recommended to delete your profile or unregister yourself from the application also.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ea440f54-bb7f-4b35-9f2b-151e30a1dccc','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_6_LABEL',' We have data security measures adopted to ensure that users data is safe and away from dangers of cyber/physical harms. More about the data security measures can be read ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('82223e87-151b-42ad-ac84-8ed7a3704194','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LABEL','HOW DO WE STORE THIS DATA?','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67fb219e-94aa-4da2-8de0-46ae4dc761ec','en_MZ','CCF_PP_DO_WE_STORE_THIS_DATA_LINK_HERE_LABEL',' here. ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b0ad2a23-e68f-49b7-b60f-718038b76b67','en_MZ','CCF_PP_GRIEVANCES_INFO_LABEL','In case of any grievances, you may send your complaints for redressal over Grievance Portal available at ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
