INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('71bee3eb-851c-483b-b5e6-e09fe015a03b','en_MZ','CCF_PP_GRIEVANCES_LABEL','GRIEVANCES','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('66b60de0-81de-4682-a520-f98112a9cf1c','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_10_LABEL','Payments made through the PROGRAM NAME App/website are processed via secure payment gateways.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('62c81d51-686a-4452-8e23-0fc040a69422','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_11_LABEL','We will not process, disclose, or share your data except as described in this policy, or as otherwise authorized by you.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f22ca52f-6fb0-4f19-9cb1-c3d996b93f32','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_1_LABEL','We use this data to serve you with the best civic experience, such as providing digital grievance redressal systems, efficient service delivery, creating dashboards of ULB activities, etc. Data is only processed on the basis of a legal mandate and for a legitimate and necessary purpose (to deliver to you the services you are requesting, and to make improvements in service delivery and administration, as well as any other purposes specified by law).','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('85d31aac-4583-481f-a669-d48107ca3303','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_2_LABEL','We process data which is necessary to provide you with the services you are requesting','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1c0480b1-f6cc-421d-916a-17d4125f4a46','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_3_LABEL','We may process, disclose, or share certain metadata, as well as aggregated and anonymised data, in order to assess and improve the status of such service delivery over time.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d458e7b0-8d92-4e24-86cf-9aaa849c7941','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_4_LABEL','We may disclose or share this data to/with employees and/or contractors of the urban local body, state government, or other government agencies, service providers, whose role requires them to view or use this information in order to perform their official duties, including providing you the service(s) you are requesting.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7a0282d-6eb7-4bdf-b2ea-5eb12d0e04f9','en_MZ','CCF_PP_HOW_DO_WE_PROCESS_INFO_5_LABEL','Data processed or shared while resolving any disputes that may arise with respect to the transactions/deals that you may conduct using the app/website.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
