INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2fc7c15c-d93e-421c-b83f-8a450358f0dc','en_MZ','CCF_STORE_DELETE_YOUR_ACCOUNT_LABEL','You may delete your account any time you wish. In case of deletion, we will remove all your PII  from the system, so that it is not visible and/or accessible from any regular operation. However, the PII may be retained in an encrypted manner for the purpose of legal requirements/compliances {AS PER UNION / STATE / ULB LAWS} from the date of deletion/termination.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
