INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e39706b5-35ec-436f-ac6e-e4121b217658','en_MZ','CCF_STORE_SECURE_MANNER_LABEL','Your data is stored in a secure manner. DIGIT platform, which has embedded privacy settings (such as encryption), which does not allow your data to be visible to anyone, except persons who are authorized to do so by virtue of their official role. Unless indicated otherwise, this data will be retained for a minimum period of {AS PER UNION / STATE / ULB LAWS} and a maximum period of {AS PER UNION / STATE / ULB LAWS}. ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
