INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('053a70a5-86f4-496a-9408-aea057a72435','en_MZ','CCF_STORE_THIS_DATA_LABEL','HOW DO WE STORE THIS DATA?','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
