INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa84605b-5b25-4185-bb7b-086ac6f5d764','en_MZ','CITIZEN_CONSENT_FORM_PP_ACCESS_AVAIL_LABEL','Through PROGRAM NAME, you can access and avail services offered by STATE OR ULB NAME Government departments, Central Government department, Local bodies & their agencies and corporate/private bodies (utility services) (Service Providers). You can use PROGRAM NAME website / application / services in different ways such as, service discovery, availing services, registering grievances, and so on.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('be3f4663-681c-4ce8-b902-fcf2e1367f28','en_MZ','CITIZEN_CONSENT_FORM_PP_DD_DEAL_LABEL','This Privacy Policy describes and determines how we deal with your personal and usage information in accordance with the applicable laws of India.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f3d415b-f529-4aa9-8257-cb84cf3ff841','en_MZ','CITIZEN_CONSENT_FORM_PP_POWERED_BY_DIGIT_LABEL','PROGRAM NAME is a collaboration between PARTNER(S) NAME(S) and eGovernments Foundation. It is powered by DIGIT, which is an open-source software platform developed by eGovernments Foundation.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
