INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('30875b2f-c784-4bac-b4cf-6690f96ccc69','en_MZ','NEW_FSM_SMS_ASSING_DSO_PAY','Dear Applicant, Amount of Rs.{#var#}/- is received towards the payment of cleaning septic tank /pit with reference no. {#var#}. You will be notified when an operator is assigned to a request. Please click this link {#var#}{#var#} to download the receipt.EGOVS','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
