INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2e096785-59ea-4f57-be26-c6d3a815ac8d','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY','Please carry valid ID proof along with the Curfew e-Pass.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('37f4292a-eeed-468d-8567-67b7c874364d','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_FIFTH','5. All Pass holders to observe all COVID19 social distancing and hygiene protocols instructions as issued by the government from time to time mandatorily .','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bea50592-8685-4595-9a0b-4d4e29013217','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_FIRST','1. Lockdown e-Pass is only valid upon showing any of the ID proofs which include Aadhar Card Driving License and Voter ID Card.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3f786f7f-b6e7-41a7-9ce5-446984766e21','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_FOURTH','4. Only travel if you are healthy and fit to travel.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d2439e8e-b1c6-474d-8ee2-8164710ff1a9','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_SECOND','2. Lockdown e-Pass is only valid till 2 days from the date of issue.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4f617367-dd43-4589-bbaa-c120134ea641','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_SEVENTH','7. This e-Pass Certificate can be validated using in any QR code scanner','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b2753340-a923-4885-afb4-031261e4d82f','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_SIXTH','6. All Pass holders should report to the local health department / District administration on reaching their destination and give information of their travel. If necessary, to comply with sample giving / test formalities as necessitated by local authority.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5b12496-0564-43f5-aa37-1c1777cdd6dd','en_MZ','PDF_STATIC_LABEL_CONSOLIDATED_TLCERTIFICATE_LICENSE_DISCLAIMER_BODY_THIRD','3. This e-Pass is only valid for a one time use','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
