INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8a80cc67-4cf7-40f7-b284-0724d33c89ce','en_MZ','PRIVACY_HEADER_2_SUB_1_DESC_2','To update the geotable with shapes that are uploaded to the Business Document Server, you need SAP HANA 2.0 Rev 45','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cd7e03aa-52ad-408f-8eff-857361259ad0','en_MZ','PRIVACY_HEADER_2_SUB_2','Procedure','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2fbc39c4-c313-483d-9823-f553f757d194','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','1. You are on the BI Clients tab in the characteristic editing screen in the BW modeling tools. You have chosen Shapes or Shapes and Point Data as the geographical type.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6327564b-8112-499d-98bd-ec4e413450bd','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','2. Choose Upload Shapefiles under Actions. Choose Go. The BW/4 back end opens.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e45a89a9-867f-4e4c-8438-7207f0b7d05c','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','3. Select your shapefiles. You need the following three shapefiles: .dbf, . shp, .shx. The shapefiles must be in the Spatial Reference ID 4326 and should all have the same name before the ending.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('07564e51-95b6-43e4-b501-7198281ee9bd','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','4. Choose Update Geotable under Actions. Choose Go. You can choose either Delta Update or Full Update.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d12cad79-8fdc-46ef-b5ed-d8fbf5e0c54a','en_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','5. The uploaded shapes are transformed and stored in SRID (Spatial Reference ID) 3857.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d3c0e250-7dde-4c0f-96f4-f1a179a32120','en_MZ','PROFILE_UPDATED','Profile updated successfully','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('79f6f94c-4d67-464b-b9da-09b49e549cce','en_MZ','PROJECTS_DESCRIPTION','Project Description','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7ca8f8a2-3590-41bf-9021-d802405c66e1','en_MZ','PROJECT_BANNER','Only jpg, pdf, doc, docx, xls, xlsx files can be uploaded. File size should not exceed 5 MB.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
