INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('49e101b5-f1b4-4da0-a963-e34b7d987334','en_MZ','TL_FAQ_ANS_ONE','You can renew trade licenses at the counter or through the portal. After logging in, search for the relevant trade license in the portal. Then click on link for the trade license that you wish to renew. Next, complete the application for the renewal of Trade License and click submit.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99542393-52eb-41ae-a734-0bef50dddc24','en_MZ','TL_FAQ_ANS_THREE','After you login with your credentials, click on my application. Among all the applications listed, find the one for which status is ''approved'' and click on ''View Details''. In the next page, click on the ''Download'' button on top right corner. In case of approved applications, TL certiifcate and Payment Receipt will be show in the drop down and click on the relevant one to download. ','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('153ff642-3bdd-45b4-a645-8f719b91ac5c','en_MZ','TL_FAQ_ANS_THREE_APP_ACKNOWLEDGE','In case application is under processing, then you can download an Application Acknowledgement through the same methodology.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3da50b53-8931-4c6e-a97f-eb3334cba4d4','en_MZ','TL_FAQ_ANS_TWO','You can search for your previous applications by clicking on My Applications in the home screen. Then click on the relevant application card among the list.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
