INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5fe1511d-64fe-4545-9c5a-903dc5c3e3ff','pt_MZ','PRIVACY_HEADER_2_SUB_1','Pré-requisitos','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('09e57cd8-82b5-400f-b23b-59c6a44aca72','pt_MZ','PRIVACY_HEADER_2_SUB_1_DESC_1','Você adicionou uma coluna ou campo com o nome da característica aos shapefiles para os quais deseja carregar formas. Se estiver usando características compostas, você adicionou diversas colunas. Mais informações: Preparando Shapefiles','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('98972ffc-19a9-4bd9-b1a5-4fdd91d12f46','pt_MZ','PRIVACY_HEADER_2_SUB_1_DESC_2','Para atualizar a tabela geográfica com formas que são carregadas no Business Document Server, você precisa do SAP HANA 2.0 Rev 45','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ec4cb8ef-5e5c-4e5c-adf1-96f42525bb0e','pt_MZ','PRIVACY_HEADER_2_SUB_2','Procedimento','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0a1431e0-3cef-4422-af40-b94d8fb31584','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','1. Você está na aba Clientes BI na tela de edição de características nas ferramentas de modelagem do BW. Você escolheu Formas ou Formas e dados de pontos como tipo geográfico.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d813d4c1-7727-4add-9b02-d5c1654356f6','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','2. Escolha Carregar Shapefiles em Ações. Escolha Ir. O back-end do BW/4 é aberto.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('490ff456-43f5-43a0-a233-0c597f5dae08','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','3. Selecione seus shapefiles. Você precisa dos três shapefiles a seguir: .dbf, . shp, .shx. Os shapefiles devem estar na Referência Espacial ID 4326 e devem ter todos o mesmo nome antes do final.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9a7ecf04-bc41-4847-8ced-8c12989cef84','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','4. Escolha Atualizar tabela geográfica em Ações. Escolha Ir. Você pode escolher Atualização Delta ou Atualização Completa.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db986baa-26ab-4635-b9b5-b8a24276e82c','pt_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','5. As formas carregadas são transformadas e armazenadas no SRID (Spatial Reference ID) 3857.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('585f51d3-1873-4e07-b54a-1804a64111d5','pt_MZ','ROWS_PER_PAGE','Linhas por página','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
