INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f0c39053-7221-406e-b9a2-190ec70befcb','fr_MZ','PRIVACY_HEADER','Remarque sur la confidentialité','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2efa7ef5-046f-4d24-9994-8f04dad5e6cf','fr_MZ','PRIVACY_HEADER_2_SUB_1','Conditions préalables','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8095be9d-95fe-4447-b324-e7f2d97e554d','fr_MZ','PRIVACY_HEADER_2_SUB_1_DESC_1','Vous avez ajouté une colonne ou un champ portant le nom de la caractéristique aux fichiers de formes pour lesquels vous souhaitez charger des formes. Si vous utilisez des caractéristiques composées, vous avez ajouté plusieurs colonnes. Plus d''informations : Préparation des fichiers de formes','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5ffab407-1930-48de-8856-4e33db0a531d','fr_MZ','PRIVACY_HEADER_2_SUB_1_DESC_2','Pour mettre à jour la géotable avec les formes téléchargées sur le Business Document Server, vous avez besoin de SAP HANA 2.0 Rev 45.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0f64af0c-7592-4699-9cbf-40483ba7a3fa','fr_MZ','PRIVACY_HEADER_2_SUB_2','Procédure','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3765edeb-05f9-46e5-becf-89c794ec4bad','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_1','1. Vous êtes sur l''onglet Clients BI dans l''écran d''édition des caractéristiques dans les outils de modélisation BW. Vous avez choisi Formes ou Formes et données de points comme type géographique.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5f547aca-57de-4656-b984-32bc896897fc','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_2','2. Choisissez Télécharger des fichiers de formes sous Actions. Choisissez Aller. Le back-end BW/4 s’ouvre.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99d2a875-8dc5-4d27-9fa5-937a3af23740','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_3','3. Sélectionnez vos fichiers de formes. Vous avez besoin des trois fichiers de formes suivants : .dbf, . shp, .shx. Les fichiers de formes doivent figurer dans l''ID de référence spatiale 4326 et doivent tous avoir le même nom avant la fin.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2d68f622-4c16-4d79-be35-ab853d1e8103','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_4','4. Choisissez Mettre à jour la géotable sous Actions. Choisissez Aller. Vous pouvez choisir entre la mise à jour Delta ou la mise à jour complète.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('58d44896-2ffd-4cf5-a8c3-6f3fd3c710cf','fr_MZ','PRIVACY_HEADER_2_SUB_2_DESC_5','5. Les formes téléchargées sont transformées et stockées dans SRID (Spatial Reference ID) 3857.','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('12c7098a-7194-4fb9-9d76-ba5e4e571827','fr_MZ','ROWS_PER_PAGE','Lignes par page','mz','rainmaker-common',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
