INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6555f183-f2ad-4f80-bc87-d06b0666164b','en_MZ','DASHBOARD_BUILT_WITH_PURPOSE','With the Health Campaign Management Dashboard, users can quickly identify campaign progress, generate detailed summary reports with a single click, and measure the campaign coverage, and identify potential roadblocks. This information can help users to plan stock requirements and identify areas for planning future campaigns. Additionally, the dashboard enables users to track the progress rate of healthcare campaign services.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
