INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('578290f5-5944-4bc8-90cf-931ab0db5811','en_MZ','DSS_ABOUT','About','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1df0c12f-4459-4c71-8fc7-a9f95f9f9f2d','en_MZ','DSS_ABOUT_ACCESS_CONTROL','Access control: Access to the dashboard is limited to authorized personnel only and data access can be limited based on role-based permissions.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4269ad0b-1966-4331-8412-4e5e45cc10ff','en_MZ','DSS_ABOUT_ANALYZE_PERFORMANCE','Analyze the campaign performance data by drilling down from province to district to administrative post to locality to village level using the available charts.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2cd1d17e-a754-483c-bf54-6577d64c0c70','en_MZ','DSS_ABOUT_ANS_DASHBOARD_USECASE_A','A dashboard is a visual representation of performance metrics and data related to a healthcare campaign. It provides an easy-to-understand overview of the campaign''s performance and monitoring the campaign. The data presented on the dashboard is aggregated and anonymized, ensuring the confidentiality of individual households and population data.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1ac4590a-0f04-4aad-854d-c6579c49d828','en_MZ','DSS_ABOUT_ANS_DASHBOARD_USECASE_B','The dashboard also enables analysis of the campaign''s performance at various levels and provides visualizations such as graphs and heat maps. Using a dashboard can help health campaign platform users make informed decisions, improve the campaign''s effectiveness, and ensure efficient delivery of healthcare services and interventions to the target population.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5af7b94-68c7-48d4-9624-83b769b02fe2','en_MZ','DSS_ABOUT_ANS_DATA_SECURITY','To ensure the security of data in the dashboard, several measures are implemented, including:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bd96659b-de09-43c8-8b3e-b74c24ae2501','en_MZ','DSS_ABOUT_ANS_GET_ALTERNATIVE','Alternatively, the country may have developed its own digital means of providing information to the dashboard or may use a platform similar to DIGIT. In any case, having a digital platform for managing and monitoring the healthcare campaign is essential for tracking progress and ensuring that the campaign''s objectives are met.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('df850805-ab6b-4f25-9d92-5bf19b743ab4','en_MZ','DSS_ABOUT_ANS_GET_CAMPAIGN','In the healthcare campaign, Field Level Workers (FLWs) are responsible for collecting and inputting data related to households and citizens. This data is crucial in analyzing the performance of the campaign, identifying areas that require attention and monitoring progress.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7f50765f-2fc0-4927-85e9-6a27d96759fd','en_MZ','DSS_ABOUT_ANS_GET_CAMPAIGN_FLW','The FLWs share this data while providing campaign services and interventions, enabling the system to collect relevant data at the ground level. The data collected by the FLWs is then used to create a comprehensive overview of the campaign''s performance, which is presented on the campaign dashboard.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3217bd4b-e978-46e9-ad04-4f0c92163250','en_MZ','DSS_ABOUT_ANS_GET_HCM','The healthcare campaign management service in the country is based on DIGIT, a platform that provides tools to manage healthcare campaigns effectively. This platform streamlines the process of data collection, storage, and analysis, making it easier for FLWs and boundary-level users to input data into the system. The platform also provides tools to generate reports and visualizations, making it easier to monitor the campaign''s performance and identify areas for improvement.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1ed51cb8-9e50-40a7-bfa7-97e060649568','en_MZ','DSS_ABOUT_ANS_GET_MANAGERS','Supervisors and warehouse managers, who are boundary-level users, also play a crucial role in providing datasets required for the dashboard. They contribute to the dashboard by providing data on the supply chain, stock management, and other relevant information. The datasets provided by these users are combined with the data collected by the FLWs to create a comprehensive picture of the healthcare campaign''s performance.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1334240b-3d66-4d4c-a9d1-a1e42d901665','en_MZ','DSS_ABOUT_ANS_WHAT_CAN_DASHBOARD_VIEWER_SEE_AND_DO','The dashboard enables the user to view:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51232c19-129d-4d19-9afa-47572f44785c','en_MZ','DSS_ABOUT_AREA_BOUNDARY','Performance metrics presented based on area boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('38ea6f59-7f4b-44de-8a98-2bed7e47871e','en_MZ','DSS_ABOUT_BOUNDARIES_DATA','Boundaries Data - This refers to the information gathered by field-level workers responsible for the assigned area of the campaign. This data is used to track progress and inform decision-making through the dashboard.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('26ef8bc5-c650-4453-93f2-75645f6508bd','en_MZ','DSS_ABOUT_CLARITY_ON_DASHBOARD','To clarify certain terms used in the dashboard:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f91e7a94-8fc2-45a9-9665-36512fd26d3f','en_MZ','DSS_ABOUT_COMPARE_PERFORMANCE','Compare the campaign performance of different districts within the province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2cc2410f-8fad-4811-a322-d1b813052103','en_MZ','DSS_ABOUT_DASHBOARD','About the Dashboard','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('99411b0f-a8df-4d1a-87b9-dbfb39a33197','en_MZ','DSS_ABOUT_DASHBOARD_DESIGN','The dashboard is designed to present a summary of the data collected through the front line app used for the delivery of health interventions. The data is aggregated, meaning it has been compiled and processed to create a comprehensive overview of the healthcare campaign''s performance. The information presented on the dashboard does not contain any personally identifiable details, such as Team worker names or any personal detail.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8cf3d87c-7215-4ed9-ab92-e7e5c902f86b','en_MZ','DSS_ABOUT_DASHBOARD_OBJECTIVE','The primary objective of the dashboard is to provide an overview of the health campaign''s performance. The dashboard uses specific identifiers to categorize and organize the data, making it easier for viewers to understand and interpret the information presented.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('03570758-7ca4-4af3-907e-bd1dd8f2678d','en_MZ','DSS_ABOUT_DASHBOARD_USE','With the Health Campaign Management Dashboard, users can quickly identify campaign progress, generate detailed summary reports with a single click, and measure the campaign coverage, and identify potential roadblocks. This information can help users to plan stock requirements and identify areas for planning future campaigns. Additionally, the dashboard enables users to track the progress rate of healthcare campaign services.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c032d642-6439-40f1-9631-4bfb17ece831','en_MZ','DSS_ABOUT_DASHBOARD_USE_IDENTIFIERS','Using these identifiers, the dashboard can showcase the strengths and weaknesses of the healthcare campaign across various districts, administrative posts, localities or villages in the provinces, highlighting areas that require further attention and improvement.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9c231b9-073b-49a0-ae01-7559be72fb9a','en_MZ','DSS_ABOUT_DATA_MASKING','Data masking: The sensitive data is masked to protect personally identifiable information, and only authorized personnel can access the unmasked data.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('598aa7c4-0442-4293-ba84-da58f2b595b4','en_MZ','DSS_ABOUT_ENCRYPTION','Encryption: The data transmitted to and from the dashboard is encrypted using secure communication protocols, such as HTTPS or SSL, to protect against interception and unauthorized access. The data can be encrypted to prevent unauthorized access and ensure data confidentiality. This can be done using secure encryption protocols such as AES or RSA.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2d75eaba-84a6-4fb4-addb-0278fae989ef','en_MZ','DSS_ABOUT_FOLLOWING_VIEWER_DO_ON_DASHBOARD','On the dashboard, the user can:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7e1d91c8-e1a4-4d7b-863c-c50dd47e0709','en_MZ','DSS_ABOUT_KEY_TERMS','Key Terms','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('af60e2bb-ef41-43a4-b13e-853f1fc73242','en_MZ','DSS_ABOUT_MONITOR_PERFORMANCE','Monitor campaign performance at all boundary levels of the province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5b7e8f42-2a2e-404a-8985-085793add62d','en_MZ','DSS_ABOUT_PERFORMANCES_IN_FORM_VISUALIZATIONS','Performance metrics are presented through visualizations such as graphs and heat maps.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4bf08529-334c-49f1-bcc7-a2bc282f12d7','en_MZ','DSS_ABOUT_PERFORMANCE_METRICS','Performance metrics for the healthcare campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8a657050-2082-4b22-9d84-a14ac382828e','en_MZ','DSS_ABOUT_PURPOSE','Purpose','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('905e568b-d1df-4d2b-9121-b027e6667182','en_MZ','DSS_ABOUT_PURPOSE_DEFINE','The purpose of the dashboard is to ensure data transparency, provide easy access to data, promote accountability, and facilitate data-driven decision-making.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa34a130-0dfa-467d-8a38-fbb716f88dec','en_MZ','DSS_ABOUT_PURPOSE_INFO','The Health Campaign Management DIGIT Dashboard is a Decision Support System (DSS) tool that provides health campaign management teams with a consolidated and interactive dashboard. The dashboard presents key metrics in a visually appealing format, making it easier for users to understand campaign progress, stock efficiency, and areas for improvement.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a9ac0d02-c4d2-4ad8-8d2a-e707531b49b6','en_MZ','DSS_ABOUT_QUES_DASHBOARD_USE','Why is a dashboard used in healthcare campaigns?','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('13f71a5c-f24a-4cac-9506-7d8ed8848334','en_MZ','DSS_ABOUT_QUES_GET_DATA_FROM_DASHBOARD','Where does the data for the dashboard come from?','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0f6dcdf1-a1f2-4469-897b-d03ed7800376','en_MZ','DSS_ABOUT_QUES_HOW_DATA_SECURED','How is this data secured?','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b8c70980-f733-4651-823b-bb14f6e9d009','en_MZ','DSS_ABOUT_QUES_WHAT_CAN_DASHBOARD_VIEWER_SEE_AND_DO','What can the user of the dashboard see and do?','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c47eae23-5c30-4ee1-8f80-ed911f62bd44','en_MZ','DSS_ABOUT_QUES_WHAT_IS_DATA','What is ‘data’?','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5b05b117-2aa1-466a-a465-9fee68814e74','en_MZ','DSS_ABOUT_REGULAR_BACKUPS','Regular backups:  The data can be regularly backed up to prevent data loss in the event of a security breach or system failure.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f1bbb076-130a-4174-8894-8b99c801a18f','en_MZ','DSS_ABOUT_REGULAR_SECURITY_AUDITS','Regular security audits: Regular security audits should be conducted to ensure that the dashboard remains secure and to identify and fix any security vulnerabilities that may arise.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d493f836-b505-4933-906c-34c5d991456b','en_MZ','DSS_ABOUT_SECURE_HOSTING','Secure hosting: The dashboard should be hosted on a secure server that is regularly updated with security patches and other security measures to prevent hacking and data breaches.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('595f057f-12e7-409f-99d9-8be36bf1f8e4','en_MZ','DSS_ABOUT_SERVICE_LEVEL_PERFORMANCE','Performance metrics presented at various levels, including province, district, administrative post, locality and village.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51784478-17be-41e6-8c04-fa5d5972b5f0','en_MZ','DSS_ABOUT_UNIQUE_CHAR','# / % - In the dashboard, the "#" symbol represents data that is displayed as a count, while the "%" symbol represents data that is displayed as a percentage. These symbols are used to identify the format in which the data is presented in the dashboard.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ba02110-dca2-4a7f-a213-b3ae7d4020b1','en_MZ','DSS_ABOUT_USERS_DEFINE','Users - These are the.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('39e5bd49-70d5-44c4-90bb-c7b0b757a990','en_MZ','DSS_ABSENT_WORKERS_ONCE','Absent Workers','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31f7f6bc-4811-4198-8dd5-a27a639b8c0c','en_MZ','DSS_ATTENDED_WORKERS','Attended Workers','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1a6e08d7-b675-48f0-bc78-abac396631d7','en_MZ','DSS_ATTENDED_WORKERS_PERCENT','% Attended Workers','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d77f7e8c-81b3-40e6-bc56-7f0eee3bb236','en_MZ','DSS_CALCULATIONS','Calculations','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('67076bca-540d-4500-8856-7bae2e6c0e8e','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR','Average Complaint Resolution Time (Hrs)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dcb84d6a-3d0e-4619-b50c-a2020b608172','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR_FIVE','The Boundary data could be ‘districts’ for provincial/national users and ‘Administrative posts’ for district user roles.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4768938-87d4-4112-ba5b-65bebecce9b3','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR_FOUR','The average complaint resolution time is then calculated by adding all resolved and rejected complaints time and then dividing it by the total number of resolved and rejected complaints for that particular boundary and date range. This calculation gives the average time taken to resolve a complaint for that boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9045a679-3c39-421c-81ff-985a88dfced2','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR_ONE','The Average Complaint Resolution and Response Time chart is used to show the average time taken to resolve a complaint for each boundary. The chart will be a bar chart, with the y-axis showing the average time taken in hours and the x-axis showing the different boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8ca13c0d-f51d-4173-bca5-66ea6a6f5274','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR_SIX','The bar chart will show the average complaint resolution time for each boundary, with the height of each bar representing the average time taken to resolve a complaint. This chart helps to identify which boundaries are taking longer to resolve complaints and could indicate areas where improvements are needed to improve the complaint resolution process.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7853071-dcb5-4ef5-aa97-14894c0452ff','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR_THREE','For each ‘resolved’ complaint, we calculate the difference in time between the time at which the complaint was created and the time at which it was resolved. Similarly, for each ‘rejected’ complaint, we calculate the difference in time between the time at which the complaint was created and the time at which it was rejected. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4f7a0e07-98cc-4fe3-8d52-c70b278d4237','en_MZ','DSS_CALCULATION_AVERAGE_COMPLAINTS_RESOLUTION_TIME_HOURS_BAR_TWO','To calculate the average complaint resolution time, only those complaints whose statuses are either ''REJECTED'' or ''RESOLVED'' (within the selected date range) should be considered.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('df022bff-f26b-475a-b26b-527bd7c8fe05','en_MZ','DSS_CALCULATION_BOUNDARY_WISE_SHARE_OF_COMPLAINTS','Boundary Wise Share Of Complaints','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a846fc64-56d5-4d71-a435-ab2b89c0bfa6','en_MZ','DSS_CALCULATION_BOUNDARY_WISE_SHARE_OF_COMPLAINTS_FOUR','To validate the accuracy of the chart, the sum total of all bars should be equal to 100%.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0da5c93c-077f-48da-84ac-48679601eda7','en_MZ','DSS_CALCULATION_BOUNDARY_WISE_SHARE_OF_COMPLAINTS_ONE','The "Boundary Wise Share of Complaints" is a bar chart that shows the percentage share of complaints created for each boundary within a selected date range. The chart is based on two data sources: Boundary Data from the MDMS and Complaints data from the Complaints module in the mobile application.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bef4049a-fc40-4c3a-9f84-1b499fc40067','en_MZ','DSS_CALCULATION_BOUNDARY_WISE_SHARE_OF_COMPLAINTS_THREE','For National and Provincial Users, the boundaries are ‘districts’, whereas for District Users, the boundaries are ‘administrative posts’. The chart shows the distribution of total complaints across different boundaries, allowing the user to identify which boundaries have the highest and lowest number of complaints created within the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('822c7a0b-d5b1-4047-8db6-7cee05c867e2','en_MZ','DSS_CALCULATION_BOUNDARY_WISE_SHARE_OF_COMPLAINTS_TWO','Each bar of the chart represents a specific boundary, which can be a district or an administrative province (AP) as per the user role. Each bar of the chart represents the percentage share of complaints created for that boundary, out of the total complaints created in all the boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c523fd26-3d86-45e4-bac4-b9415ae3a7f2','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_BOUNDARY','Complaints By Boundary','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('651aa377-fd36-44d7-861e-c7be8d9ddf07','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_BOUNDARY_FOUR','However, the complaints where status=Created should not be considered to avoid repetition.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('14292dff-6d76-4e7a-a6d7-5c1395841beb','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_BOUNDARY_ONE','This bar chart presents the total number of complaints by boundary for the selected date range. The data source for this chart is the Complaints module in the mobile application, and the boundary data is obtained from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6646db57-a154-4c71-a2ee-b1870029f248','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_BOUNDARY_THREE','Each bar in the graph represents the total number of complaints for a specific boundary. The total complaints for each boundary will be calculated as the sum of open, resolved, and rejected complaints, during the selected date range. The date range is selected from the date range filter on the dashboard.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('66ab236c-639f-4044-8c15-14001bf8d089','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_BOUNDARY_TWO','The chart is displayed as a bar chart with the number of complaints on the y-axis and the boundary data on the x-axis. The boundary data is districts for National & Provincial users and administrative posts for District users.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3660cd2f-3edf-4aac-9b9c-d481e583b00a','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_STATUS','Complaints By Status','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2d4d791b-2479-489f-a516-821856cdd688','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_STATUS_FIVE','It is important to note that the complaints where status is ‘Created’ are not considered to avoid repetition.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2a658305-9ca5-46ba-9dd2-20c333786b55','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_STATUS_FOUR','The x-axis of the chart represents the selected boundary (district or administrative post), and the y-axis represents the number of complaints. The total number of complaints is calculated as the sum of Open, Resolved, and Rejected complaints.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('beafa1c0-3fff-4fa4-a122-ddd7bb2f3007','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_STATUS_ONE','The "Complaints by Status" chart is a stacked bar chart that shows the distribution of complaints by their status (Open, Resolved, and Rejected) across different boundaries (districts or administrative posts) for a selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('046bf664-6216-4913-b344-42d808691ba8','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_STATUS_THREE','There are two toggle options for the chart - ‘number’ toggle and ‘percentage’ toggle. When the number toggle is selected, the chart displays the absolute count of complaints for each status. When the percentage toggle is selected, the chart shows the percentage distribution of complaints for each status.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8cc6ee91-3a90-4b55-9663-1214adb966cd','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_STATUS_TWO','The calculation involves counting the total number of complaints created for a selected boundary (province, district, or administrative post) for a date range. Then, for each boundary, the number of complaints that are Open, Resolved, and Rejected are counted and represented as a stack in the bar chart.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e7e8453c-d4b1-4d9c-a56d-28393073634c','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE','Complaints By Type','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5d75433d-5fc8-44dc-ba29-f233f9afb944','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_FOUR','For national and provincial users, the selected province will be the boundary data, while for district users, the assigned district will be the boundary data.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f8784e8f-8737-4a12-9ba5-e9e05869b4b8','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_ONE','The "Complaints by Type" have a pie chart that shows the total number of complaints by their types in a selected province or district for a date range. As this report is presented in a pie chart format, where each slice of the pie represents a specific complaint type.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('74ce9ada-2511-474d-a3dd-0afa53bc0f52','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR','Complaints By Type','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ef12cf68-c9dc-4406-9dd7-7a04af3b8761','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR_FIVE','The x-axis of the chart represents the different boundaries, with districts displayed for National and Provincial users and administrative posts displayed for District users. Each bar of the graph shows the total complaints stacked with the complaint type, boundary, and date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a3d58316-27ce-4d23-9470-68fb673020d1','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR_FOUR','For the percentage toggle, each stack of the bar represents the percentage of complaints for a specific complaint type within a particular boundary and date range, calculated as a percentage of the total complaints for that boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('56ab67cc-078f-4eda-88b6-665f78cab705','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR_ONE','The ‘Complaints by Type’ stacked bar chart shows the total number of complaints by their type for the selected date range, displayed as a stacked bar chart. The chart is divided into sections, with each section representing a different type of complaint, such as Logged, Synced, or Crashed etc…','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5239ffd4-e5c3-49a3-9397-e0843a949cf6','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR_SIX','To ensure accuracy, the sum total of all complaint types for a particular boundary should be equal to the total complaints for that boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7910d916-b4a2-4d64-bf5a-6d48a2985d80','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR_THREE','The chart can be toggled between showing the ‘number’ of complaints and the ‘percentage’ of complaints for each complaint type. For the number toggle, each stack of the bar represents the total number of complaints for a specific complaint type within a particular boundary and date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('38e56351-88b9-4cf5-b902-6f07ef612dd1','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_STACKED_BAR_TWO','The data for the chart is taken from the Complaints module in the mobile application and is organized by boundary data from MDMS. The total number of complaints for each boundary is calculated by summing all complaints created for that boundary and within the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c250c44-a461-4cc9-9075-723aba4963c8','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_THREE','The data of the "Complaints" module is taken from the mobile application, which is available in the MDMS. The complaint types will be predetermined values, such as "App Malfunction," "Login error," "Sync error," "Forgot password," and "Others," which are configured in the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7763bcac-1adf-436f-8b82-a3a6e332361e','en_MZ','DSS_CALCULATION_COMPLAINTS_BY_TYPE_TWO','The percentage of each slice is calculated based on the total number of complaints for that specific type and the total number of complaints for the selected boundary role user. The count of complaints for each type will also be displayed as a tooltip when hovering over the slice of the pie.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('307f4103-badd-46b9-88a8-4c6be09dde13','en_MZ','DSS_CALCULATION_COMPLAINTS_TAB_OVERVIEW_ONE','A section of the dashboard displaying analytics on complaints, including complaint type, response, and status. This information can be used to make improvements to the complaint handling process and to address any recurring issues.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('605950af-25dd-4c43-a377-7fede8bd4e50','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY','Number Of Days To Last Inventory','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('252a3ac2-b53d-4bba-b3ee-80f3f277890f','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_ONE','The ''Number of days to last inventory'' is a metric that represents the number of days the current inventory of bednets can last based on the current rate of consumption. This metric is useful for the dashboard users to determine when to order more bednets to ensure that there is an adequate supply to meet the demand.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('90e894ca-f0c0-4882-b3ed-1c7eaab71494','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_POINTS_HEADING','The calculation involves the following steps:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('08a67e9b-c44f-472a-abef-668c0ba0e519','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_POINT_FOUR','Number of days the inventory can last based on the current consumption rate, this is calculated as the ‘total stock on hand’ divided by the total expected consumption for all warehouses within the boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d5cccd10-690f-4a87-b5ad-026519a6b401','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_POINT_ONE','Determine the stock on hand as of today''s date for each warehouse in the district or administrative post.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e16920b6-69a8-4e58-8aa7-99fbcb7f7551','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_POINT_THREE','Calculate the total expected consumption for all warehouses within the boundary. This is calculated as the sum of the bed nets of the stock on hand for each warehouse and the daily microplan target for the district or administrative post.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('198b63b4-0de1-40e0-9bb6-29363b94b412','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_POINT_TWO','Calculate the daily microplan target for bed nets.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c1a4b13e-fdc1-4963-8a4d-4d01aa6a4065','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_THREE','It is important to note that the micro plan target should be set based on the daily bednet target for the province and the stock on hand should be considered for all warehouses within the boundary of the district or administrative post.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5013cb3d-3cdb-471e-a794-513cad2e71fd','en_MZ','DSS_CALCULATION_INVENTORY_NO_OF_DAYS_TO_LAST_INTVENTORY_TWO','To calculate this metric, the application uses the inventory management data from the ''Stock Reconciliation'' page, which includes the stock on hand for each warehouse individually. The calculation takes into account the daily microplan targets for bednets and the total number of warehouses within the boundary of the district or administrative post.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f5c1ba9f-3a16-4f76-b2e5-cb57cf305ab4','en_MZ','DSS_CALCULATION_INVENTORY_STOCK_IN_HAND','Stock In Hand','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ab3f14b7-ab14-4613-8a20-a79577acce30','en_MZ','DSS_CALCULATION_INVENTORY_STOCK_IN_HAND_ONE','The "Stock in Hand” metric represents the total available and Required bednets as of today in each boundary according to the last updated data. This metric is calculated using the Inventory Management data from the Stock reconciliation page of the application, which includes the stock on hand for the current day. The calculation for the side-by-side bar graph is done as:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('44265109-e7b7-478d-a1ce-4cc6cfd9233b','en_MZ','DSS_CALCULATION_INVENTORY_STOCK_IN_HAND_POINT_ONE','Calculate the number of ‘available’ bednets (Blue Bar): Get the stock in hand for the current day from the Inventory Management data. This includes the stock in hand day plus any stock received, minus any stock issued, returned on the current day. Further calculate the total available bed nets in each warehouse for the given boundary (District or Administrative Posts) by multiplying the daily micro plan target by the number of campaign days and summing across all warehouses.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f2a92330-16d9-4a92-846f-0802ab0bcbda','en_MZ','DSS_CALCULATION_INVENTORY_STOCK_IN_HAND_POINT_TWO','Calculate the number of required bednets (Orange Bar): The bed nets required for the boundary as per the micro plan for the entire campaign duration based on the project setup. Further now calculate the cumulative bed nets distributed so far. Calculate the remaining bed nets required by subtracting the cumulative bed nets distributed from the bed nets required.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2d83c829-3382-4d4a-bd5f-883e4fe3b5ee','en_MZ','DSS_CALCULATION_INVENTORY_STOCK_IN_HAND_TWO','The resulting metric is represented as a side-by-side bar chart that shows the number of ‘available’ bednets and the actual ‘required’ number of bednets for each boundary. The "Available" bars are represented in blue, and the "Required" bars are represented in orange. The metric is presented in a default view of district-wise for national and provincial users and administrative-post wise for district-level users.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e6d6834-a47b-4121-bbcd-f29f7ffb6b2a','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT','Summary Report','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db6356a5-f137-4df6-911b-9a9c01305665','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_BOUNDARY_NAME','Boundary Name','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('00ad5c8f-755b-439f-b02c-17524e5ee156','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_BOUNDARY_NAME_ONE','The boundary column in the summary report table indicates the level of division for which the stock report is being displayed. For National and Provincial level users, the boundary column will display the names of the districts, whereas for District level users, the boundary column will display the names of the administrative posts.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('22790da3-5242-470b-a034-e135ebc74e3c','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_BOUNDARY_NAME_TWO','This column is used to group and organize the stock data for each division. The drill-down feature can be used to view the stock detail for all warehouses within a specific boundary at the granular level.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bbd7da27-d0ca-4581-a7d4-42e91d382030','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_DAYS_TO_LAST','Days To Last','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('48ad3eda-90a7-4082-b827-70413824a852','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_DAYS_TO_LAST_FOUR','In summary, the "Days to last" column provides valuable information on the number of days that the current stock of bednets can last, based on the current rate of distribution and consumption, which is calculated by dividing the total number of bednets in stock by the daily microplan target.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b56ae8ba-312e-4b17-b154-649efe33df25','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_DAYS_TO_LAST_ONE','The "Days to last" column in the summary report refers to the number of days that the bednets currently in stock can last, based on the current rate of distribution and consumption. This is calculated by dividing the total number of bednets currently in stock, denoted as ''c'', by the daily microplan target, denoted as ''b''.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('db71ff32-39af-4257-8248-aff729bc340c','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_DAYS_TO_LAST_THREE','The total number of bednets in stock, denoted as ''c'', is the sum of bednets across all warehouses under this boundary. The value of ''b'' is the daily microplan target for the bednets, which is set in the project setup. Finally, the value of "Days to Last" , denoted, is calculated as c/b.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2e0f24b3-9cc3-420d-a9ba-7536abf9dd43','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_DAYS_TO_LAST_TWO','To calculate the total number of bednets in stock, we need to use the stock reconciliation page, which calculates the stock on hand for the current day, denoted as ''a''. This is calculated by adding the stock in hand from the previous day with the stock received and returned, and then subtracting the stock issued.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('998195d2-74ed-45cf-932b-fe5fd53659f4','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_DISTRIBUTED','Nets Distributed','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('955f00b9-4aaf-4cda-884c-ce03988436ff','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_DISTRIBUTED_ONE','The "Nets distributed" column in the summary report shows the number of nets that were distributed during the selected date range. The calculation is based on the quantity of nets recorded in the "Record Stock issued" form in the Inventory Management system for each warehouse under the boundary. The sum of the quantity of nets distributed across all warehouses under the boundary is then displayed in the "Nets distributed" column.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('027aa67f-f473-4698-ba21-aaf17c83973c','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_DISTRIBUTED_TWO','To calculate the "Nets distributed" column, the system first looks at the quantity of nets distributed from each warehouse during the selected date range. It then adds up these quantities across all warehouses under the boundary. Finally, the total quantity of nets distributed is displayed in the "Nets distributed" column of the summary report for the selected boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57d26053-fa87-4110-affc-f2d1107fe5d1','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_IN_STOCK','Nets In Stock','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b2098535-08b8-49ec-afce-e294a1de0473','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_IN_STOCK_ONE','The "Nets in Stock" column in the summary report represents the total number of available bed nets in each boundary, according to the last updated data. This figure is calculated by summing up the number of nets across all warehouses under the boundary. The "Stock on Hand" column in the stock reconciliation page. The figure is then summed up across all warehouses under the boundary to obtain the total number of bed nets available in the boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e9fa8b48-4c82-4354-9ff0-8a523d2ad637','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_IN_STOCK_TWO','The resulting figure is then entered into the "Nets in Stock" column in the summary report, which is further divided into warehouse details, micro plan targets for nets, and warehouse boundary details, depending on the project setup.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9201af6c-d760-4928-bcd0-f522c66a480b','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RECEIVED','Nets Received','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d7e0f288-74c1-4d75-9ab7-da46806e4ce3','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RECEIVED_ONE','In the summary report, "Nets received" refers to the total number of bed nets that were actually received for the selected date range in all the warehouses under the specific boundary. This metric is calculated by summing up the quantity received from each warehouse within the boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('63c7f0d8-5021-4ab4-b221-8181881d5eed','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RECEIVED_TWO','The data for this metric is collected from the "Inventory Management" module, specifically from the "Record Stock received form" where the quantity received for each shipment is recorded. The warehouse name/ID and the boundary details are also recorded during project setup.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9e8d0caa-aa1a-4e60-9264-9f8242aedd3a','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RETURNED','Nets Returned','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5cfa8f22-58cd-4f6b-9770-9caaa32fb3bf','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RETURNED_ONE','The "Nets returned" column in the summary report represents the total number of nets returned for the selected date range. This includes all the nets returned across all the warehouses within the selected boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06c26472-f539-4921-b592-a5cf721676f3','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RETURNED_THREE','The sum of the quantity of nets returned across all the warehouses within the selected boundary is calculated using this formula to give the final value for the "Nets returned" column in the summary report.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('88ec9418-b0b9-4116-9819-1e70f86bca3f','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_RETURNED_TWO','The calculation for this column involves collecting the quantity of nets returned for the date range selection from each warehouse under the selected boundary, and then summing them up to get the total number of nets returned. This is done using the "Quantity returned" field in the Inventory Management module''s "Record Stock returned" form.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5fc1de2f-4bfe-4020-8455-390110e835d3','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_TO_RECEIVE_AS_PER_MICROPLAN','Nets to receive as per microplan','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4a468571-2afb-46e0-a9b0-cc56276e3b52','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_TO_RECEIVE_AS_PER_MICROPLAN_FOUR','This point is important as it helps in determining whether the actual number of bed nets received is meeting the planned targets or not. It can also help in identifying any discrepancies or gaps in the warehouse management system.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0098ca68-b0ff-4735-a327-56da6c53b572','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_TO_RECEIVE_AS_PER_MICROPLAN_ONE','The "Nets to receive as per micro plan" point in the summary report refers to the number of bed nets that were planned to be received as per the micro plan for a specific boundary such as a district or administrative post. This value is calculated based on the micro plan targets for the bed nets that were set up during the project setup phase.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('25b0785c-8800-4072-addb-0fc39d1ee1d2','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_TO_RECEIVE_AS_PER_MICROPLAN_THREE','This point is important as it helps in determining whether the actual number of bed nets received is meeting the planned targets or not. It can also help in identifying any discrepancies or gaps in the supply chain and logistics management system.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fcfcbccd-557d-4a9f-8cd8-ad5427fba267','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_NETS_TO_RECEIVE_AS_PER_MICROPLAN_TWO','The calculation takes into account the number of bed nets received across all warehouses under the boundary for a specific date range. It is calculated by summing up the quantity received for each warehouse and multiplying it with the total number of warehouses for that boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca3ded74-a200-4e96-ae67-71bec4d9fbbd','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_ONE','A summary report is a consolidated report that provides an overview of the inventory stock at the boundary level. The report includes all the warehouses within the boundary, and it is generated by aggregating data from individual warehouse reports.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2a2ccbb9-51d4-4a09-9d66-9b85e3545b81','en_MZ','DSS_CALCULATION_INVENTORY_SUMMARY_REPORT_TWO','The summary report can be accessed by users at different levels. For national and provincial-level users, the report shows the stock details for each district, while for district-level users, the report shows the stock details for each administrative post (AP) within the district.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('425c6167-a62e-4e68-8c7a-64782ae6d0da','en_MZ','DSS_CALCULATION_INVENTORY_TAB_OVERVIEW_ONE','The "Inventory" section is a part of the dashboard that provides data analytics related to inventory and warehouse management. This section is designed to give users an update on the stock levels and consumption trends. The data for this section is sourced from the warehouse manager application, which allows users to see data on inventory levels, stock movements, and consumption patterns.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f5c88e69-963f-492a-979a-3135ed3e1f34','en_MZ','DSS_CALCULATION_INVENTORY_TAB_OVERVIEW_TWO',' By utilizing the information in the "Inventory" section, dashboard users can make informed decisions on inventory management, including reordering and restocking, to ensure that their warehouses are efficiently managed and inventory levels are maintained at optimal levels. Overall, the "Inventory" section provides valuable insights into warehouse management and inventory control.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9d2c2300-43e3-4e48-83e2-fcd3a5abac72','en_MZ','DSS_CALCULATION_INVENTORY_WAREHOUSE_DISTRIBUTION','Warehouse Distribution','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2f47ef99-eb87-44a1-9a16-c86db2f94087','en_MZ','DSS_CALCULATION_INVENTORY_WAREHOUSE_DISTRIBUTION_FOUR','The status of the warehouse is also indicated, with the ''Sufficient'' label indicating that the stock levels are expected to last until the end of the campaign, and the ''Insufficient'' label indicating that the stock levels are expected to run out before the end of the campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('17e180a3-fef5-4f77-b2b2-1d762545f06a','en_MZ','DSS_CALCULATION_INVENTORY_WAREHOUSE_DISTRIBUTION_ONE','This shows a geo map that is a visual representation of the locations of all the warehouses within the boundary, marked with their corresponding latitude and longitude coordinates. This map is integrated with the inventory management system and allows the user to click on any warehouse and view its details such as the warehouse ID, stock received, stock distributed, stock returned, stock in hand, and how long the stock will last based on the current consumption rate.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eec5d50e-973a-47d8-a5ab-338e8ba892ea','en_MZ','DSS_CALCULATION_INVENTORY_WAREHOUSE_DISTRIBUTION_THREE','Clicking on a warehouse on the map will open up and display the detailed information about that particular warehouse. This information includes the warehouse ID, the stock received, stock distributed, stock returned, stock in hand, and how long the stock is expected to last based on the current consumption rate. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('45dde3e0-152d-4a75-a3e5-4fee025e3027','en_MZ','DSS_CALCULATION_INVENTORY_WAREHOUSE_DISTRIBUTION_TWO','The inventory data for each warehouse is captured in the backend of the mobile application and is displayed on the map as its detail. The map can be zoomed in and out to provide a better view of the location of the warehouses.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('70964f49-c90e-4d59-b46f-ea3724455da1','en_MZ','DSS_CALCULATION_NATIONAL_BEDNETS_DISTRIBUTED','Bed Nets Distributed','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e8da72f1-bd68-4cce-b16b-fcaa24e739a7','en_MZ','DSS_CALCULATION_NATIONAL_BEDNETS_DISTRIBUTED_TODAY','Bed Nets Distributed Today','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6a95d430-4428-4ac3-b870-2d1867794120','en_MZ','DSS_CALCULATION_NATIONAL_BEDNETS_DISTRIBUTED_TODAY_ONE','The KPI "Bed nets Distributed Today" represents the total number of bed nets distributed today across all provinces. This metric is calculated by adding up the number of bed nets distributed for each household across all provinces for the date range of today. The data source for this KPI is the Delivery Intervention Screen, which provides the number of bed nets distributed for each household.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2bf23c10-d9f0-4b75-9b15-b1abf432fc9e','en_MZ','DSS_CALCULATION_NATIONAL_BEDNETS_DISTRIBUTED_TODAY_TWO','This Insight is also available where the percentage change in bed nets distributed from the previous day to the current day is measured, which provides additional insights into the performance of the distribution campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5f7676bd-4467-47ce-bd3b-5d4af611f0d9','en_MZ','DSS_CALCULATION_NATIONAL_COVERAGE_BY_PROVINCE','Coverage By Province','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('29ef4f50-7645-4ce5-aee9-b1d74134e02d','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS','Households','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('df6798a5-4b0e-4ffe-b99c-c4866717ce3b','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS_VISITED_TODAY','Households Visited Today','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('28479f47-6c22-41bb-b7ef-02c0688143d2','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS_VISITED_TODAY_FIVE','This formula is used to calculate the percentage change in the number of households visited between "today" and the "previous day". The result of this calculation provides insight into the trend of households visited over time.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7345c5ff-2d72-478c-897a-c78b2aa8e67e','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS_VISITED_TODAY_FOUR','((Today - Previous day) / Previous day) * 100','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1df2e25d-b419-4fcb-968a-d48025247da3','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS_VISITED_TODAY_ONE','The calculation for "Households Visited Today" KPI is as follows:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a950fe63-b88e-4e10-9135-707007e13070','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS_VISITED_TODAY_THREE','The formula for calculating the percentage change between "Today" and "Previous day" is:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6e3b3919-a07a-4cfa-835e-2867004ca30b','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLDS_VISITED_TODAY_TWO','First, the total number of households visited for current day i.e today is calculated for each province. Then, the aggregate of all households visited across all provinces for "today" is calculated.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c53fe9e5-e9e5-4340-b3a3-c71f8dbe3846','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLD_COVERAGE','Household Coverage (%)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0be30935-8205-4c38-b472-4225e0082513','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLD_COVERAGE_FOUR','Additionally, hovering over the province or district the metric can also provide an insight into the change in coverage from the previous day, expressed as a percentage.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d15bc513-e8ef-4b4e-973f-caa37841f856','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLD_COVERAGE_ONE','The Household Coverage (%) metric shows the percentage of households visited compared to the micro plan targets for each province and district. The micro plan targets are set up at the project setup phase.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('396ca92b-f8aa-450f-b4bb-438747194c98','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLD_COVERAGE_THREE','For the zoom-in/drill-down view, the calculation is the same, but using district targets instead of province targets.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d3856433-415c-463e-8e26-236693737ae1','en_MZ','DSS_CALCULATION_NATIONAL_HOUSEHOLD_COVERAGE_TWO','The calculation for the default view at the national level is, the total number of households visited until today divided by the household micro plan target for each province, multiplied by 100.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('769e137a-acfe-4360-b668-9a58f6600486','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERAGE','Population Coverage (%)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a7d7859a-2a1a-4fd7-8948-6d17ee89e006','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERAGE_FIVE','Additionally hovering over the province or district the metric also includes an applicable insight, which is to measure the percentage change in population coverage from the previous day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('529b7ef4-94ce-4537-b5ad-400634da6210','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERAGE_FOUR','For the zoom-in/drill-down view, the formula is the same, but for each district within the selected province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6449d59d-3555-48a4-bb32-2934bafab126','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERAGE_ONE','The population coverage (%) achieved against micro plan targets shows a heat map of the coverage percentage across different provinces. The micro plan targets are set up during the project setup, and the population data is obtained from the delivery intervention screen, the calculation takes into account the campaign start date from the campaign setup date and boundary data from MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('88641e1e-de29-4cfb-93d1-e65f97823018','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERAGE_THREE','For the “default view” at the national level, the formula is the sum of the population covered (bed nets distributed) for each province divided by the population micro plan target for that province, all multiplied by 100.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa6b0c4c-01e3-453e-b501-3bed230eef3c','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERAGE_TWO','Note: It is assumed that, the total number of bednets that have been delivered to the household, is the total number of population covered.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a8493585-f02e-45bb-a702-00385735a523','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERED','Population Covered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2dde5750-da07-4e18-ba00-23d4a2bcc914','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERED_TODAY','Population Covered Today','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('346991aa-7df0-4a12-81a3-1bf57d243caf','en_MZ','DSS_CALCULATION_NATIONAL_POPULATION_COVERED_TODAY_ONE','The "Population Covered Today" metric shows the total number of people covered by the campaign in all provinces for the current day. The population data used for the calculation is sourced from the “Registration and Delivery” FLWs application, and the bednets quantity distributed is taken into consideration.In addition to this, the "Additional Insights" show the percentage change in population coverage from the previous day to the current day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e126f36d-f6ae-43b3-927b-f6e54481d7db','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_BEDNETS_DISTRIBUTED','Total Bed Nets Distributed (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0a550d15-4ef0-4fba-9e3b-9bcb4b6fe47b','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_BEDNETS_DISTRIBUTED_ONE','The Total Bed Nets distributed (Cumulative) is the total number of bednets distributed since the start of the campaign across all provinces. It shows the sum of bednets distributed for each province since the beginning of the campaign. Bed Nets distributed data can be obtained from the Delivery Intervention Screen as "a".','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('79eea9dd-3447-4b53-90e4-3df840033b54','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_BEDNETS_DISTRIBUTED_THREE','It can be written as Σx [ Σi(a)i ], for date range (Campaign start date - TODAY).','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('082de6d2-e67d-49a5-a905-f26012974266','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_BEDNETS_DISTRIBUTED_TWO','The Campaign Start Date is recorded as the Project Setup date. The calculation can be expressed as the sum of bednets distributed for each household (i) in each province (x) for the date range from the Campaign Start Date to Today.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('90a1e75d-7eda-41a4-a21b-541fa69a7847','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_HOUSEHOLDS_VISITED','Total Households Visited (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20cda8c4-ee79-4686-bab2-a8a5c3b01c40','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_HOUSEHOLDS_VISITED_ONE','The "Total Households Visited (Cumulative)" metric represents the total number of households that have been visited since the start of the campaign across all provinces.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('866631c9-5858-47df-bec4-b18efef1205d','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_HOUSEHOLDS_VISITED_THREE','The calculation for this metric involves summing up the total number of households visited for each province from the campaign start date up to the current date.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b349049f-50c0-4b9a-88b4-96cfcdb40f65','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_HOUSEHOLDS_VISITED_TWO','This metric takes into account all households visited in each province since the campaign start date, which is set up during campaign setup.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7df3de5c-793d-4c58-aae7-0e40bd3e16f7','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_POPULATION_COVERED','Total Population Covered (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1a5a513d-41b5-4139-990f-d48c4ce79af8','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_POPULATION_COVERED_ONE','The Total Population Covered (Cumulative) is the sum of population covered for all provinces, since the start of the campaign. The data for population and quantity distributed is taken from the Delivery Intervention update Screen. The Campaign Start Date is the date when the campaign project was set up.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('171e4a32-e8c6-4d25-bab9-8906d0713350','en_MZ','DSS_CALCULATION_NATIONAL_TOTAL_POPULATION_COVERED_TWO','The calculation formula is the sum of households visited in each province multiplied by the average population per household, for the date range from the Campaign Start Date to Today. The result is the total population covered for all provinces since the start of the campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4bad6013-69f9-4444-af29-c9a7c96f7061','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE','Bed nets coverage (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa3dcabe-dd68-40f0-a60d-db4923355556','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE_FIVE','The insights available for this metric can be the percentage change in coverage from the previous day, which can help in monitoring the progress and identifying any issues that need to be addressed.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('76ab27c1-dfde-4a21-809c-b727ff7489e2','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE_FOUR','The bednets coverage can be calculated cumulatively from the start of the campaign till the current date. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aceea286-a836-4ef5-8297-2946951f6f69','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE_ONE','Bednets coverage represents the percentage of bednets distributed against the targeted distribution as per the microplan. This metric helps to evaluate the efficiency and effectiveness of the bednet distribution campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5cb1926e-53ef-4b77-bb6d-430cbe68101a','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE_THREE','The data for bed nets distributed and microplan targets are sourced from the Delivery Intervention screen in the application and the campaign project setup, respectively. The boundary data is obtained from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f665ee1b-0dc4-47a0-9682-075222b40e95','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE_TWO','The bednets coverage can be calculated at different levels, i.e., national, provincial, and district level, depending on the role of the user.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc5c2bde-c979-4b90-adfd-e53096c752a5','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_DISTRIBUTED','Bed Nets Distributed','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('53540ad4-54c0-4ee0-b6f7-784e9d455898','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_DISTRIBUTED_DATE_RANGE','Bed Nets Distributed (For selected date range)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a24a90ee-cb1d-4100-963d-a50914f3571b','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_DISTRIBUTED_DATE_RANGE_ONE','This metric shows the total number of bednets distributed within a selected boundary as per the user role, for a specific date range. The data for this metric is collected from the "Delivery Intervention'''' screen in the application and the field name “quantity distributed” is recorded in the application. The boundary data used to determine the bed nets distributed is taken from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4b44925c-31be-428c-8f64-80b94940c0c2','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_DISTRIBUTED_DATE_RANGE_TWO','The calculation is performed by summing the quantity of bednets distributed for all households within the selected boundary and date range. The result is the total number of bednets distributed for the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4ee70b2d-60b2-4ace-b8c2-cbaf31349fb8','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED','Bed Nets Not Delivered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dfa0bcc0-c606-4493-9047-70b35ff154d6','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED_FIVE','The pie chart helps to visualize percent of the failed delivery for each of the reasons.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9945122f-9045-46d8-9db8-eb8ed831ef66','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED_FOUR','For the national and provincial level roles, the total number of households where bed net delivery has not taken place for each “delivery comment” reason is calculated based on the selected date range and province. For the district level role, it is calculated based on the selected date range and district, for each “reason”.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('16e2a4d5-6ba9-4d54-b1b9-c0c55c119b6a','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED_ONE','The metric shows data in the pie chart, where the total number of households where bed net delivery has not taken place during the selected date range. The total number of households is obtained from the application, where the intervention delivery has been attempted, but the bed nets have not been delivered for some reason.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3755ad92-03fb-4e84-9b54-1d44136870e8','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED_THREE','The pie chart section of the metric shows the “split” by reason for the households where bed net delivery has not taken place. The reasons for failed delivery are obtained from the "Delivery Comments" field in the Deliver Intervention Screen.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('228ed837-44af-484f-9696-395624e536c9','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED_TWO','For the national and provincial level roles, the “total” number of households where bed net delivery has not taken place is calculated based on the selected date range and province. For the district level role, it is calculated based on the selected date range and district. This data is displayed in the center of the pie chart.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ee5db20d-6ea1-4a8a-88ca-af0972390639','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_TARGETED_DATE_RANGE','Bed Nets Targeted (For selected date range)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57d79544-bad9-4bf8-9711-d2bef84c2ac6','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_TARGETED_DATE_RANGE_ONE','This metric refers to the number of bednets that have been targeted for distribution as per the microplan for the selected date range. The target number of bednets will be different depending on the level of the role: national level, provincial level, or district level of user.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0b003671-6bbb-443e-9256-5abfb39dc460','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_TARGETED_DATE_RANGE_THREE','The microplan targets and boundary data are determined during the project setup and stored in the MDMS (Master Data Management System). This metric is used to track the progress of bednets distribution during the campaign, and to ensure that the target number of bednets is distributed within the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3c7358a4-c91f-424f-847e-61e677101c91','en_MZ','DSS_CALCULATION_OVERVIEW_BEDNETS_TARGETED_DATE_RANGE_TWO','For the national and provincial level roles, the bednets micro plan target for the province per day is multiplied by the number of days in the selected date range to determine the bednets targeted for distribution. For the district level role, the bednets micro plan target for the district per day is multiplied by the number of days in the selected date range to determine the bednets targeted for distribution.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4b884f3-9e33-4acb-ba34-f950a8cfe483','en_MZ','DSS_CALCULATION_OVERVIEW_COMPLAINTS','Complaints','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bf7ba568-c1bd-474a-b900-dc7666943253','en_MZ','DSS_CALCULATION_OVERVIEW_COMPLAINTS_FIVE','Overall, this visualization provides a quick and easy way to understand the number of complaints received and their current status, allowing for better monitoring and management of complaints for the boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('991b9fd4-9cf4-400a-b89f-fee665ce1f21','en_MZ','DSS_CALCULATION_OVERVIEW_COMPLAINTS_FOUR','It is important to note that complaints where the status is ''Created'' should not be included in the visualization to avoid duplication. Additionally, the sum of complaints with ''Open'', ''Resolved'', and ''Rejected'' statuses should equal the total number of complaints created during the selected date range mentioned in the center of the pie chart.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f48ce44-ab98-4a8e-b641-7b9e694634e1','en_MZ','DSS_CALCULATION_OVERVIEW_COMPLAINTS_ONE','This metric shows the pie chart visualization which provides information on the number of complaints received, categorized by their current status, for the selected date range and boundary. The total number of complaints created during the selected date range will be displayed in the center of the pie chart, with three slices representing the different status categories - Open, Resolved, and Rejected.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('41bad8b5-3a51-4156-8c1b-3707c2e6704d','en_MZ','DSS_CALCULATION_OVERVIEW_COMPLAINTS_THREE','Each slice of the pie chart represents the percent of complaints for a particular status (Open, Resolved, or Rejected) for the selected province / district and date range. The boundary data will be as per the user role, which is national and provincial for the selected province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('163690d7-c92a-490a-af1d-276df8b2572b','en_MZ','DSS_CALCULATION_OVERVIEW_COMPLAINTS_TWO','The complaints data will be sourced from the Complaints module in the mobile app, and the boundary data will be obtained from the MDMS. The pie chart center will display the total number of complaints created for the selected province or district (as per the user role ) and the date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('676c398d-ac5d-4e01-a317-13ff5c85daa1','en_MZ','DSS_CALCULATION_OVERVIEW_DATA_SYNC','Data Sync','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f888d84e-d476-4c03-b780-ddbec2934342','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_COVERAGE_CUMULATIVE','Households coverage (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ec19320e-443a-45c2-be72-9ab51a03f6ea','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_COVERAGE_CUMULATIVE_FOUR','Additionally, the insight of comparing today''s household coverage with the previous day''s household coverage, which shows the percent change in the data for today.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('39adfb1a-f56d-4411-b449-378f4e293f2f','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_COVERAGE_CUMULATIVE_ONE','The households coverage refers to the percentage of households visited against the micro plan target. This is calculated differently depending on the user role. For the national and provincial level roles, it is the percentage of households visited against the micro plan target for the selected province since the start of the campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('636d9c9a-b41d-47a5-8023-9c17e6a86b65','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_COVERAGE_CUMULATIVE_THREE','The micro plan targets are set up in the project setup, while the data on households visited is added by the field workers in the application. The boundary data is obtained from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a589ac53-a81e-4076-bcd2-d1090ffca65b','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_COVERAGE_CUMULATIVE_TWO','For the district level role, it is the percentage of households visited against the micro plan target for the corresponding district since the start of the campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ddb10b43-2f31-4679-be6e-1edfc58706db','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_TARGETED_DATE_RANGE','Households Targeted (For selected date range)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a7ce1b11-2b7d-4841-a69f-fb2e61f39871','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_TARGETED_DATE_RANGE_ONE','The calculation for the number of households targeted for the selected date range depends on the user role. For the national and provincial user roles, the calculation is based on the household micro plan target for the province per day multiplied by the number of days in the selected date range. For the district user role, the calculation is based on the household micro plan target for the district per day multiplied by the number of days in the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f6239a90-b386-4ce6-a8ac-32711cb20904','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_TARGETED_DATE_RANGE_TWO','The household micro plan target is defined in the project setup, and the date range is selected by the user in the filter. The boundary data is obtained from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3e227323-5944-4710-81c5-34173ccf520e','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_VISITED','Households','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d1aaac19-f123-49a8-b48a-fead74cd972a','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_VISITED_DATE_RANGE','Households Visited (For the selected date range)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('18a7c3e0-a5be-4554-a5c8-6ae6b0971a43','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_VISITED_DATE_RANGE_ONE','This metric measures the total number of households visited since the start of the campaign. It is calculated by aggregating all the households visited for the selected province or district since the start of the campaign, depending on the user’s role level. The input fields for this metric include the households visited data which is collected by the Field worker application, the campaign start date from the Campaign project setup, and boundary data from MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('da9af09a-ba38-4dcc-9ef5-737b35f5a33d','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_VISITED_DATE_RANGE_THREE','At the District role level, the calculation is the sum of households visited for each administrative province within the boundary for the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4debb551-9783-4da7-abc4-b56394b43f38','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_VISITED_DATE_RANGE_TWO','At the National and Provincial role level, the calculation is the sum of households visited for each district within the boundary for the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b8b60cd7-349b-4f01-a84c-b979001e3ba4','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING','Household Coverage Ranking','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e5ca65b-8008-46ee-ad44-e7ea388e714f','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING_FIVE','Overall, the Household Coverage Ranking will provide useful information for program managers to monitor which area (district / APs) have covered nearly all the household and where there is most pending, for the intervention coverage so that areas improvement / focus in the process can be planned.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce4df49c-008f-4fbe-95f6-d7c3ddfa6045','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING_FOUR','The data required for the calculation will be obtained from the project setup and the application. The household coverage will be calculated based on the households visited which will be taken from the data submitted by the application. The household microplan target will be taken from the project setup.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc104b3a-1131-4977-b2e1-885b2dcedbe2','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING_ONE','The Household Coverage Ranking is in percentage and provides a visual representation of the performance of different districts or administrative posts in terms of achieving household coverage targets. The chart will be displayed as a bar chart in descending order from left to right.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce5a02b2-a111-4aec-afd6-1751623bebc7','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING_THREE','For the national level role, the ranking will be provided for all the districts within the selected province. For the provincial level role, the ranking will be provided for all the districts within the respective province. For the district level role, the ranking will be provided for all the administrative posts within the respective district.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc0f097e-5eb0-4f43-ba99-6fa6639694e4','en_MZ','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING_TWO','The calculation will be based on the ratio of the total households visited till today to the household microplan target for each district or administrative post. The result will be expressed as a percentage.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('80f421e1-63df-4584-8a9e-6c9cb6b25922','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY','Number Of Days To Last Inventory','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('40d0bf60-e22f-4d1e-bb06-3ee0ec97c5fd','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY_FIVE','It is important to note that when calculating the total number of bed nets needed per day, the micro plan target should be based on the daily bed nets target for the province for national and provincial level users, and the district for district level users. Additionally, the sum total of "stock in hand" across all warehouses should be considered when calculating the number of days the inventory can last.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a19e0c67-cb6e-4674-bbe5-7931a02235b8','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY_FOUR','The number of days the inventory can last is then obtained by dividing the total stock in hand by the total number of bed nets needed per day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dbce0fed-8d0e-451c-9c22-376896a1122f','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY_ONE','The "Number Of Days To Last Inventory" is a bar chart that measures and displays how long the current inventory of bed nets can last based on the current rate of consumption. The metric is calculated by dividing the total number of bed nets in stock for all the warehouses for the boundary by the average daily consumption rate.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('278bc0e6-fac8-47d3-ae89-201c8ecba908','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY_SIX','Overall, this metric provides an indication of the adequacy of bed net stocks and the need for replenishment to ensure that there are enough bed nets to meet the demand for campaign fulfillment.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2f3000a3-b769-481d-bed4-edb6f7ab2d1b','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY_THREE','The calculation for this metric involves obtaining the current "stock in hand" for each warehouse within the selected district, as obtained from the stock reconciliation page in the inventory management system. The daily bed nets microplan target is then obtained from the project setup data, and the total number of bed nets needed is calculated as the product of the daily target and the total number of warehouses in the district. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ffc53be4-57f4-44d2-90eb-1bb3fe9830fe','en_MZ','DSS_CALCULATION_OVERVIEW_NO_OF_DAYS_TO_LAST_INVENTORY_TWO','The bar chart will display the number of days the current inventory can last for each district within the selected province for national and provincial level users, and for each administrative post within the respective district for district level users.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('82f30b02-f204-4fba-b3f9-32b5a5cdbf2b','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE','Overall Checklists Completion Rate','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fb9363d2-f524-4efa-afaa-4e8b71df60a2','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE_FIVE','The completion rate is then calculated as a percentage by dividing the Mandated Checklist completion rate by the Actual Checklist completion rate and multiplying the result by 100.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6ea14034-8d72-4ba1-85ba-f86b0292f732','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE_FOUR','The ‘Actual National/Provincial/District Checklist completion rate’ is calculated by summing up the actual number of times each checklist was filled out by the respective supervisors within the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8b307f19-2854-42df-b5be-820ea7413594','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE_ONE','The Overall Checklists Completion Rate bar chart displays the percentage of supervisors who have completed all the assigned checklists within a selected date range. The chart is divided into three categories: National, Provincial, and District supervisors.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9332f8f2-892e-4696-af12-58df12222b9c','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE_SIX','The bar chart displays the completion rate of checklists for each boundary level (national, provincial, and district), based on the number of checklists assigned and the number of times they were actually completed by the supervisors.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c7366665-84b8-46bc-8ec9-3e240d7b50c3','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE_THREE','For National and Provincial Supervisors, the ‘Mandated National/Provincial Checklist completion rate’ is calculated by multiplying the total number of national/provincial supervisors by the sum of the frequency of each checklist for the respective supervisor level. The Mandated District Checklist completion rate is calculated by multiplying the total number of district supervisors by the sum of the frequency of each checklist for the district level.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a671da02-7fe2-4408-b317-1492ee1a23b5','en_MZ','DSS_CALCULATION_OVERVIEW_OVERALL_CHECKLISTS_COMPLETION_RATE_TWO','The calculation for the completion rate is based on the number of checklists that are mandated for each supervisor level and the actual number of times each checklist was filled out by supervisors within the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f50394fa-0003-4b14-b734-e35b4109d3cf','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERAGE_CUMULATIVE','Population coverage (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7eca2a7d-e731-469a-b3da-1a0b0776c114','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERAGE_CUMULATIVE_ONE','This metric measures the percentage of the population that has been covered with the intervention (in this case, the distribution of bed nets) against the microplan target. The microplan target refers to the number of individuals that were targeted to receive the intervention according to the project setup.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7d643686-e4ce-48ed-a79f-6b9a51b98aea','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERAGE_CUMULATIVE_THREE','Additionally, an insight is available to show the percentage change in population coverage from the previous day. This can provide an indication of how quickly the population coverage is increasing or decreasing compared to the previous day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('504959b9-b104-4b03-a02d-319e661cc4aa','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERAGE_CUMULATIVE_TWO','The calculation takes the sum of the population covered (based on the quantity of bed nets distributed) for the selected province, district, or corresponding district (depending on the user role) since the start of the campaign, and then divides it by the population microplan target for that area. This quotient is then multiplied by 100 to get a percentage.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2dba0002-ba20-4b86-bcc3-9d68ca9d12de','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERED','Population Covered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a1cda59f-65e4-41bc-99e2-a8463023c832','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERED_DATE_RANGE','Population covered (For selected date range)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('47c6f451-0564-4b11-a4ab-e0ef8593dfc3','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERED_DATE_RANGE_FOUR','In other words, we are calculating the total population covered for the selected date range by summing up the population covered for each household within the selected boundary. The boundary data is obtained from MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('84b90f5a-4f5e-48f1-9cda-8e94ec865a80','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERED_DATE_RANGE_ONE','In the "Population Covered" metric, firstly, we need to know the population data of the household, which can be found in the "Delivery Intervention" screen and let us denote it as "b".','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('24a2f5ff-eb03-40ff-a967-fd2c9f1c7015','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERED_DATE_RANGE_THREE','For the selected date range, we need to sum up the "a" values for all households within the selected boundary (districts for national and provincial level roles, and Administrative Post for district level roles).','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c7e2fcb0-1026-4cea-ad14-1cdbbd939b9f','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_COVERED_DATE_RANGE_TWO','Then, we calculate the “population covered” for each household by multiplying "b" by 1.8, which is denoted as "a".','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5d54ecb2-59bb-4a22-abd0-3200a8f3e9bb','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_TARGETED_DATE_RANGE','Population Targeted (For selected date range)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('55c2e3b0-e4fe-447f-87e5-64952742b885','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_TARGETED_DATE_RANGE_FOUR','In summary, the "Population Targeted" metric gives an indication of the expected coverage or reach of the campaign, and can help to assess the campaign towards achieving its goals.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3c9b71b7-99c0-4c9f-86b8-9b2f3c89df64','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_TARGETED_DATE_RANGE_ONE','The "Population Targeted" metric refers to the total number of people that are expected to be reached or covered by the campaign during the selected date range. This metric is based on the microplan targets that were set up during the project setup phase.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6de1a02a-d85c-4d3c-8c27-7a3746db224f','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_TARGETED_DATE_RANGE_THREE','To calculate the population target for the date range, the microplan targets for the province or district are multiplied by the number of days in the selected date range. This gives an estimate of the total number of people that are expected to be reached or covered during the campaign. The boundary data used for this calculation is obtained from MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fb16216d-1ee8-4a68-b3ab-3da33f5bec8c','en_MZ','DSS_CALCULATION_OVERVIEW_POPULATION_TARGETED_DATE_RANGE_TWO','The population target varies based on the user role. For the national level role and provincial level role, the population target is for the selected “province”, while for the district level role, it is for the “Administrative Posts”.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0d66eb14-32bf-48ee-a47d-aea3be97b429','en_MZ','DSS_CALCULATION_OVERVIEW_SYNC_RATE','Sync Rate','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b8ac268a-1e53-4a98-a0d0-093880ff7d97','en_MZ','DSS_CALCULATION_OVERVIEW_SYNC_RATE_ONE','This indicates the percentage of field workers who have synced their device at least once for the current day, i.e. from 12:00AM to 11:59PM.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('354ea4ae-a196-4d1b-8e4d-893d535021ee','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_BEDNETS_DISTRIBUTED_CUMULATIVE','Total Bed Nets Distributed (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ffdcf36b-9594-40c0-985e-af1adf487a88','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_BEDNETS_DISTRIBUTED_CUMULATIVE_FIVE','Overall, this metric provides an indication of the progress of the campaign in distributing bed nets to the targeted population.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7defd2b5-4375-47a7-b034-c52f23cb2549','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_BEDNETS_DISTRIBUTED_CUMULATIVE_FOUR','The insight is available for this metric which provides a percent change in the number of bed nets distributed between the current day and the previous day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('421ac221-5035-4744-9681-0ac4607d6b48','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_BEDNETS_DISTRIBUTED_CUMULATIVE_ONE','This metric represents the total number of bed nets distributed since the start of the campaign, for the selected province, corresponding province, or corresponding district.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('189344f2-abb3-40e8-92e3-9bbadcb76e6c','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_BEDNETS_DISTRIBUTED_CUMULATIVE_THREE','This formula is applied for the entire campaign duration, which is calculated as the time between the campaign start date and the current date.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e3a4dfa-7e24-4f9e-9fc5-d1326bdea1d7','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_BEDNETS_DISTRIBUTED_CUMULATIVE_TWO','To calculate this metric, the quantity of bed nets distributed to households is captured in the "Delivery Intervention" screen of the application and recorded in the "Quantity distributed" field. The start date of the campaign is determined during the project setup phase, and the boundary data is obtained from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d5af7cb5-9d71-47c8-a82d-73698ba9898e','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_HOUSEHOLDS_VISITED_CUMULATIVE','Total Households Visited (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4d71f230-99f4-4936-836d-6553f5b2bf1b','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_HOUSEHOLDS_VISITED_CUMULATIVE_ONE','This metric measures the total number of households visited since the start of the campaign. It is calculated by aggregating all the households visited for the selected province or district since the start of the campaign, depending on the user’s role level. The input fields for this metric include the households visited data which is collected by the Field worker application, the campaign start date from the Campaign project setup, and boundary data from MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cc5a0cd2-f780-4aaa-8e3c-fcd1a8c1b802','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_HOUSEHOLDS_VISITED_CUMULATIVE_TWO','This also provides additional insights into the percentage change in the number of households visited from the previous day to today.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9ef5de94-9230-47ff-be27-7602b0f5e7ce','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_POPULATION_COVERED_CUMULATIVE','Total Population Covered (Cumulative)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a43c2b48-aef9-4ee9-886a-518e71832fbf','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_POPULATION_COVERED_CUMULATIVE_FOUR','Overall, the Total Population Covered (Cumulative) metric provides an indication of how effective the intervention has been in reaching the target population and meeting the campaign goals.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce4e2d10-59c4-4866-bcb8-760451095b22','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_POPULATION_COVERED_CUMULATIVE_ONE','The Total Population Covered (Cumulative) is a metric that shows the total population covered since the start of the campaign, and it is used for monitoring the progress of the intervention in reaching the target population. This metric is applicable for all user roles: national, provincial, and district level, the data will be displayed as per the boundaries permission allotted.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6d095d69-c5a2-4fb3-ac1e-21ed54beda3d','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_POPULATION_COVERED_CUMULATIVE_THREE','Additionally, an insight is available for this metric, which is (Today - Previous day) / Previous Day * 100. This insight shows the percentage increase or decrease in the metric from the previous day to the current day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9b1ea31f-ff82-4ebc-97a5-196b3bbb627d','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_POPULATION_COVERED_CUMULATIVE_TWO','To calculate this metric, we use the Population Data for household Covered, which is obtained by multiplying the Quantity of bednets Distributed to the household by 1.8. The campaign start date is obtained from the Project Setup, and the Boundary data is obtained from the MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a219460e-d4a7-4067-89df-bfecf5aa777d','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_USERS_CREATED','Total Users Created','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4be7b65-5c43-4e57-803b-cdd90ed36888','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_USERS_CREATED_ONE','The "Total users created" KPI card refers to the total number of field workers who have been created in the user management module. This includes all field workers who have been assigned to the campaign in a particular province. The total number of staff created and assigned to the campaign is determined by the boundary, which can be at the province or district level. The Dashboard displays the user-created data, based on the user type of the dashboard.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2a4434be-1370-4651-a7ab-386920671c32','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_USERS_SYNCED_ATLEAST_ONCE','Total Users Synced At Least Once','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a84191e0-12f0-494f-9b9f-74450cdfcf76','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_USERS_SYNCED_ATLEAST_ONCE_ONE','This key performance indicator (KPI) measures the number of field workers who have synchronized their data at least once in a day using the "sync tag" button on their mobile application. The count includes unique syncs from different field workers, and multiple syncs from the same device will only be counted as one. The time frame for a day is from 12:00AM to 11:59PM.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d1d8e585-c91e-4595-8a25-7f7e8b239ef3','en_MZ','DSS_CALCULATION_OVERVIEW_TOTAL_USERS_SYNCED_ATLEAST_ONCE_TWO',' It''s important to note that if a field worker has synced their data once but after that it has unsynced data, it will not be reflected in this KPI.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fec90eb9-d3b9-4b32-972d-f695ec6d2f24','en_MZ','DSS_CALCULATION_REEGISTRATION_AND_DELIVERY_TAB_OVERVIEW_ONE','The "Registration and Delivery" section in the dashboard provides information about the field workers who are involved in two different activities: household registration and intervention delivery.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('696a2fc6-b3ae-4fda-b48b-b6fb62e3f7f4','en_MZ','DSS_CALCULATION_REEGISTRATION_AND_DELIVERY_TAB_OVERVIEW_TWO','The data displayed to the user is totally as per the user role who is viewing:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c807abd-8aac-4629-84fb-cac545e14fdf','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_DISTRIBUTED','Bed Nets Distributed','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f00fd007-06af-4781-99f3-134d804d5b7a','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_DISTRIBUTED_FOUR','Overall, this metric provides insight into the effectiveness of bed net distribution efforts within a given area and time period.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7233a322-5694-4eed-9728-0046b3a844a1','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_DISTRIBUTED_ONE','The Bed nets Distributed KPI shows a bar chart with the total number of bed nets distributed within a selected date range and boundary. The data is collected from the Delivery Intervention Screen in the mobile application, specifically the Quantity distributed field.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f496069a-9e7f-4b21-bb71-3ea776fcfcd5','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_DISTRIBUTED_THREE','For the “%” toggle, the metric is calculated as the percentage of bed nets distributed compared to the daily Bed nets Micro plan target for each district or administrative province, multiplied by the number of days in the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a661fed8-8c43-4df0-80a6-ce8918abe28c','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_DISTRIBUTED_TWO','For the “Number” toggle, the metric is calculated as the sum of bed nets distributed for each household within the selected date range and boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1ad799d7-c2f5-4e03-b8eb-c67825823192','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_NOT_DELIVERED','Bed Nets Not Delivered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f175e2ec-3ef3-4b8f-b68f-956a964adecf','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_NOT_DELIVERED_ONE','The KPI for "Bed Nets Not Delivered" is a measure of the number of households where bed net delivery did not take place within a selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2c49ba09-49a9-48ac-8bbd-62fcef368ed4','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_NOT_DELIVERED_THREE','The data displayed in the bar chart in the number count for this metric, which displays the total number of households with no bed net delivery for the selected date range, broken down by district or administrative post region, depending on the user''s role.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9cd912c1-5088-4426-9a98-008db6468104','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_BEDNETS_NOT_DELIVERED_TWO','To calculate this metric, the data is taken from the application, specifically the count of resources delivered for each household. The total number of households with no bed net delivery is then aggregated and displayed as a bar chart.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5b893b49-b5f3-41ac-9e7a-3030b5e2639b','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED','Households Visited','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3d645355-2c31-4e1b-8a53-a228f130044f','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_FIVE','For example, for national and provincial roles, the chart will show the percentage of households visited in each district compared to the daily households microplan target. For district roles, the chart will show the percentage of households visited in each administrative province compared to the daily households microplan target.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f8a5127b-1b1e-4a0e-8c77-c5b68ec8450c','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_FOUR','In the "%", toggle the chart shows the percentage of households visited for the selected date range in each district or administrative province, compared to the daily households microplan target and the number of days in the date range selection. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3da1319a-6122-4889-aa54-7bcd833aea53','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_MAP','Households Visited','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1710991b-8150-41c5-ba48-f9c98931f18f','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_MAP_ONE','The "Households visited" section in the dashboard provides a map with latitude/longitude coordinates of the households that have been visited within the selected boundary. The map can be zoomed in or out for better clarity of the households.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1c8cab17-8c56-4245-a694-5795c2abf576','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_MAP_THREE','For district supervisors, hovering over any boundary on the map shows a tooltip showing the name of the boundary and the total number of households covered within that boundary. Clicking on "+" or "-" will zoom in or out of the map, respectively.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1f199462-c464-4168-9e73-9295a7c5fe79','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_MAP_TWO','For national and provincial users, hovering over any boundary on the map will display a tooltip showing the name of the boundary and the total number of households covered within that boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2b45bc73-e34b-4aed-b316-1fd134944ee8','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_ONE','The "Households Visited" KPI in the “Registration and Delivery” dashboard section shows the total number of households visited during the selected date range. The data is sourced from the application.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('046adb59-1e7b-4fb8-8cd9-6c8d4808a967','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_THREE','In the "Number" toggle, the chart shows the total number of households visited for the selected date range in each district or administrative province. I.e. For national and provincial roles, the chart will show the total number of households visited in each district. For district roles, the chart will show the total number of households visited in each administrative province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a2109624-6119-448a-b1cb-4be1aced59d1','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_HOUSEHOLDS_VISITED_TWO','This section includes a bar chart that displays the aggregate of all households visited within the selected boundary. The chart can be toggled between two options: "Number" and "%".','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('07556f4d-f562-4940-99e6-19f3b25a3143','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS','Planned vs Actual Campaign Progress','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ce265f7-2012-40cb-bb3d-20f3af3ca0ec','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_BEDNETS','Planned vs Actual Campaign Progress (Bed nets)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1350ee82-4fc2-434b-9ce8-6ad88054ae12','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_BEDNETS_ONE','The Planned vs Actual Campaign Progression (Bednets) chart displays the comparison of bed nets distributed, showing the planned and actual distribution over time. The chart also extrapolates the graph to show when the bed nets distribution will meet the target. The data for bed nets distributed is taken from the Delivery Intervention Screen''s ''Quantity distributed'' field, and the target bed nets from the Micro plan.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0ed188e6-3073-4215-b362-57c50a26f470','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_BEDNETS_TWO','For the planned line, the cumulative ''Quantity distributed'' for the assigned boundary is used, and for the actual line, the ''Quantity distributed'' for the date range is used. To calculate the X-intercept, the bed nets targeted to distribute per day for assigned boundary or district is multiplied by the number of days in the date range (Campaign start date - TODAY). Finally, the interval for the x-axis is kept for every 1 day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('57420bea-960f-4877-ac2f-6a7b15309226','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_HOUSEHOLD','Planned vs Actual Campaign Progress (Household)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('90ea5e7d-bd0a-4d84-aecb-cd70b99ce6a0','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_HOUSEHOLD_FIVE','The interval for the X-axis is kept for every 1 day, meaning that each point on the chart represents the progress made in one day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0231bfd8-ab38-4ddd-b453-235a81806812','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_HOUSEHOLD_FOUR','To calculate the X-intercept of the “planned” line, the number of households targeted to visit per day for the assigned boundary is multiplied by the number of days in the date range (Campaign start date - TODAY). For the X-intercept of the “actual” line, the current date is added to the difference between the target number of households and the total number of households visited to date, divided by the number of households targeted per day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e06f7919-2f89-46f4-9215-3df5ea6ed6e0','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_HOUSEHOLD_ONE','This chart is used to track the planned versus actual progress of a campaign to deliver household visits, and to project when the campaign will reach its target. The chart is a line chart with two lines: one for the planned progress and one for the actual progress.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('68c28478-c816-4732-a25f-90b95233972a','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_HOUSEHOLD_THREE','The “actual” line represents the actual number of households that were visited each day, starting from the beginning of the campaign up to the current day. The total number of households visited for each day is used to plot this line. The X-intercept of the actual line shows the projected date when the campaign is expected to meet its target, based on the current rate of progress.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bfe4e1d2-315a-4070-92ce-8ed88555aa52','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_HOUSEHOLD_TWO','The “planned” line represents the expected number of households that should have been visited each day, based on the micro plan. The cumulative number of households that were targeted to visit each day is used to plot this line. The X-intercept of the planned line shows the date when the campaign is expected to meet its target.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a2d63592-594a-477b-a523-ea10486ff62a','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_POPULATION','Planned vs Actual Campaign Progress (Population)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('68d66a74-e112-4039-8213-c9d302734f1f','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_POPULATION_FIVE','The x-axis interval is set to 1 day, meaning that each point on the chart represents the progress made in one day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('093b39b4-f391-43e6-9f9b-9ed4515f4423','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_POPULATION_FOUR','The calculation of the intercept is done by dividing the difference between the target population and the actual population covered by the population targeted per day and adding the result to today''s date.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0731c077-7d24-4053-8367-d7755225c285','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_POPULATION_ONE','This is a line chart that compares the planned and actual campaign progression for population coverage.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('74f74ef1-9b88-4893-b5e9-47b8465c6725','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_POPULATION_THREE','The actual data is obtained from the quantity distributed for a given date range. The X-intercept on the chart indicates when the population target is expected to be met based on the current rate of coverage.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aa842870-546e-427c-8788-8bf7f84cb083','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_PLANNED_VS_ACTUAL_PROGRESS_POPULATION_TWO','Planned data is calculated by adding up the cumulative quantity delivered and multiplying it by a factor of 1.8, representing the average population per household.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06018dc1-0193-4c66-b737-3bdb2b6e1f01','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_POPULATION_COVERED','Population Covered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3805e7e7-f4fc-41da-b456-64ff12ac89ad','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_POPULATION_COVERED_ONE','This KPI visualization in the “Registration and Delivery” dashboard section displays the total population covered within the selected date range. This data is sourced from the application''s delivery intervention screen where the quantity of bed nets delivered is recorded. The boundary data used for this section is MDMS.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5922fb05-5a9a-4b9f-869a-40791b3f9b85','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_POPULATION_COVERED_THREE','For the "%" toggle, the data is presented as a percentage of the total population covered, calculated by summing the number of individuals covered in each household and multiplying it by 100, and then dividing it by the daily population microplan target and the number of days in the selected date range. The data is presented separately for each boundary, which could be districts for national and provincial roles, and Administrative posts for district roles.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('808b38e0-a057-4d8b-92af-b3cfa5e1c2ba','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_POPULATION_COVERED_TWO','For the "Number" toggle, the data is presented as a sum of all households visited within the selected date range. The data is presented separately for each boundary, which could be districts for national and provincial roles, and Administrative posts for district roles.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b428801c-d598-4102-a90d-2ffbb3ca8bce','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT','Summary Report','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f4480946-1365-42fc-997c-b9103ddccc0e','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_BOUNDARY','Summary Report (Boundary)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cbb00ba3-104e-4a68-9f32-266dcdb5e008','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_BOUNDARY_FOUR','The report allows for drill-down functionality, allowing users to view data at a more granular level for each boundary. The Target Achievement columns show the percentage of micro plan targets achieved for household coverage, population coverage, and bed nets distribution.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('45e1298e-0b0c-459d-93ba-2341a1316e00','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_BOUNDARY_ONE','The summary report provides an overview of the progress of the campaign in different boundaries such as district, administrative post, for different metrics such as household coverage, population coverage, and bed nets distribution.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fcc4c112-43fa-42a8-8d3a-4d500eb1fe7b','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_BOUNDARY_THREE','Additionally, it provides data on the number of households where no delivery has taken place and the reasons for the non-delivery.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c303d3bd-8d41-4996-9fe7-270a36df8189','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_BOUNDARY_TWO','The report also includes information on the total number of households visited, the total population covered, and the total bed nets distributed for the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f580e269-657d-4bf5-aa93-5f41d0d8f543','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_DAY','Summary Report (Day)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6fddbed8-fb47-431b-ba73-03317145fc19','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_DAY_ONE','The summary table provides an overview of the campaign progress for each day. The table shows the date, target achievement percentage for households, population, and bed nets distribution, the total number of households visited, the total population covered, the total number of bed nets distributed, and the total number of households where no delivery has taken place along with the reasons.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e547766c-b46d-417c-acc6-0c1417c0d308','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_SUMMARY_REPORT_DAY_TWO','The table does not allow drilling down on the dates, and the last row of each column represents the sum of all data above it. This report helps to monitor the progress of the campaign, and it provides a daily summary of the achievements and challenges faced during the campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c057806f-bfaa-4ee0-bf7e-0f3551913503','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TAB_OVERVIEW_FIVE','District Level User: He is able to view the data for the respective district that he has been assigned.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc3d206a-213d-45b8-8de1-0f03d200faef','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TAB_OVERVIEW_FOUR','Province Level User: He is able to view the data for the respective province he has been assigned.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b1b2c003-6209-4668-ba2e-e24370f13a62','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TAB_OVERVIEW_THREE','National Level User : He is able to view the data for the selected province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('12a84c3f-a0d2-4899-b1be-deae84170d5c','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT','Target Achievement','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('14b8efc1-d90c-4efe-b084-bdceeb623cc5','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_BEDNETS','Target Achievement (Bed nets)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5b43e5c1-3cc7-449f-ab7a-7a0f932e4410','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_BEDNETS_FIVE','Insights are also available, with the percentage change in coverage between the current day and the previous day indicated.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7e3c54a7-5456-47ed-adda-2e4a719447ae','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_BEDNETS_FOUR','The formula used to calculate the coverage percentage is the sum of the bed nets distributed in each AP divided by the bed nets micro plan target for that AP.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d1c70825-a81b-4d21-9799-a31d80118dbc','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_BEDNETS_ONE','The heat map metric measures the distribution coverage of bed nets achieved against micro plan targets across different districts. The micro plan targets are set up during the project setup phase, and the bed nets distributed are recorded in the Delivery Intervention screen in the mobile application under the Quantity Distributed field.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31a76963-f445-4c7e-93f9-a62231b9e63b','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_BEDNETS_THREE','For district-level users, the default view of the heat map is at the assigned district level, with the bed nets distribution coverage indicated as a percentage for each administrative post (AP) within the district. However, since shapefiles are not available at the AP level, the view will have only the district outer boundary and not AP boundaries within it.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ee2a610c-5dee-450a-99ec-bac8b38186b1','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_BEDNETS_TWO','For national and provincial level users, the default view of the heat map is at the province level, with the bed nets distribution coverage indicated as a percentage for each district. The formula used to calculate the coverage percentage is the sum of the bed nets distributed in each district divided by the bed nets micro plan target for that district.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f9ccb6e7-292d-40e9-aa7f-8b93c85f6ac7','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_HOUSEHOLD','Target Achievement (Household)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a558ade0-60f2-4a87-afd8-ed0d86b5ae2a','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_HOUSEHOLD_FIVE','Finally, due to the unavailability of shapefiles beyond the district level, zooming in beyond the district level is not possible, and therefore, the map will only show the outer boundary of the district or administrative post.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('77f6d7f0-5d59-4290-8d9d-3adcd11457c9','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_HOUSEHOLD_FOUR','The metric also provides an insight that compares the household coverage between two days, expressed as a percentage change.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b3171f7a-dc58-4df6-9c05-6f55a2754feb','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_HOUSEHOLD_ONE','The Target Achievement of Households shows the geo map with percentage of households covered against the micro plan targets set for a particular district or administrative post. The micro plan targets are set at the project setup stage, and the household coverage is based on data fetched from the mobile application, which shows the households that have been visited. The metric is presented as a heat map that visualizes the percentage of household coverage achieved across different districts.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('92e315f0-04ae-421e-9f2a-44a27f7a37f7','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_HOUSEHOLD_THREE','For district-level users, the default view of the map is at the district level, and the metric is calculated as follows: Total households visited till today in an administrative post (AP) divided by the Household Micro plan target set for that AP multiplied by 100. The same calculation is performed for each AP within the district.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ea242460-9ae1-4263-9f12-d0f854384d54','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_HOUSEHOLD_TWO','For national and provincial users, the default view of the map is at the province level, and the metric is calculated as follows: Total households visited till today in a district divided by the Household Micro plan target set for that district multiplied by 100. The same calculation is performed for each district within the province.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9d92f3a7-1246-4e5b-a08b-fd9a48aaf475','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION','Target Achievement (Population)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5f2056a7-dffc-48ac-a3a5-cd61a8f2a694','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION_FIVE','Insights will be available in terms of percentage change in coverage between today and the previous day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1d1c9f1f-eb6c-43f3-bdc2-75e2f0097395','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION_FOUR','However, due to the unavailability of shapefiles beyond the district level, there will be no zoom-in available for both national/provincial and district-level users.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('050c9133-6673-4912-9858-b3416e160d79','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION_ONE','This metric measures the population coverage achieved against the micro plan targets in percentage. It will be presented as a heat map that shows the coverage percentage across different districts.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cbb35837-821b-4616-b08c-505d8b51e1ea','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION_SIX','It is important to note that for district-level users, the view will only show the district outer boundary, as the shapefiles for administrative posts are not available.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a590a64c-d555-45fc-bb6f-bb3436372b39','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION_THREE','For national and provincial level users, the default view will be at the province level, with the coverage percentage calculated as the sum of the population data covered in each district divided by the population micro plan target of that district, multiplied by 100. The same formula will be used for district-level users, with the default view set at the district level.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1dccc96b-5893-4a8b-99c2-a52504876705','en_MZ','DSS_CALCULATION_REGISTRATION_AND_DELIVERY_TARGET_ACHIEVEMENT_POPULATION_TWO','The micro plan targets and boundary data are provided in the project setup, while the bed nets distributed and population data covered are obtained from the delivery intervention screen in the application. The population data covered is calculated as the quantity distributed multiplied by 1.8, which is the average number of people per household in the country.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('000d9786-abf0-45b5-afc2-63dd6d1d5527','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS','Summary Report (Open complaints)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('038c37c2-d8d0-409f-9561-b1f77098f90d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_BOUNDARY','Boundary','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2f9b2edd-3fa4-4c12-af64-5ff99f21a192','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_BOUNDARY_ONE','This metric of the tabular chart displays the different boundaries for which the open complaints data count is reported. The boundary data will be as per the user role. I.e. ‘National’ and ‘provincial’ level users will get district level boundary data, whereas ‘district’ level users will get administrative post level boundary data. The drill-down functionality will be available for all levels of boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('448d3260-6509-41e8-8f45-55a0b0fc0f89','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_ONE','The Summary Report for Open Complaints is a tabular chart that shows the overview of complaints that are open from a particular duration with respect to the boundary. The report is categorized according to different boundaries within MDMS, and the complaints data is sourced for the “Open”, Complaints data module in the mobile application. The report allows for drill-down capabilities from one level of boundary to the last.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c399b7ef-0950-49e0-93cb-1c3cf8d3ab24','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_FOURTY_EIGHT_HOURS','Open since > 48 hrs','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7a73b298-cdec-440b-9e3d-9fa577bcce80','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_FOURTY_EIGHT_HOURS_ONE','This report shows the total number of open complaints for a particular boundary where the complaints have been open for more than 48 hours during the selected date range. The report calculates this by summing all the complaints where the status is "Open" and the time between the created time and 23:59 hours on selected end Date is more than 48 hours.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bdcaf289-7f09-4952-9b00-a4d288c4ca64','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_FOURTY_EIGHT_HOURS_TWO','The total number of open complaints is calculated by subtracting the sum of rejected and resolved complaints from the total number of complaints. The boundary for users can be a district for National & Provincial supervisors, and Administrative post for District supervisors. The last row of the column should be the sum of all columns above, which represents the total number of open complaints for more than 48 hours in the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fa6633f0-e827-4649-a448-0dd29dfca9e2','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_SIX_HOURS','Open since < 6 hrs ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('681f5e94-b1eb-4f38-825b-2098368c0121','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_SIX_HOURS_ONE','The "Open since < 6 Hours" summary report shows the total number of open complaints that are less than 6 hours old for the selected date range. The calculation for this report involves summing up all complaints where the status is "Open" and the complaint was created within the selected date range. In addition to this, the complaint must also have been created within 6 hours of the end of the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9252313b-1201-4afd-b76f-3acc0462af9d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_SIX_HOURS_TWO','The last row of the column shows the total sum of all columns above. This report helps supervisors to quickly identify newly registered complaints that need to be addressed urgently.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('091f064c-55ad-4a90-a434-52d8c03215e8','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_SIX_TO_TWELVE_HOURS','Open since > 6 hrs & <12 hrs ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f068a484-337a-4602-a350-d72d52905617','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_SIX_TO_TWELVE_HOURS_ONE','The "Open since > 6 hrs & <12 hrs" column in the summary report shows the total number of open complaints for the selected date range that have been open for more than 6 hours but less than 12 hours. The calculation is based on the time difference between the created time of the complaint and the end of the day on the specified date, which should fall between 6 and 12 hours.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('03ca1567-2e47-42b1-865e-27570d7ab5f5','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_SIX_TO_TWELVE_HOURS_TWO','The total number of open complaints for a given boundary (i.e., district or province) is calculated by summing all the complaints in that boundary that have the "OPEN" status and were created within the selected date range. This number is then further filtered to include only those complaints that have been open for more than 6 hours but less than 12 hours. The last row of the column shows the sum of all the values in that column for each boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e24dace2-9c9b-4cfb-b360-0bb6679ac830','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_TWELVE_TO_TWENTY_FOUR_HOURS','Open since > 12 hrs & <24 hrs ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9a3cf38-386f-4d43-a3e8-d0eb9c545c8d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_TWELVE_TO_TWENTY_FOUR_HOURS_ONE','The "Open since > 12 hours & <24 hours" section of the report shows the total number of open complaints that have been open for more than 12 hours but less than 24 hours, for a particular boundary within the selected date range. This is calculated by adding up all the complaints with the status of "OPEN" that were created within the boundary and have been open for more than 12 hours but less than 24 hours. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('48568270-e1a9-422a-b0fb-d61928003101','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_TWELVE_TO_TWENTY_FOUR_HOURS_TWO','The open complaints are determined by subtracting the sum of "Resolved" and "Rejected” complaints from the total complaints created for the boundary. The boundary is for which the data is being displayed, which can be District or Provincial, depending on the user role assigned. The last row of the column shows the sum of all the complaints in the column.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b55297d6-14d5-4371-9355-b6b94860b97d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_TWENTY_FOUR_FOURTY_EIGHT_HOURS','Open since > 24 hrs & < 48 hrs ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f14f471-3499-43a2-b199-5f98cef0e328','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_TWENTY_FOUR_FOURTY_EIGHT_HOURS_ONE','This report shows the total number of complaints that are still open and have not been resolved within the specified time frame, which is between 24 to 48 hours. The calculation is based on the time difference between the complaint creation time and the end of the day on the selected date. The data is filtered by the boundary of districts for national and provincial supervisors, and Administrative Posts for district supervisors.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fe406168-e5b3-4901-a475-7f87c95c2d18','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_OPEN_SINCE_TWENTY_FOUR_FOURTY_EIGHT_HOURS_TWO','The open complaints are calculated as the difference between the total complaints and the resolved and rejected complaints. The last row of the column is the sum of all the values in the respective columns. This report helps supervisors to monitor the number of open complaints that have not been resolved within the specified time frame.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('51dff220-91c8-4d9d-ba44-40c35950b44a','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_OPEN_COMPLAINTS_TWO','If a date range is selected, the end date will default to today''s date. The report will display the total number of open complaints for each boundary, with the last row of the column showing the sum of all columns. In summary, the Summary Report for Open Complaints provides a quick overview of the number of complaints that are still open within a selected duration and allows users to drill down to different levels of boundaries to get more granular information.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e455ca91-2ecf-4445-8704-3d3c7d13ceea','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS','Summary Report (Total complaints)','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6dbd6fd2-c2c2-4266-8ac7-fafe0cc24ea6','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE','Summary Report  (Total Complaints ) : ‘Boundary’ Toggle','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('12948d9e-189a-4641-a2cc-510bb4979631','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_BOUNDARY','Boundary','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ec1d69bd-cf61-4817-bf82-30e5075c7fcb','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_BOUNDARY_ONE','This metric of the tabular chart displays the different boundaries for which the complaints data is reported. The boundary data will be as per the user role. I.e. ‘National’ and ‘provincial’ level users will get district level boundary data, whereas ‘district’ level users will get administrative post level boundary data. The drill-down functionality will be available for all levels of boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cacbe0ff-8480-4265-b7ab-44b0795b32a2','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_ONE','The summary report for total complaints will be presented in a tabular chart format, which will provide an overview of the total complaints according to the boundary. Each boundary will be clickable and will allow drilling down to the next level of boundary for detailed information. The boundary data will be taken from the MDMS, and complaints data will be from the complaints module in the mobile application.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca3c9e94-cfbf-4d51-befe-8262932adfdf','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_OPEN','Open','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8ae905aa-d6b8-4854-8498-9b3847bc28cc','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_OPEN_ONE','The ‘Open’ Complaints in the summary report refers to the total number of complaints that are currently open and have not yet been resolved or rejected. All the complaints which do not have the status as Resolved or Rejected are termed as open; else to whatever state/status they are in. This means that no action has been taken on these complaints, and they are still waiting for attention from the relevant authorities. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ddea913b-2573-4b70-bab1-aac3475ed09c','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_OPEN_THREE','Finally, the report provides a total row at the bottom that sums up all the open complaints for all the boundaries. This information is helpful in identifying the workload and the current state of the complaint handling process.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8934ff90-ad43-4bad-a6ee-812547cc4dff','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_OPEN_TWO','The report calculates this number by summing up all the complaints in the selected boundary where the status is marked as "Open" and the date range is within the selected range. The report distinguishes between the different levels of authorities, such as National, Provincial, or District supervisors, and shows the total number of open complaints for each one accordingly. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f7048d08-06f4-4bfe-b273-2f03d964ed47','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REGISTERED','Registered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('54c77363-42de-4c38-b1b6-7c87af44542f','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REGISTERED_ONE','This provides information about the total number of complaints registered for the selected date range for each boundary level. The calculation for the "Total Complaints Registered" is the sum of all complaints that were created for the selected date range for each boundary level.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7116ca5-c195-4bf4-9cb7-8c09531c5cca','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REGISTERED_TWO','This includes complaints that are open, resolved, and rejected. The last row of the column should be equal to the sum of all the columns above it, providing the total number of complaints registered across all boundary levels.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a5f3f440-1441-4364-acda-64804c6af99a','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REJECTED','Rejected By Supervisor','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3e36d80b-6ec1-4e2e-bb76-fb3c408fc1b1','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REJECTED_ONE','This the total number of complaints that were rejected by a supervisor for the selected date range. The data field in the report shows the total number of complaints rejected for each boundary. Further the boundaries displayed depend on the user role, with national and provincial level users seeing districts as the default boundary data, while district level users see administrative posts as the default boundary data. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f8c8722a-8385-4362-add7-9b8f16469cd8','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REJECTED_THREE','The last row of the "Rejected by Supervisor" column shows the sum of all columns above it, indicating the total number of complaints rejected for all boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3bbc1c7e-09a5-493e-829d-8f3a7d8a354b','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_REJECTED_TWO','The drill-down feature is available for all boundaries, till the last village level. To calculate the total number of complaints rejected for each boundary, the system sums up all the complaints where the status is marked as "Rejected" and where the boundary is equal to different districts or administrative posts as applicable by user role and the date range is the one selected by the user. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4fb7177d-1b66-4b85-ad03-0f974140f64f','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_RESOLVED','Resolved','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9b0dc915-33d5-4b21-a33f-3bf50b13c615','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_RESOLVED_ONE','The purpose of the section is to show the total number of complaints that were resolved within the selected date range for each boundary. This displays the data for each boundary, which could be district or administrative posts depending on the user''s role. The calculation for the number of resolved complaints involves adding up all the complaints where the status is marked as "RESOLVED" for a given boundary and date range. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('74383a22-6cc9-4747-9aa2-a752618bf39d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_BOUNDARY_TOGGLE_RESOLVED_TWO','The last row of the "Resolved" column shows the sum of all the resolved complaints for each boundary, giving an overall count of the number of complaints resolved for the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d5c509b0-9baa-40a6-9757-02a26d26a5fa','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE','Summary Report  (Total Complaints ) : ‘Day’ Toggle','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('148711ed-1290-4b90-9834-c12a80c67254','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_DATE','Date','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d743e1c3-c397-4341-bb0a-cd4df80f629d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_DATE_ONE','The "Date" column in the summary report with "Day" toggle shows the complaint data according to the date. The default view is the starting date of the campaign. and there is no drill-down available for the dates.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d3904883-e8de-4287-b453-6284dde49872','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_ONE','The Summary Report with ''Day'' Toggle displays a tabular chart that shows data for each day of the campaign, with no drill down on the dates. The report shows Complaint data as per the date, with Boundary data coming from MDMS and Complaint data from the Complaints module in the mobile application. The last row of each column will be the total sum of all columns. The Date Report does not have any change as per the date range selected. The Report will be from the Campaign start date till today.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('305c4f5b-1de1-4537-9c75-e3406b714224','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_OPEN','Open','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9e8434d8-f0c3-4dd3-b883-8cd567d19a5e','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_OPEN_ONE','The "Open" column in the Day toggle chart shows the total number of complaints on a particular day for which no action has been taken yet and the status is not Rejected or Resolved. Using the three metrics (Total Complaints: / Rejected / Resolved), the number of open complaints can be calculated by subtracting the total number of resolved and rejected complaints from the total number of complaints created on a particular day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('339c6688-2a27-4d40-80d0-b2838dcb21dc','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_OPEN_TWO','The last row of the column shows the sum of all open complaints. The Day toggle chart data is not affected by the date range selection.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7e9df17e-9c03-4cc0-9274-385d79fbb849','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_REGISTERED','Registered','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('21671314-6e2d-476d-90ed-20b55d86fa97','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_REGISTERED_ONE','The summary of Registered complaints shows the total number of complaints that have been registered on each day. The total complaints registered for a particular date is calculated by summing up all the complaints that have been created on that date for the user boundary allotted. The boundary data is determined by the user''s role. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20e05374-46c6-4d77-9608-7f2aab84daed','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_REGISTERED_TWO','National and provincial supervisors will have the default boundary data set to the district, whereas district supervisors will have administrative posts as the default boundary data. The total number of complaints is calculated as the sum of all complaints that are currently open, resolved, or rejected.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9b267d7a-a4c1-4fec-b988-262986e987f6','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_REJECTED','Rejected By Supervisor','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3aa5727f-e894-4792-99f9-72806da89e64','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_REJECTED_ONE','The "Rejected by Supervisor" column in the Day toggle chart displays the total number of complaints that were rejected by the supervisor for each date. This is calculated as the difference between "Total Complaints Registered" and the sum of open and resolved complaints.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ecc28134-56ce-4edb-b648-951ae59e45d1','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_REJECTED_TWO','The last row of the column shows the total number of complaints that were rejected by the supervisor, across all dates. It should be noted that the Day toggle chart is not affected by the date range selection, and always displays data for each day of the campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fc8014af-3354-45b0-9fe0-9f466395ca6b','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_RESOLVED','Resolved','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fca4d7f4-7f62-47db-90d0-7ee7c06af81e','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_RESOLVED_ONE','This section in the summary report for ‘Day’ toggle shows the total number of complaints that were resolved on each date. This is calculated by summing up all the complaints that have a status of "RESOLVED" for the corresponding date and boundary (i.e., "Province" for Provincial and National supervisors and "District" for District supervisors).','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('13dc43ab-a305-4765-a8d4-d062bad0170d','en_MZ','DSS_CALCULATION_SUMMARY_REPORT_TOTAL_COMPLAINTS_DAY_TOGGLE_RESOLVED_TWO','The last row of the "Resolved" column is the sum of all the resolved complaints for all the dates. The Day toggle chart is not affected by the DATE RANGE selection, which means that the chart will show data for each day of the campaign regardless of the selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2b4268c1-95ce-4085-bed4-8b9174f66078','en_MZ','DSS_CALCULATION_SUPERVISION_DATA_SYNC','Data Sync','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('05c9484b-cb06-4161-b96b-bd3508e7aa25','en_MZ','DSS_CALCULATION_SUPERVISION_DATA_SYNC_ONE','Data Sync rate refers to the percentage of users who have synced their device with the application at least once for a specified time period. It is calculated as the total number of users who have synced their device divided by the total number of users created, expressed as a percentage.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5fe3ccd1-fb62-4fdc-aa1a-7de426c1e980','en_MZ','DSS_CALCULATION_SUPERVISION_DATA_SYNC_THREE','The drill-down for this information is limited to the Administrative Post level. This means that for National/Provincial supervisors, the drill-down will be from "District" to "Administrative Post". For District supervisors, the information will directly display the Administrative Post without the need for drill-down.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b08267fa-e645-451d-9150-24e40770c6ca','en_MZ','DSS_CALCULATION_SUPERVISION_DATA_SYNC_TWO','In addition, the percentage of users who have synced their device at least once for the selected day will be displayed. This information will be displayed in the form of a bar chart, with the x-axis showing the different boundaries as per the user role who is viewing, and the y-axis showing the percentage of users who have synced their device in that boundary.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c1fea7c4-1337-4e06-9899-1e6e992acc8b','en_MZ','DSS_CALCULATION_SUPERVISION_DISTRICT_SUPERVISORS_CHECKLIST_COMPLETION_RATE','District Supervisors Checklists Completion Rate','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc899f3a-333a-42e1-ba55-f8d60c9cd10c','en_MZ','DSS_CALCULATION_SUPERVISION_DISTRICT_SUPERVISORS_CHECKLIST_COMPLETION_RATE_ONE','The District Supervisors Checklists Completion Rate is a bar chart that shows the percentage completion of checklists allotted and to be filled by district-level supervisors. The data for this feature is taken from the supervisor module in the application, specifically for checklists completion. The level of the supervisor is retrieved from the user management module.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3b80eaee-3d63-4465-a680-3c5d76131d1c','en_MZ','DSS_CALCULATION_SUPERVISION_DISTRICT_SUPERVISORS_CHECKLIST_COMPLETION_RATE_POINT_ONE','For ‘National/Provincial Supervisors’ the number of entries is calculated by counting the number of checklists created within the selected/assigned province and selected date range, where the supervisor level is District and the number of checklists available and assigned.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('147c780a-326a-4b0c-b6fc-35120e539461','en_MZ','DSS_CALCULATION_SUPERVISION_DISTRICT_SUPERVISORS_CHECKLIST_COMPLETION_RATE_POINT_TWO','For ‘District Supervisors’ the number of entries is calculated by counting the number of checklists created within the assigned district and selected date range, where the supervisor level is District and the different checklists available for him and assigned.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8444360d-ed63-48ee-b4d4-3d6b537945f6','en_MZ','DSS_CALCULATION_SUPERVISION_DISTRICT_SUPERVISORS_CHECKLIST_COMPLETION_RATE_TWO','The calculation for the chart is as follows:','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b75ad735-e2b5-4961-9013-562a6b718e1d','en_MZ','DSS_CALCULATION_SUPERVISION_NATIONAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE','National Supervisors Checklists Completion Rate','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b7cdbfde-1dfe-43cb-b4b8-ebebc1a7693f','en_MZ','DSS_CALCULATION_SUPERVISION_NATIONAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_FOUR','The result is presented as a bar chart that displays the percentage completion of checklists by national-level supervisors. This metric provides an overview of how national-level supervisors are performing in terms of completing the checklists assigned to them, and it helps in identifying areas where further attention is required to ensure that the checklists are completed on time.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('94b1cb9a-50fc-4645-bb28-5cfde97c99e5','en_MZ','DSS_CALCULATION_SUPERVISION_NATIONAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_ONE','The ‘National Supervisors Checklists Completion Rate’ is a metric displayed as a bar chart in the dashboard section. This metric measures the percentage completion of checklists by national-level supervisors. The data is derived from the supervisor application, user management module, and the frequency of checklist completion.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ba540da8-ceba-47fd-b85c-627c36858728','en_MZ','DSS_CALCULATION_SUPERVISION_NATIONAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_THREE','For ‘national/provincial supervisors’, the number of entries is calculated where supervisor level is national and checklists are the different checklists available to be filled. For ‘district supervisors’, the number of entries is calculated where supervisor level is national and checklists are different checklists available to be filled at the district level.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e206c04f-6674-4ad6-a4bd-048781c72b49','en_MZ','DSS_CALCULATION_SUPERVISION_NATIONAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_TWO','To calculate this metric, the application requires input fields such as the level of supervisor, frequency of checklist completion, and the number of checklists created within the selected/assigned province or district and selected date range.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('46fb972b-6aa2-4bed-ae9f-69a1723bfbb6','en_MZ','DSS_CALCULATION_SUPERVISION_PROVINCIAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE','Provincial Supervisors Checklists Completion Rate','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a69760d6-2222-4521-83bb-d7d0c9d80bff','en_MZ','DSS_CALCULATION_SUPERVISION_PROVINCIAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_FIVE','The level of the supervisor is obtained from the user management module, and the frequency of checklist completion is also considered in the calculation. For national/provincial supervisors, the number of entries is calculated for the selected/assigned province and the checklist name, whereas for district supervisors, the number of entries is calculated for the assigned district and checklist name.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a54d2e56-f30f-42d0-bb11-c573ab12a684','en_MZ','DSS_CALCULATION_SUPERVISION_PROVINCIAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_FOUR','The data required for the calculation of this metric is obtained from the supervisor application/module, which is used for checklists completion. ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6636dcd3-38be-402f-ad8d-5660851246c9','en_MZ','DSS_CALCULATION_SUPERVISION_PROVINCIAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_ONE','Provincial Supervisors Checklists Completion Rate is a metric that shows the percentage completion of checklists by provincial-level supervisors. This bar chart is displayed in the dashboard, and helps to monitor the performance of the checklist that has been filled and submitted by provincial-level supervisors.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('884960b4-3f9b-4131-b7db-ad42201ba19a','en_MZ','DSS_CALCULATION_SUPERVISION_PROVINCIAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_THREE','This calculation is performed for each checklist assigned to the provincial-level supervisors, and the results are displayed in a bar chart format.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('705d8682-7128-4e39-88b9-2e00ea8fa7cb','en_MZ','DSS_CALCULATION_SUPERVISION_PROVINCIAL_SUPERVISORS_CHECKLIST_COMPLETION_RATE_TWO','To calculate this metric, the number of checklists created for provincial-level supervisors to be filled, for the selected/assigned province and selected date range is counted, and the number of checklists completed is calculated. The completed checklists are then divided by the total number of checklists created, and this ratio is multiplied by 100 to get the percentage completion rate.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('13e50f9f-0190-4c86-badc-8375602bd2ac','en_MZ','DSS_CALCULATION_SUPERVISION_TAB_OVERVIEW_ONE','The ‘Supervisor’ section in the dashboard provides a visual representation of the actions taken by supervisors on the activities / checklist assigned to them. This section shows the response of all three levels of users: National, Provincial, and District.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e869c70f-6800-4d50-ba97-43da6802a541','en_MZ','DSS_CALCULATION_SUPERVISION_TAB_OVERVIEW_THREE','This information can be used by higher-level management to monitor the progress of activities and identify any potential issues that may arise.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f70ea71-abfb-42be-a75d-b64360f4e356','en_MZ','DSS_CALCULATION_SUPERVISION_TAB_OVERVIEW_TWO','At the National level, the dashboard displays the number of times the checklist has been allotted and filled by the supervisors across the country. At the Provincial level, the dashboard shows the same information but only for the province in question. At the District level, the dashboard displays the number of times the checklist has been allotted and filled by the supervisors for the district.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1ee1ba70-5ef4-49c4-86f0-ace10d371053','en_MZ','DSS_CARD_HEADER_DASHBOARD','Dashboard','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e8b7c4f7-0971-4655-ab10-3f2eb2de2392','en_MZ','DSS_CMN_TABLE_INFO',' ','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f47333a7-9294-4d88-995d-b464a9e9781e','en_MZ','DSS_COMPLAINTS_REJECTION_REASON_INVALID_COMPLAINT','Invalid Complaint','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3d81072e-6ee8-467c-96d1-3da8fab1457b','en_MZ','DSS_COVERAGE_BY_PROVINCE','Coverage By Province','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
