INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('be70cce4-689c-443f-9f48-e83f8d0df2ff','en_MZ','DSS_FAQ_SYNC_RATE_METRIC','In the Data Sync card, there is a metric called "sync rate" that indicates the percentage of total workers who have synced their device at least once for the day.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('622984ad-053a-499f-8886-815a9d839cdd','en_MZ','DSS_FAQ_SYNC_RATE_SHOWS_PROPORTION','The sync rate shows the proportion of data collected by all workers that have been synced with the system, indicating the dashboard''s data is up-to-date.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('057e0333-173c-4343-be81-167ab06be419','en_MZ','DSS_FAQ_TOP_BEDNETS_CARD','At the top of the screen, they will see the "Bed Nets Distributed" card.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d16f6848-bcda-4ead-b9a5-c9d6c6c15b0f','en_MZ','DSS_FAQ_TOTAL_HOUSEHOLD_VISITED_DATA','The "Total household visited" data on the Household card represents the total number of households visited since the start of the campaign across all provinces.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('49de8acf-63ff-47cd-9b48-1ce0e6a4a33b','en_MZ','DSS_FAQ_TOTAL_METRICS_DISTRIBUTED_METRIC','In this card, the "Total Bednet Distributed" metric displays the total number of bednets that have been distributed since the beginning of the campaign across all provinces.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b769744f-e73d-41a9-9808-7ccaa35f42b7','en_MZ','DSS_FAQ_TOTAL_USER_CREATED_COUNT','The "Total user created" count on this card represents the total number of workers assigned to the selected campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bccfff8f-0a35-40d2-866d-e6834a76f216','en_MZ','DSS_FAQ_TO_DOWNLOAD_ENTIRE_PAGE','To download the entire page, click on the "Download" button located at the top right corner of the page.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6a485484-27dc-4968-b31f-f334380b35e9','en_MZ','DSS_FAQ_TO_DOWNLOAD_INDIVIDUAL_CARD','To download or share an individual card, graph, or summary table, click on the kebab menu icon (a vertical three dots icon) located at the top right corner of each individual card, and choose the download or share option.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d14e5089-941d-4161-a3a6-25c5770da378','en_MZ','DSS_FAQ_TO_DRILL_DOWN_BOUNDARY','To drill down to various boundary levels of data in the dashboard, users can click on the legends with the different boundary names displayed on the "bar graph," "heat map," and "summary reports." For instance, if a user wants to view data at a lower level, they can click on the name of the boundary to scatter it to the next lowest level of data.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ca107a4c-b7fb-4e53-bd9d-ccf54fa0bf9c','en_MZ','DSS_FAQ_TO_SHARE_ENTIRE_PAGE','To share the entire page, click on the "Share" button at the top right corner of the page and choose the desired sharing option (such as WhatsApp or email).','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('31ad8235-7566-484f-a898-40e19adb78a0','en_MZ','DSS_FAQ_TO_USER_CAN_NAVIGATE','This means that the user can easily navigate through different levels of data, from higher administrative levels such as provinces and districts, to lower administrative levels such as localities and villages.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('90b8cb4b-bcd0-4bc3-b705-a78d9c965747','en_MZ','DSS_FAQ_USER_WILL_BE_DIRECTED','The user will be directed to the national dashboard for the selected campaign.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fd3c973d-7d91-45f5-884c-cb5bcedc32bb','en_MZ','DSS_FAQ_VIEW_COMPARE_COVERAGE','To view and compare the household coverage ranking for boundary data, users can access the overview section of the province-level dashboard for National and Province Level Users, or the District Level dashboard for District Level Users. The bar graph is available in the “Household Coverage Ranking” Card in this section which arranges boundaries in descending order based on their household coverage data, making it easy for users to compare rankings.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('130a39ee-f1f2-42ee-bfcf-b3ef7fe81a13','en_MZ','DSS_FAQ_VIEW_POPULATION_COVERAGE','View the "Population coverage" card with a bar graph','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dd1255d3-e17a-422a-86dc-672efe462845','en_MZ','DSS_FAQ_VIEW_VALUES_ON_LINE','To view values on a line or bar graph, hover over the line or bar for the respective boundaries.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7808c012-379f-4510-ae63-4fd1c37fa936','en_MZ','DSS_FAQ_VIEW_VALUES_ON_PIE','To view values on a pie chart, hover over the individual slice of the pie to view the absolute or percentage value for that portion.','mz','rainmaker-hcm-dss',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
